/// Battle-fairy death/equipment transitions используют runtime только для
/// точного old-client goods codec; player property state и `0xBF721` принадлежат
/// `CGame/CPlayer` и не передаются через этот context.
pub(crate) trait BattleFairyDeathContext: OldClientGoodsCodec {}

/// Единая runtime-граница virtual `CPlayer::UpdateProperty`. Все reached
/// callers применяют один полный snapshot независимо от причины mutation;
/// локальные `CGame` owners сохраняют собственный порядок publication и
/// последующие TaoZhuang/state side effects.
pub(crate) trait PlayerPropertyContext {
    fn recompute_enhancement_player_properties(
        &mut self,
        player: &CPlayer,
    ) -> PlayerCombatProperties;
}

/// Общая граница завершения смерти монстра. Она нужна и боевому проходу ИИ,
/// и `KillMonster`: награда, добыча, свойства игрока и помещение предмета в
/// регион используют одних владельцев и не расходятся по двум реализациям.
pub(crate) trait MonsterDeathContext:
    GameClockContext
    + OldClientGoodsCodec
    + ServerRegionMembershipContext
    + PlayerPropertyContext
    + NationCombatContext
{
}

impl<T> MonsterDeathContext for T where
    T: GameClockContext
        + OldClientGoodsCodec
        + ServerRegionMembershipContext
        + PlayerPropertyContext
        + NationCombatContext
{
}

/// Exact virtual `CPlayer::UpdateProperty` после realm hidden-skill mutation.
/// Runtime владеет ещё не сведёнными equipment/state/GlobeSetup источниками;
/// CGame применяет возвращённый полный snapshot и сам публикует `0xBF721`.
pub(crate) trait RealmAppellationScriptContext:
    BattleFairyDeathContext + PlayerPropertyContext
{
    /// `AddExState` type `0x12F` сначала снимает concrete
    /// `SKILL_GOD_BLESS`. Общий state registry ещё остаётся у runtime, но
    /// вызов идёт из реального script owner-а до replacement нового state.
    fn remove_script_god_bless_state(&mut self, player_id: i32);
}

pub(crate) trait BattleFairySkillResetContext {
    fn publish_battle_fairy_skill_reset_packet_consumption(
        &mut self,
        effect: &BattleFairySkillResetEffect,
    ) -> Vec<i32>;
}

/// Нематериализованные virtual owners skill-state остаются на
/// runtime-границе. Player GameSave, live pet/carriage snapshots,
/// region/player maps, session state и message wire исполняет `CGame`.
pub(crate) trait ScriptRegionChangeContext: NationCombatContext {
    fn prepare_script_region_companions(
        &mut self,
        player: &mut CPlayer,
        source_region_id: i32,
        target_region_id: i32,
        target_tile_x: i32,
        target_tile_y: i32,
        carriage_distance: i32,
        changing_server: bool,
    );

    fn refresh_script_region_auto_protect(&mut self, player: &mut CPlayer);
}

pub(crate) trait GameRegionEnterContext: NationCombatContext {
    /// Remaining `8F801` serialization/weather/state tail after concrete
    /// destination membership has been established by `CGame`.
    fn publish_changed_player_region_entry(
        &mut self,
        game: &mut CGame,
        player_id: i32,
        region_id: i32,
        entry_token: i32,
        socket_id: i32,
    );
}

/// Внешняя половина initial-login owner-а: player codec, map, spatial
/// membership, login/honor scripts и Billing account entry исполняет `CGame`.
/// Ещё не материализованные полный client snapshot и virtual property
/// recompute получают тот же live runtime в исходном порядке. GoodsAI tree
/// принадлежит canonical player и заполняется после успешной регистрации.
pub(crate) trait GamePlayerLoginContext:
    NationCombatContext + OldClientGoodsCodec + PlayerPropertyContext
{
    fn publish_initial_player_client_snapshot(
        &mut self,
        game: &mut CGame,
        player_id: i32,
        first_login: bool,
    );
}

