struct GameCountryRegionAiContext<'a, Runtime> {
    game: &'a mut CGame,
    runtime: &'a mut Runtime,
    region: CServerRegion,
    ai_tick: i32,
}

impl<Runtime: GameMainLoopRuntime> CountryContendEntryContext
    for GameCountryRegionAiContext<'_, Runtime>
{
    fn now_millis(&mut self) -> u32 {
        self.runtime.now_milliseconds()
    }

    fn send_contend_time(&mut self, player_id: i32, time: i32) {
        let mut message = CMessage::new(0x000b_ff29);
        message.add_long(time);
        let delivery = message.send_to_player(self.game.net_server(), player_id);
        tracing::trace!(
            player_id,
            percentage = time,
            delivery,
            "отправлено время захвата символа государства"
        );
    }

    fn set_known_player_contend_state(&mut self, player_id: i32, state: bool) {
        let around_delivery =
            self.game
                .publish_war_player_contend_state(&self.region, player_id, state);
        tracing::trace!(
            player_id,
            state,
            ?around_delivery,
            "опубликовано состояние захвата символа государства"
        );
    }

    fn notify_player(&mut self, player_id: i32, string_id: &'static str) {
        let message = colored_player_notice_message(
            0xffff_ffff,
            0xffff_0000,
            self.game.get_string_by_id(string_id.as_bytes()),
        );
        let delivery = message.send_to_player(self.game.net_server(), player_id);
        tracing::trace!(
            player_id,
            string_id,
            delivery,
            "отправлено уведомление захвата символа государства"
        );
    }
}

impl<Runtime: GameMainLoopRuntime> CountryContendContext
    for GameCountryRegionAiContext<'_, Runtime>
{
    fn run_base_region_ai(
        &mut self,
        region: &mut CServerRegion,
    ) -> Result<(), ServerRegionMonsterRectBlock> {
        let tick_interval_ms = GAME_TICK_INTERVAL_MS as i32;
        self.game.run_server_region_base_ai(
            region,
            self.ai_tick,
            tick_interval_ms,
            self.runtime,
        )?;
        self.region = region.clone();
        Ok(())
    }

    fn find_global_player(&mut self, player_id: i32) -> Option<CountryContendPlayer> {
        self.game
            .find_player(player_id)
            .map(|player| CountryContendPlayer {
                player_id,
                faction_id: player.faction_id(),
                country: player.country(),
                shape_type: 400,
                is_dead: player.is_dead(),
            })
    }

    fn set_global_player_contend_state(&mut self, player_id: i32, state: bool) {
        self.set_known_player_contend_state(player_id, state);
    }

    fn on_country_win_one_symbol(&mut self, country: i32, symbol_id: i32) {
        // Country-region не переопределяет пустой base virtual slot; реальный
        // owned result уже записан в `symbol_hold` перед этим уведомлением.
        tracing::trace!(country, symbol_id, "государство захватило символ");
    }

    fn send_country_symbol_captured_region_notice(&mut self, country: u8, symbol_name: &str) {
        let country_name = self
            .game
            .globe_setup
            .country_name(country)
            .unwrap_or_default();
        let text = format_legacy_text_fields(
            self.game.get_string_by_id(b"GS0226"),
            &[country_name, symbol_name.as_bytes()],
            0x3ff,
        );
        let delivery = colored_text_message(0xbf806, 0xffff_ffff, 0xffff_0000, &text)
            .send_to_region(Some(&self.region), None, self.game);
        tracing::trace!(
            country,
            symbol_name,
            delivery,
            "отправлено уведомление региона о захвате символа государства"
        );
    }

    fn send_country_symbol_captured_top_info(
        &mut self,
        country: u8,
        region_name: &str,
        symbol_name: &str,
    ) {
        let country_name = self
            .game
            .globe_setup
            .country_name(country)
            .unwrap_or_default();
        let text = format_legacy_text_fields(
            self.game.get_string_by_id(b"GS0227"),
            &[country_name, region_name.as_bytes(), symbol_name.as_bytes()],
            0x3ff,
        );
        let delivery = self.game.send_top_info_to_client(-1, 0, 1, 1, &text);
        tracing::trace!(
            country,
            region_name,
            symbol_name,
            ?delivery,
            "отправлена верхняя строка о захвате символа государства"
        );
    }
}

struct GameCityRegionAiContext<'a, Runtime> {
    game: &'a mut CGame,
    runtime: &'a mut Runtime,
    region: CServerRegion,
    ai_tick: i32,
    war_number: i32,
    owner: WarRegionOwnership,
    defence_side_faction_id: i32,
}

impl<Runtime: GameMainLoopRuntime> WarRegionContext for GameCityRegionAiContext<'_, Runtime> {
    type MembershipError = AttackCityMembershipBlock;

    fn player_faction_id(&mut self, player_id: i32) -> Option<i32> {
        self.game.find_player(player_id).map(CPlayer::faction_id)
    }

    fn is_apply_war_faction(&mut self, faction_id: i32) -> Result<bool, Self::MembershipError> {
        self.game
            .attack_city_sys()
            .is_already_declar_for_war(self.war_number, faction_id)
    }

    fn send_contend_time(&mut self, player_id: i32, time: i32) {
        let mut message = CMessage::new(0x000b_ff29);
        message.add_long(time);
        let delivery = message.send_to_player(self.game.net_server(), player_id);
        tracing::trace!(
            player_id,
            percentage = time,
            delivery,
            "отправлено время захвата городского символа"
        );
    }

    fn set_global_player_contend_state(&mut self, player_id: i32, state: bool) {
        let around_delivery =
            self.game
                .publish_war_player_contend_state(&self.region, player_id, state);
        tracing::trace!(
            player_id,
            state,
            ?around_delivery,
            "опубликовано состояние захвата городского символа"
        );
    }

    fn set_region_player_contend_state(&mut self, region_id: i32, player_id: i32, state: bool) {
        if self
            .game
            .find_player(player_id)
            .is_some_and(|player| player.server_region_id() == Some(region_id))
        {
            self.set_global_player_contend_state(player_id, state);
        }
    }
}

impl<Runtime: GameMainLoopRuntime> WarContendEntryContext for GameCityRegionAiContext<'_, Runtime> {
    fn now_millis(&mut self) -> u32 {
        self.runtime.now_milliseconds()
    }

    fn is_owner(&mut self, faction_id: i32) -> bool {
        faction_id != 0 && faction_id == self.owner.faction_id
    }

    fn player_has_good(&mut self, player_id: i32, good_name: &str) -> bool {
        let goods_index = self
            .game
            .goods_factory()
            .query_goods_id_by_original_name(Some(good_name.as_bytes()));
        self.game
            .find_player(player_id)
            .is_some_and(|player| player.check_item_in_packet(goods_index) != 0)
    }

    fn set_known_player_contend_state(&mut self, player_id: i32, state: bool) {
        self.set_global_player_contend_state(player_id, state);
    }

    fn notify_player(&mut self, player_id: i32, string_id: &'static str) {
        let message = colored_player_notice_message(
            0xffff_ffff,
            0xffff_0000,
            self.game.get_string_by_id(string_id.as_bytes()),
        );
        let delivery = message.send_to_player(self.game.net_server(), player_id);
        tracing::trace!(
            player_id,
            string_id,
            delivery,
            "отправлено уведомление захвата городского символа"
        );
    }

    fn register_needed_good(&mut self, _good_name: &str) {
        // City virtual slot +0x118 — подтверждённый no-op.
    }

    fn send_first_faction_contender_notice(
        &mut self,
        country: u8,
        faction_name: &str,
        symbol_name: &str,
    ) {
        let country_name = self
            .game
            .globe_setup
            .country_name(country)
            .unwrap_or_default();
        let text = format_legacy_text_fields(
            self.game.get_string_by_id(b"GS0246"),
            &[
                country_name,
                faction_name.as_bytes(),
                symbol_name.as_bytes(),
            ],
            0x3ff,
        );
        let delivery = colored_text_message(0xbf806, 0xffff_ffff, 0xffff_0000, &text)
            .send_to_region(Some(&self.region), None, self.game);
        tracing::trace!(
            country,
            faction_name,
            symbol_name,
            delivery,
            "отправлено уведомление о первом претенденте на городской символ"
        );
    }
}

impl<Runtime: GameMainLoopRuntime> WarContendContext for GameCityRegionAiContext<'_, Runtime> {
    fn run_base_region_ai(
        &mut self,
        region: &mut CServerRegion,
    ) -> Result<(), ServerRegionMonsterRectBlock> {
        let tick_interval_ms = GAME_TICK_INTERVAL_MS as i32;
        self.game.run_server_region_base_ai(
            region,
            self.ai_tick,
            tick_interval_ms,
            self.runtime,
        )?;
        self.region = region.clone();
        self.owner = WarRegionOwnership {
            faction_id: region.param.owned_faction_id,
            union_id: region.param.owned_union_id,
        };
        Ok(())
    }

    fn find_global_player(&mut self, player_id: i32) -> Option<ContendPlayerState> {
        self.game
            .find_player(player_id)
            .map(|player| ContendPlayerState {
                player_id,
                faction_id: player.faction_id(),
                union_id: player.union_id(),
                country: player.country(),
                faction_name: String::from_utf8_lossy(player.faction_name()).into_owned(),
                shape_type: 400,
                is_dead: player.is_dead(),
            })
    }

    fn on_faction_win_one_symbol(&mut self, faction_id: i32, symbol_id: i32) {
        if symbol_id == 0 {
            self.defence_side_faction_id = faction_id;
            tracing::trace!(faction_id, "изменена защищающая городская сторона");
        }
    }

    fn on_faction_victory(
        &mut self,
        faction_id: i32,
        union_id: i32,
        current_owner: WarRegionOwnership,
    ) -> WarRegionOwnership {
        let current = if self.region.city_state == 0 {
            current_owner
        } else {
            self.defence_side_faction_id = faction_id;
            CityRegionContext::on_one_message_size_over(self.runtime, faction_id, union_id);
            CityRegionContext::send_city_victory(
                self.runtime,
                self.war_number,
                self.region.id,
                faction_id,
                union_id,
            );
            WarRegionOwnership {
                faction_id,
                union_id,
            }
        };
        self.owner = current;
        tracing::trace!(faction_id, union_id, previous = ?current_owner, ?current, "обработана победа фракции в городе");
        current
    }

    fn send_symbol_captured_region_notice(&mut self) {
        let delivery = colored_text_message(
            0xbf806,
            0xffff_ffff,
            0xffff_0000,
            self.game.get_string_by_id(b"GS0241"),
        )
        .send_to_region(Some(&self.region), None, self.game);
        tracing::trace!(
            delivery,
            "отправлено уведомление региона о захвате городского символа"
        );
    }

    fn send_symbol_captured_top_info(&mut self, faction_name: &str, symbol_name: &str) {
        let text = format_legacy_text_fields(
            self.game.get_string_by_id(b"GS0227"),
            &[faction_name.as_bytes(), symbol_name.as_bytes()],
            0x3ff,
        );
        let delivery = self.game.send_top_info_to_client(-1, 0, 1, 1, &text);
        tracing::trace!(
            faction_name,
            symbol_name,
            ?delivery,
            "отправлена верхняя строка о захвате городского символа"
        );
    }

    fn write_symbol_capture_logs(&mut self, capture: SymbolCaptureLog<'_>) {
        self.game.write_war_symbol_capture_log(&capture);
        tracing::trace!(
            war_number = capture.war_number,
            owned_faction_id = capture.owned_faction_id,
            owned_union_id = capture.owned_union_id,
            faction_name = capture.faction_name,
            faction_id = capture.faction_id,
            player_id = capture.player_id,
            symbol_id = capture.symbol_id,
            union_id = capture.union_id,
            "записан журнал захвата городского символа"
        );
    }
}

struct GameVillageRegionAiContext<'a, Runtime> {
    game: &'a mut CGame,
    runtime: &'a mut Runtime,
    region: CServerRegion,
    war_number: i32,
    ai_tick: i32,
    flag_owner_faction_id: i32,
    needed_goods: Vec<String>,
}

impl<Runtime: GameMainLoopRuntime> WarRegionContext for GameVillageRegionAiContext<'_, Runtime> {
    type MembershipError = Infallible;

    fn player_faction_id(&mut self, player_id: i32) -> Option<i32> {
        self.game.find_player(player_id).map(CPlayer::faction_id)
    }

    fn is_apply_war_faction(&mut self, faction_id: i32) -> Result<bool, Self::MembershipError> {
        Ok(self
            .game
            .village_war_sys()
            .is_already_declar_for_war(self.war_number, faction_id))
    }

    fn send_contend_time(&mut self, player_id: i32, time: i32) {
        let mut message = CMessage::new(0x000b_ff29);
        message.add_long(time);
        let delivery = message.send_to_player(self.game.net_server(), player_id);
        tracing::trace!(
            player_id,
            percentage = time,
            delivery,
            "отправлено время захвата деревенского символа"
        );
    }

    fn set_global_player_contend_state(&mut self, player_id: i32, state: bool) {
        let around_delivery =
            self.game
                .publish_war_player_contend_state(&self.region, player_id, state);
        tracing::trace!(
            player_id,
            state,
            ?around_delivery,
            "опубликовано состояние захвата деревенского символа"
        );
    }

    fn set_region_player_contend_state(&mut self, region_id: i32, player_id: i32, state: bool) {
        if self
            .game
            .find_player(player_id)
            .is_some_and(|player| player.server_region_id() == Some(region_id))
        {
            self.set_global_player_contend_state(player_id, state);
        }
    }
}

impl<Runtime: GameMainLoopRuntime> WarContendEntryContext
    for GameVillageRegionAiContext<'_, Runtime>
{
    fn now_millis(&mut self) -> u32 {
        self.runtime.now_milliseconds()
    }

    fn is_owner(&mut self, faction_id: i32) -> bool {
        let village_region_id = self
            .game
            .village_war_sys()
            .get_village_region_id_by_time(self.war_number);
        let owner = self
            .game
            .find_region(village_region_id)
            .map(|region| region.base().owned_city_faction())
            .or_else(|| {
                self.game
                    .find_proxy_region(village_region_id)
                    .map(|region| region.owned_city_org().0)
            })
            .unwrap_or(0);
        faction_id != 0 && faction_id == owner
    }

    fn player_has_good(&mut self, player_id: i32, good_name: &str) -> bool {
        let goods_index = self
            .game
            .goods_factory()
            .query_goods_id_by_original_name(Some(good_name.as_bytes()));
        self.game
            .find_player(player_id)
            .is_some_and(|player| player.check_item_in_packet(goods_index) != 0)
    }

    fn set_known_player_contend_state(&mut self, player_id: i32, state: bool) {
        self.set_global_player_contend_state(player_id, state);
    }

    fn notify_player(&mut self, player_id: i32, string_id: &'static str) {
        let message = colored_player_notice_message(
            0xffff_ffff,
            0xffff_0000,
            self.game.get_string_by_id(string_id.as_bytes()),
        );
        let delivery = message.send_to_player(self.game.net_server(), player_id);
        tracing::trace!(
            player_id,
            string_id,
            delivery,
            "отправлено уведомление захвата деревенского символа"
        );
    }

    fn register_needed_good(&mut self, good_name: &str) {
        if good_name.is_empty() {
            return;
        }
        self.needed_goods.push(good_name.to_owned());
        tracing::trace!(
            good_name,
            "зарегистрирован необходимый предмет деревенской войны"
        );
    }

    fn send_first_faction_contender_notice(
        &mut self,
        country: u8,
        faction_name: &str,
        symbol_name: &str,
    ) {
        let country_name = self
            .game
            .globe_setup
            .country_name(country)
            .unwrap_or_default();
        let text = format_legacy_text_fields(
            self.game.get_string_by_id(b"GS0246"),
            &[
                country_name,
                faction_name.as_bytes(),
                symbol_name.as_bytes(),
            ],
            0x3ff,
        );
        let delivery = colored_text_message(0xbf806, 0xffff_ffff, 0xffff_0000, &text)
            .send_to_region(Some(&self.region), None, self.game);
        tracing::trace!(
            country,
            faction_name,
            symbol_name,
            delivery,
            "отправлено уведомление о первом претенденте на деревенский символ"
        );
    }
}

