/// Concrete Script/region/AI/session owners подключаются сюда по мере их
/// материализации; message routing уже исполняется самим `CGame`, а region
/// decoder получает тот же live factory-контекст без отдельного shadow state.
pub(crate) trait GameMainLoopRuntime:
    InitialRegionStartupContext
    + GameRegionEnterContext
    + GamePlayerLoginContext
    + GameOrganizingWarRuntime
    + GameCountryWarRuntime
    + GameContainerMessageRuntime
    + GameGoodsMessageRuntime
    + GameSkillMessageRuntime
    + GameShapeMessageRuntime
    + GamePlayerMessageRuntime
    + NationContendContext
    + GodsBattleNpcContendContext
    + ServerRegionAreaTransitionContext
{
    fn exit_requested(&self) -> bool;
    /// Завершает только пока не материализованный владелец состояния предмета
    /// `CParticularState` с ID `0x186a5` перед `CPlayer::RestoreHpMp`.
    /// Четырьмя автоматическими состояниями HP/MP владеет
    /// `CanonicalStateStorage`.
    fn end_player_particular_states_for_restore(&mut self, game: &mut CGame, player_id: i32);
    /// Исполняет только ещё не материализованные state-классы из
    /// `CMoveShape::UpdateAbnormality` после owned change-body/extended/
    /// appellation/ride owners и до `CPlayer::UpdateCurrentState`.
    fn player_move_shape_unmaterialized_state_ai(&mut self, game: &mut CGame, player_id: i32);
    /// Concrete `CSkill/CBaseAI` execution boundary одного normal FIFO front.
    /// `Pending` оставляет команду для следующего tick; terminal outcome
    /// удаляет только тот же front. `first_contact` является event этого tick.
    fn execute_player_skill_dispatch(
        &mut self,
        game: &mut CGame,
        player_id: i32,
        dispatch: PlayerSkillDispatch,
    ) -> QueuedSkillExecutionOutcome;
    /// Отдельная war-soul очередь исполняется тем же tick независимо от
    /// normal skill queue, как два native `m_qTarget*` owner-а.
    fn execute_battle_fairy_skill_dispatch(
        &mut self,
        game: &mut CGame,
        player_id: i32,
        dispatch: BattleFairySkillDispatch,
    ) -> QueuedSkillExecutionOutcome;
    /// Исполняет оставшийся `CBaseAI::Run` prefix virtual `CPlayerAI::Run`
    /// после owned `UpdateCurrentState` и двух materialized FIFO front.
    /// Возвращает post-AI restored-state current war-soul skill; owned
    /// auto-exp/CheckLevel/energy tails идут сразу после.
    fn player_move_shape_active_state_ai(
        &mut self,
        game: &mut CGame,
        player_id: i32,
        player_ai: &mut CPlayerAI,
    ) -> Option<bool>;
    /// Разрешает state ground goods и прочих external shape owners, которых
    /// нет в player/monster/NPC Rust storage.
    fn external_region_shape_change_state(
        &mut self,
        game: &mut CGame,
        region: &mut CServerRegion,
        identity: ShapeIdentity,
    ) -> Option<i32>;
    fn reset_external_region_shape_change_state(
        &mut self,
        game: &mut CGame,
        region: &mut CServerRegion,
        identity: ShapeIdentity,
    );
    /// Virtual shape `AI` вызывается только для state `CS_NONE`; новое state
    /// исходник увидит на следующем region tick.
    fn run_region_active_shape_ai(
        &mut self,
        game: &mut CGame,
        region: &mut CServerRegion,
        identity: ShapeIdentity,
    );
    fn remove_external_region_shape(
        &mut self,
        game: &mut CGame,
        region: &mut CServerRegion,
        identity: ShapeIdentity,
    ) -> Option<Result<bool, RegionMembershipBlock>>;
}

