    #[allow(clippy::too_many_arguments)]
    pub(crate) fn transfer_player_enhancement_goods<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        shadow_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<EnhancementTransferReport, EnhancementTransferBlock> {
        if !matches!(destination_extend_id, 1 | 2) {
            return Err(EnhancementTransferBlock::UnsupportedDestinationContainer {
                extend_id: destination_extend_id,
            });
        }
        let mut player = self
            .players
            .remove(&player_id)
            .ok_or(EnhancementTransferBlock::MissingPlayer)?;
        let result = self.transfer_player_enhancement_goods_inner(
            &mut player,
            shadow_position,
            goods_id,
            amount,
            destination_extend_id,
            destination_position,
            context,
        );
        self.players.insert(player_id, player);
        result
    }

    /// Замыкает direct `0x90301` ownership transfer в двухъячеечный
    /// `m_cAuctionContainer`. Equipment source проходит тот же полный remove
    /// callback/effect tail, depot source — lock/anchor и World audit `8`.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn move_player_goods_to_auction_listing<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<AuctionListingTransferReport, AuctionListingTransferBlock> {
        if !matches!(source_extend_id, 1 | 2 | 9 | 11 | 12 | 14 | 17) {
            return Err(AuctionListingTransferBlock::UnsupportedSourceContainer {
                extend_id: source_extend_id,
            });
        }
        if source_extend_id == 12 && BattleFairyCell::from_position(source_position).is_none() {
            return Err(AuctionListingTransferBlock::InvalidBattleFairyCell {
                position: source_position,
            });
        }
        let depot_audit = (source_extend_id == 9 && self.log_system.goods_depot_get_log_enabled())
            .then(|| {
                self.find_player(player_id)
                    .and_then(|player| player.depot().get_goods(source_position))
                    .map(|goods| (goods.price(), goods.name().to_vec()))
            })
            .flatten();
        let mut player = self
            .players
            .remove(&player_id)
            .ok_or(AuctionListingTransferBlock::MissingSourceGoods)?;
        let result = self.move_player_goods_to_auction_listing_inner(
            &mut player,
            source_extend_id,
            source_position,
            goods_id,
            amount,
            destination_position,
            context,
        );
        self.players.insert(player_id, player);
        if let Ok(report) = &result
            && let Some((price, name)) = depot_audit
        {
            let _ =
                self.send_ground_goods_move_log(player_id, 8, report.goods, price, &name, amount);
        }
        result
    }

    #[allow(clippy::too_many_arguments)]
    fn move_player_goods_to_auction_listing_inner<Context: GameContainerMessageRuntime>(
        &self,
        player: &mut CPlayer,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<AuctionListingTransferReport, AuctionListingTransferBlock> {
        if destination_position >= 2
            || !player
                .auction_listing()
                .is_space_enough(destination_position)
        {
            return Err(AuctionListingTransferBlock::InvalidDestinationPosition {
                position: destination_position,
            });
        }
        let goods = match source_extend_id {
            1 => player.packet().get_goods(source_position),
            2 => player.equipment().get_goods(source_position),
            9 => player.depot().get_goods(source_position),
            11 => player.fairy_container().base().get_goods(source_position),
            12 => player
                .battle_fairy_container()
                .base()
                .get_goods(source_position),
            17 => player.ci_qing_compose_goods(source_position),
            14 => player.auction_goods().get_goods(source_position),
            _ => unreachable!("source extend проверен выше"),
        }
        .filter(|goods| goods.identity().ex_id == goods_id && goods.amount() == amount)
        .ok_or(AuctionListingTransferBlock::MissingSourceGoods)?;
        if matches!(
            goods.base_properties_index(),
            index if index == self.goods_factory.get_gold_coin_index()
                || index == self.goods_factory.get_yuan_bao_index()
        ) {
            return Err(AuctionListingTransferBlock::InvalidCurrency);
        }
        if self
            .goods_factory
            .query_goods_base_properties(goods.base_properties_index())
            .is_none()
        {
            return Err(AuctionListingTransferBlock::MissingBaseProperties);
        }
        if destination_position == 0
            && !CPlayer::auction_listing_goods_allowed(goods, &self.goods_factory)
        {
            return Err(AuctionListingTransferBlock::AuctionLimitRejected);
        }
        let goods_identity = goods.identity();
        let slot_zero_was_empty = player.auction_listing().get_goods(0).is_none();
        let pack_add_enabled = self.globe_setup.pack_add_enabled();

        let (removal, mut incoming) = match source_extend_id {
            1 => {
                let removed = player
                    .packet_mut()
                    .remove_goods(goods_id)
                    .ok_or(AuctionListingTransferBlock::PacketRemovalFailed)?;
                let removed = match removed {
                    VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Removed(removed)) => {
                        removed
                    }
                    _ => return Err(AuctionListingTransferBlock::PacketRemovalFailed),
                };
                let crate::gameserver::appserver::container::camountlimitgoodscontainer::AmountLimitGoodsRemoved {
                    owner_type,
                    owner_id,
                    position,
                    amount,
                    listeners,
                    goods,
                } = removed;
                (
                    AuctionListingTransferRemoval::Packet {
                        owner_type,
                        owner_id,
                        position: position.unwrap_or(source_position),
                        amount,
                        listeners,
                    },
                    Some(goods),
                )
            }
            14 => {
                let removed = player
                    .auction_goods_mut()
                    .remove_goods(goods_id)
                    .ok_or(AuctionListingTransferBlock::AuctionGoodsRemovalFailed)?;
                let removed = match removed {
                    VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Removed(removed))
                    | VolumeGoodsRemoveOutcome::RemovedButCellMissing(
                        AmountLimitGoodsTaken::Removed(removed),
                    ) => removed,
                    _ => return Err(AuctionListingTransferBlock::AuctionGoodsRemovalFailed),
                };
                let crate::gameserver::appserver::container::camountlimitgoodscontainer::AmountLimitGoodsRemoved {
                    owner_type,
                    owner_id,
                    position,
                    amount,
                    listeners,
                    goods,
                } = removed;
                (
                    AuctionListingTransferRemoval::AuctionGoods {
                        owner_type,
                        owner_id,
                        position: position.unwrap_or(source_position),
                        amount,
                        listeners,
                    },
                    Some(goods),
                )
            }
            9 => {
                let removed = player.depot_mut().take_goods(
                    source_position,
                    amount,
                    &self.goods_factory,
                    |_| None,
                );
                let Some(VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Removed(
                    removed,
                ))) = removed
                else {
                    return Err(AuctionListingTransferBlock::DepotRemovalFailed);
                };
                let removal = DepotStorageRemoval {
                    owner_type: removed.owner_type,
                    owner_id: removed.owner_id,
                    position: removed.position.unwrap_or(source_position),
                    amount: removed.amount,
                    listeners: removed.listeners,
                    kind: DepotStorageRemovalKind::Removed,
                };
                (
                    AuctionListingTransferRemoval::Depot(removal),
                    Some(removed.goods),
                )
            }
            11 => {
                let mut split_template = goods.clone();
                split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
                let outcome = player.fairy_container_mut().take(
                    source_position,
                    amount,
                    &self.goods_factory,
                    |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    },
                );
                let taken = match outcome {
                    FairyContainerRemoveOutcome::Removed(VolumeGoodsRemoveOutcome::Removed(
                        taken,
                    )) => taken,
                    failed => {
                        return Err(AuctionListingTransferBlock::FairyRemovalFailed(failed));
                    }
                };
                let (goods, removal) = match taken {
                    AmountLimitGoodsTaken::Removed(removed) => (
                        removed.goods,
                        FairyStorageRemoval {
                            owner_type: removed.owner_type,
                            owner_id: removed.owner_id,
                            position: removed.position.unwrap_or(source_position),
                            amount: removed.amount,
                            listeners: removed.listeners,
                        },
                    ),
                    AmountLimitGoodsTaken::Split(split) => (
                        split.goods,
                        FairyStorageRemoval {
                            owner_type: split.owner_type,
                            owner_id: split.owner_id,
                            position: split.position.unwrap_or(source_position),
                            amount: split.amount,
                            listeners: split.listeners,
                        },
                    ),
                };
                (AuctionListingTransferRemoval::Fairy(removal), Some(goods))
            }
            12 => {
                let cell = BattleFairyCell::from_position(source_position)
                    .expect("battle-fairy source position проверена");
                let coefficients = self.globe_setup.player_property_coefficients();
                let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
                let mut report = player.take_battle_fairy_goods(
                    cell,
                    amount,
                    &self.goods_factory,
                    coefficients,
                    |_| None,
                    &mut encode,
                );
                drop(encode);
                self.deliver_battle_fairy_equipment_effects_for_player(Some(player), &mut report);
                let outcome = std::mem::replace(
                    &mut report.outcome,
                    BattleFairyEquipmentMutationOutcome::MissingGoods,
                );
                let BattleFairyEquipmentMutationOutcome::Removed(
                    VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Removed(removed)),
                ) = outcome
                else {
                    report.outcome = outcome;
                    return Err(AuctionListingTransferBlock::BattleFairyRemovalFailed(
                        report,
                    ));
                };
                let storage = BattleFairyStorageRemoval {
                    owner_type: removed.owner_type,
                    owner_id: removed.owner_id,
                    position: removed.position.unwrap_or(source_position),
                    amount: removed.amount,
                    listeners: removed.listeners,
                    cell,
                    property_applied: report.property_applied,
                };
                (
                    AuctionListingTransferRemoval::BattleFairy(storage),
                    Some(removed.goods),
                )
            }
            17 => {
                let removed = player.take_ci_qing_compose_transfer_goods(
                    source_position,
                    amount,
                    &self.goods_factory,
                    |_| None,
                );
                let Some(VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Removed(
                    removed,
                ))) = removed
                else {
                    return Err(AuctionListingTransferBlock::ComposeRemovalFailed);
                };
                let storage = CiQingComposeStorageRemoval {
                    owner_type: removed.owner_type,
                    owner_id: removed.owner_id,
                    position: removed.position.unwrap_or(source_position),
                    amount: removed.amount,
                    listeners: removed.listeners,
                };
                (
                    AuctionListingTransferRemoval::Compose(storage),
                    Some(removed.goods),
                )
            }
            2 => {
                let remove_facts =
                    context.enhancement_equipment_remove_facts(player, goods, pack_add_enabled);
                let mut recompute =
                    |player: &CPlayer| context.recompute_enhancement_player_properties(player);
                let mut report = player.remove_equipment_goods(
                    goods_id,
                    &self.goods_factory,
                    &self.skill_factory,
                    remove_facts,
                    &mut recompute,
                );
                drop(recompute);
                self.publish_player_equipment_remove_report(&mut report);
                let outcome = std::mem::replace(
                    &mut report.outcome,
                    EquipmentRemoveOutcome::Missing {
                        partial_effects: Default::default(),
                    },
                );
                let removed = match outcome {
                    EquipmentRemoveOutcome::Removed(removed) => removed,
                    outcome => {
                        report.outcome = outcome;
                        return Err(AuctionListingTransferBlock::EquipmentRemovalFailed(report));
                    }
                };
                (
                    AuctionListingTransferRemoval::Equipment {
                        event: removed.event,
                    },
                    Some(removed.goods),
                )
            }
            _ => unreachable!("source extend проверен выше"),
        };
        let owner_progress_allows = player.current_progress() == PlayerProgress::None;
        let destination = player.auction_listing_mut().add_goods_at(
            destination_position,
            &mut incoming,
            &self.goods_factory,
            owner_progress_allows,
        );
        assert!(
            incoming.is_none() && matches!(destination, VolumeGoodsAddOutcome::Added(_)),
            "предварительно проверенный пустой auction listing slot обязан принять goods"
        );
        let previous_last_operated =
            player.record_last_operated_goods(source_extend_id, source_position);
        Ok(AuctionListingTransferReport {
            goods: goods_identity,
            removal,
            destination,
            listing_slot_zero_was_empty: slot_zero_was_empty,
            previous_last_operated,
        })
    }

    /// Замыкает обратный direct `0x90301` из `m_cAuctionContainer` в
    /// packet/equipment/depot. Общий Move проверяет burden carried destination
    /// до source removal; blocked destination возвращает предмет в исходную
    /// listing-ячейку, depot success публикует World audit `7`.
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn withdraw_player_auction_listing_goods<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<AuctionListingWithdrawalReport, AuctionListingWithdrawalBlock> {
        if !matches!(destination_extend_id, 1 | 2 | 9 | 11 | 12 | 17) {
            return Err(
                AuctionListingWithdrawalBlock::UnsupportedDestinationContainer {
                    extend_id: destination_extend_id,
                },
            );
        }
        if destination_extend_id == 12
            && destination_position != u32::MAX
            && BattleFairyCell::from_position(destination_position).is_none()
        {
            return Err(AuctionListingWithdrawalBlock::InvalidBattleFairyCell {
                position: destination_position,
            });
        }
        let depot_audit = (destination_extend_id == 9
            && self.log_system.goods_depot_set_log_enabled())
        .then(|| {
            self.find_player(player_id)
                .and_then(|player| player.auction_listing().get_goods(source_position))
                .map(|goods| (goods.price(), goods.name().to_vec()))
        })
        .flatten();
        let mut player = self
            .players
            .remove(&player_id)
            .ok_or(AuctionListingWithdrawalBlock::MissingSourceGoods)?;
        let result = self.withdraw_player_auction_listing_goods_inner(
            &mut player,
            source_position,
            goods_id,
            amount,
            destination_extend_id,
            destination_position,
            context,
        );
        self.players.insert(player_id, player);
        if let Ok(report) = &result
            && matches!(
                report.outcome,
                AuctionListingWithdrawalOutcome::Moved { .. }
            )
            && let Some((price, name)) = depot_audit
        {
            let _ =
                self.send_ground_goods_move_log(player_id, 7, report.goods, price, &name, amount);
        }
        result
    }

    #[allow(clippy::too_many_arguments)]
    fn withdraw_player_auction_listing_goods_inner<Context: GameContainerMessageRuntime>(
        &self,
        player: &mut CPlayer,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<AuctionListingWithdrawalReport, AuctionListingWithdrawalBlock> {
        let goods = player
            .auction_listing()
            .get_goods(source_position)
            .filter(|goods| goods.identity().ex_id == goods_id && goods.amount() == amount)
            .ok_or(AuctionListingWithdrawalBlock::MissingSourceGoods)?;
        let goods_identity = goods.identity();
        if matches!(destination_extend_id, 1 | 2)
            && player
                .current_burden(&self.goods_factory)
                .wrapping_add(goods.weight(&self.goods_factory))
                > u32::from(player.combat_properties().burden)
        {
            return Err(AuctionListingWithdrawalBlock::BurdenExceeded);
        }

        let removed = player
            .auction_listing_mut()
            .remove_goods(goods_id)
            .ok_or(AuctionListingWithdrawalBlock::RemovalFailed)?;
        let removed = match removed {
            VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Removed(removed)) => removed,
            VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Split(_))
            | VolumeGoodsRemoveOutcome::RemovedButCellMissing(_) => {
                return Err(AuctionListingWithdrawalBlock::RemovalFailed);
            }
        };
        let removal = AuctionListingWithdrawalRemoval {
            owner_type: removed.owner_type,
            owner_id: removed.owner_id,
            position: removed.position.unwrap_or(source_position),
            amount: removed.amount,
            listeners: removed.listeners,
        };
        let mut incoming = Some(removed.goods);
        let addition = self.add_ci_qing_compose_transfer_goods(
            player,
            destination_extend_id,
            destination_position,
            &mut incoming,
            context,
        );
        let outcome = if incoming.is_none() {
            let (destination_position, destination_goods, amount) =
                Self::ci_qing_compose_transfer_destination(player, destination_position, &addition);
            AuctionListingWithdrawalOutcome::Moved {
                addition,
                destination_position,
                destination_goods,
                amount,
            }
        } else {
            let rejected = addition;
            let owner_progress_allows = player.current_progress() == PlayerProgress::None;
            let rollback = player.auction_listing_mut().add_goods_at(
                source_position,
                &mut incoming,
                &self.goods_factory,
                owner_progress_allows,
            );
            if incoming.is_none() {
                AuctionListingWithdrawalOutcome::RolledBack {
                    rejected,
                    restored: rollback,
                }
            } else {
                let goods = incoming
                    .take()
                    .expect("неуспешный auction-listing rollback сохраняет detached goods");
                let notification_delivery = send_enhancement_goods_collected(
                    self,
                    player.player_id(),
                    goods.name(),
                    goods.amount(),
                );
                AuctionListingWithdrawalOutcome::GoodsCollected {
                    rejected,
                    rollback,
                    goods: goods.identity(),
                    notification_delivery,
                }
            }
        };
        let previous_last_operated =
            matches!(&outcome, AuctionListingWithdrawalOutcome::Moved { .. })
                .then(|| player.record_last_operated_goods(13, source_position));
        Ok(AuctionListingWithdrawalReport {
            goods: goods_identity,
            removal,
            outcome,
            previous_last_operated,
        })
    }

    fn send_ground_goods_move_log(
        &self,
        player_id: i32,
        reason: u8,
        goods: ShapeIdentity,
        price: u32,
        name: &[u8],
        amount: u32,
    ) {
        let Some(player) = self.find_player(player_id) else {
            tracing::trace!(player_id, reason, "игрок для журнала перемещения предмета не найден");
            return;
        };
        let mut audit = CMessage::new(0x0006_0202);
        audit.add_byte(reason);
        audit.add_long(player_id);
        audit.base_mut().add_short(player.pk_count() as i16);
        audit.add_ulong(player.money());
        audit.add_ulong(player.depot_money());
        audit.base_mut().add_guid(goods.ex_id);
        audit.add_ulong(price);
        add_legacy_c_string(audit.base_mut(), name);
        audit.add_ulong(amount);
        audit.add_long(player.server_region_id().unwrap_or_default());
        audit.add_ulong(player.shape().get_tile_x().unwrap_or_default() as u32);
        audit.add_ulong(player.shape().get_tile_y().unwrap_or_default() as u32);
        audit.add_ulong(player.client_ip());
        let delivery = audit.send(self, false);
        tracing::trace!(player_id, reason, ?delivery, "журнал перемещения предмета отправлен");
    }

    pub(crate) fn transfer_player_bank_currency(
        &mut self,
        player_id: i32,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
    ) -> Result<(), BankCurrencyTransferBlock> {
        if !matches!(
            (source_extend_id, destination_extend_id),
            (4, 8) | (8, 4) | (15, 4)
        ) {
            return Err(BankCurrencyTransferBlock::UnsupportedRoute);
        }
        if source_position != 0 || destination_position != 0 {
            return Err(BankCurrencyTransferBlock::InvalidPosition);
        }
        let source = self
            .find_player(player_id)
            .ok_or(BankCurrencyTransferBlock::MissingPlayer)?
            .bank_transfer_currency_goods(source_extend_id)
            .ok_or(BankCurrencyTransferBlock::MissingGoods)?;
        if source.identity().ex_id != goods_id {
            return Err(BankCurrencyTransferBlock::MissingGoods);
        }
        if amount == 0 || source.amount() < amount {
            return Err(BankCurrencyTransferBlock::AmountMismatch);
        }
        if source_extend_id == 15 {
            let capacity = self
                .find_player(player_id)
                .expect("auction player проверен до capacity gate")
                .auction_money_move_capacity(&self.goods_factory);
            if !capacity.allowed {
                return Err(
                    BankCurrencyTransferBlock::AuctionCapacityRejectedBeforeRemoval {
                        wallet_amount: capacity.wallet_amount,
                        auction_amount: capacity.auction_amount,
                        maximum: capacity.maximum,
                    },
                );
            }
        }
        let audit_name = source.name().to_vec();
        let mut split_template = source.clone();
        split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));

        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен непосредственно перед bank currency removal");
        let removal = match player.take_bank_transfer_currency_goods(
            source_extend_id,
            amount,
            &self.goods_factory,
            |_| {
                (split_template.identity().ex_id != CGuid::GUID_INVALID)
                    .then(|| split_template.clone())
            },
        ) {
            Some(removal) => removal,
            None => {
                self.players.insert(player_id, player);
                return Err(BankCurrencyTransferBlock::RemovalFailed);
            }
        };
        let (detached, removal) = match removal {
            CurrencyGoodsTaken::Removed(removed) => {
                let source = removed.goods.identity();
                (
                    removed.goods,
                    BankCurrencyRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position,
                        source,
                        amount: removed.amount,
                        listeners: removed.listeners,
                        split: false,
                    },
                )
            }
            CurrencyGoodsTaken::Split(split) => (
                split.goods,
                BankCurrencyRemoval {
                    owner_type: split.owner_type,
                    owner_id: split.owner_id,
                    position: split.position,
                    source: split.source,
                    amount: split.amount,
                    listeners: split.listeners,
                    split: true,
                },
            ),
        };
        let mut incoming = Some(detached);
        if source_extend_id == 15 {
            let capacity = player.auction_money_move_capacity(&self.goods_factory);
            if !capacity.allowed {
                let rollback = player.add_bank_transfer_currency_goods(
                    source_extend_id,
                    &mut incoming,
                    &self.goods_factory,
                );
                self.players.insert(player_id, player);
                if let Some(goods) = incoming {
                    return Err(BankCurrencyTransferBlock::AuctionCapacityRollbackFailed {
                        goods,
                        wallet_amount: capacity.wallet_amount,
                        auction_amount: capacity.auction_amount,
                        maximum: capacity.maximum,
                        removal,
                        rollback,
                    });
                }
                return Err(
                    BankCurrencyTransferBlock::AuctionCapacityRejectedAfterRemoval {
                        wallet_amount: capacity.wallet_amount,
                        auction_amount: capacity.auction_amount,
                        maximum: capacity.maximum,
                        removal,
                        rollback: rollback.expect("auction wallet rollback extend проверен"),
                    },
                );
            }
        }
        let addition = player
            .add_bank_transfer_currency_goods(
                destination_extend_id,
                &mut incoming,
                &self.goods_factory,
            )
            .expect("bank transfer destination extend проверен");
        if let Some(detached) = incoming {
            let rejected = addition;
            let mut rollback_incoming = Some(detached);
            let rollback = player.add_bank_transfer_currency_goods(
                source_extend_id,
                &mut rollback_incoming,
                &self.goods_factory,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = rollback_incoming {
                return Err(BankCurrencyTransferBlock::RollbackFailed {
                    goods,
                    removal,
                    rejected,
                    rollback,
                });
            }
            return Err(BankCurrencyTransferBlock::RollbackCompleted {
                removal,
                rejected,
                rollback: rollback.expect("bank rollback extend проверен"),
            });
        }

        debug_assert!(matches!(
            &addition,
            PlayerBankCurrencyAddOutcome::Wallet(CurrencyGoodsAddOutcome::Added(_))
                | PlayerBankCurrencyAddOutcome::Wallet(CurrencyGoodsAddOutcome::Stack(
                    GoodsStackMergeOutcome::Merged { .. }
                ))
                | PlayerBankCurrencyAddOutcome::Bank(BankGoodsAddOutcome::Wallet(
                    CurrencyGoodsAddOutcome::Added(_)
                ))
                | PlayerBankCurrencyAddOutcome::Bank(BankGoodsAddOutcome::Wallet(
                    CurrencyGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged { .. })
                ))
        ));
        let (destination_identity, destination_amount) = player
            .bank_transfer_currency_goods(destination_extend_id)
            .map(|destination| (destination.identity(), destination.amount()))
            .expect("успешный bank currency add сохраняет destination goods");
        let previous_last_operated =
            player.record_last_operated_goods(source_extend_id, source_position);
        self.players.insert(player_id, player);

        if (destination_extend_id == 8
            && self.log_system.goods_bank_set_log_enabled())
            || (source_extend_id == 8 && self.log_system.goods_bank_get_log_enabled())
        {
            self.send_ground_goods_move_log(
                player_id,
                if destination_extend_id == 8 { 9 } else { 10 },
                removal.source,
                amount,
                &audit_name,
                amount,
            );
        }

        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(PLAYER_TYPE, player_id, source_position);
        moved.set_source_container_extend_id(source_extend_id);
        moved.set_destination_container(PLAYER_TYPE, player_id, destination_position);
        moved.set_destination_container_extend_id(destination_extend_id);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, destination_identity.ex_id);
        moved.set_destination_object_amount(destination_amount);
        let delivery = moved.send_to_player(self, player_id);
        tracing::trace!(
            player_id,
            ?destination_identity,
            amount,
            source_extend_id,
            destination_extend_id,
            ?removal,
            ?addition,
            ?previous_last_operated,
            delivery,
            "перевод валюты банка выполнен"
        );
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn transfer_player_depot_goods<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<(), DepotStorageTransferBlock> {
        let route_supported = matches!(
            (source_extend_id, destination_extend_id),
            (1, 2) | (2, 1) | (1, 9) | (2, 9) | (9, 1) | (9, 2)
        );
        if !route_supported {
            return Err(DepotStorageTransferBlock::UnsupportedRoute);
        }
        let player = self
            .find_player(player_id)
            .ok_or(DepotStorageTransferBlock::MissingPlayer)?;
        let source = match source_extend_id {
            1 => player.packet().get_goods(source_position),
            2 => player.equipment().get_goods(source_position),
            9 => player.depot().get_goods(source_position),
            _ => None,
        }
        .filter(|goods| goods.identity().ex_id == goods_id)
        .ok_or(DepotStorageTransferBlock::MissingGoods)?;
        if amount == 0
            || source.amount() < amount
            || source_extend_id == 2 && source.amount() != amount
        {
            return Err(DepotStorageTransferBlock::AmountMismatch);
        }
        if source.amount() != amount
            && matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            )
        {
            return Err(DepotStorageTransferBlock::PartialMoveBusy(
                player.current_progress(),
            ));
        }
        let mut burden_goods = source.clone();
        burden_goods.set_amount(amount);
        let current_burden = player.current_burden(&self.goods_factory);
        let burden_exceeded = matches!(destination_extend_id, 1 | 2)
            && if source_extend_id == 9 {
                current_burden.wrapping_add(burden_goods.weight(&self.goods_factory))
                    > u32::from(player.combat_properties().burden)
            } else {
                // Exact Move проверяет burden после source GetGoods: для
                // packet↔equipment detached weight возвращает прежний итог.
                current_burden > u32::from(player.combat_properties().burden)
            };
        let source_identity = source.identity();
        let audit_name = source.name().to_vec();
        let audit_price = source.price();
        let mut split_template = source.clone();
        split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));

        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен перед depot ownership pass");
        let (removal, mut incoming) = if source_extend_id == 1 {
            let removed = player.packet_mut().take_goods(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(DepotStorageTransferBlock::PacketRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    EnhancementTransferRemoval::Packet {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    EnhancementTransferRemoval::Packet {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                    },
                ),
            };
            (DepotStorageTransferRemoval::Player(removal), Some(goods))
        } else if source_extend_id == 2 {
            let goods = player
                .equipment()
                .get_goods(source_position)
                .expect("equipment source проверен до player removal");
            let facts = context.enhancement_equipment_remove_facts(
                &player,
                goods,
                self.globe_setup.pack_add_enabled(),
            );
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut report = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut report);
            let outcome = std::mem::replace(
                &mut report.outcome,
                EquipmentRemoveOutcome::Missing {
                    partial_effects: Default::default(),
                },
            );
            let EquipmentRemoveOutcome::Removed(removed) = outcome else {
                report.outcome = outcome;
                self.players.insert(player_id, player);
                return Err(DepotStorageTransferBlock::EquipmentRemovalFailed(report));
            };
            (
                DepotStorageTransferRemoval::Player(EnhancementTransferRemoval::Equipment {
                    event: removed.event,
                }),
                Some(removed.goods),
            )
        } else {
            let removed =
                player
                    .depot_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(DepotStorageTransferBlock::DepotRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    DepotStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: DepotStorageRemovalKind::Removed,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    DepotStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: DepotStorageRemovalKind::Split {
                            source: split.source,
                        },
                    },
                ),
            };
            (DepotStorageTransferRemoval::Depot(removal), Some(goods))
        };

        if burden_exceeded {
            let rollback = self.add_depot_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(DepotStorageTransferBlock::BurdenRollbackFailed {
                    goods,
                    removal,
                    rollback,
                });
            }
            return Err(DepotStorageTransferBlock::BurdenRollbackCompleted {
                removal,
                restored: rollback,
            });
        }

        let addition = self.add_depot_transfer_goods(
            &mut player,
            destination_extend_id,
            destination_position,
            &mut incoming,
            context,
        );
        if incoming.is_some() {
            let rejected = addition;
            let rollback = self.add_depot_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(DepotStorageTransferBlock::RollbackFailed {
                    goods,
                    removal,
                    rejected,
                    rollback,
                });
            }
            return Err(DepotStorageTransferBlock::RolledBack {
                removal,
                rejected,
                restored: rollback,
            });
        }

        let (actual_destination_position, destination_goods, destination_amount) = match &addition {
            DepotStorageTransferAddition::Player(EnhancementTransferAddition::Packet(outcome)) => {
                match outcome {
                    VolumeGoodsAddOutcome::Added(added) => {
                        let position = added.position.unwrap_or(destination_position);
                        let goods = player
                            .packet()
                            .get_goods(position)
                            .expect("packet add сохранён");
                        (position, goods.identity(), goods.amount())
                    }
                    VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                        target, ..
                    }) => {
                        let position = player
                            .packet()
                            .query_goods_position(target.ex_id)
                            .expect("packet stack position");
                        let goods = player
                            .packet()
                            .get_goods(position)
                            .expect("packet stack сохранён");
                        (position, goods.identity(), goods.amount())
                    }
                    _ => unreachable!("успешный packet add забрал incoming"),
                }
            }
            DepotStorageTransferAddition::Player(EnhancementTransferAddition::Equipment(
                report,
            )) => {
                let EquipmentAddOutcome::Added(added) = &report.outcome else {
                    unreachable!("успешный equipment add")
                };
                (added.column.position(), added.identity, added.amount)
            }
            DepotStorageTransferAddition::Depot(DepotGoodsAddOutcome::Volume(outcome)) => {
                match outcome {
                    VolumeGoodsAddOutcome::Added(added) => (
                        added.position.unwrap_or(destination_position),
                        added.identity,
                        added.amount,
                    ),
                    VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                        target, ..
                    }) => {
                        let position = player
                            .depot()
                            .base()
                            .query_goods_position(target.ex_id)
                            .expect("depot stack position");
                        let goods = player
                            .depot()
                            .get_goods(position)
                            .expect("depot stack сохранён");
                        (position, goods.identity(), goods.amount())
                    }
                    _ => unreachable!("успешный depot add забрал incoming"),
                }
            }
            _ => unreachable!("успешный depot transfer addition"),
        };
        let previous_last_operated =
            player.record_last_operated_goods(source_extend_id, source_position);
        self.players.insert(player_id, player);
        if destination_extend_id == 9
            && self.log_system.goods_depot_set_log_enabled()
            || source_extend_id == 9 && self.log_system.goods_depot_get_log_enabled()
        {
            self.send_ground_goods_move_log(
                player_id,
                if destination_extend_id == 9 { 7 } else { 8 },
                source_identity,
                audit_price,
                &audit_name,
                amount,
            );
        }
        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(PLAYER_TYPE, player_id, source_position);
        moved.set_source_container_extend_id(source_extend_id);
        moved.set_destination_container(PLAYER_TYPE, player_id, actual_destination_position);
        moved.set_destination_container_extend_id(destination_extend_id);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, destination_goods.ex_id);
        moved.set_destination_object_amount(destination_amount);
        let delivery = moved.send_to_player(self, player_id);
        tracing::trace!(
            player_id,
            ?source_identity,
            amount,
            source_extend_id,
            source_position,
            destination_extend_id,
            destination_position = actual_destination_position,
            ?removal,
            ?addition,
            ?previous_last_operated,
            delivery,
            "перемещение между хранилищами выполнено"
        );
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn move_player_goods_to_hand<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        context: &mut Context,
    ) -> Result<(), PlayerHandMoveBlock> {
        if !matches!(source_extend_id, 1 | 2 | 9) {
            return Err(PlayerHandMoveBlock::UnsupportedSource);
        }
        let player = self
            .find_player(player_id)
            .ok_or(PlayerHandMoveBlock::MissingPlayer)?;
        let source = match source_extend_id {
            1 => player.packet().get_goods(source_position),
            2 => player.equipment().get_goods(source_position),
            9 => player.depot().get_goods(source_position),
            _ => None,
        }
        .filter(|goods| goods.identity().ex_id == goods_id)
        .ok_or(PlayerHandMoveBlock::MissingGoods)?;
        if amount == 0
            || source.amount() < amount
            || source_extend_id == 2 && source.amount() != amount
        {
            return Err(PlayerHandMoveBlock::AmountMismatch);
        }
        if source.amount() != amount
            && matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            )
        {
            return Err(PlayerHandMoveBlock::PartialMoveBusy(
                player.current_progress(),
            ));
        }
        let source_identity = source.identity();
        let audit_name = source.name().to_vec();
        let audit_price = source.price();
        let mut split_template = source.clone();
        split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен перед player→hand ownership pass");
        let (removal, mut incoming) = if source_extend_id == 1 {
            let removed = player.packet_mut().take_goods(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(PlayerHandMoveBlock::PacketRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    EnhancementTransferRemoval::Packet {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    EnhancementTransferRemoval::Packet {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                    },
                ),
            };
            (PlayerHandMoveRemoval::Player(removal), Some(goods))
        } else if source_extend_id == 2 {
            let goods = player
                .equipment()
                .get_goods(source_position)
                .expect("equipment source проверен до remove");
            let facts = context.enhancement_equipment_remove_facts(
                &player,
                goods,
                self.globe_setup.pack_add_enabled(),
            );
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut report = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut report);
            let outcome = std::mem::replace(
                &mut report.outcome,
                EquipmentRemoveOutcome::Missing {
                    partial_effects: Default::default(),
                },
            );
            let EquipmentRemoveOutcome::Removed(removed) = outcome else {
                report.outcome = outcome;
                self.players.insert(player_id, player);
                return Err(PlayerHandMoveBlock::EquipmentRemovalFailed(report));
            };
            (
                PlayerHandMoveRemoval::Player(EnhancementTransferRemoval::Equipment {
                    event: removed.event,
                }),
                Some(removed.goods),
            )
        } else {
            let removed =
                player
                    .depot_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(PlayerHandMoveBlock::DepotRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    DepotStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: DepotStorageRemovalKind::Removed,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    DepotStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: DepotStorageRemovalKind::Split {
                            source: split.source,
                        },
                    },
                ),
            };
            (PlayerHandMoveRemoval::Depot(removal), Some(goods))
        };

        let addition = self.add_ground_hand_goods(&mut player, 0, &mut incoming);
        if incoming.is_some() {
            let rejected = addition;
            let rollback = self.add_depot_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(PlayerHandMoveBlock::RollbackFailed {
                    goods,
                    removal,
                    rejected,
                    rollback,
                });
            }
            return Err(PlayerHandMoveBlock::RolledBack {
                removal,
                rejected,
                restored: rollback,
            });
        }

        let hand_goods = player.hand().get_goods(0).expect("hand Put сохранён");
        let destination_identity = hand_goods.identity();
        let destination_amount = hand_goods.amount();
        let previous_last_operated =
            player.record_last_operated_goods(source_extend_id, source_position);
        self.players.insert(player_id, player);
        if source_extend_id == 9 && self.log_system.goods_depot_get_log_enabled() {
                self.send_ground_goods_move_log(
                    player_id,
                    8,
                    source_identity,
                    audit_price,
                    &audit_name,
                    amount,
                );
        }
        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(PLAYER_TYPE, player_id, source_position);
        moved.set_source_container_extend_id(source_extend_id);
        moved.set_destination_container(PLAYER_TYPE, player_id, 0);
        moved.set_destination_container_extend_id(3);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, destination_identity.ex_id);
        moved.set_destination_object_amount(destination_amount);
        let delivery = moved.send_to_player(self, player_id);
        tracing::trace!(
            player_id,
            ?source_identity,
            amount,
            source_extend_id,
            source_position,
            ?removal,
            ?addition,
            ?previous_last_operated,
            delivery,
            "предмет перемещён в руку"
        );
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn transfer_player_fairy_goods<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<(), FairyStorageTransferBlock> {
        let supported = matches!(source_extend_id, 1 | 2 | 3 | 9) && destination_extend_id == 11
            || source_extend_id == 11 && matches!(destination_extend_id, 1 | 2 | 3 | 9);
        if !supported {
            return Err(FairyStorageTransferBlock::UnsupportedRoute);
        }
        let player = self
            .find_player(player_id)
            .ok_or(FairyStorageTransferBlock::MissingPlayer)?;
        let source = match source_extend_id {
            1 => player.packet().get_goods(source_position),
            2 => player.equipment().get_goods(source_position),
            3 => player.hand().get_goods(source_position),
            9 => player.depot().get_goods(source_position),
            11 => player.fairy_container().base().get_goods(source_position),
            _ => None,
        }
        .filter(|goods| goods.identity().ex_id == goods_id)
        .ok_or(FairyStorageTransferBlock::MissingGoods)?;
        if amount == 0
            || source.amount() < amount
            || source_extend_id == 2 && source.amount() != amount
        {
            return Err(FairyStorageTransferBlock::AmountMismatch);
        }
        if source.amount() != amount
            && matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            )
        {
            return Err(FairyStorageTransferBlock::PartialMoveBusy(
                player.current_progress(),
            ));
        }
        let source_identity = source.identity();
        let audit_name = source.name().to_vec();
        let audit_price = source.price();
        let mut burden_goods = source.clone();
        burden_goods.set_amount(amount);
        let burden_exceeded = source_extend_id == 11
            && matches!(destination_extend_id, 1 | 2 | 3)
            && player
                .current_burden(&self.goods_factory)
                .wrapping_add(burden_goods.weight(&self.goods_factory))
                > u32::from(player.combat_properties().burden);
        let mut split_template = source.clone();
        split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен перед fairy ownership pass");

        let (removal, mut incoming) = if source_extend_id == 1 {
            let removed = player.packet_mut().take_goods(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(FairyStorageTransferBlock::PacketRemovalFailed);
            };
            let (goods, removal) = Self::player_packet_taken(taken, source_position);
            (FairyStorageTransferRemoval::Player(removal), Some(goods))
        } else if source_extend_id == 2 {
            let goods = player
                .equipment()
                .get_goods(source_position)
                .expect("equipment source проверен до remove");
            let facts = context.enhancement_equipment_remove_facts(
                &player,
                goods,
                self.globe_setup.pack_add_enabled(),
            );
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut report = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut report);
            let outcome = std::mem::replace(
                &mut report.outcome,
                EquipmentRemoveOutcome::Missing {
                    partial_effects: Default::default(),
                },
            );
            let EquipmentRemoveOutcome::Removed(removed) = outcome else {
                report.outcome = outcome;
                self.players.insert(player_id, player);
                return Err(FairyStorageTransferBlock::EquipmentRemovalFailed(report));
            };
            (
                FairyStorageTransferRemoval::Player(EnhancementTransferRemoval::Equipment {
                    event: removed.event,
                }),
                Some(removed.goods),
            )
        } else if source_extend_id == 3 {
            let removed =
                player
                    .hand_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(taken) = removed else {
                self.players.insert(player_id, player);
                return Err(FairyStorageTransferBlock::HandRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    GroundHandRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: GroundHandRemovalKind::Removed,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    GroundHandRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: GroundHandRemovalKind::Split {
                            source: split.source,
                        },
                    },
                ),
            };
            (FairyStorageTransferRemoval::Hand(removal), Some(goods))
        } else if source_extend_id == 9 {
            let removed =
                player
                    .depot_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(FairyStorageTransferBlock::DepotRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    DepotStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: DepotStorageRemovalKind::Removed,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    DepotStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: DepotStorageRemovalKind::Split {
                            source: split.source,
                        },
                    },
                ),
            };
            (FairyStorageTransferRemoval::Depot(removal), Some(goods))
        } else {
            let outcome = player.fairy_container_mut().take(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let taken = match outcome {
                FairyContainerRemoveOutcome::Removed(VolumeGoodsRemoveOutcome::Removed(taken)) => {
                    taken
                }
                failed => {
                    self.players.insert(player_id, player);
                    return Err(FairyStorageTransferBlock::FairyRemovalFailed(failed));
                }
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    FairyStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    FairyStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                    },
                ),
            };
            (FairyStorageTransferRemoval::Fairy(removal), Some(goods))
        };

        if burden_exceeded {
            let rollback = self.add_fairy_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(FairyStorageTransferBlock::BurdenRollbackFailed {
                    goods,
                    removal,
                    rollback,
                });
            }
            return Err(FairyStorageTransferBlock::BurdenRolledBack {
                removal,
                restored: rollback,
            });
        }

        let addition = self.add_fairy_transfer_goods(
            &mut player,
            destination_extend_id,
            destination_position,
            &mut incoming,
            context,
        );
        if incoming.is_some() {
            let rejected = addition;
            let rollback = self.add_fairy_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(FairyStorageTransferBlock::RollbackFailed {
                    goods,
                    removal,
                    rejected,
                    rollback,
                });
            }
            return Err(FairyStorageTransferBlock::RolledBack {
                removal,
                rejected,
                restored: rollback,
            });
        }

        let (actual_position, destination_goods, destination_amount) =
            Self::fairy_transfer_destination(&player, destination_position, &addition);
        let previous_last_operated =
            player.record_last_operated_goods(source_extend_id, source_position);
        self.players.insert(player_id, player);
        if destination_extend_id == 9
            && self.log_system.goods_depot_set_log_enabled()
            || source_extend_id == 9 && self.log_system.goods_depot_get_log_enabled()
        {
            self.send_ground_goods_move_log(
                player_id,
                if destination_extend_id == 9 { 7 } else { 8 },
                source_identity,
                audit_price,
                &audit_name,
                amount,
            );
        }
        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(PLAYER_TYPE, player_id, source_position);
        moved.set_source_container_extend_id(source_extend_id);
        moved.set_destination_container(PLAYER_TYPE, player_id, actual_position);
        moved.set_destination_container_extend_id(destination_extend_id);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, destination_goods.ex_id);
        moved.set_destination_object_amount(destination_amount);
        let delivery = moved.send_to_player(self, player_id);
        tracing::trace!(
            player_id,
            ?source_identity,
            amount,
            source_extend_id,
            source_position,
            destination_extend_id,
            destination_position = actual_position,
            ?removal,
            ?addition,
            ?previous_last_operated,
            delivery,
            "перемещение феи выполнено"
        );
        Ok(())
    }

    fn player_packet_taken(
        taken: AmountLimitGoodsTaken,
        source_position: u32,
    ) -> (CGoods, EnhancementTransferRemoval) {
        match taken {
            AmountLimitGoodsTaken::Removed(removed) => (
                removed.goods,
                EnhancementTransferRemoval::Packet {
                    owner_type: removed.owner_type,
                    owner_id: removed.owner_id,
                    position: removed.position.unwrap_or(source_position),
                    amount: removed.amount,
                    listeners: removed.listeners,
                },
            ),
            AmountLimitGoodsTaken::Split(split) => (
                split.goods,
                EnhancementTransferRemoval::Packet {
                    owner_type: split.owner_type,
                    owner_id: split.owner_id,
                    position: split.position.unwrap_or(source_position),
                    amount: split.amount,
                    listeners: split.listeners,
                },
            ),
        }
    }

    fn add_fairy_transfer_goods<Context: GameContainerMessageRuntime>(
        &self,
        player: &mut CPlayer,
        extend_id: i32,
        position: u32,
        incoming: &mut Option<CGoods>,
        context: &mut Context,
    ) -> FairyStorageTransferAddition {
        if extend_id == 11 {
            let owner_progress_allows = !matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            );
            let outcome = if position == u32::MAX {
                player.fairy_container_mut().add(
                    incoming,
                    &self.goods_factory,
                    owner_progress_allows,
                )
            } else {
                player.fairy_container_mut().add_at(
                    position,
                    incoming,
                    &self.goods_factory,
                    owner_progress_allows,
                )
            };
            return FairyStorageTransferAddition::Fairy(outcome);
        }
        if extend_id == 3 {
            return FairyStorageTransferAddition::Hand(
                self.add_ground_hand_goods(player, position, incoming),
            );
        }
        FairyStorageTransferAddition::Player(
            self.add_depot_transfer_goods(player, extend_id, position, incoming, context),
        )
    }

    fn fairy_transfer_destination(
        player: &CPlayer,
        requested_position: u32,
        addition: &FairyStorageTransferAddition,
    ) -> (u32, ShapeIdentity, u32) {
        match addition {
            FairyStorageTransferAddition::Player(addition) => {
                Self::depot_transfer_destination(player, requested_position, addition)
            }
            FairyStorageTransferAddition::Hand(_) => {
                let goods = player.hand().get_goods(0).expect("fairy→hand add сохранён");
                (0, goods.identity(), goods.amount())
            }
            FairyStorageTransferAddition::Fairy(FairyContainerAddOutcome::Base(outcome)) => {
                match outcome {
                    VolumeGoodsAddOutcome::Added(added) => {
                        let position = added.position.unwrap_or(requested_position);
                        let goods = player
                            .fairy_container()
                            .base()
                            .get_goods(position)
                            .expect("fairy add сохранён");
                        (position, goods.identity(), goods.amount())
                    }
                    VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                        target, ..
                    }) => {
                        let position = player
                            .fairy_container()
                            .base()
                            .query_goods_position(target.ex_id)
                            .expect("fairy stack position");
                        let goods = player
                            .fairy_container()
                            .base()
                            .get_goods(position)
                            .expect("fairy stack сохранён");
                        (position, goods.identity(), goods.amount())
                    }
                    _ => unreachable!("успешный fairy add забрал incoming"),
                }
            }
            FairyStorageTransferAddition::Fairy(FairyContainerAddOutcome::Rejected(_)) => {
                unreachable!("успешный fairy transfer не содержит reject")
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn transfer_player_battle_fairy_goods<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<(), BattleFairyTransferBlock> {
        let supported = matches!(source_extend_id, 1 | 2 | 3 | 9 | 11)
            && destination_extend_id == 12
            || source_extend_id == 12 && matches!(destination_extend_id, 1 | 2 | 3 | 9 | 11);
        if !supported {
            return Err(BattleFairyTransferBlock::UnsupportedRoute);
        }
        if destination_extend_id == 12
            && destination_position != u32::MAX
            && BattleFairyCell::from_position(destination_position).is_none()
        {
            return Err(BattleFairyTransferBlock::InvalidCell {
                position: destination_position,
            });
        }
        let player = self
            .find_player(player_id)
            .ok_or(BattleFairyTransferBlock::MissingPlayer)?;
        let source = match source_extend_id {
            1 => player.packet().get_goods(source_position),
            2 => player.equipment().get_goods(source_position),
            3 => player.hand().get_goods(source_position),
            9 => player.depot().get_goods(source_position),
            11 => player.fairy_container().base().get_goods(source_position),
            12 => player
                .battle_fairy_container()
                .base()
                .get_goods(source_position),
            _ => None,
        }
        .filter(|goods| goods.identity().ex_id == goods_id)
        .ok_or(BattleFairyTransferBlock::MissingGoods)?;
        if amount == 0
            || source.amount() < amount
            || source_extend_id == 2 && source.amount() != amount
        {
            return Err(BattleFairyTransferBlock::AmountMismatch);
        }
        if source.amount() != amount
            && matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            )
        {
            return Err(BattleFairyTransferBlock::PartialMoveBusy(
                player.current_progress(),
            ));
        }
        let source_identity = source.identity();
        let audit_name = source.name().to_vec();
        let audit_price = source.price();
        let mut burden_goods = source.clone();
        burden_goods.set_amount(amount);
        let burden_exceeded = source_extend_id == 12
            && matches!(destination_extend_id, 1 | 2 | 3)
            && player
                .current_burden(&self.goods_factory)
                .wrapping_add(burden_goods.weight(&self.goods_factory))
                > u32::from(player.combat_properties().burden);
        let mut split_template = source.clone();
        split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен перед battle-fairy ownership pass");

        let (removal, mut incoming) = if source_extend_id == 1 {
            let removed = player.packet_mut().take_goods(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(BattleFairyTransferBlock::PacketRemovalFailed);
            };
            let (goods, removal) = Self::player_packet_taken(taken, source_position);
            (BattleFairyTransferRemoval::Player(removal), Some(goods))
        } else if source_extend_id == 2 {
            let goods = player
                .equipment()
                .get_goods(source_position)
                .expect("equipment source проверен до remove");
            let facts = context.enhancement_equipment_remove_facts(
                &player,
                goods,
                self.globe_setup.pack_add_enabled(),
            );
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut report = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut report);
            let outcome = std::mem::replace(
                &mut report.outcome,
                EquipmentRemoveOutcome::Missing {
                    partial_effects: Default::default(),
                },
            );
            let EquipmentRemoveOutcome::Removed(removed) = outcome else {
                report.outcome = outcome;
                self.players.insert(player_id, player);
                return Err(BattleFairyTransferBlock::EquipmentRemovalFailed(report));
            };
            (
                BattleFairyTransferRemoval::Player(EnhancementTransferRemoval::Equipment {
                    event: removed.event,
                }),
                Some(removed.goods),
            )
        } else if source_extend_id == 3 {
            let removed =
                player
                    .hand_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(taken) = removed else {
                self.players.insert(player_id, player);
                return Err(BattleFairyTransferBlock::HandRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    GroundHandRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: GroundHandRemovalKind::Removed,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    GroundHandRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: GroundHandRemovalKind::Split {
                            source: split.source,
                        },
                    },
                ),
            };
            (BattleFairyTransferRemoval::Hand(removal), Some(goods))
        } else if source_extend_id == 9 {
            let removed =
                player
                    .depot_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(BattleFairyTransferBlock::DepotRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    DepotStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: DepotStorageRemovalKind::Removed,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    DepotStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: DepotStorageRemovalKind::Split {
                            source: split.source,
                        },
                    },
                ),
            };
            (BattleFairyTransferRemoval::Depot(removal), Some(goods))
        } else if source_extend_id == 11 {
            let outcome = player.fairy_container_mut().take(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let taken = match outcome {
                FairyContainerRemoveOutcome::Removed(VolumeGoodsRemoveOutcome::Removed(taken)) => {
                    taken
                }
                failed => {
                    self.players.insert(player_id, player);
                    return Err(BattleFairyTransferBlock::FairyRemovalFailed(failed));
                }
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    FairyStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    FairyStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                    },
                ),
            };
            (BattleFairyTransferRemoval::Fairy(removal), Some(goods))
        } else {
            let Some(cell) = BattleFairyCell::from_position(source_position) else {
                self.players.insert(player_id, player);
                return Err(BattleFairyTransferBlock::InvalidCell {
                    position: source_position,
                });
            };
            let coefficients = self.globe_setup.player_property_coefficients();
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            let mut report = player.take_battle_fairy_goods(
                cell,
                amount,
                &self.goods_factory,
                coefficients,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
                &mut encode,
            );
            drop(encode);
            self.deliver_battle_fairy_equipment_effects_for_player(Some(&player), &mut report);
            let outcome = std::mem::replace(
                &mut report.outcome,
                BattleFairyEquipmentMutationOutcome::MissingGoods,
            );
            let BattleFairyEquipmentMutationOutcome::Removed(VolumeGoodsRemoveOutcome::Removed(
                taken,
            )) = outcome
            else {
                report.outcome = outcome;
                self.players.insert(player_id, player);
                return Err(BattleFairyTransferBlock::BattleFairyRemovalFailed(report));
            };
            let (goods, storage) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    BattleFairyStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        cell,
                        property_applied: report.property_applied,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    BattleFairyStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        cell,
                        property_applied: report.property_applied,
                    },
                ),
            };
            (
                BattleFairyTransferRemoval::BattleFairy(storage),
                Some(goods),
            )
        };

        if burden_exceeded {
            let rollback = self.add_battle_fairy_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(BattleFairyTransferBlock::BurdenRollbackFailed {
                    goods,
                    removal,
                    rollback,
                });
            }
            return Err(BattleFairyTransferBlock::BurdenRolledBack {
                removal,
                restored: rollback,
            });
        }

        let addition = self.add_battle_fairy_transfer_goods(
            &mut player,
            destination_extend_id,
            destination_position,
            &mut incoming,
            context,
        );
        if incoming.is_some() {
            let rejected = addition;
            let rollback = self.add_battle_fairy_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(BattleFairyTransferBlock::RollbackFailed {
                    goods,
                    removal,
                    rejected,
                    rollback,
                });
            }
            return Err(BattleFairyTransferBlock::RolledBack {
                removal,
                rejected,
                restored: rollback,
            });
        }

        let (actual_position, destination_goods, destination_amount) =
            Self::battle_fairy_transfer_destination(&player, destination_position, &addition);
        let previous_last_operated =
            player.record_last_operated_goods(source_extend_id, source_position);
        self.players.insert(player_id, player);
        if destination_extend_id == 9
            && self.log_system.goods_depot_set_log_enabled()
            || source_extend_id == 9 && self.log_system.goods_depot_get_log_enabled()
        {
            self.send_ground_goods_move_log(
                player_id,
                if destination_extend_id == 9 { 7 } else { 8 },
                source_identity,
                audit_price,
                &audit_name,
                amount,
            );
        }
        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(PLAYER_TYPE, player_id, source_position);
        moved.set_source_container_extend_id(source_extend_id);
        moved.set_destination_container(PLAYER_TYPE, player_id, actual_position);
        moved.set_destination_container_extend_id(destination_extend_id);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, destination_goods.ex_id);
        moved.set_destination_object_amount(destination_amount);
        let delivery = moved.send_to_player(self, player_id);
        tracing::trace!(
            player_id,
            ?source_identity,
            amount,
            source_extend_id,
            source_position,
            destination_extend_id,
            destination_position = actual_position,
            ?removal,
            ?addition,
            ?previous_last_operated,
            delivery,
            "перемещение боевой феи выполнено"
        );
        Ok(())
    }

    fn add_battle_fairy_transfer_goods<Context: GameContainerMessageRuntime>(
        &self,
        player: &mut CPlayer,
        extend_id: i32,
        position: u32,
        incoming: &mut Option<CGoods>,
        context: &mut Context,
    ) -> BattleFairyTransferAddition {
        if extend_id == 12 {
            let coefficients = self.globe_setup.player_property_coefficients();
            let owner_progress_allows = !matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            );
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            let mut report = if position == u32::MAX {
                player.add_battle_fairy_goods_auto(
                    incoming,
                    &self.goods_factory,
                    coefficients,
                    owner_progress_allows,
                    &mut encode,
                )
            } else if let Some(cell) = BattleFairyCell::from_position(position) {
                player.add_battle_fairy_goods(
                    cell,
                    incoming,
                    &self.goods_factory,
                    coefficients,
                    owner_progress_allows,
                    &mut encode,
                )
            } else {
                unreachable!("battle-fairy position проверена до ownership pass")
            };
            drop(encode);
            self.deliver_battle_fairy_equipment_effects_for_player(Some(player), &mut report);
            return BattleFairyTransferAddition::BattleFairy(report);
        }
        if extend_id == 11 {
            let owner_progress_allows = !matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            );
            let outcome = if position == u32::MAX {
                player.fairy_container_mut().add(
                    incoming,
                    &self.goods_factory,
                    owner_progress_allows,
                )
            } else {
                player.fairy_container_mut().add_at(
                    position,
                    incoming,
                    &self.goods_factory,
                    owner_progress_allows,
                )
            };
            return BattleFairyTransferAddition::Fairy(outcome);
        }
        if extend_id == 3 {
            return BattleFairyTransferAddition::Hand(
                self.add_ground_hand_goods(player, position, incoming),
            );
        }
        BattleFairyTransferAddition::Player(
            self.add_depot_transfer_goods(player, extend_id, position, incoming, context),
        )
    }

    fn battle_fairy_transfer_destination(
        player: &CPlayer,
        requested_position: u32,
        addition: &BattleFairyTransferAddition,
    ) -> (u32, ShapeIdentity, u32) {
        match addition {
            BattleFairyTransferAddition::Player(addition) => {
                Self::depot_transfer_destination(player, requested_position, addition)
            }
            BattleFairyTransferAddition::Hand(_) => {
                let goods = player
                    .hand()
                    .get_goods(0)
                    .expect("battle-fairy→hand add сохранён");
                (0, goods.identity(), goods.amount())
            }
            BattleFairyTransferAddition::Fairy(FairyContainerAddOutcome::Base(outcome)) => {
                let position = match outcome {
                    VolumeGoodsAddOutcome::Added(added) => {
                        added.position.unwrap_or(requested_position)
                    }
                    VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                        target, ..
                    }) => player
                        .fairy_container()
                        .base()
                        .query_goods_position(target.ex_id)
                        .expect("fairy stack position"),
                    _ => unreachable!("успешный fairy storage add"),
                };
                let goods = player
                    .fairy_container()
                    .base()
                    .get_goods(position)
                    .expect("fairy add сохранён");
                (position, goods.identity(), goods.amount())
            }
            BattleFairyTransferAddition::Fairy(FairyContainerAddOutcome::Rejected(_)) => {
                unreachable!("успешный fairy transfer не содержит reject")
            }
            BattleFairyTransferAddition::BattleFairy(report) => {
                let BattleFairyEquipmentMutationOutcome::Added(
                    crate::gameserver::appserver::container::cbattlefairycontainer::BattleFairyContainerAddOutcome::Stored { base, .. },
                ) = &report.outcome
                else {
                    unreachable!("успешный battle-fairy add")
                };
                let position = match base {
                    VolumeGoodsAddOutcome::Added(added) => {
                        added.position.unwrap_or(requested_position)
                    }
                    VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                        target, ..
                    }) => player
                        .battle_fairy_container()
                        .base()
                        .query_goods_position(target.ex_id)
                        .expect("battle-fairy stack position"),
                    _ => unreachable!("успешный battle-fairy storage add"),
                };
                let goods = player
                    .battle_fairy_container()
                    .base()
                    .get_goods(position)
                    .expect("battle-fairy add сохранён");
                (position, goods.identity(), goods.amount())
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn transfer_player_ci_qing_compose_goods<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<(), CiQingComposeTransferBlock> {
        let supported = matches!(source_extend_id, 1 | 2 | 3 | 9 | 11 | 12)
            && destination_extend_id == 17
            || source_extend_id == 17 && matches!(destination_extend_id, 1 | 2 | 3 | 9 | 11 | 12);
        if !supported {
            return Err(CiQingComposeTransferBlock::UnsupportedRoute);
        }
        if destination_extend_id == 12
            && destination_position != u32::MAX
            && BattleFairyCell::from_position(destination_position).is_none()
        {
            return Err(CiQingComposeTransferBlock::InvalidBattleFairyCell {
                position: destination_position,
            });
        }
        let player = self
            .find_player(player_id)
            .ok_or(CiQingComposeTransferBlock::MissingPlayer)?;
        let source = match source_extend_id {
            1 => player.packet().get_goods(source_position),
            2 => player.equipment().get_goods(source_position),
            3 => player.hand().get_goods(source_position),
            9 => player.depot().get_goods(source_position),
            11 => player.fairy_container().base().get_goods(source_position),
            12 => player
                .battle_fairy_container()
                .base()
                .get_goods(source_position),
            17 => player.ci_qing_compose_goods(source_position),
            _ => None,
        }
        .filter(|goods| goods.identity().ex_id == goods_id)
        .ok_or(CiQingComposeTransferBlock::MissingGoods)?;
        if amount == 0
            || source.amount() < amount
            || source_extend_id == 2 && source.amount() != amount
        {
            return Err(CiQingComposeTransferBlock::AmountMismatch);
        }
        if source.amount() != amount
            && matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            )
        {
            return Err(CiQingComposeTransferBlock::PartialMoveBusy(
                player.current_progress(),
            ));
        }

        let source_identity = source.identity();
        let audit_name = source.name().to_vec();
        let audit_price = source.price();
        let mut burden_goods = source.clone();
        burden_goods.set_amount(amount);
        let burden_exceeded = source_extend_id == 17
            && matches!(destination_extend_id, 1 | 2 | 3)
            && player
                .current_burden(&self.goods_factory)
                .wrapping_add(burden_goods.weight(&self.goods_factory))
                > u32::from(player.combat_properties().burden);
        let mut split_template = source.clone();
        split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен перед CiQing compose ownership pass");

        let (removal, mut incoming) = if source_extend_id == 1 {
            let removed = player.packet_mut().take_goods(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(CiQingComposeTransferBlock::PacketRemovalFailed);
            };
            let (goods, removal) = Self::player_packet_taken(taken, source_position);
            (CiQingComposeTransferRemoval::Player(removal), Some(goods))
        } else if source_extend_id == 2 {
            let goods = player
                .equipment()
                .get_goods(source_position)
                .expect("equipment source проверен до remove");
            let facts = context.enhancement_equipment_remove_facts(
                &player,
                goods,
                self.globe_setup.pack_add_enabled(),
            );
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut report = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut report);
            let outcome = std::mem::replace(
                &mut report.outcome,
                EquipmentRemoveOutcome::Missing {
                    partial_effects: Default::default(),
                },
            );
            let EquipmentRemoveOutcome::Removed(removed) = outcome else {
                report.outcome = outcome;
                self.players.insert(player_id, player);
                return Err(CiQingComposeTransferBlock::EquipmentRemovalFailed(report));
            };
            (
                CiQingComposeTransferRemoval::Player(EnhancementTransferRemoval::Equipment {
                    event: removed.event,
                }),
                Some(removed.goods),
            )
        } else if source_extend_id == 3 {
            let removed =
                player
                    .hand_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(taken) = removed else {
                self.players.insert(player_id, player);
                return Err(CiQingComposeTransferBlock::HandRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    GroundHandRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: GroundHandRemovalKind::Removed,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    GroundHandRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: GroundHandRemovalKind::Split {
                            source: split.source,
                        },
                    },
                ),
            };
            (CiQingComposeTransferRemoval::Hand(removal), Some(goods))
        } else if source_extend_id == 9 {
            let removed =
                player
                    .depot_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(CiQingComposeTransferBlock::DepotRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    DepotStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: DepotStorageRemovalKind::Removed,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    DepotStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: DepotStorageRemovalKind::Split {
                            source: split.source,
                        },
                    },
                ),
            };
            (CiQingComposeTransferRemoval::Depot(removal), Some(goods))
        } else if source_extend_id == 11 {
            let outcome = player.fairy_container_mut().take(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let taken = match outcome {
                FairyContainerRemoveOutcome::Removed(VolumeGoodsRemoveOutcome::Removed(taken)) => {
                    taken
                }
                failed => {
                    self.players.insert(player_id, player);
                    return Err(CiQingComposeTransferBlock::FairyRemovalFailed(failed));
                }
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    FairyStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    FairyStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                    },
                ),
            };
            (CiQingComposeTransferRemoval::Fairy(removal), Some(goods))
        } else if source_extend_id == 12 {
            let Some(cell) = BattleFairyCell::from_position(source_position) else {
                self.players.insert(player_id, player);
                return Err(CiQingComposeTransferBlock::InvalidBattleFairyCell {
                    position: source_position,
                });
            };
            let coefficients = self.globe_setup.player_property_coefficients();
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            let mut report = player.take_battle_fairy_goods(
                cell,
                amount,
                &self.goods_factory,
                coefficients,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
                &mut encode,
            );
            drop(encode);
            self.deliver_battle_fairy_equipment_effects_for_player(Some(&player), &mut report);
            let outcome = std::mem::replace(
                &mut report.outcome,
                BattleFairyEquipmentMutationOutcome::MissingGoods,
            );
            let BattleFairyEquipmentMutationOutcome::Removed(VolumeGoodsRemoveOutcome::Removed(
                taken,
            )) = outcome
            else {
                report.outcome = outcome;
                self.players.insert(player_id, player);
                return Err(CiQingComposeTransferBlock::BattleFairyRemovalFailed(report));
            };
            let (goods, storage) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    BattleFairyStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        cell,
                        property_applied: report.property_applied,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    BattleFairyStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        cell,
                        property_applied: report.property_applied,
                    },
                ),
            };
            (
                CiQingComposeTransferRemoval::BattleFairy(storage),
                Some(goods),
            )
        } else {
            let removed = player.take_ci_qing_compose_transfer_goods(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(CiQingComposeTransferBlock::ComposeRemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    CiQingComposeStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    CiQingComposeStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                    },
                ),
            };
            (CiQingComposeTransferRemoval::Compose(removal), Some(goods))
        };

        if burden_exceeded {
            let rollback = self.add_ci_qing_compose_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(CiQingComposeTransferBlock::BurdenRollbackFailed {
                    goods,
                    removal,
                    rollback,
                });
            }
            return Err(CiQingComposeTransferBlock::BurdenRolledBack {
                removal,
                restored: rollback,
            });
        }

        // Exact PutGoods проверяет именно source position, а не compose
        // destination position. Сохраняем quirk после GetGoods: remove- и
        // equipment-effects уже произошли и общий RollBack возвращает owner.
        if destination_extend_id == 17 && source_position == 2 {
            let rollback = self.add_ci_qing_compose_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(
                    CiQingComposeTransferBlock::DestinationRejectRollbackFailed {
                        goods,
                        source_position,
                        removal,
                        rollback,
                    },
                );
            }
            return Err(CiQingComposeTransferBlock::DestinationRejectsSourceSlot {
                source_position,
                removal,
                restored: rollback,
            });
        }

        let addition = self.add_ci_qing_compose_transfer_goods(
            &mut player,
            destination_extend_id,
            destination_position,
            &mut incoming,
            context,
        );
        if incoming.is_some() {
            let rejected = addition;
            let rollback = self.add_ci_qing_compose_transfer_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
                context,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(CiQingComposeTransferBlock::RollbackFailed {
                    goods,
                    removal,
                    rejected,
                    rollback,
                });
            }
            return Err(CiQingComposeTransferBlock::RolledBack {
                removal,
                rejected,
                restored: rollback,
            });
        }

        let (actual_position, destination_goods, destination_amount) =
            Self::ci_qing_compose_transfer_destination(&player, destination_position, &addition);
        let previous_last_operated =
            player.record_last_operated_goods(source_extend_id, source_position);
        self.players.insert(player_id, player);
        if destination_extend_id == 9
            && self.log_system.goods_depot_set_log_enabled()
            || source_extend_id == 9 && self.log_system.goods_depot_get_log_enabled()
        {
            self.send_ground_goods_move_log(
                player_id,
                if destination_extend_id == 9 { 7 } else { 8 },
                source_identity,
                audit_price,
                &audit_name,
                amount,
            );
        }
        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(PLAYER_TYPE, player_id, source_position);
        moved.set_source_container_extend_id(source_extend_id);
        moved.set_destination_container(PLAYER_TYPE, player_id, actual_position);
        moved.set_destination_container_extend_id(destination_extend_id);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, destination_goods.ex_id);
        moved.set_destination_object_amount(destination_amount);
        let delivery = moved.send_to_player(self, player_id);
        tracing::trace!(
            player_id,
            ?source_identity,
            amount,
            source_extend_id,
            source_position,
            destination_extend_id,
            destination_position = actual_position,
            ?removal,
            ?addition,
            ?previous_last_operated,
            delivery,
            "перемещение состава CiQing выполнено"
        );
        Ok(())
    }

    fn add_ci_qing_compose_transfer_goods<Context: GameContainerMessageRuntime>(
        &self,
        player: &mut CPlayer,
        extend_id: i32,
        position: u32,
        incoming: &mut Option<CGoods>,
        context: &mut Context,
    ) -> CiQingComposeTransferAddition {
        if extend_id == 17 {
            return CiQingComposeTransferAddition::Compose(
                player.add_ci_qing_compose_transfer_goods(incoming, position, &self.goods_factory),
            );
        }
        if extend_id == 12 {
            let coefficients = self.globe_setup.player_property_coefficients();
            let owner_progress_allows = !matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            );
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            let mut report = if position == u32::MAX {
                player.add_battle_fairy_goods_auto(
                    incoming,
                    &self.goods_factory,
                    coefficients,
                    owner_progress_allows,
                    &mut encode,
                )
            } else {
                let cell = BattleFairyCell::from_position(position)
                    .expect("battle-fairy position проверена до ownership pass");
                player.add_battle_fairy_goods(
                    cell,
                    incoming,
                    &self.goods_factory,
                    coefficients,
                    owner_progress_allows,
                    &mut encode,
                )
            };
            drop(encode);
            self.deliver_battle_fairy_equipment_effects_for_player(Some(player), &mut report);
            return CiQingComposeTransferAddition::BattleFairy(report);
        }
        if extend_id == 11 {
            let owner_progress_allows = !matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            );
            let outcome = if position == u32::MAX {
                player.fairy_container_mut().add(
                    incoming,
                    &self.goods_factory,
                    owner_progress_allows,
                )
            } else {
                player.fairy_container_mut().add_at(
                    position,
                    incoming,
                    &self.goods_factory,
                    owner_progress_allows,
                )
            };
            return CiQingComposeTransferAddition::Fairy(outcome);
        }
        if extend_id == 3 {
            return CiQingComposeTransferAddition::Hand(
                self.add_ground_hand_goods(player, position, incoming),
            );
        }
        CiQingComposeTransferAddition::Player(
            self.add_depot_transfer_goods(player, extend_id, position, incoming, context),
        )
    }

    fn ci_qing_compose_transfer_destination(
        player: &CPlayer,
        requested_position: u32,
        addition: &CiQingComposeTransferAddition,
    ) -> (u32, ShapeIdentity, u32) {
        match addition {
            CiQingComposeTransferAddition::Player(addition) => {
                Self::depot_transfer_destination(player, requested_position, addition)
            }
            CiQingComposeTransferAddition::Hand(_) => {
                let goods = player
                    .hand()
                    .get_goods(0)
                    .expect("CiQing compose→hand add сохранён");
                (0, goods.identity(), goods.amount())
            }
            CiQingComposeTransferAddition::Fairy(FairyContainerAddOutcome::Base(outcome)) => {
                let position = match outcome {
                    VolumeGoodsAddOutcome::Added(added) => {
                        added.position.unwrap_or(requested_position)
                    }
                    VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                        target, ..
                    }) => player
                        .fairy_container()
                        .base()
                        .query_goods_position(target.ex_id)
                        .expect("fairy stack position"),
                    _ => unreachable!("успешный fairy storage add"),
                };
                let goods = player
                    .fairy_container()
                    .base()
                    .get_goods(position)
                    .expect("fairy add сохранён");
                (position, goods.identity(), goods.amount())
            }
            CiQingComposeTransferAddition::Fairy(FairyContainerAddOutcome::Rejected(_)) => {
                unreachable!("успешный fairy transfer не содержит reject")
            }
            CiQingComposeTransferAddition::BattleFairy(report) => {
                let BattleFairyEquipmentMutationOutcome::Added(
                    crate::gameserver::appserver::container::cbattlefairycontainer::BattleFairyContainerAddOutcome::Stored { base, .. },
                ) = &report.outcome
                else {
                    unreachable!("успешный battle-fairy add")
                };
                let position = match base {
                    VolumeGoodsAddOutcome::Added(added) => {
                        added.position.unwrap_or(requested_position)
                    }
                    VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                        target, ..
                    }) => player
                        .battle_fairy_container()
                        .base()
                        .query_goods_position(target.ex_id)
                        .expect("battle-fairy stack position"),
                    _ => unreachable!("успешный battle-fairy storage add"),
                };
                let goods = player
                    .battle_fairy_container()
                    .base()
                    .get_goods(position)
                    .expect("battle-fairy add сохранён");
                (position, goods.identity(), goods.amount())
            }
            CiQingComposeTransferAddition::Compose(addition) => {
                let goods = player
                    .ci_qing_compose_goods(addition.position)
                    .expect("успешный CiQing compose add сохранён");
                (addition.position, goods.identity(), goods.amount())
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn return_auction_goods_to_inventory<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<(), AuctionGoodsInventoryBlock> {
        if !matches!(destination_extend_id, 1 | 2 | 3 | 9 | 11 | 12 | 17) {
            return Err(AuctionGoodsInventoryBlock::UnsupportedDestination);
        }
        if destination_extend_id == 12
            && destination_position != u32::MAX
            && BattleFairyCell::from_position(destination_position).is_none()
        {
            return Err(AuctionGoodsInventoryBlock::InvalidBattleFairyCell {
                position: destination_position,
            });
        }
        let player = self
            .find_player(player_id)
            .ok_or(AuctionGoodsInventoryBlock::MissingPlayer)?;
        let source = player
            .auction_goods()
            .get_goods(source_position)
            .filter(|goods| goods.identity().ex_id == goods_id)
            .ok_or(AuctionGoodsInventoryBlock::MissingGoods)?;
        if amount == 0 || source.amount() < amount {
            return Err(AuctionGoodsInventoryBlock::AmountMismatch);
        }
        if source.amount() != amount
            && matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            )
        {
            return Err(AuctionGoodsInventoryBlock::PartialMoveBusy(
                player.current_progress(),
            ));
        }
        let source_identity = source.identity();
        let audit_name = source.name().to_vec();
        let audit_price = source.price();
        let mut burden_goods = source.clone();
        burden_goods.set_amount(amount);
        let burden_exceeded = matches!(destination_extend_id, 1 | 2 | 3)
            && player
                .current_burden(&self.goods_factory)
                .wrapping_add(burden_goods.weight(&self.goods_factory))
                > u32::from(player.combat_properties().burden);
        let mut split_template = source.clone();
        split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен перед auction-goods ownership pass");
        let removed = player.auction_goods_mut().take_goods(
            source_position,
            amount,
            &self.goods_factory,
            |_| {
                (split_template.identity().ex_id != CGuid::GUID_INVALID)
                    .then(|| split_template.clone())
            },
        );
        let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
            self.players.insert(player_id, player);
            return Err(AuctionGoodsInventoryBlock::RemovalFailed);
        };
        let (goods, removal) = match taken {
            AmountLimitGoodsTaken::Removed(removed) => (
                removed.goods,
                AuctionGoodsInventoryRemoval {
                    owner_type: removed.owner_type,
                    owner_id: removed.owner_id,
                    position: removed.position.unwrap_or(source_position),
                    amount: removed.amount,
                    listeners: removed.listeners,
                },
            ),
            AmountLimitGoodsTaken::Split(split) => (
                split.goods,
                AuctionGoodsInventoryRemoval {
                    owner_type: split.owner_type,
                    owner_id: split.owner_id,
                    position: split.position.unwrap_or(source_position),
                    amount: split.amount,
                    listeners: split.listeners,
                },
            ),
        };
        let mut incoming = Some(goods);

        if burden_exceeded {
            let rollback =
                self.rollback_auction_goods_transfer(&mut player, source_position, &mut incoming);
            self.players.insert(player_id, player);
            return Err(AuctionGoodsInventoryBlock::BurdenExceeded { removal, rollback });
        }

        if destination_extend_id == 17 && source_position == 2 {
            let rollback =
                self.rollback_auction_goods_transfer(&mut player, source_position, &mut incoming);
            self.players.insert(player_id, player);
            return Err(AuctionGoodsInventoryBlock::DestinationRejectsSourceSlot {
                source_position,
                removal,
                rollback,
            });
        }

        // Exact PutGoods игнорирует присланную packet position для source 14:
        // FindPositionForGoods выбирает compatible stack либо первый empty
        // slot до bind mutation и до positional Add.
        let actual_destination_position = if destination_extend_id == 1 {
            let Some(position) = incoming.as_ref().and_then(|goods| {
                player
                    .packet()
                    .find_position_for_goods(goods, &self.goods_factory)
            }) else {
                let rollback = self.rollback_auction_goods_transfer(
                    &mut player,
                    source_position,
                    &mut incoming,
                );
                self.players.insert(player_id, player);
                return Err(AuctionGoodsInventoryBlock::PacketPositionUnavailable {
                    removal,
                    rollback,
                });
            };
            position
        } else {
            destination_position
        };
        let bind_cleared = destination_extend_id == 1
            && incoming
                .as_mut()
                .is_some_and(|goods| goods.set_addon_property_value_core(GAP_GOODS_BIND, 2, 0));
        let addition = self.add_ci_qing_compose_transfer_goods(
            &mut player,
            destination_extend_id,
            actual_destination_position,
            &mut incoming,
            context,
        );
        if incoming.is_some() {
            let rejected = addition;
            let rollback =
                self.rollback_auction_goods_transfer(&mut player, source_position, &mut incoming);
            self.players.insert(player_id, player);
            return Err(AuctionGoodsInventoryBlock::RolledBack {
                removal,
                bind_cleared,
                rejected,
                rollback,
            });
        }

        let (actual_destination_position, destination_goods, destination_amount) =
            Self::ci_qing_compose_transfer_destination(
                &player,
                actual_destination_position,
                &addition,
            );
        let previous_last_operated = player.record_last_operated_goods(14, source_position);
        self.players.insert(player_id, player);
        if destination_extend_id == 9 && self.log_system.goods_depot_set_log_enabled() {
                self.send_ground_goods_move_log(
                    player_id,
                    7,
                    source_identity,
                    audit_price,
                    &audit_name,
                    amount,
                );
        }
        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(PLAYER_TYPE, player_id, source_position);
        moved.set_source_container_extend_id(14);
        moved.set_destination_container(PLAYER_TYPE, player_id, actual_destination_position);
        moved.set_destination_container_extend_id(destination_extend_id);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, destination_goods.ex_id);
        moved.set_destination_object_amount(destination_amount);
        let delivery = moved.send_to_player(self, player_id);
        tracing::trace!(
            player_id,
            ?source_identity,
            amount,
            source_position,
            destination_extend_id,
            destination_position = actual_destination_position,
            ?removal,
            bind_cleared,
            ?addition,
            ?previous_last_operated,
            delivery,
            "аукционный предмет возвращён в инвентарь"
        );
        Ok(())
    }

    fn rollback_auction_goods_transfer(
        &self,
        player: &mut CPlayer,
        source_position: u32,
        incoming: &mut Option<CGoods>,
    ) -> AuctionGoodsInventoryRollback {
        let owner_progress_allows = player.current_progress() == PlayerProgress::None;
        let outcome = player.auction_goods_mut().add_goods_at(
            source_position,
            incoming,
            &self.goods_factory,
            owner_progress_allows,
        );
        if let Some(goods) = incoming.take() {
            AuctionGoodsInventoryRollback::Failed { goods, outcome }
        } else {
            AuctionGoodsInventoryRollback::Restored(outcome)
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn transfer_hand_auction_listing_goods(
        &mut self,
        player_id: i32,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
    ) -> Result<(), HandAuctionListingBlock> {
        if !matches!((source_extend_id, destination_extend_id), (3, 13) | (13, 3)) {
            return Err(HandAuctionListingBlock::UnsupportedRoute);
        }
        if source_extend_id == 3 && source_position != 0
            || destination_extend_id == 3 && destination_position != 0
            || source_extend_id == 13 && source_position >= 2
            || destination_extend_id == 13 && destination_position >= 2
        {
            return Err(HandAuctionListingBlock::InvalidPosition);
        }
        let player = self
            .find_player(player_id)
            .ok_or(HandAuctionListingBlock::MissingPlayer)?;
        let source = if source_extend_id == 3 {
            player.hand().get_goods(source_position)
        } else {
            player.auction_listing().get_goods(source_position)
        }
        .filter(|goods| goods.identity().ex_id == goods_id)
        .ok_or(HandAuctionListingBlock::MissingGoods)?;
        if amount == 0 || source.amount() < amount {
            return Err(HandAuctionListingBlock::AmountMismatch);
        }
        if source.amount() != amount
            && matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            )
        {
            return Err(HandAuctionListingBlock::PartialMoveBusy(
                player.current_progress(),
            ));
        }
        let source_identity = source.identity();
        let mut burden_goods = source.clone();
        burden_goods.set_amount(amount);
        let burden_exceeded = source_extend_id == 13
            && player
                .current_burden(&self.goods_factory)
                .wrapping_add(burden_goods.weight(&self.goods_factory))
                > u32::from(player.combat_properties().burden);
        let mut split_template = source.clone();
        split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен перед hand↔auction-listing ownership pass");

        let (removal, mut incoming) = if source_extend_id == 3 {
            let removed =
                player
                    .hand_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(taken) = removed else {
                self.players.insert(player_id, player);
                return Err(HandAuctionListingBlock::RemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    GroundHandRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: GroundHandRemovalKind::Removed,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    GroundHandRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: GroundHandRemovalKind::Split {
                            source: split.source,
                        },
                    },
                ),
            };
            (HandAuctionListingRemoval::Hand(removal), Some(goods))
        } else {
            let removed = player.auction_listing_mut().take_goods(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                return Err(HandAuctionListingBlock::RemovalFailed);
            };
            let (goods, removal) = match taken {
                AmountLimitGoodsTaken::Removed(removed) => (
                    removed.goods,
                    AuctionListingWithdrawalRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    },
                ),
                AmountLimitGoodsTaken::Split(split) => (
                    split.goods,
                    AuctionListingWithdrawalRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                    },
                ),
            };
            (HandAuctionListingRemoval::Listing(removal), Some(goods))
        };

        if burden_exceeded {
            let rollback = self.add_hand_auction_listing_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(HandAuctionListingBlock::RollbackFailed {
                    goods,
                    removal,
                    rejected: None,
                    rollback,
                });
            }
            return Err(HandAuctionListingBlock::BurdenRolledBack {
                removal,
                restored: rollback,
            });
        }

        if destination_extend_id == 13
            && destination_position == 0
            && !CPlayer::auction_listing_goods_allowed(
                incoming
                    .as_ref()
                    .expect("listing limit получает detached goods"),
                &self.goods_factory,
            )
        {
            let rollback = self.add_hand_auction_listing_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(HandAuctionListingBlock::RollbackFailed {
                    goods,
                    removal,
                    rejected: None,
                    rollback,
                });
            }
            return Err(HandAuctionListingBlock::AuctionLimitRejected {
                removal,
                restored: rollback,
            });
        }

        let addition = self.add_hand_auction_listing_goods(
            &mut player,
            destination_extend_id,
            destination_position,
            &mut incoming,
        );
        if incoming.is_some() {
            let rejected = addition;
            let rollback = self.add_hand_auction_listing_goods(
                &mut player,
                source_extend_id,
                source_position,
                &mut incoming,
            );
            self.players.insert(player_id, player);
            if let Some(goods) = incoming {
                return Err(HandAuctionListingBlock::RollbackFailed {
                    goods,
                    removal,
                    rejected: Some(rejected),
                    rollback,
                });
            }
            return Err(HandAuctionListingBlock::Rejected {
                removal,
                rejected,
                restored: rollback,
            });
        }

        let (actual_position, destination_goods, destination_amount) =
            Self::hand_auction_listing_destination(&player, destination_position, &addition);
        let previous_last_operated =
            player.record_last_operated_goods(source_extend_id, source_position);
        self.players.insert(player_id, player);
        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(PLAYER_TYPE, player_id, source_position);
        moved.set_source_container_extend_id(source_extend_id);
        moved.set_destination_container(PLAYER_TYPE, player_id, actual_position);
        moved.set_destination_container_extend_id(destination_extend_id);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, destination_goods.ex_id);
        moved.set_destination_object_amount(destination_amount);
        let delivery = moved.send_to_player(self, player_id);
        tracing::trace!(
            player_id,
            ?source_identity,
            amount,
            source_extend_id,
            source_position,
            destination_extend_id,
            destination_position = actual_position,
            ?removal,
            ?addition,
            ?previous_last_operated,
            delivery,
            "перемещение между рукой и аукционным лотом выполнено"
        );
        Ok(())
    }

    fn add_hand_auction_listing_goods(
        &self,
        player: &mut CPlayer,
        extend_id: i32,
        position: u32,
        incoming: &mut Option<CGoods>,
    ) -> HandAuctionListingAddition {
        if extend_id == 3 {
            return HandAuctionListingAddition::Hand(
                self.add_ground_hand_goods(player, position, incoming),
            );
        }
        let owner_progress_allows = player.current_progress() == PlayerProgress::None;
        HandAuctionListingAddition::Listing(player.auction_listing_mut().add_goods_at(
            position,
            incoming,
            &self.goods_factory,
            owner_progress_allows,
        ))
    }

    fn hand_auction_listing_destination(
        player: &CPlayer,
        requested_position: u32,
        addition: &HandAuctionListingAddition,
    ) -> (u32, ShapeIdentity, u32) {
        match addition {
            HandAuctionListingAddition::Hand(_) => {
                let goods = player.hand().get_goods(0).expect("успешный hand add");
                (0, goods.identity(), goods.amount())
            }
            HandAuctionListingAddition::Listing(outcome) => match outcome {
                VolumeGoodsAddOutcome::Added(added) => {
                    let position = added.position.unwrap_or(requested_position);
                    let goods = player
                        .auction_listing()
                        .get_goods(position)
                        .expect("успешный listing add");
                    (position, goods.identity(), goods.amount())
                }
                VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged { target, .. }) => {
                    let position = player
                        .auction_listing()
                        .query_goods_position(target.ex_id)
                        .expect("listing stack position");
                    let goods = player
                        .auction_listing()
                        .get_goods(position)
                        .expect("успешный listing stack");
                    (position, goods.identity(), goods.amount())
                }
                _ => unreachable!("успешный listing add забрал incoming"),
            },
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn move_hand_goods_to_player_container<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<(), HandContainerMoveBlock> {
        if !matches!(destination_extend_id, 1 | 2 | 9) {
            return Err(HandContainerMoveBlock::UnsupportedDestination);
        }
        let player = self
            .find_player(player_id)
            .ok_or(HandContainerMoveBlock::MissingPlayer)?;
        let source = player
            .hand()
            .get_goods(0)
            .filter(|goods| goods.identity().ex_id == goods_id)
            .ok_or(HandContainerMoveBlock::MissingGoods)?;
        if amount == 0 || source.amount() < amount {
            return Err(HandContainerMoveBlock::AmountMismatch);
        }
        if source.amount() != amount
            && matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            )
        {
            return Err(HandContainerMoveBlock::PartialMoveBusy(
                player.current_progress(),
            ));
        }
        let source_identity = source.identity();
        let audit_name = source.name().to_vec();
        let audit_price = source.price();
        let burden_exceeded = matches!(destination_extend_id, 1 | 2)
            && player.current_burden(&self.goods_factory)
                > u32::from(player.combat_properties().burden);
        let mut split_template = source.clone();
        split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));

        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен перед hand ownership pass");
        let removed = player
            .hand_mut()
            .take_goods(0, amount, &self.goods_factory, |_| {
                (split_template.identity().ex_id != CGuid::GUID_INVALID)
                    .then(|| split_template.clone())
            });
        let Some(removed) = removed else {
            self.players.insert(player_id, player);
            return Err(HandContainerMoveBlock::AmountMismatch);
        };
        let (mut incoming, removal) = match removed {
            AmountLimitGoodsTaken::Removed(removed) => (
                Some(removed.goods),
                GroundHandRemoval {
                    owner_type: removed.owner_type,
                    owner_id: removed.owner_id,
                    position: removed.position.unwrap_or(0),
                    amount: removed.amount,
                    listeners: removed.listeners,
                    kind: GroundHandRemovalKind::Removed,
                },
            ),
            AmountLimitGoodsTaken::Split(split) => (
                Some(split.goods),
                GroundHandRemoval {
                    owner_type: split.owner_type,
                    owner_id: split.owner_id,
                    position: split.position.unwrap_or(0),
                    amount: split.amount,
                    listeners: split.listeners,
                    kind: GroundHandRemovalKind::Split {
                        source: split.source,
                    },
                },
            ),
        };

        if burden_exceeded {
            let restored = self.add_ground_hand_goods(&mut player, 0, &mut incoming);
            self.players.insert(player_id, player);
            return Err(HandContainerMoveBlock::BurdenExceeded { restored });
        }

        let addition = self.add_depot_transfer_goods(
            &mut player,
            destination_extend_id,
            destination_position,
            &mut incoming,
            context,
        );
        if incoming.is_none() {
            let (actual_position, destination_goods, destination_amount) =
                Self::depot_transfer_destination(&player, destination_position, &addition);
            let previous_last_operated = player.record_last_operated_goods(3, 0);
            self.players.insert(player_id, player);
            if destination_extend_id == 9 && self.log_system.goods_depot_set_log_enabled() {
                    self.send_ground_goods_move_log(
                        player_id,
                        7,
                        source_identity,
                        audit_price,
                        &audit_name,
                        amount,
                    );
            }
            let mut moved = CS2CContainerObjectMove::default();
            moved.set_operation(ContainerObjectMoveOperation::MoveObject);
            moved.set_source_container(PLAYER_TYPE, player_id, 0);
            moved.set_source_container_extend_id(3);
            moved.set_destination_container(PLAYER_TYPE, player_id, actual_position);
            moved.set_destination_container_extend_id(destination_extend_id);
            moved.set_source_object(GOODS_TYPE, goods_id, amount);
            moved.set_destination_object(GOODS_TYPE, destination_goods.ex_id);
            moved.set_destination_object_amount(destination_amount);
            let delivery = moved.send_to_player(self, player_id);
            tracing::trace!(
                player_id,
                ?source_identity,
                amount,
                destination_extend_id,
                destination_position = actual_position,
                ?removal,
                ?addition,
                ?previous_last_operated,
                delivery,
                "предмет из руки перемещён в контейнер"
            );
            return Ok(());
        }

        let progress = player.current_progress();
        if matches!(
            progress,
            PlayerProgress::Trading | PlayerProgress::OpenStall | PlayerProgress::Upgrade
        ) {
            let restored = self.add_ground_hand_goods(&mut player, 0, &mut incoming);
            self.players.insert(player_id, player);
            return Err(HandContainerMoveBlock::SwapBusy {
                rejected: addition,
                restored,
            });
        }

        let mut swap_failure = None;
        let swapped = if destination_extend_id == 1 {
            let expanded = player.equipment().expanded_package_num();
            if !player.packet().can_swap(
                destination_position,
                expanded,
                self.globe_setup.pack_add_enabled(),
            ) {
                None
            } else {
                player.packet_mut().swap_goods(
                    destination_position,
                    &mut incoming,
                    &self.goods_factory,
                    true,
                )
            }
            .and_then(|outcome| match outcome {
                VolumeGoodsSwapOutcome::Swapped {
                    outgoing,
                    removed,
                    added,
                } => Some((
                    outgoing,
                    HandContainerSwapDestination::Volume {
                        extend_id: 1,
                        removed,
                        added,
                    },
                )),
                failed => {
                    swap_failure = Some(HandContainerSwapFailure::Volume(failed));
                    None
                }
            })
        } else if destination_extend_id == 9 {
            let outcome = player.depot_mut().swap_goods(
                destination_position,
                &mut incoming,
                &self.goods_factory,
                true,
            );
            match outcome {
                Some(VolumeGoodsSwapOutcome::Swapped {
                    outgoing,
                    removed,
                    added,
                }) => {
                    if let Some(goods_id) = player
                        .depot()
                        .get_goods(destination_position)
                        .map(|goods| goods.identity().ex_id)
                    {
                        Self::register_player_goods_ai(&mut player, &self.goods_factory, goods_id);
                    }
                    Some((
                        outgoing,
                        HandContainerSwapDestination::Volume {
                            extend_id: 9,
                            removed,
                            added,
                        },
                    ))
                }
                Some(failed) => {
                    swap_failure = Some(HandContainerSwapFailure::Volume(failed));
                    None
                }
                None => None,
            }
        } else {
            self.swap_hand_goods_with_equipment(
                &mut player,
                destination_position,
                &mut incoming,
                context,
                &mut swap_failure,
            )
        };

        let Some((displaced, destination)) = swapped else {
            let restored = self.add_ground_hand_goods(&mut player, 0, &mut incoming);
            let rollback_failed = incoming.take();
            self.players.insert(player_id, player);
            if let Some(goods) = rollback_failed {
                return Err(HandContainerMoveBlock::RollbackFailed {
                    goods,
                    rejected: addition,
                    rollback: restored,
                });
            }
            return Err(HandContainerMoveBlock::SwapFailed {
                rejected: addition,
                swap: swap_failure,
                restored,
            });
        };

        let displaced_identity = displaced.identity();
        let hand_add = player.hand_mut().add_goods(displaced, &self.goods_factory);
        let (hand_addition, displaced_collected) = match hand_add {
            Ok(added) => (Some(added), false),
            Err(_collected) => (None, true),
        };
        let previous_last_operated = player.record_last_operated_goods(0, 0);
        self.players.insert(player_id, player);
        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::SwitchObject);
        moved.set_source_container(PLAYER_TYPE, player_id, 0);
        moved.set_source_container_extend_id(3);
        moved.set_destination_container(PLAYER_TYPE, player_id, destination_position);
        moved.set_destination_container_extend_id(destination_extend_id);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, displaced_identity.ex_id);
        let delivery = moved.send_to_player(self, player_id);
        tracing::trace!(
            player_id,
            ?source_identity,
            amount,
            destination_extend_id,
            destination_position,
            ?removal,
            ?destination,
            ?displaced_identity,
            ?hand_addition,
            displaced_collected,
            ?previous_last_operated,
            delivery,
            "предмет из руки обменён с контейнером"
        );
        Ok(())
    }

    fn depot_transfer_destination(
        player: &CPlayer,
        requested_position: u32,
        addition: &DepotStorageTransferAddition,
    ) -> (u32, ShapeIdentity, u32) {
        match addition {
            DepotStorageTransferAddition::Player(EnhancementTransferAddition::Packet(outcome)) => {
                match outcome {
                    VolumeGoodsAddOutcome::Added(added) => {
                        let position = added.position.unwrap_or(requested_position);
                        let goods = player
                            .packet()
                            .get_goods(position)
                            .expect("packet add сохранён");
                        (position, goods.identity(), goods.amount())
                    }
                    VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                        target, ..
                    }) => {
                        let position = player
                            .packet()
                            .query_goods_position(target.ex_id)
                            .expect("packet stack position");
                        let goods = player
                            .packet()
                            .get_goods(position)
                            .expect("packet stack сохранён");
                        (position, goods.identity(), goods.amount())
                    }
                    _ => unreachable!("успешный packet add забрал incoming"),
                }
            }
            DepotStorageTransferAddition::Player(EnhancementTransferAddition::Equipment(
                report,
            )) => {
                let EquipmentAddOutcome::Added(added) = &report.outcome else {
                    unreachable!("успешный equipment add")
                };
                (added.column.position(), added.identity, added.amount)
            }
            DepotStorageTransferAddition::Depot(DepotGoodsAddOutcome::Volume(outcome)) => {
                match outcome {
                    VolumeGoodsAddOutcome::Added(added) => (
                        added.position.unwrap_or(requested_position),
                        added.identity,
                        added.amount,
                    ),
                    VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                        target, ..
                    }) => {
                        let position = player
                            .depot()
                            .base()
                            .query_goods_position(target.ex_id)
                            .expect("depot stack position");
                        let goods = player
                            .depot()
                            .get_goods(position)
                            .expect("depot stack сохранён");
                        (position, goods.identity(), goods.amount())
                    }
                    _ => unreachable!("успешный depot add забрал incoming"),
                }
            }
            _ => unreachable!("успешный player-container addition"),
        }
    }

    fn swap_hand_goods_with_equipment<Context: GameContainerMessageRuntime>(
        &self,
        player: &mut CPlayer,
        position: u32,
        incoming: &mut Option<CGoods>,
        context: &mut Context,
        failure: &mut Option<HandContainerSwapFailure>,
    ) -> Option<(CGoods, HandContainerSwapDestination)> {
        let incoming_goods = incoming.as_ref()?;
        if player.can_mount_equip(incoming_goods, &self.goods_factory) != 9 {
            return None;
        }
        let properties = self
            .goods_factory
            .query_goods_base_properties(incoming_goods.base_properties_index())?;
        let column = EquipmentColumn::from_position(position)?;
        if !crate::gameserver::appserver::container::cequipmentcontainer::CEquipmentContainer::does_equip_place_fit(
            column,
            properties.equip_place(),
        ) {
            return None;
        }
        let old_goods = player.equipment().get_goods(position)?.clone();
        if self.globe_setup.pack_add_enabled()
            && old_goods.query_attribute(GAP_GOODS_PACKAGE_EXTENTION)
            && old_goods.addon_property_value(&self.goods_factory, GAP_GOODS_PACKAGE_EXTENTION, 1)
                == 2
        {
            let required =
                old_goods.addon_property_value(&self.goods_factory, GAP_GOODS_PACKAGE_EXTENTION, 2)
                    as u32;
            let available = player.packet().activated_but_unused_count(true);
            if available < required {
                *failure = Some(HandContainerSwapFailure::EquipmentCapacity {
                    required,
                    available,
                });
                return None;
            }
        }
        let remove_facts = context.enhancement_equipment_remove_facts(
            player,
            &old_goods,
            self.globe_setup.pack_add_enabled(),
        );
        let mut recompute =
            |player: &CPlayer| context.recompute_enhancement_player_properties(player);
        let mut removed_report = player.remove_equipment_goods(
            old_goods.identity().ex_id,
            &self.goods_factory,
            &self.skill_factory,
            remove_facts,
            &mut recompute,
        );
        drop(recompute);
        self.publish_player_equipment_remove_report(&mut removed_report);
        let outcome = std::mem::replace(
            &mut removed_report.outcome,
            EquipmentRemoveOutcome::Missing {
                partial_effects: Default::default(),
            },
        );
        let EquipmentRemoveOutcome::Removed(removed) = outcome else {
            removed_report.outcome = outcome;
            *failure = Some(HandContainerSwapFailure::EquipmentRemoval(removed_report));
            return None;
        };
        let removed_mutation = EnhancementTransferRemoval::Equipment {
            event: removed.event,
        };
        let mut outgoing = Some(removed.goods);
        let added = self.add_enhancement_transfer_goods(
            player,
            2,
            position,
            incoming,
            self.globe_setup.pack_add_enabled(),
            context,
        );
        let EnhancementTransferAddition::Equipment(added_report) = added else {
            unreachable!("equipment positional add возвращает equipment report")
        };
        if incoming.is_none() {
            return Some((
                outgoing.take().expect("removed equipment сохранён"),
                HandContainerSwapDestination::Equipment {
                    removed: removed_mutation,
                    added: added_report,
                },
            ));
        }

        let restored = self.add_enhancement_transfer_goods(
            player,
            2,
            position,
            &mut outgoing,
            self.globe_setup.pack_add_enabled(),
            context,
        );
        let EnhancementTransferAddition::Equipment(restored_report) = restored else {
            unreachable!("equipment rollback возвращает equipment report")
        };
        let _collected = outgoing.take();
        *failure = Some(HandContainerSwapFailure::Equipment {
            removed: removed_mutation,
            rejected: added_report,
            restored: restored_report,
        });
        None
    }

    fn add_depot_transfer_goods<Context: GameContainerMessageRuntime>(
        &self,
        player: &mut CPlayer,
        extend_id: i32,
        position: u32,
        incoming: &mut Option<CGoods>,
        context: &mut Context,
    ) -> DepotStorageTransferAddition {
        let owner_progress_allows = !matches!(
            player.current_progress(),
            PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
        );
        if extend_id == 9 {
            if position != u32::MAX
                && position >= 96
                && !CDepot::is_extension_item_position(position)
                && !player.depot().is_activated(position)
            {
                return DepotStorageTransferAddition::Depot(DepotGoodsAddOutcome::Rejected(
                    DepotGoodsAddBlock::ExtensionGroupInactive { position },
                ));
            }
            let outcome = if position == u32::MAX {
                player
                    .depot_mut()
                    .add_goods(incoming, &self.goods_factory, owner_progress_allows)
            } else {
                player.depot_mut().add_goods_at(
                    position,
                    incoming,
                    &self.goods_factory,
                    owner_progress_allows,
                )
            };
            if let DepotGoodsAddOutcome::Volume(VolumeGoodsAddOutcome::Added(added)) = &outcome
                && let Some(goods_id) = player
                    .depot()
                    .get_goods(added.position.unwrap_or(position))
                    .map(|goods| goods.identity().ex_id)
            {
                Self::register_player_goods_ai(player, &self.goods_factory, goods_id);
            }
            return DepotStorageTransferAddition::Depot(outcome);
        }
        if extend_id == 1 {
            let outcome = if position == u32::MAX {
                player
                    .packet_mut()
                    .add_goods(incoming, &self.goods_factory, owner_progress_allows)
            } else {
                player.packet_mut().add_goods_at(
                    position,
                    incoming,
                    &self.goods_factory,
                    owner_progress_allows,
                )
            };
            return DepotStorageTransferAddition::Player(EnhancementTransferAddition::Packet(
                outcome,
            ));
        }
        DepotStorageTransferAddition::Player(self.add_enhancement_transfer_goods(
            player,
            extend_id,
            position,
            incoming,
            self.globe_setup.pack_add_enabled(),
            context,
        ))
    }

    fn add_ground_hand_goods(
        &self,
        player: &mut CPlayer,
        position: u32,
        incoming: &mut Option<CGoods>,
    ) -> GroundHandAddition {
        if player.hand().get_goods(position).is_some() {
            let owner_progress_allows = player.current_progress() == PlayerProgress::None;
            return GroundHandAddition::Stack(player.hand_mut().merge_goods_at(
                position,
                incoming,
                &self.goods_factory,
                owner_progress_allows,
            ));
        }
        let goods = incoming.take().expect("hand add получает detached goods");
        match player.hand_mut().add_goods(goods, &self.goods_factory) {
            Ok(added) => GroundHandAddition::Added(added),
            Err(goods) => {
                *incoming = Some(goods);
                GroundHandAddition::Stack(GoodsStackMergeOutcome::Incompatible)
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn drop_player_goods_to_region<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        region_id: i32,
        source_extend_id: i32,
        source_position: u32,
        goods_id: CGuid,
        amount: u32,
        context: &mut Context,
    ) -> Result<(), GroundGoodsMoveBlock> {
        let player = self
            .find_player(player_id)
            .ok_or(GroundGoodsMoveBlock::MissingPlayer)?;
        if player.server_region_id() != Some(region_id) {
            return Err(GroundGoodsMoveBlock::RegionMismatch);
        }
        let source = match source_extend_id {
            1 => player.packet().get_goods(source_position),
            2 => player.equipment().get_goods(source_position),
            3 => player.hand().get_goods(source_position),
            4 | 5 => player.ground_currency_goods(source_extend_id),
            9 => player.depot().get_goods(source_position),
            11 => player.fairy_container().base().get_goods(source_position),
            _ => None,
        }
        .filter(|goods| goods.identity().ex_id == goods_id)
        .ok_or(GroundGoodsMoveBlock::MissingGoods)?
        .clone();
        let source_is_currency = matches!(
            source.base_properties_index(),
            index if index == self.goods_factory.get_gold_coin_index()
                || index == self.goods_factory.get_yuan_bao_index()
        );
        if source.amount() != amount
            && !source_is_currency
            && matches!(
                player.current_progress(),
                PlayerProgress::OpenStall | PlayerProgress::Trading | PlayerProgress::Upgrade
            )
        {
            return Err(GroundGoodsMoveBlock::DropBusy(player.current_progress()));
        }
        if source.amount() < amount
            || amount == 0
            || (source_extend_id == 2 && source.amount() != amount)
        {
            return Err(GroundGoodsMoveBlock::AmountMismatch);
        }
        if source.addon_property_value(&self.goods_factory, GAP_PARTICULAR_ATTRIBUTE, 1) & 0x100
            != 0
        {
            return Err(GroundGoodsMoveBlock::DropForbidden);
        }
        let origin_x = player.shape().get_tile_x().map_err(|error| {
            GroundGoodsMoveBlock::Region(RegionMembershipBlock::ShapeCoordinate(error))
        })?;
        let origin_y = player.shape().get_tile_y().map_err(|error| {
            GroundGoodsMoveBlock::Region(RegionMembershipBlock::ShapeCoordinate(error))
        })?;

        let mut owner = self
            .take_region_owner(region_id)
            .ok_or(GroundGoodsMoveBlock::MissingRegion)?;
        let (tile_x, tile_y, destination_position) =
            match owner.base().get_drop_goods_position(origin_x, origin_y, 0) {
                Ok(Some(position)) => position,
                Ok(None) => {
                    self.restore_region_owner(owner);
                    return Err(GroundGoodsMoveBlock::NoDropPosition);
                }
                Err(error) => {
                    self.restore_region_owner(owner);
                    return Err(GroundGoodsMoveBlock::Region(
                        RegionMembershipBlock::RegionCell(error),
                    ));
                }
            };
        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен непосредственно перед synchronous packet removal");
        let (
            detached,
            source_mutation,
            source_hand_mutation,
            source_currency_mutation,
            source_depot_mutation,
            source_fairy_mutation,
        ) = if source_extend_id == 1 {
            let mut split_template = source.clone();
            split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
            let Some(removed) = player.packet_mut().take_goods(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            ) else {
                self.players.insert(player_id, player);
                self.restore_region_owner(owner);
                return Err(GroundGoodsMoveBlock::PacketRemovalFailed);
            };
            match removed {
                VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Removed(removed))
                | VolumeGoodsRemoveOutcome::RemovedButCellMissing(
                    AmountLimitGoodsTaken::Removed(removed),
                ) => {
                    let mutation = EnhancementTransferRemoval::Packet {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    };
                    (removed.goods, Some(mutation), None, None, None, None)
                }
                VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Split(split))
                | VolumeGoodsRemoveOutcome::RemovedButCellMissing(AmountLimitGoodsTaken::Split(
                    split,
                )) => {
                    let mutation = EnhancementTransferRemoval::Packet {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                    };
                    (split.goods, Some(mutation), None, None, None, None)
                }
            }
        } else if source_extend_id == 2 {
            let pack_add_enabled = self.globe_setup.pack_add_enabled();
            let remove_facts =
                context.enhancement_equipment_remove_facts(&player, &source, pack_add_enabled);
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut report = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                remove_facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut report);
            let outcome = std::mem::replace(
                &mut report.outcome,
                EquipmentRemoveOutcome::Missing {
                    partial_effects: Default::default(),
                },
            );
            let removed = match outcome {
                EquipmentRemoveOutcome::Removed(removed) => removed,
                outcome => {
                    report.outcome = outcome;
                    self.players.insert(player_id, player);
                    self.restore_region_owner(owner);
                    return Err(GroundGoodsMoveBlock::EquipmentRemovalFailed(report));
                }
            };
            let mutation = EnhancementTransferRemoval::Equipment {
                event: removed.event,
            };
            (removed.goods, Some(mutation), None, None, None, None)
        } else if source_extend_id == 3 {
            let mut split_template = source.clone();
            split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
            let Some(removed) =
                player
                    .hand_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    })
            else {
                self.players.insert(player_id, player);
                self.restore_region_owner(owner);
                return Err(GroundGoodsMoveBlock::HandRemovalFailed);
            };
            match removed {
                AmountLimitGoodsTaken::Removed(removed) => {
                    let mutation = GroundHandRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: GroundHandRemovalKind::Removed,
                    };
                    (removed.goods, None, Some(mutation), None, None, None)
                }
                AmountLimitGoodsTaken::Split(split) => {
                    let mutation = GroundHandRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: GroundHandRemovalKind::Split {
                            source: split.source,
                        },
                    };
                    (split.goods, None, Some(mutation), None, None, None)
                }
            }
        } else if source_extend_id == 9 {
            let mut split_template = source.clone();
            split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
            let removed =
                player
                    .depot_mut()
                    .take_goods(source_position, amount, &self.goods_factory, |_| {
                        (split_template.identity().ex_id != CGuid::GUID_INVALID)
                            .then(|| split_template.clone())
                    });
            let Some(VolumeGoodsRemoveOutcome::Removed(taken)) = removed else {
                self.players.insert(player_id, player);
                self.restore_region_owner(owner);
                return Err(GroundGoodsMoveBlock::DepotRemovalFailed);
            };
            match taken {
                AmountLimitGoodsTaken::Removed(removed) => {
                    let mutation = DepotStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: DepotStorageRemovalKind::Removed,
                    };
                    (removed.goods, None, None, None, Some(mutation), None)
                }
                AmountLimitGoodsTaken::Split(split) => {
                    let mutation = DepotStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: DepotStorageRemovalKind::Split {
                            source: split.source,
                        },
                    };
                    (split.goods, None, None, None, Some(mutation), None)
                }
            }
        } else if source_extend_id == 11 {
            let mut split_template = source.clone();
            split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
            let outcome = player.fairy_container_mut().take(
                source_position,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            );
            let taken = match outcome {
                FairyContainerRemoveOutcome::Removed(VolumeGoodsRemoveOutcome::Removed(taken)) => {
                    taken
                }
                failed => {
                    self.players.insert(player_id, player);
                    self.restore_region_owner(owner);
                    return Err(GroundGoodsMoveBlock::FairyRemovalFailed(failed));
                }
            };
            match taken {
                AmountLimitGoodsTaken::Removed(removed) => {
                    let mutation = FairyStorageRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    };
                    (removed.goods, None, None, None, None, Some(mutation))
                }
                AmountLimitGoodsTaken::Split(split) => {
                    let mutation = FairyStorageRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position.unwrap_or(source_position),
                        amount: split.amount,
                        listeners: split.listeners,
                    };
                    (split.goods, None, None, None, None, Some(mutation))
                }
            }
        } else {
            let mut split_template = source.clone();
            split_template.set_ex_id(CGuid::create().unwrap_or(CGuid::GUID_INVALID));
            let Some(removed) = player.take_ground_currency_goods(
                source_extend_id,
                amount,
                &self.goods_factory,
                |_| {
                    (split_template.identity().ex_id != CGuid::GUID_INVALID)
                        .then(|| split_template.clone())
                },
            ) else {
                self.players.insert(player_id, player);
                self.restore_region_owner(owner);
                return Err(GroundGoodsMoveBlock::CurrencyRemovalFailed);
            };
            match removed {
                CurrencyGoodsTaken::Removed(removed) => {
                    let mutation = GroundCurrencyRemoval {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position,
                        amount: removed.amount,
                        listeners: removed.listeners,
                        kind: GroundCurrencyRemovalKind::Removed,
                    };
                    (removed.goods, None, None, Some(mutation), None, None)
                }
                CurrencyGoodsTaken::Split(split) => {
                    let mutation = GroundCurrencyRemoval {
                        owner_type: split.owner_type,
                        owner_id: split.owner_id,
                        position: split.position,
                        amount: split.amount,
                        listeners: split.listeners,
                        kind: GroundCurrencyRemovalKind::Split {
                            source: split.source,
                        },
                    };
                    (split.goods, None, None, Some(mutation), None, None)
                }
            }
        };
        let goods = detached.identity();
        let particular_attribute =
            detached.addon_property_value(&self.goods_factory, GAP_PARTICULAR_ATTRIBUTE, 1) as u32;
        let old_client_payload = context.encode_goods_for_old_client(&detached);
        let now_ms = context.now_milliseconds();
        let (area_width, area_height) = self.area_dimensions();
        if let Err((error, detached)) = owner.base_mut().add_owned_ground_goods(
            detached,
            tile_x,
            tile_y,
            particular_attribute,
            now_ms,
            area_width,
            area_height,
            context,
        ) {
            let mut incoming = Some(detached);
            let (rollback, hand_rollback, currency_rollback, depot_rollback, fairy_rollback) =
                match source_extend_id {
                    1 => (
                        Some(EnhancementTransferAddition::Packet(
                            player.packet_mut().add_goods_at(
                                source_position,
                                &mut incoming,
                                &self.goods_factory,
                                true,
                            ),
                        )),
                        None,
                        None,
                        None,
                        None,
                    ),
                    2 => (
                        Some(self.add_enhancement_transfer_goods(
                            &mut player,
                            2,
                            source_position,
                            &mut incoming,
                            self.globe_setup.pack_add_enabled(),
                            context,
                        )),
                        None,
                        None,
                        None,
                        None,
                    ),
                    3 => (
                        None,
                        Some(self.add_ground_hand_goods(
                            &mut player,
                            source_position,
                            &mut incoming,
                        )),
                        None,
                        None,
                        None,
                    ),
                    4 | 5 => (
                        None,
                        None,
                        player.add_ground_currency_goods(
                            source_extend_id,
                            &mut incoming,
                            &self.goods_factory,
                            true,
                        ),
                        None,
                        None,
                    ),
                    9 => (
                        None,
                        None,
                        None,
                        Some(self.add_depot_transfer_goods(
                            &mut player,
                            9,
                            source_position,
                            &mut incoming,
                            context,
                        )),
                        None,
                    ),
                    11 => (
                        None,
                        None,
                        None,
                        None,
                        Some(self.add_fairy_transfer_goods(
                            &mut player,
                            11,
                            source_position,
                            &mut incoming,
                            context,
                        )),
                    ),
                    _ => unreachable!("ground source extend проверен до removal"),
                };
            self.players.insert(player_id, player);
            self.restore_region_owner(owner);
            if let Some(goods) = incoming {
                return Err(GroundGoodsMoveBlock::RollbackFailed {
                    goods,
                    region_error: error,
                    source_mutation,
                    container_mutation: rollback,
                    hand_removal: source_hand_mutation,
                    hand_addition: hand_rollback,
                    currency_removal: source_currency_mutation,
                    currency_addition: currency_rollback,
                    depot_removal: source_depot_mutation,
                    depot_addition: depot_rollback,
                    fairy_removal: source_fairy_mutation,
                    fairy_addition: fairy_rollback,
                });
            }
            return Err(
                if let (Some(removal), Some(rollback)) = (source_mutation, rollback) {
                    GroundGoodsMoveBlock::ContainerRollbackCompleted {
                        region_error: error,
                        removal,
                        rollback,
                    }
                } else if let (Some(removal), Some(rollback)) =
                    (source_hand_mutation, hand_rollback)
                {
                    GroundGoodsMoveBlock::HandRollbackCompleted {
                        region_error: error,
                        removal,
                        rollback,
                    }
                } else if let (Some(removal), Some(rollback)) =
                    (source_currency_mutation, currency_rollback)
                {
                    GroundGoodsMoveBlock::CurrencyRollbackCompleted {
                        region_error: error,
                        removal,
                        rollback,
                    }
                } else if let (Some(removal), Some(rollback)) =
                    (source_depot_mutation, depot_rollback)
                {
                    GroundGoodsMoveBlock::DepotRollbackCompleted {
                        region_error: error,
                        removal,
                        rollback,
                    }
                } else {
                    GroundGoodsMoveBlock::FairyRollbackCompleted {
                        region_error: error,
                        removal: source_fairy_mutation.expect("fairy removal сохранён"),
                        rollback: fairy_rollback.expect("fairy rollback выполнен"),
                    }
                },
            );
        }
        let previous_last_operated =
            Some(player.record_last_operated_goods(source_extend_id, source_position));
        self.players.insert(player_id, player);
        self.restore_region_owner(owner);

        if self.log_system.goods_drop_to_region_log_enabled() {
            self.send_ground_goods_move_log(
                player_id,
                3,
                goods,
                if source_is_currency {
                    amount
                } else {
                    source.price()
                },
                source.name(),
                amount,
            );
        }
        if source_extend_id == 9 && self.log_system.goods_depot_get_log_enabled() {
            self.send_ground_goods_move_log(
                player_id,
                8,
                goods,
                source.price(),
                source.name(),
                amount,
            );
        }

        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(PLAYER_TYPE, player_id, source_position);
        moved.set_source_container_extend_id(source_extend_id);
        moved.set_destination_container(200, region_id, destination_position);
        moved.set_source_object(GOODS_TYPE, source.identity().ex_id, amount);
        moved.set_destination_object(GOODS_TYPE, goods.ex_id);
        moved.set_destination_object_amount(amount);
        let player_delivery = moved.send_to_player(self, player_id);

        let mut appeared = CS2CContainerObjectMove::default();
        appeared.set_operation(ContainerObjectMoveOperation::NewObject);
        appeared.set_destination_container(200, region_id, destination_position);
        appeared.set_destination_object(GOODS_TYPE, goods.ex_id);
        appeared.set_destination_object_amount(amount);
        appeared.set_object_stream(old_client_payload);
        let around_message = appeared.message();
        let around_delivery = self.send_player_shape_around(player_id, None, &around_message);
        tracing::trace!(
            player_id,
            region_id,
            ?goods,
            amount,
            source_position,
            destination_position,
            ?source_mutation,
            ?source_hand_mutation,
            ?source_currency_mutation,
            ?source_depot_mutation,
            ?source_fairy_mutation,
            ?previous_last_operated,
            player_delivery,
            ?around_delivery,
            "предмет выброшен в регион"
        );
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn pick_up_ground_goods_to_player<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        region_id: i32,
        source_position: u32,
        goods_id: CGuid,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<(), GroundGoodsMoveBlock> {
        let player = self
            .find_player(player_id)
            .ok_or(GroundGoodsMoveBlock::MissingPlayer)?;
        if player.server_region_id() != Some(region_id) {
            return Err(GroundGoodsMoveBlock::RegionMismatch);
        }
        let player_x = player.shape().get_tile_x().map_err(|error| {
            GroundGoodsMoveBlock::Region(RegionMembershipBlock::ShapeCoordinate(error))
        })?;
        let player_y = player.shape().get_tile_y().map_err(|error| {
            GroundGoodsMoveBlock::Region(RegionMembershipBlock::ShapeCoordinate(error))
        })?;
        let player_team_id = player.team_id();
        let player_current_burden = player.current_burden(&self.goods_factory);
        let player_max_burden = u32::from(player.combat_properties().burden);

        let mut owner = self
            .take_region_owner(region_id)
            .ok_or(GroundGoodsMoveBlock::MissingRegion)?;
        let Some(ground) = owner.base().find_ground_goods(goods_id) else {
            self.restore_region_owner(owner);
            return Err(GroundGoodsMoveBlock::MissingGoods);
        };
        let ground_x = match ground.shape().get_tile_x() {
            Ok(value) => value,
            Err(error) => {
                self.restore_region_owner(owner);
                return Err(GroundGoodsMoveBlock::Region(
                    RegionMembershipBlock::ShapeCoordinate(error),
                ));
            }
        };
        let ground_y = match ground.shape().get_tile_y() {
            Ok(value) => value,
            Err(error) => {
                self.restore_region_owner(owner);
                return Err(GroundGoodsMoveBlock::Region(
                    RegionMembershipBlock::ShapeCoordinate(error),
                ));
            }
        };
        if ground_x.abs_diff(player_x) >= 2 || ground_y.abs_diff(player_y) >= 2 {
            self.restore_region_owner(owner);
            return Err(GroundGoodsMoveBlock::PickupOutOfRange);
        }
        if !owner
            .base()
            .can_pick_up_ground_goods(goods_id, player_id, player_team_id)
        {
            self.restore_region_owner(owner);
            return Err(GroundGoodsMoveBlock::PickupProtected);
        }
        let burden_exceeded = matches!(destination_extend_id, 1 | 2)
            && player_current_burden.wrapping_add(ground.weight(&self.goods_factory))
                > player_max_burden;
        let amount = ground.amount();
        let audit_base_index = ground.base_properties_index();
        let audit_price = ground.price();
        let audit_name = ground.name().to_vec();
        let particular_attribute =
            ground.addon_property_value(&self.goods_factory, GAP_PARTICULAR_ATTRIBUTE, 1) as u32;
        let (destination_extend_id, destination_position) =
            if matches!(destination_extend_id, 1 | 2) {
                (destination_extend_id, destination_position)
            } else if audit_base_index == self.goods_factory.get_gold_coin_index() {
                (4, 0)
            } else if audit_base_index == self.goods_factory.get_yuan_bao_index() {
                (5, 0)
            } else {
                (destination_extend_id, destination_position)
            };
        let detached = match owner
            .base_mut()
            .remove_owned_ground_goods(goods_id, particular_attribute)
        {
            Ok(Some(goods)) => goods,
            Ok(None) => {
                self.restore_region_owner(owner);
                return Err(GroundGoodsMoveBlock::MissingGoods);
            }
            Err(error) => {
                self.restore_region_owner(owner);
                return Err(GroundGoodsMoveBlock::Region(error));
            }
        };
        if burden_exceeded {
            let now_ms = context.now_milliseconds();
            let (area_width, area_height) = self.area_dimensions();
            let rollback = owner.base_mut().add_owned_ground_goods(
                detached,
                ground_x,
                ground_y,
                particular_attribute,
                now_ms,
                area_width,
                area_height,
                context,
            );
            self.restore_region_owner(owner);
            if let Err((error, goods)) = rollback {
                return Err(GroundGoodsMoveBlock::RollbackFailed {
                    goods,
                    region_error: error,
                    source_mutation: None,
                    container_mutation: None,
                    hand_removal: None,
                    hand_addition: None,
                    currency_removal: None,
                    currency_addition: None,
                    depot_removal: None,
                    depot_addition: None,
                    fairy_removal: None,
                    fairy_addition: None,
                });
            }
            return Err(GroundGoodsMoveBlock::BurdenExceeded);
        }

        let mut player = self
            .players
            .remove(&player_id)
            .expect("player проверен непосредственно перед synchronous container add");
        let mut incoming = Some(detached);
        let (
            destination_mutation,
            destination_hand_mutation,
            destination_currency_mutation,
            destination_depot_mutation,
            destination_fairy_mutation,
        ) = if destination_extend_id == 1 {
            let addition = if destination_position == u32::MAX {
                player
                    .packet_mut()
                    .add_goods(&mut incoming, &self.goods_factory, true)
            } else {
                player.packet_mut().add_goods_at(
                    destination_position,
                    &mut incoming,
                    &self.goods_factory,
                    true,
                )
            };
            (
                Some(EnhancementTransferAddition::Packet(addition)),
                None,
                None,
                None,
                None,
            )
        } else if destination_extend_id == 2 {
            (
                Some(self.add_enhancement_transfer_goods(
                    &mut player,
                    2,
                    destination_position,
                    &mut incoming,
                    self.globe_setup.pack_add_enabled(),
                    context,
                )),
                None,
                None,
                None,
                None,
            )
        } else if destination_extend_id == 3 {
            (
                None,
                Some(self.add_ground_hand_goods(&mut player, destination_position, &mut incoming)),
                None,
                None,
                None,
            )
        } else if destination_extend_id == 9 {
            (
                None,
                None,
                None,
                Some(self.add_depot_transfer_goods(
                    &mut player,
                    9,
                    destination_position,
                    &mut incoming,
                    context,
                )),
                None,
            )
        } else if destination_extend_id == 11 {
            (
                None,
                None,
                None,
                None,
                Some(self.add_fairy_transfer_goods(
                    &mut player,
                    11,
                    destination_position,
                    &mut incoming,
                    context,
                )),
            )
        } else {
            let owner_progress_allows = player.current_progress() == PlayerProgress::None;
            (
                None,
                None,
                player.add_ground_currency_goods(
                    destination_extend_id,
                    &mut incoming,
                    &self.goods_factory,
                    owner_progress_allows,
                ),
                None,
                None,
            )
        };
        if incoming.is_some() {
            let detached = incoming
                .take()
                .expect("rejected container add сохраняет ground goods owner");
            let now_ms = context.now_milliseconds();
            let (area_width, area_height) = self.area_dimensions();
            let rollback = owner.base_mut().add_owned_ground_goods(
                detached,
                ground_x,
                ground_y,
                particular_attribute,
                now_ms,
                area_width,
                area_height,
                context,
            );
            self.players.insert(player_id, player);
            self.restore_region_owner(owner);
            if let Err((error, goods)) = rollback {
                return Err(GroundGoodsMoveBlock::RollbackFailed {
                    goods,
                    region_error: error,
                    source_mutation: None,
                    container_mutation: destination_mutation.clone(),
                    hand_removal: None,
                    hand_addition: destination_hand_mutation.clone(),
                    currency_removal: None,
                    currency_addition: destination_currency_mutation.clone(),
                    depot_removal: None,
                    depot_addition: destination_depot_mutation.clone(),
                    fairy_removal: None,
                    fairy_addition: destination_fairy_mutation.clone(),
                });
            }
            return Err(
                match (
                    destination_mutation,
                    destination_hand_mutation,
                    destination_currency_mutation,
                    destination_depot_mutation,
                    destination_fairy_mutation,
                ) {
                    (Some(EnhancementTransferAddition::Packet(_)), _, _, _, _) => {
                        GroundGoodsMoveBlock::PacketAdditionRejected
                    }
                    (Some(EnhancementTransferAddition::Equipment(report)), _, _, _, _) => {
                        GroundGoodsMoveBlock::EquipmentAdditionRejected(report)
                    }
                    (None, Some(_), _, _, _) => GroundGoodsMoveBlock::HandAdditionRejected,
                    (None, None, Some(outcome), _, _) => {
                        GroundGoodsMoveBlock::CurrencyAdditionRejected(outcome)
                    }
                    (None, None, None, Some(outcome), _) => {
                        GroundGoodsMoveBlock::DepotAdditionRejected(outcome)
                    }
                    (None, None, None, None, Some(outcome)) => {
                        GroundGoodsMoveBlock::FairyAdditionRejected(outcome)
                    }
                    _ => unreachable!("ground destination mutation получена"),
                },
            );
        }
        let (actual_destination_position, destination_goods, destination_amount) = match (
            &destination_mutation,
            &destination_hand_mutation,
            &destination_currency_mutation,
            &destination_depot_mutation,
            &destination_fairy_mutation,
        ) {
            (Some(EnhancementTransferAddition::Packet(addition)), _, _, _, _) => match addition {
                VolumeGoodsAddOutcome::Added(added) => {
                    let position = added.position.unwrap_or(destination_position);
                    let stored = player
                        .packet()
                        .get_goods(position)
                        .expect("успешный packet add публикует destination goods");
                    (position, stored.identity(), stored.amount())
                }
                VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged { target, .. }) => {
                    let position = player
                        .packet()
                        .query_goods_position(target.ex_id)
                        .expect("успешный stack сохраняет destination cell");
                    let stored = player
                        .packet()
                        .get_goods(position)
                        .expect("успешный stack сохраняет destination goods");
                    (position, stored.identity(), stored.amount())
                }
                VolumeGoodsAddOutcome::Stack(_) | VolumeGoodsAddOutcome::Rejected(_) => {
                    unreachable!("успешный packet add обязан забрать incoming goods")
                }
            },
            (Some(EnhancementTransferAddition::Equipment(report)), _, _, _, _) => {
                match &report.outcome {
                    EquipmentAddOutcome::Added(added) => {
                        (added.column.position(), added.identity, added.amount)
                    }
                    EquipmentAddOutcome::Blocked(_) => {
                        unreachable!("успешный equipment add обязан забрать incoming goods")
                    }
                }
            }
            (None, Some(GroundHandAddition::Added(added)), _, _, _) => (
                added.position.unwrap_or(destination_position),
                added.identity,
                added.amount,
            ),
            (
                None,
                Some(GroundHandAddition::Stack(GoodsStackMergeOutcome::Merged { target, .. })),
                _,
                _,
                _,
            ) => {
                let stored = player
                    .hand()
                    .find(target.ex_id)
                    .expect("успешный hand stack сохраняет target");
                (destination_position, stored.identity(), stored.amount())
            }
            (None, None, Some(CurrencyGoodsAddOutcome::Added(added)), _, _) => {
                (added.position, added.identity, added.amount)
            }
            (
                None,
                None,
                Some(CurrencyGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                    target, ..
                })),
                _,
                _,
            ) => {
                let stored = player
                    .ground_currency_goods(destination_extend_id)
                    .expect("успешный currency stack сохраняет target");
                debug_assert_eq!(stored.identity(), *target);
                (0, stored.identity(), stored.amount())
            }
            (None, None, None, Some(addition), _) => {
                Self::depot_transfer_destination(&player, destination_position, addition)
            }
            (None, None, None, None, Some(addition)) => {
                Self::fairy_transfer_destination(&player, destination_position, addition)
            }
            _ => unreachable!("успешный destination add забирает incoming goods"),
        };
        self.players.insert(player_id, player);
        self.restore_region_owner(owner);

        if self.log_system.goods_get_from_region_log_enabled()
            && self.log_system.is_log_item(audit_base_index as i32)
        {
            self.send_ground_goods_move_log(
                player_id,
                0,
                ShapeIdentity {
                    object_type: GOODS_TYPE,
                    id: 0,
                    ex_id: goods_id,
                },
                if matches!(
                    audit_base_index,
                    index if index == self.goods_factory.get_gold_coin_index()
                        || index == self.goods_factory.get_yuan_bao_index()
                ) {
                    amount
                } else {
                    audit_price
                },
                &audit_name,
                amount,
            );
        }
        if destination_extend_id == 9 && self.log_system.goods_depot_set_log_enabled() {
            self.send_ground_goods_move_log(
                player_id,
                7,
                ShapeIdentity {
                    object_type: GOODS_TYPE,
                    id: 0,
                    ex_id: goods_id,
                },
                audit_price,
                &audit_name,
                amount,
            );
        }

        let mut moved = CS2CContainerObjectMove::default();
        moved.set_operation(ContainerObjectMoveOperation::MoveObject);
        moved.set_source_container(200, region_id, source_position);
        moved.set_destination_container(PLAYER_TYPE, player_id, actual_destination_position);
        moved.set_destination_container_extend_id(destination_extend_id);
        moved.set_source_object(GOODS_TYPE, goods_id, amount);
        moved.set_destination_object(GOODS_TYPE, destination_goods.ex_id);
        moved.set_destination_object_amount(destination_amount);
        let player_delivery = moved.send_to_player(self, player_id);

        let mut disappeared = CS2CContainerObjectMove::default();
        disappeared.set_operation(ContainerObjectMoveOperation::DeleteObject);
        disappeared.set_source_container(200, region_id, source_position);
        disappeared.set_source_object(GOODS_TYPE, goods_id, amount);
        let around_message = disappeared.message();
        let around_delivery = self.send_player_shape_around(player_id, None, &around_message);
        tracing::trace!(player_id, region_id, goods_id = ?goods_id, amount, source_position, destination_position = actual_destination_position, ?destination_goods, destination_amount, ?destination_mutation, ?destination_hand_mutation, ?destination_currency_mutation, ?destination_depot_mutation, ?destination_fairy_mutation, player_delivery, ?around_delivery, "предмет подобран из региона");
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn transfer_player_enhancement_goods_inner<Context: GameContainerMessageRuntime>(
        &self,
        player: &mut CPlayer,
        shadow_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<EnhancementTransferReport, EnhancementTransferBlock> {
        let source = player
            .enhancement_original_container(shadow_position, goods_id)
            .ok_or(EnhancementTransferBlock::MissingShadow)?;
        if !matches!(source.container_extend_id, 1 | 2) {
            return Err(EnhancementTransferBlock::UnsupportedSourceContainer {
                extend_id: source.container_extend_id,
            });
        }
        let goods = match source.container_extend_id {
            1 => player.packet().get_goods(source.goods_position),
            2 => player.equipment().get_goods(source.goods_position),
            _ => unreachable!("source extend проверен выше"),
        }
        .filter(|goods| goods.identity().ex_id == goods_id && goods.amount() == amount)
        .ok_or(EnhancementTransferBlock::MissingSourceGoods)?;
        let goods_identity = goods.identity();
        let pack_add_enabled = self.globe_setup.pack_add_enabled();

        let (removal, mut incoming) = if source.container_extend_id == 1 {
            let removed = player
                .packet_mut()
                .remove_goods(goods_id)
                .ok_or(EnhancementTransferBlock::PacketRemovalFailed)?;
            let removed = match removed {
                VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Removed(removed)) => {
                    removed
                }
                VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Split(_))
                | VolumeGoodsRemoveOutcome::RemovedButCellMissing(_) => {
                    return Err(EnhancementTransferBlock::PacketRemovalFailed);
                }
            };
            let removal = EnhancementTransferRemoval::Packet {
                owner_type: removed.owner_type,
                owner_id: removed.owner_id,
                position: removed.position.unwrap_or(source.goods_position),
                amount: removed.amount,
                listeners: removed.listeners,
            };
            (removal, Some(removed.goods))
        } else {
            let remove_facts =
                context.enhancement_equipment_remove_facts(player, goods, pack_add_enabled);
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut report = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                remove_facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut report);
            let outcome = std::mem::replace(
                &mut report.outcome,
                EquipmentRemoveOutcome::Missing {
                    partial_effects: Default::default(),
                },
            );
            let removed = match outcome {
                EquipmentRemoveOutcome::Removed(removed) => removed,
                outcome => {
                    report.outcome = outcome;
                    return Err(EnhancementTransferBlock::EquipmentRemovalFailed(report));
                }
            };
            let removal = EnhancementTransferRemoval::Equipment {
                event: removed.event,
            };
            (removal, Some(removed.goods))
        };

        let shadow = player
            .enhancement_remove_shadow(goods_id)
            .expect("shadow проверен до удаления source goods");
        let delete_shadow_delivery =
            send_enhancement_shadow_deleted(self, player.player_id(), goods_identity, &shadow);
        let destination = self.add_enhancement_transfer_goods(
            player,
            destination_extend_id,
            destination_position,
            &mut incoming,
            pack_add_enabled,
            context,
        );
        let outcome = if incoming.is_none() {
            EnhancementTransferOutcome::Moved(destination)
        } else {
            let rejected = destination;
            let rollback = self.add_enhancement_transfer_goods(
                player,
                source.container_extend_id,
                source.goods_position,
                &mut incoming,
                pack_add_enabled,
                context,
            );
            if incoming.is_none() {
                EnhancementTransferOutcome::RolledBack {
                    rejected,
                    restored: rollback,
                }
            } else {
                let goods = incoming
                    .take()
                    .expect("неуспешный rollback сохраняет detached goods");
                let notification_delivery = send_enhancement_goods_collected(
                    self,
                    player.player_id(),
                    goods.name(),
                    goods.amount(),
                );
                let goods = goods.identity();
                EnhancementTransferOutcome::GoodsCollected {
                    rejected,
                    rollback,
                    goods,
                    notification_delivery,
                }
            }
        };
        Ok(EnhancementTransferReport {
            goods: goods_identity,
            source,
            removal,
            shadow,
            delete_shadow_delivery,
            outcome,
        })
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn transfer_player_equipment_session_goods<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        session_id: i32,
        session_extend_id: i32,
        shadow_position: u32,
        goods_id: CGuid,
        amount: u32,
        destination_extend_id: i32,
        destination_position: u32,
        context: &mut Context,
    ) -> Result<EnhancementTransferReport, EnhancementTransferBlock> {
        if !matches!(destination_extend_id, 1 | 2) {
            return Err(EnhancementTransferBlock::UnsupportedDestinationContainer {
                extend_id: destination_extend_id,
            });
        }
        let source = self
            .session_factory
            .equipment_session_shadow_original(session_id, session_extend_id, player_id, goods_id)
            .ok_or(EnhancementTransferBlock::MissingShadow)?;
        let recorded_position = self
            .session_factory
            .equipment_session_shadow_position(session_id, session_extend_id, player_id, goods_id)
            .ok_or(EnhancementTransferBlock::MissingShadow)?;
        if recorded_position != shadow_position
            || source.container_type != 400
            || source.container_id != player_id
        {
            return Err(EnhancementTransferBlock::MissingShadow);
        }
        if !matches!(source.container_extend_id, 1 | 2) {
            return Err(EnhancementTransferBlock::UnsupportedSourceContainer {
                extend_id: source.container_extend_id,
            });
        }

        let mut player = self
            .players
            .remove(&player_id)
            .ok_or(EnhancementTransferBlock::MissingPlayer)?;
        let result = (|| {
            let goods = match source.container_extend_id {
                1 => player.packet().get_goods(source.goods_position),
                2 => player.equipment().get_goods(source.goods_position),
                _ => unreachable!("source extend проверен выше"),
            }
            .filter(|goods| goods.identity().ex_id == goods_id && goods.amount() == amount)
            .ok_or(EnhancementTransferBlock::MissingSourceGoods)?;
            let goods_identity = goods.identity();
            let pack_add_enabled = self.globe_setup.pack_add_enabled();

            let (removal, mut incoming) = if source.container_extend_id == 1 {
                let removed = player
                    .packet_mut()
                    .remove_goods(goods_id)
                    .ok_or(EnhancementTransferBlock::PacketRemovalFailed)?;
                let removed = match removed {
                    VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Removed(removed)) => {
                        removed
                    }
                    VolumeGoodsRemoveOutcome::Removed(AmountLimitGoodsTaken::Split(_))
                    | VolumeGoodsRemoveOutcome::RemovedButCellMissing(_) => {
                        return Err(EnhancementTransferBlock::PacketRemovalFailed);
                    }
                };
                (
                    EnhancementTransferRemoval::Packet {
                        owner_type: removed.owner_type,
                        owner_id: removed.owner_id,
                        position: removed.position.unwrap_or(source.goods_position),
                        amount: removed.amount,
                        listeners: removed.listeners,
                    },
                    Some(removed.goods),
                )
            } else {
                let remove_facts =
                    context.enhancement_equipment_remove_facts(&player, goods, pack_add_enabled);
                let mut recompute =
                    |player: &CPlayer| context.recompute_enhancement_player_properties(player);
                let mut report = player.remove_equipment_goods(
                    goods_id,
                    &self.goods_factory,
                    &self.skill_factory,
                    remove_facts,
                    &mut recompute,
                );
                drop(recompute);
                self.publish_player_equipment_remove_report(&mut report);
                let outcome = std::mem::replace(
                    &mut report.outcome,
                    EquipmentRemoveOutcome::Missing {
                        partial_effects: Default::default(),
                    },
                );
                let removed = match outcome {
                    EquipmentRemoveOutcome::Removed(removed) => removed,
                    outcome => {
                        report.outcome = outcome;
                        return Err(EnhancementTransferBlock::EquipmentRemovalFailed(report));
                    }
                };
                (
                    EnhancementTransferRemoval::Equipment {
                        event: removed.event,
                    },
                    Some(removed.goods),
                )
            };

            let shadow = self
                .session_factory
                .remove_equipment_session_shadow(session_id, session_extend_id, player_id, goods_id)
                .expect("session shadow проверен до удаления source goods")
                .removed;
            let delete_shadow_delivery =
                send_enhancement_shadow_deleted(self, player_id, goods_identity, &shadow);
            let destination = self.add_enhancement_transfer_goods(
                &mut player,
                destination_extend_id,
                destination_position,
                &mut incoming,
                pack_add_enabled,
                context,
            );
            let outcome = if incoming.is_none() {
                EnhancementTransferOutcome::Moved(destination)
            } else {
                let rejected = destination;
                let rollback = self.add_enhancement_transfer_goods(
                    &mut player,
                    source.container_extend_id,
                    source.goods_position,
                    &mut incoming,
                    pack_add_enabled,
                    context,
                );
                if incoming.is_none() {
                    EnhancementTransferOutcome::RolledBack {
                        rejected,
                        restored: rollback,
                    }
                } else {
                    let goods = incoming
                        .take()
                        .expect("неуспешный rollback сохраняет detached goods");
                    let notification_delivery = send_enhancement_goods_collected(
                        self,
                        player_id,
                        goods.name(),
                        goods.amount(),
                    );
                    EnhancementTransferOutcome::GoodsCollected {
                        rejected,
                        rollback,
                        goods: goods.identity(),
                        notification_delivery,
                    }
                }
            };
            Ok(EnhancementTransferReport {
                goods: goods_identity,
                source,
                removal,
                shadow,
                delete_shadow_delivery,
                outcome,
            })
        })();
        self.players.insert(player_id, player);
        result
    }

    fn add_enhancement_transfer_goods<Context: GameContainerMessageRuntime>(
        &self,
        player: &mut CPlayer,
        extend_id: i32,
        position: u32,
        incoming: &mut Option<CGoods>,
        pack_add_enabled: bool,
        context: &mut Context,
    ) -> EnhancementTransferAddition {
        if extend_id == 1 {
            let owner_progress_allows = player.current_progress() == PlayerProgress::None;
            return EnhancementTransferAddition::Packet(player.packet_mut().add_goods_at(
                position,
                incoming,
                &self.goods_factory,
                owner_progress_allows,
            ));
        }
        let add_facts = context.enhancement_equipment_add_facts(
            player,
            incoming
                .as_ref()
                .expect("destination/rollback add получает detached goods"),
            pack_add_enabled,
        );
        let mut goods_ai_ids = Vec::new();
        let mut report = {
            let context_cell = std::cell::RefCell::new(&mut *context);
            let mut register = |goods: &CGoods| {
                goods_ai_ids.push(goods.identity().ex_id);
            };
            let mut recompute = |player: &CPlayer| {
                context_cell
                    .borrow_mut()
                    .recompute_enhancement_player_properties(player)
            };
            player.add_equipment_goods(
                position,
                incoming,
                &self.goods_factory,
                &self.skill_factory,
                add_facts,
                &mut register,
                &mut recompute,
            )
        };
        for goods_id in goods_ai_ids {
            Self::register_player_goods_ai(player, &self.goods_factory, goods_id);
        }
        self.publish_player_equipment_add_report(&mut report);
        EnhancementTransferAddition::Equipment(report)
    }

    /// Создаёт достигнутый GameServer goods core; исходный код игнорировал
    /// ошибку `CoCreateGuid`, поэтому failure оставляет нулевой GUID.
    pub(crate) fn create_goods_core(&mut self, goods_index: u32) -> Option<CGoods> {
        let random_state = &mut self.random_state;
        self.goods_factory.create_goods_core(
            goods_index,
            |upper_bound| game_legacy_random(random_state, upper_bound),
            || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
        )
    }

    /// Общий exact overload `CreateGoods(index, amount, vector)` с теми же
    /// Game RNG, GUID и fairy threshold owner-ами, что и остальные callers.
    pub(crate) fn create_goods_batch(&mut self, goods_index: u32, amount: u32) -> Vec<CGoods> {
        let (random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
            &mut self.random_state,
            &self.goods_factory,
            &self.fairy_exp_conf,
            &self.battle_fairy_exp_config,
        );
        let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
        goods_factory.create_goods_batch(
            goods_index,
            amount,
            &mut random,
            || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
            |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
            |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
        )
    }

    /// Достигнутый `AddGoods(name, amount, upgrade, particular)` готовит весь
    /// batch до передачи packet owner-у. Upgrade использует тот же Game RNG,
    /// particular attribute пишет modifier первой instance-пары, как native
    /// `SetAddonPropertyModifier`.
    pub(crate) fn create_script_goods_batch(
        &mut self,
        goods_index: u32,
        amount: u32,
        upgrade_level: i32,
        particular_attribute: i32,
    ) -> Vec<CGoods> {
        let mut goods = self.create_goods_batch(goods_index, amount);
        let (factory, random_state) = (&self.goods_factory, &mut self.random_state);
        for item in &mut goods {
            if upgrade_level != 0 {
                let _ = factory.upgrade_equipment(item, upgrade_level, |upper_bound| {
                    game_legacy_random(random_state, upper_bound)
                });
            }
            if particular_attribute != 0 {
                let _ = item.set_addon_property_modifier_core(
                    GAP_PARTICULAR_ATTRIBUTE,
                    1,
                    particular_attribute,
                );
            }
        }
        goods
    }

    /// Полный проход `9605 / AddTimeGoods`: каждый созданный предмет получает
    /// свойства в исходном порядке, отдельно проходит добавление в сумку и
    /// публикует результат до перехода к следующему предмету.
    pub(crate) fn add_script_timed_goods<Context, EvaluateSockets>(
        &mut self,
        player_id: i32,
        original_name: &[u8],
        goods_index: u32,
        parameters: ScriptTimedGoodsParameters,
        context: &mut Context,
        mut evaluate_sockets: EvaluateSockets,
    ) -> i32
    where
        Context: OldClientGoodsCodec,
        EvaluateSockets: FnMut(&mut Self, &mut Context) -> Option<[(i32, i32); 10]>,
    {
        if !self.players.contains_key(&player_id) {
            return 0;
        }
        let created = self.create_goods_batch(goods_index, parameters.amount);
        for mut goods in created {
            if goods.addon_property_value(&self.goods_factory, GAP_BF_BATTLE_FAIRY, 1) == 1 {
                let initialized = {
                    let (players, factory, skill_factory) =
                        (&mut self.players, &self.goods_factory, &self.skill_factory);
                    let player = players
                        .get_mut(&player_id)
                        .expect("игрок проверен перед LoadBFDefualtProperty");
                    let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
                    player.initialize_script_battle_fairy_goods(
                        &mut goods,
                        factory,
                        skill_factory,
                        &mut encode,
                    )
                };
                if let Some((goods_update, skills)) = initialized {
                    for skill in skills {
                        if let Some(message) = player_skill_learned_message(
                            skill.message_type,
                            skill.skill_id,
                            skill.skill_level,
                            skill.skill_level,
                            &skill.skill_name,
                            &self.skill_factory,
                            false,
                        ) {
                            let _ = message.send_to_player(self.net_server(), skill.player_id);
                        }
                    }
                    let _ = self.send_battle_fairy_goods_update(&goods_update);
                }
            }

            if parameters.upgrade_level != 0 {
                let (factory, random_state) = (&self.goods_factory, &mut self.random_state);
                let _ =
                    factory.upgrade_equipment(&mut goods, parameters.upgrade_level, |maximum| {
                        game_legacy_random(random_state, maximum)
                    });
            }
            if parameters.particular_attribute != 0 {
                let _ = goods.set_addon_property_modifier_core(
                    GAP_PARTICULAR_ATTRIBUTE,
                    1,
                    parameters.particular_attribute,
                );
            }
            if parameters.item_quality != 0 {
                let _ = goods.set_addon_property_modifier_core(
                    GAP_ITEM_QUALITY,
                    1,
                    parameters.item_quality,
                );
                let text = format_legacy_text_fields(
                    self.get_string_by_id(b"ZHGS0043"),
                    &[original_name],
                    0xff,
                );
                add_game_log_text(&text);
            }
            if parameters.equipment_active != 0 {
                let _ = goods.set_addon_property_modifier_core(
                    GAP_EQUIP_ACTIVE,
                    2,
                    parameters.equipment_active,
                );
            }
            if parameters.anima_bind != 0 {
                let _ = goods.set_addon_property_modifier_core(
                    GAP_ANIMA_BIND,
                    2,
                    parameters.anima_bind,
                );
            }
            if parameters.anima_bind_enabled {
                let _ = goods.set_addon_property_modifier_core(GAP_ANIMA_BIND, 1, 1);
            }
            if parameters.equipment_state != 0 {
                let _ = goods.set_addon_property_modifier_core(
                    GAP_EQUIP_STATE,
                    1,
                    parameters.equipment_state,
                );
            }
            if parameters.equipment_state_value != 0 {
                let _ = goods.set_addon_property_modifier_core(
                    GAP_EQUIP_STATE,
                    2,
                    parameters.equipment_state_value,
                );
            }

            if goods.query_attribute(GAP_DAKONG_1)
                && let Some(mut sockets) = evaluate_sockets(self, context)
            {
                for (socket, (color, gem_index)) in sockets.iter_mut().enumerate() {
                    if *gem_index == 1 {
                        let (setup, random_state) =
                            (&self.da_kong_xiang_qian, &mut self.random_state);
                        *color = setup
                            .get_color(socket as i32, |maximum| {
                                game_legacy_random(random_state, maximum)
                            })
                            .wrapping_add(2);
                        *gem_index = 0;
                        if socket == 6 {
                            *color = 8;
                        }
                    }
                    let property = GAP_DAKONG_1 + socket as i32;
                    let _ = goods.set_addon_property_value_core(property, 1, *color);
                    let _ = goods.set_addon_property_modifier_core(property, 2, *gem_index);
                }
                let (factory, setup, random_state) = (
                    &self.goods_factory,
                    &self.da_kong_xiang_qian,
                    &mut self.random_state,
                );
                factory.da_kong_xiang_qian(&mut goods, setup, |maximum| {
                    game_legacy_random(random_state, maximum)
                });
            }

            goods.set_goods_time_type(parameters.time_type);
            goods.set_goods_lifetime(parameters.lifetime);
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            let Some((additions, _rejected)) =
                self.add_goods_to_player_packet(player_id, vec![goods], &mut encode)
            else {
                continue;
            };
            for addition in &additions {
                if let VolumeGoodsAddOutcome::Added(added) = &addition.outcome {
                    let _ = self.players.get_mut(&player_id).is_some_and(|player| {
                        player.register_goods_ai_by_id(
                            added.identity.ex_id,
                            &self.goods_factory,
                            game_wall_time_seconds(),
                        )
                    });
                }
                let _ = self.send_player_packet_addition(addition);
            }
        }
        1
    }

