    pub(crate) fn open_script_npc_shop(
        &mut self,
        player_id: i32,
        npc_id: i32,
        trade_name: &[u8],
    ) -> ScriptNpcShopOpenOutcome {
        let Some(player) = self.find_player(player_id) else {
            tracing::trace!(player_id, npc_id, "игрок сценарного магазина не найден");
            return ScriptNpcShopOpenOutcome::MissingContext;
        };
        if player.current_progress() != PlayerProgress::None {
            tracing::trace!(
                player_id,
                npc_id,
                "игрок занят при открытии сценарного магазина"
            );
            return ScriptNpcShopOpenOutcome::Busy;
        }
        let Some(trade) = self.trade_list.get_trade(trade_name) else {
            tracing::trace!(
                player_id,
                npc_id,
                "торговый список сценарного магазина не найден"
            );
            return ScriptNpcShopOpenOutcome::MissingTrade;
        };
        let Ok(goods_count) = i32::try_from(trade.goods().len()) else {
            tracing::warn!(
                player_id,
                npc_id,
                "торговый список сценарного магазина не помещается в wire-счётчик"
            );
            return ScriptNpcShopOpenOutcome::InvalidTradeGoods;
        };
        let mut message = CMessage::new(0x000b_fa01);
        message.add_long(npc_id);
        message.add_long(goods_count);
        for goods in trade.goods() {
            let Some(properties) = self
                .goods_factory
                .query_goods_base_properties(goods.goods_id)
            else {
                tracing::warn!(
                    player_id,
                    npc_id,
                    goods_id = goods.goods_id,
                    "базовые свойства товара сценарного магазина не найдены"
                );
                return ScriptNpcShopOpenOutcome::InvalidTradeGoods;
            };
            if goods.page >= 4
                || goods.position_x >= 8
                || goods.position_y >= 11
                || goods.amount == 0
            {
                tracing::warn!(
                    player_id,
                    npc_id,
                    goods_id = goods.goods_id,
                    "товар сценарного магазина имеет недопустимые координаты или количество"
                );
                return ScriptNpcShopOpenOutcome::InvalidTradeGoods;
            }
            message.add_byte(goods.page);
            message.add_byte(goods.position_x);
            message.add_byte(goods.position_y);
            message.add_byte(goods.amount);
            message.add_ulong(properties.price());
            message.add_ulong(properties.weight());
            message.add_ulong(goods.goods_id);
        }
        let transition = self
            .find_player_mut(player_id)
            .map(|player| player.begin_equipment_session(PlayerProgress::Shopping, true));
        let delivery = message.send_to_player(self.net_server(), player_id);
        if delivery == 0 {
            let rollback = self
                .find_player_mut(player_id)
                .map(|player| player.release_goods_session_state());
            tracing::warn!(
                player_id,
                npc_id,
                delivery,
                ?transition,
                ?rollback,
                "отправка открытия сценарного магазина завершилась ошибкой"
            );
            return ScriptNpcShopOpenOutcome::SendFailed;
        }
        tracing::trace!(
            player_id,
            npc_id,
            delivery,
            ?transition,
            "сценарный магазин открыт"
        );
        ScriptNpcShopOpenOutcome::Opened
    }

    pub(crate) fn open_script_depot(&mut self, player_id: i32) -> ScriptDepotOpenOutcome {
        let Some(player) = self.find_player(player_id) else {
            tracing::trace!(player_id, "игрок сценарного склада не найден");
            return ScriptDepotOpenOutcome::MissingPlayer;
        };
        if player.current_progress() != PlayerProgress::None {
            tracing::trace!(player_id, "игрок занят при открытии сценарного склада");
            return ScriptDepotOpenOutcome::Busy;
        }
        let goods_amount = player.depot().goods_amount(&self.goods_factory);
        if goods_amount > 96 {
            tracing::warn!(
                player_id,
                goods_amount,
                "число товаров сценарного склада превышает wire-предел"
            );
            return ScriptDepotOpenOutcome::TooManyGoods;
        }
        let password_required = !player.depot_password().is_empty();
        self.find_player_mut(player_id)
            .expect("игрок проверен до подготовки склада")
            .prepare_depot_storage(password_required);

        let (depot_money, bank_guid, snapshots) = {
            let player = self
                .find_player(player_id)
                .expect("игрок сохраняется во время снимка склада");
            let snapshots = player
                .depot()
                .snapshot_goods()
                .map(|(position, goods)| (position, goods.clone()))
                .collect::<Vec<_>>();
            (
                player.depot_money(),
                player
                    .bank_snapshot_goods(0)
                    .map_or(CGuid::GUID_INVALID, |goods| goods.identity().ex_id),
                snapshots,
            )
        };
        let mut message = CMessage::new(0x000b_fb01);
        message.add_byte(u8::from(password_required));
        message.add_ulong(depot_money);
        message.base_mut().add_guid(bank_guid);
        message.add_byte(goods_amount as u8);
        for (position, goods) in snapshots {
            let Some(properties) = self
                .goods_factory
                .query_goods_base_properties(goods.base_properties_index())
            else {
                self.find_player_mut(player_id)
                    .expect("игрок сохраняется при отказе снимка склада")
                    .close_depot_storage();
                tracing::warn!(
                    player_id,
                    goods_amount,
                    "базовые свойства товара сценарного склада не найдены"
                );
                return ScriptDepotOpenOutcome::InvalidGoods;
            };
            if goods.amount() == 0 || goods.amount() > u16::MAX as u32 || position >= 96 {
                self.find_player_mut(player_id)
                    .expect("игрок сохраняется при отказе снимка склада")
                    .close_depot_storage();
                tracing::warn!(
                    player_id,
                    goods_amount,
                    position,
                    amount = goods.amount(),
                    "товар сценарного склада не помещается в wire-поля"
                );
                return ScriptDepotOpenOutcome::InvalidGoods;
            }
            let mut payload = Vec::new();
            if !goods.serialize_for_old_client(&mut payload, &self.goods_factory, true) {
                self.find_player_mut(player_id)
                    .expect("игрок сохраняется при отказе снимка склада")
                    .close_depot_storage();
                tracing::warn!(
                    player_id,
                    goods_amount,
                    position,
                    "товар сценарного склада не сериализован для старого клиента"
                );
                return ScriptDepotOpenOutcome::InvalidGoods;
            }
            message.add_byte(u8::from(properties.goods_type() == GOODS_TYPE_EQUIPMENT));
            message.add_short(goods.amount() as i16);
            message.add_byte(position as u8);
            message.base_mut().add(&payload);
        }
        self.find_player_mut(player_id)
            .expect("игрок сохраняется перед открытием склада")
            .set_current_progress_snapshot(PlayerProgress::Banking);
        let delivery = message.send_to_player(self.net_server(), player_id);
        if delivery == 0 {
            self.find_player_mut(player_id)
                .expect("игрок сохраняется при откате открытия склада")
                .close_depot_storage();
            tracing::warn!(
                player_id,
                password_required,
                goods_amount,
                delivery,
                "отправка открытия сценарного склада завершилась ошибкой"
            );
            return ScriptDepotOpenOutcome::SendFailed;
        }
        tracing::trace!(
            player_id,
            password_required,
            goods_amount,
            delivery,
            "сценарный склад открыт"
        );
        ScriptDepotOpenOutcome::Opened
    }

    pub(crate) fn open_equipment_session(
        &mut self,
        player_id: i32,
        kind: EquipmentSessionPlugKind,
    ) {
        if kind == EquipmentSessionPlugKind::DaKong && !self.da_kong_xiang_qian.key() {
            tracing::trace!(player_id, ?kind, "сессия оборудования отключена");
            return;
        }
        let Some(player) = self.find_player(player_id) else {
            tracing::trace!(
                player_id,
                ?kind,
                "игрок открытия сессии оборудования не найден"
            );
            return;
        };
        if player.is_dead() {
            tracing::trace!(
                player_id,
                ?kind,
                "мёртвый игрок не может открыть сессию оборудования"
            );
            return;
        }
        if player.current_progress() != PlayerProgress::None {
            let string_id = match kind {
                EquipmentSessionPlugKind::Upgrade => "GS0177",
                EquipmentSessionPlugKind::DaKong => "GS1057",
                EquipmentSessionPlugKind::Compose => "GS1061",
            };
            let notification_delivery =
                self.send_equipment_session_notification(player_id, string_id);
            tracing::trace!(
                player_id,
                ?kind,
                notification_delivery,
                "игрок занят при открытии сессии оборудования"
            );
            return;
        }
        if kind != EquipmentSessionPlugKind::Upgrade
            && self
                .find_player(player_id)
                .is_some_and(CPlayer::has_team_recruitment_state)
        {
            let string_id = match kind {
                EquipmentSessionPlugKind::DaKong => "GS1058",
                EquipmentSessionPlugKind::Compose => "GS1062",
                EquipmentSessionPlugKind::Upgrade => unreachable!(),
            };
            let notification_delivery =
                self.send_equipment_session_notification(player_id, string_id);
            tracing::trace!(
                player_id,
                ?kind,
                notification_delivery,
                "командное состояние блокирует сессию оборудования"
            );
            return;
        }
        let Some((session_id, plug_id)) = self
            .session_factory
            .create_equipment_session(kind, player_id)
        else {
            tracing::trace!(player_id, ?kind, "фабрика отклонила сессию оборудования");
            return;
        };
        let (progress, lock_movement, message_type) = match kind {
            EquipmentSessionPlugKind::Upgrade => (PlayerProgress::Upgrade, false, 0x0b_f912),
            EquipmentSessionPlugKind::DaKong => (PlayerProgress::DaKong, false, 0x0b_f929),
            EquipmentSessionPlugKind::Compose => (PlayerProgress::Compose, true, 0x0b_f92a),
        };
        let (listener_attach, player_transition) = self
            .find_player_mut(player_id)
            .map(|player| {
                let listener_attach = player.attach_equipment_session_listener(plug_id);
                let transition = player.begin_equipment_session(progress, lock_movement);
                (Some(listener_attach), Some(transition))
            })
            .unwrap_or((None, None));
        let mut message = CMessage::new(message_type);
        message.add_long(session_id);
        message.add_long(plug_id);
        if kind == EquipmentSessionPlugKind::Upgrade {
            message.add_long(player_id);
        }
        let delivery = message.send_to_player(self.net_server(), player_id);
        if delivery == 0 {
            let collected_plug_ids = self.session_factory.garbage_collect_session(session_id);
            if let Some(player) = self.find_player_mut(player_id) {
                let _listener_detach = player.detach_equipment_session_listener(plug_id);
                let _ = player.release_goods_session_state();
            }
            tracing::trace!(
                player_id,
                ?kind,
                session_id,
                plug_id,
                ?listener_attach,
                ?player_transition,
                ?collected_plug_ids,
                "открытие сессии оборудования не доставлено"
            );
            return;
        }
        tracing::trace!(
            player_id,
            ?kind,
            session_id,
            plug_id,
            ?listener_attach,
            ?player_transition,
            delivery,
            "сессия оборудования открыта"
        );
    }

    pub(crate) fn upgrade_equipment<Context: EquipmentUpgradeContext>(
        &mut self,
        player_id: i32,
        session_id: i32,
        requested_plug_id: i32,
        context: &mut Context,
    ) {
        if self.session_factory.query_session(session_id).is_none() {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                "сессия улучшения не найдена"
            );
            return;
        }
        let actual_plug_id = self
            .session_factory
            .query_session_plug_by_owner(session_id, 400, player_id)
            .map(|plug| plug.id());
        let Some(actual_plug_id) = actual_plug_id else {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                "plug улучшения не найден"
            );
            return;
        };
        if actual_plug_id != requested_plug_id {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                actual_plug_id,
                "plug улучшения не совпал"
            );
            return;
        }
        let Some(mut plug) = self
            .session_factory
            .take_equipment_upgrade_plug(actual_plug_id)
        else {
            tracing::trace!(
                player_id,
                session_id,
                actual_plug_id,
                "владелец plug улучшения не найден"
            );
            return;
        };
        let Some(mut player) = self.players.remove(&player_id) else {
            self.session_factory
                .register_equipment_upgrade_plug(actual_plug_id, plug);
            tracing::trace!(
                player_id,
                session_id,
                actual_plug_id,
                "игрок улучшения не найден"
            );
            return;
        };
        self.upgrade_equipment_inner(
            &mut player,
            &mut plug,
            session_id,
            requested_plug_id,
            context,
        );
        self.players.insert(player_id, player);
        self.session_factory
            .register_equipment_upgrade_plug(actual_plug_id, plug);
    }

    fn upgrade_equipment_inner<Context: EquipmentUpgradeContext>(
        &mut self,
        player: &mut CPlayer,
        plug: &mut CEquipmentUpgrade,
        session_id: i32,
        requested_plug_id: i32,
        context: &mut Context,
    ) {
        let player_id = player.player_id();
        let Some(region_id) = player.server_region_id() else {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                "регион игрока улучшения не найден"
            );
            return;
        };
        let tile_x = player.shape().get_tile_x().unwrap_or(0);
        let tile_y = player.shape().get_tile_y().unwrap_or(0);
        let price = plug.upgrade_price(|goods_id| {
            player.get_goods_by_id(goods_id).map_or(0, |goods| {
                CEquipmentUpgrade::price_property(goods, &self.goods_factory)
            })
        });
        if player.money() < price {
            self.send_equipment_upgrade_notification(player_id, "GS0250", Some(price));
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                price,
                "недостаточно денег при проверке улучшения"
            );
            return;
        }
        let Some(equipment_id) = plug.goods_id(UpgradeEquipmentCell::Equipment) else {
            self.send_equipment_upgrade_notification(player_id, "GS0249", None);
            tracing::trace!(
                player_id,
                session_id,
                "оборудование для улучшения не выбрано"
            );
            return;
        };
        let Some(equipment) = player.get_goods_by_id(equipment_id) else {
            tracing::trace!(
                player_id,
                session_id,
                ?equipment_id,
                "оборудование для улучшения не найдено"
            );
            return;
        };
        if !equipment.can_upgraded(&self.goods_factory) {
            self.send_equipment_upgrade_notification(player_id, "GS0249", None);
            tracing::trace!(
                player_id,
                session_id,
                ?equipment_id,
                "оборудование нельзя улучшить"
            );
            return;
        }
        let current_level = equipment.addon_property_value(
            &self.goods_factory,
            crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_WEAPON_LEVEL,
            1,
        );
        let Some(base_gem_id) = plug.goods_id(UpgradeEquipmentCell::BaseGem) else {
            self.send_equipment_upgrade_notification(player_id, "GS0248", None);
            tracing::trace!(player_id, session_id, "базовый камень улучшения не выбран");
            return;
        };
        let Some(base_gem) = player.get_goods_by_id(base_gem_id) else {
            tracing::trace!(
                player_id,
                session_id,
                ?base_gem_id,
                "базовый камень улучшения не найден"
            );
            return;
        };
        let minimum_level = base_gem.addon_property_value(
            &self.goods_factory,
            crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_GEM_LEVEL,
            1,
        );
        let maximum_level = minimum_level.max(base_gem.addon_property_value(
            &self.goods_factory,
            crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_GEM_LEVEL,
            2,
        ));
        if current_level < minimum_level || maximum_level < current_level {
            self.send_equipment_upgrade_notification(player_id, "GS0247", None);
            tracing::trace!(
                player_id,
                session_id,
                current_level,
                minimum_level,
                maximum_level,
                "уровень оборудования вне диапазона камня"
            );
            return;
        }
        if 98 < current_level as u32 {
            self.send_equipment_upgrade_notification(player_id, "GS0257", None);
            tracing::trace!(
                player_id,
                session_id,
                current_level,
                "достигнут максимальный уровень улучшения"
            );
            return;
        }
        let probability = plug.probability(|goods_id, property, value_id| {
            player.get_goods_by_id(goods_id).map_or(0, |goods| {
                goods.addon_property_value(&self.goods_factory, property, value_id)
            })
        });
        if player.money() < price {
            self.send_equipment_upgrade_notification(player_id, "GS0256", None);
            tracing::trace!(
                player_id,
                session_id,
                price,
                "недостаточно денег при выполнении улучшения"
            );
            return;
        }

        let money = player.decrease_money(price, &self.goods_factory);
        let money_deliveries = self.send_player_money_decrease(player_id, &money.outcome);
        tracing::trace!(
            player_id,
            session_id,
            previous_money = money.previous,
            current_money = money.current,
            ?money_deliveries,
            "списана стоимость улучшения"
        );
        let roll = game_legacy_random(&mut self.random_state, 100) as u32 + 1;

        let gem_cells = [
            UpgradeEquipmentCell::BaseGem,
            UpgradeEquipmentCell::GemOne,
            UpgradeEquipmentCell::GemTwo,
            UpgradeEquipmentCell::GemThree,
        ];
        let gems = gem_cells.map(|cell| {
            plug.goods_id(cell)
                .and_then(|id| player.get_goods_by_id(id))
                .map(EquipmentUpgradeGoodsSnapshot::capture)
        });

        let success = roll <= probability;
        if success {
            let succeed = plug.succeed_result(
                |goods_id, property, value_id| {
                    player.get_goods_by_id(goods_id).map_or(0, |goods| {
                        goods.addon_property_value(&self.goods_factory, property, value_id)
                    })
                },
                |upper_bound| game_legacy_random(&mut self.random_state, upper_bound),
            );
            let target_level = (current_level as u32).wrapping_add(succeed).min(99) as i32;
            if let Some(equipment) = player.get_goods_by_id_mut(equipment_id) {
                let (factory, random_state) = (&self.goods_factory, &mut self.random_state);
                let _ = factory.upgrade_equipment(equipment, target_level, |upper_bound| {
                    game_legacy_random(random_state, upper_bound)
                });
            }
            self.send_equipment_upgrade_notification(player_id, "GS0251", None);
            if self.log_system.goods_upgrade_success_enabled() {
                let audit = EquipmentUpgradeAuditLog {
                    reason: EQUIPMENT_UPGRADE_SUCCESS_LOG_REASON,
                    player_id,
                    equipment: player
                        .get_goods_by_id(equipment_id)
                        .map(EquipmentUpgradeGoodsSnapshot::capture)
                        .expect("успешный upgrade сохраняет equipment"),
                    gems,
                    region_id,
                    tile_x,
                    tile_y,
                };
                self.send_equipment_upgrade_audit(&audit);
            }
            self.publish_equipment_upgrade_update(player, equipment_id, context);
            tracing::trace!(
                player_id,
                session_id,
                price,
                probability,
                roll,
                previous_level = current_level,
                resulting_level = target_level,
                "оборудование улучшено"
            );
        } else {
            let equipment_snapshot = player
                .get_goods_by_id(equipment_id)
                .map(EquipmentUpgradeGoodsSnapshot::capture)
                .expect("equipment проверен до failure audit");
            if self.log_system.goods_upgrade_failure_enabled() {
                let audit = EquipmentUpgradeAuditLog {
                    reason: EQUIPMENT_UPGRADE_FAILURE_LOG_REASON,
                    player_id,
                    equipment: equipment_snapshot.clone(),
                    gems,
                    region_id,
                    tile_x,
                    tile_y,
                };
                self.send_equipment_upgrade_audit(&audit);
            }
            match plug.failed_result(|goods_id, property, value_id| {
                player.get_goods_by_id(goods_id).map_or(0, |goods| {
                    goods.addon_property_value(&self.goods_factory, property, value_id)
                })
            }) {
                1 => {
                    self.send_equipment_upgrade_notification(player_id, "GS0252", None);
                    tracing::trace!(
                        player_id,
                        session_id,
                        probability,
                        roll,
                        current_level,
                        "неудачное улучшение не изменило уровень"
                    );
                }
                2 => {
                    let target_level = current_level.saturating_sub(1);
                    if let Some(equipment) = player.get_goods_by_id_mut(equipment_id) {
                        let (factory, random_state) = (&self.goods_factory, &mut self.random_state);
                        let _ = factory.upgrade_equipment(equipment, target_level, |upper_bound| {
                            game_legacy_random(random_state, upper_bound)
                        });
                    }
                    self.send_equipment_upgrade_notification(player_id, "GS0253", None);
                    self.publish_equipment_upgrade_update(player, equipment_id, context);
                    tracing::trace!(
                        player_id,
                        session_id,
                        probability,
                        roll,
                        previous_level = current_level,
                        resulting_level = target_level,
                        "неудачное улучшение снизило уровень"
                    );
                }
                3 => {
                    if let Some(equipment) = player.get_goods_by_id_mut(equipment_id) {
                        let (factory, random_state) = (&self.goods_factory, &mut self.random_state);
                        let _ = factory.upgrade_equipment(equipment, 0, |upper_bound| {
                            game_legacy_random(random_state, upper_bound)
                        });
                    }
                    self.send_equipment_upgrade_notification(player_id, "GS0254", None);
                    self.publish_equipment_upgrade_update(player, equipment_id, context);
                    tracing::trace!(
                        player_id,
                        session_id,
                        probability,
                        roll,
                        previous_level = current_level,
                        "неудачное улучшение сбросило уровень"
                    );
                }
                _ => {
                    self.send_equipment_upgrade_notification(player_id, "GS0255", None);
                    if self.log_system.goods_lost_by_upgrade_enabled() {
                        let lost = EquipmentUpgradeLostAuditLog {
                            reason: EQUIPMENT_UPGRADE_LOST_LOG_REASON,
                            player_id,
                            pk_count: player.pk_count(),
                            money: player.money(),
                            depot_money: player.depot_money(),
                            equipment: equipment_snapshot,
                            amount: 1,
                            region_id,
                            tile_x,
                            tile_y,
                            client_ip: player.client_ip(),
                        };
                        self.send_equipment_upgrade_lost_audit(&lost);
                    }
                    self.consume_equipment_upgrade_cell(
                        player,
                        plug,
                        UpgradeEquipmentCell::Equipment,
                        context,
                    );
                    tracing::trace!(
                        player_id,
                        session_id,
                        probability,
                        roll,
                        "неудачное улучшение уничтожило оборудование"
                    );
                }
            }
        }

        for cell in gem_cells {
            self.consume_equipment_upgrade_cell(player, plug, cell, context);
        }
    }

    fn send_equipment_upgrade_notification(
        &self,
        player_id: i32,
        string_id: &str,
        format_value: Option<u32>,
    ) {
        let template = self.get_string_by_id(string_id.as_bytes());
        let text = format_value.map_or_else(
            || legacy_c_string_prefix(template).to_vec(),
            |value| format_single_legacy_u32(template, value, 255),
        );
        let delivery = colored_player_notice_message(0xffff_ffff, 0, &text)
            .send_to_player(self.net_server(), player_id);
        tracing::trace!(
            player_id,
            string_id,
            delivery,
            "отправлено уведомление улучшения"
        );
    }

    fn send_equipment_upgrade_audit(&self, audit: &EquipmentUpgradeAuditLog) {
        let mut message = CMessage::new(0x0006_0203);
        message.add_byte(audit.reason);
        message.add_long(audit.player_id);
        add_equipment_upgrade_log_goods(&mut message, Some(&audit.equipment));
        for gem in &audit.gems {
            add_equipment_upgrade_log_goods(&mut message, gem.as_ref());
        }
        message.add_long(audit.region_id);
        message.add_long(audit.tile_x);
        message.add_long(audit.tile_y);
        let deliveries = message.send(self, false);
        tracing::trace!(
            player_id = audit.player_id,
            reason = audit.reason,
            ?deliveries,
            "отправлен журнал улучшения в World"
        );
    }

    fn send_equipment_upgrade_lost_audit(&self, audit: &EquipmentUpgradeLostAuditLog) {
        let mut message = CMessage::new(0x0006_0202);
        message.add_byte(audit.reason);
        message.add_long(audit.player_id);
        message.base_mut().add_short(audit.pk_count as i16);
        message.add_ulong(audit.money);
        message.add_ulong(audit.depot_money);
        message.base_mut().add_guid(audit.equipment.identity.ex_id);
        // Primary GameServer сохраняет этот legacy wire mismatch: equipment
        // price занимает World-поле amount, literal amount — поле price.
        message.add_ulong(audit.equipment.price);
        add_legacy_c_string(message.base_mut(), &audit.equipment.name);
        message.add_ulong(audit.amount);
        message.add_long(audit.region_id);
        message.add_long(audit.tile_x);
        message.add_long(audit.tile_y);
        message.add_ulong(audit.client_ip);
        let deliveries = message.send(self, false);
        tracing::trace!(
            player_id = audit.player_id,
            reason = audit.reason,
            ?deliveries,
            "отправлен журнал потери оборудования в World"
        );
    }

    fn send_equipment_upgrade_consumption(
        &self,
        previous: &crate::gameserver::appserver::container::ccontainer::PreviousContainer,
        consumption: &CiQingPacketConsumption,
    ) {
        if consumption.remaining_amount == 0 {
            let delivery = self.send_container_object_delete(
                consumption.player_id,
                previous,
                consumption.goods,
                consumption.previous_amount,
            );
            tracing::trace!(player_id = consumption.player_id, ?consumption.goods, delivery, "отправлено удаление расходника улучшения");
            return;
        }
        let mut message = CS2CContainerObjectAmountChange::default();
        message.set_source_container(
            previous.container_type,
            previous.container_id,
            previous.goods_position,
        );
        message.set_source_container_extend_id(previous.container_extend_id);
        message.set_object(consumption.goods.object_type, consumption.goods.ex_id);
        message.set_object_amount(consumption.remaining_amount);
        let delivery = message.send_to_player(self, consumption.player_id);
        tracing::trace!(player_id = consumption.player_id, ?consumption.goods, delivery, remaining_amount = consumption.remaining_amount, "отправлено изменение расходника улучшения");
    }

    fn send_container_object_delete(
        &self,
        player_id: i32,
        previous: &crate::gameserver::appserver::container::ccontainer::PreviousContainer,
        goods: ShapeIdentity,
        amount: u32,
    ) -> i32 {
        let mut message = CS2CContainerObjectMove::default();
        message.set_operation(ContainerObjectMoveOperation::DeleteObject);
        message.set_source_container(
            previous.container_type,
            previous.container_id,
            previous.goods_position,
        );
        message.set_source_container_extend_id(previous.container_extend_id);
        message.set_source_object(goods.object_type, goods.ex_id, amount);
        message.send_to_player(self, player_id)
    }

    fn publish_equipment_upgrade_update<Context: EquipmentUpgradeContext>(
        &self,
        player: &CPlayer,
        equipment_id: CGuid,
        context: &mut Context,
    ) {
        let Some(goods) = player.get_goods_by_id(equipment_id) else {
            return;
        };
        let player_id = player.player_id();
        let goods = goods.identity();
        let old_client_payload = context.encode_goods_for_old_client(
            player
                .get_goods_by_id(equipment_id)
                .expect("оборудование проверено"),
        );
        let mut message = CMessage::new(0x0b_f918);
        message.add_long(player_id);
        message.base_mut().add_guid(goods.ex_id);
        message.add_ulong(old_client_payload.len() as u32);
        message.base_mut().add(&old_client_payload);
        let delivery = message.send_to_player(self.net_server(), player_id);
        tracing::trace!(
            player_id,
            ?goods,
            delivery,
            "отправлено обновление улучшенного оборудования"
        );
    }

    fn consume_equipment_upgrade_cell<Context: EquipmentUpgradeContext>(
        &self,
        player: &mut CPlayer,
        plug: &mut CEquipmentUpgrade,
        cell: UpgradeEquipmentCell,
        context: &mut Context,
    ) {
        let Some(goods_id) = plug.goods_id(cell) else {
            return;
        };
        let previous = plug
            .upgrade_container()
            .base()
            .base()
            .original_container_information(goods_id)
            .unwrap_or_default();
        let identity = player
            .get_goods_by_id(goods_id)
            .map(CGoods::identity)
            .unwrap_or(ShapeIdentity {
                object_type: 700,
                id: 0,
                ex_id: goods_id,
            });
        let previous_amount = player.get_goods_by_id(goods_id).map_or(0, CGoods::amount);
        let source_removed = if player.packet().base().find(goods_id).is_some() {
            match player.remove_packet_goods_by_id(goods_id, 1) {
                Some(consumption) => {
                    self.send_equipment_upgrade_consumption(&previous, &consumption);
                    true
                }
                None => false,
            }
        } else if let Some(goods) = player.equipment().find(goods_id) {
            let facts = context.enhancement_equipment_remove_facts(
                player,
                goods,
                self.globe_setup.pack_add_enabled(),
            );
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut removal = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut removal);
            if matches!(removal.outcome, EquipmentRemoveOutcome::Removed(_)) {
                let delivery = self.send_container_object_delete(
                    player.player_id(),
                    &previous,
                    identity,
                    previous_amount,
                );
                tracing::trace!(
                    player_id = player.player_id(),
                    ?identity,
                    delivery,
                    "отправлено удаление расходника улучшения из экипировки"
                );
            }
            matches!(removal.outcome, EquipmentRemoveOutcome::Removed(_))
        } else {
            false
        };
        if source_removed {
            let _ = plug.upgrade_container_mut().on_source_removed(goods_id, 1);
        }
        tracing::trace!(
            player_id = player.player_id(),
            ?cell,
            ?identity,
            source_removed,
            "обработан расход ячейки улучшения"
        );
    }

    pub(crate) fn close_equipment_upgrade(&mut self, player_id: i32, session_id: i32) {
        if self.session_factory.query_session(session_id).is_none() {
            tracing::trace!(
                player_id,
                session_id,
                "закрываемая сессия улучшения не найдена"
            );
            return;
        }
        let plug_id = self
            .session_factory
            .query_session_plug_by_owner(session_id, 400, player_id)
            .map(|plug| plug.id());
        let Some(plug_id) = plug_id else {
            tracing::trace!(
                player_id,
                session_id,
                "закрываемый plug улучшения не найден"
            );
            return;
        };
        let Some(mut plug) = self.session_factory.take_equipment_upgrade_plug(plug_id) else {
            tracing::trace!(
                player_id,
                session_id,
                plug_id,
                "владелец закрываемого plug улучшения не найден"
            );
            return;
        };
        let session_end = self.session_factory.end_session(session_id);
        let mut listener_detach = None;
        let mut previous_progress = None;
        if let Some(player) = self.find_player_mut(player_id) {
            listener_detach = Some(player.detach_equipment_session_listener(plug_id));
            let previous = player.current_progress();
            player.set_current_progress_snapshot(PlayerProgress::None);
            previous_progress = Some(previous);
        }
        let cleared_shadows = plug.close();
        let message = CMessage::new(0x0b_f913);
        let close_delivery = message.send_to_player(self.net_server(), player_id);
        let collected_plug_ids = self.session_factory.garbage_collect_session(session_id);
        tracing::trace!(
            player_id,
            session_id,
            plug_id,
            ?session_end,
            ?listener_detach,
            ?previous_progress,
            cleared_shadows,
            close_delivery,
            ?collected_plug_ids,
            "сессия улучшения закрыта"
        );
    }

    pub(crate) fn compose_equipment<Context: EquipmentComposeContext + ScriptFunctionRuntime>(
        &mut self,
        player_id: i32,
        session_id: i32,
        requested_plug_id: i32,
        context: &mut Context,
    ) {
        if self.session_factory.query_session(session_id).is_none() {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                "сессия соединения оборудования не найдена"
            );
            return;
        }
        let actual_plug_id = self
            .session_factory
            .query_session_plug_by_owner(session_id, 400, player_id)
            .map(|plug| plug.id());
        let Some(actual_plug_id) = actual_plug_id else {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                "plug соединения оборудования не найден"
            );
            return;
        };
        if actual_plug_id != requested_plug_id {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                actual_plug_id,
                "plug соединения оборудования не совпал"
            );
            return;
        }
        let Some(mut plug) = self
            .session_factory
            .take_equipment_compose_plug(actual_plug_id)
        else {
            tracing::trace!(
                player_id,
                session_id,
                actual_plug_id,
                "владелец plug соединения оборудования не найден"
            );
            return;
        };
        self.compose_equipment_inner(player_id, session_id, &mut plug, context);
        self.session_factory
            .register_equipment_compose_plug(actual_plug_id, plug);
    }

    fn compose_equipment_inner<Context: EquipmentComposeContext + ScriptFunctionRuntime>(
        &mut self,
        player_id: i32,
        session_id: i32,
        plug: &mut CEquipmentCompose,
        context: &mut Context,
    ) {
        let Some(player) = self.find_player(player_id) else {
            tracing::trace!(
                player_id,
                session_id,
                "игрок соединения оборудования не найден"
            );
            return;
        };
        if player.server_region_id().is_none() {
            tracing::trace!(
                player_id,
                session_id,
                "регион игрока соединения оборудования не найден"
            );
            return;
        }
        let Some(base_id) = plug
            .compose_container()
            .goods_id(ComposeEquipmentCell::BaseEquipment)
        else {
            self.send_equipment_compose_notification(player_id, "GS1156", &[]);
            tracing::trace!(
                player_id,
                session_id,
                "основное оборудование для соединения не выбрано"
            );
            return;
        };
        let Some(sub_id) = plug
            .compose_container()
            .goods_id(ComposeEquipmentCell::SubEquipment)
        else {
            self.send_equipment_compose_notification(player_id, "GS1157", &[]);
            tracing::trace!(
                player_id,
                session_id,
                "дополнительное оборудование для соединения не выбрано"
            );
            return;
        };
        let Some(base_source) = player
            .get_goods_by_id(base_id)
            .map(|goods| EquipmentComposeSourceSnapshot::capture(goods, &self.goods_factory))
        else {
            tracing::trace!(
                player_id,
                session_id,
                ?base_id,
                "основное оборудование для соединения не найдено"
            );
            return;
        };
        let Some(sub_source) = player
            .get_goods_by_id(sub_id)
            .map(|goods| EquipmentComposeSourceSnapshot::capture(goods, &self.goods_factory))
        else {
            tracing::trace!(
                player_id,
                session_id,
                ?sub_id,
                "дополнительное оборудование для соединения не найдено"
            );
            return;
        };
        if player.check_item_in_packet(COMPOSE_STONE_GOODS_INDEX) == 0 {
            self.send_equipment_compose_notification(player_id, "GS1158", &[]);
            tracing::trace!(player_id, session_id, "камень соединения не найден");
            return;
        }
        if base_source.base_index == 0 || base_source.base_index != sub_source.base_index {
            self.send_equipment_compose_notification(player_id, "GS1159", &[]);
            tracing::trace!(
                player_id,
                session_id,
                base_index = base_source.base_index,
                sub_index = sub_source.base_index,
                "оборудование для соединения различается"
            );
            return;
        }
        let first = self
            .equipment_compose_list
            .get_first_compose(base_source.base_index);
        let second = self
            .equipment_compose_list
            .get_second_compose(base_source.base_index);
        let (result_index, step, required_level) = if second != 0 {
            (second, 2, 20)
        } else {
            (first, 1, 15)
        };
        if result_index == 0 {
            self.send_equipment_compose_notification(player_id, "GS1160", &[]);
            tracing::trace!(
                player_id,
                session_id,
                base_index = base_source.base_index,
                "рецепт соединения не найден"
            );
            return;
        }
        if base_source.weapon_level < required_level || sub_source.weapon_level < required_level {
            self.send_equipment_compose_notification(player_id, "GS1161", &[step, required_level]);
            tracing::trace!(
                player_id,
                session_id,
                step,
                required_level,
                base_level = base_source.weapon_level,
                sub_level = sub_source.weapon_level,
                "уровень оборудования недостаточен для соединения"
            );
            return;
        }
        if base_source.anima_bind != 1 || sub_source.anima_bind != 1 {
            self.send_equipment_compose_notification(player_id, "GS1162", &[]);
            tracing::trace!(
                player_id,
                session_id,
                "оборудование для соединения не привязано"
            );
            return;
        }
        if base_source.quality != sub_source.quality {
            self.send_equipment_compose_notification(player_id, "GS1163", &[]);
            tracing::trace!(
                player_id,
                session_id,
                base_quality = base_source.quality,
                sub_quality = sub_source.quality,
                "качество оборудования для соединения различается"
            );
            return;
        }

        let mut created = {
            let (random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
                &mut self.random_state,
                &self.goods_factory,
                &self.fairy_exp_conf,
                &self.battle_fairy_exp_config,
            );
            goods_factory.create_goods_batch(
                result_index,
                1,
                |upper_bound| game_legacy_random(random_state, upper_bound),
                || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
            )
        };
        let Some(mut result) = created.pop() else {
            tracing::trace!(
                player_id,
                session_id,
                result_index,
                "фабрика отклонила результат соединения"
            );
            return;
        };

        for source in [&base_source, &sub_source] {
            let log = EquipmentComposeAuditLog {
                player_id,
                reason: COMPOSE_CONSUME_REASON,
                goods: source.identity,
                base_index: source.base_index,
                price: source.price,
                name: source.name.clone(),
            };
            self.record_equipment_compose_log(&log);
        }
        for (cell, source) in [
            (ComposeEquipmentCell::BaseEquipment, base_source.clone()),
            (ComposeEquipmentCell::SubEquipment, sub_source.clone()),
        ] {
            let previous = plug
                .compose_container()
                .original_container_information(source.identity.ex_id)
                .unwrap_or_default();
            let removed =
                self.consume_equipment_compose_source(player_id, &source, &previous, context);
            if removed {
                plug.compose_container_mut()
                    .remove_shadow(source.identity.ex_id);
            }
            tracing::trace!(player_id, session_id, ?cell, goods_id = ?source.identity.ex_id, removed, "обработан источник соединения оборудования");
        }
        let stone_consumptions = self
            .find_player_mut(player_id)
            .expect("compose owner проверен до stone removal")
            .remove_item_in_packet(COMPOSE_STONE_GOODS_INDEX, 1);
        for consumption in stone_consumptions {
            let deliveries = self.send_player_packet_consumption(&consumption);
            tracing::trace!(player_id, session_id, goods_id = ?consumption.goods.ex_id, ?deliveries, "израсходован камень соединения");
        }

        let packet_position = self.find_player(player_id).and_then(|player| {
            player
                .packet()
                .find_position_for_goods(&result, &self.goods_factory)
        });
        let Some(packet_position) = packet_position else {
            tracing::trace!(player_id, session_id, result = ?result.identity(), "результат соединения не помещается в инвентарь после расхода источников");
            return;
        };
        let result_log = EquipmentComposeAuditLog {
            player_id,
            reason: COMPOSE_CREATE_REASON,
            goods: result.identity(),
            base_index: result.base_properties_index(),
            price: result.price(),
            name: result.name().to_vec(),
        };
        self.record_equipment_compose_log(&result_log);
        for &(property, value_id, value) in &base_source.transferred_addons {
            let _ = result.set_addon_property_value_first_core(property, value_id, value);
        }
        let (factory, random_state) = (&self.goods_factory, &mut self.random_state);
        let _ = factory.upgrade_equipment(&mut result, required_level, |upper_bound| {
            game_legacy_random(random_state, upper_bound)
        });
        let _ = result.set_addon_property_value_first_core(
            crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_WEAPON_LEVEL,
            1,
            required_level,
        );
        let result_identity = result.identity();
        let (addition, rejected_result) = {
            let (players, goods_factory) = (&mut self.players, &self.goods_factory);
            let player = players
                .get_mut(&player_id)
                .expect("compose owner проверен до packet add");
            let mut incoming = Some(result);
            let outcome = player.packet_mut().add_goods_at(
                packet_position,
                &mut incoming,
                goods_factory,
                true,
            );
            let (old_client_payload, resulting_amount) = match &outcome {
                VolumeGoodsAddOutcome::Added(added) => {
                    let stored = player
                        .packet()
                        .base()
                        .find(added.identity.ex_id)
                        .expect("успешный packet add сохранил compose result");
                    (
                        Some(context.encode_goods_for_old_client(stored)),
                        Some(stored.amount()),
                    )
                }
                VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged { target, .. }) => (
                    None,
                    player
                        .packet()
                        .base()
                        .find(target.ex_id)
                        .map(CGoods::amount),
                ),
                VolumeGoodsAddOutcome::Stack(_) | VolumeGoodsAddOutcome::Rejected(_) => {
                    (None, None)
                }
            };
            (
                CiQingPacketAddition {
                    player_id,
                    source: result_identity,
                    position: Some(packet_position),
                    outcome,
                    old_client_payload,
                    resulting_amount,
                },
                incoming.map(|goods| goods.identity()),
            )
        };
        if let Some(rejected_result) = rejected_result {
            tracing::trace!(player_id, session_id, ?rejected_result, ?addition.outcome, "инвентарь отклонил результат соединения после расхода источников");
            return;
        }
        let addition_deliveries = self.send_player_packet_addition(&addition);
        tracing::trace!(
            player_id,
            session_id,
            ?addition_deliveries,
            "результат соединения опубликован в инвентарь"
        );

        if let Some(stored) = self
            .find_player(player_id)
            .and_then(|player| player.packet().base().find(result_identity.ex_id))
        {
            let previous = PreviousContainer {
                container_type: 400,
                container_id: player_id,
                container_extend_id: 1,
                goods_position: packet_position,
            };
            let result_shadow = plug.compose_container_mut().insert_shadow(
                ComposeEquipmentCell::ComposeEquipment,
                stored,
                previous,
            );
            tracing::trace!(
                player_id,
                session_id,
                ?result_shadow,
                "результат соединения помещён в shadow"
            );
        }
        let region_id = self
            .find_player(player_id)
            .and_then(CPlayer::server_region_id);
        let script_dispatched = self
            .run_script_file(
                b"scripts/goods/shenbing_gonggao.script",
                ScriptExecutionContext {
                    player_id: Some(player_id),
                    region_id,
                    ..ScriptExecutionContext::default()
                },
                context,
            )
            .is_some();
        tracing::trace!(
            player_id,
            session_id,
            result_index,
            required_level,
            script_dispatched,
            "соединение оборудования завершено"
        );
    }

    fn send_equipment_compose_notification(&self, player_id: i32, string_id: &str, values: &[i32]) {
        let template = self.get_string_by_id(string_id.as_bytes());
        let text = if let [first, second] = values {
            format_two_legacy_i32(template, *first, *second, 255)
        } else {
            legacy_c_string_prefix(template).to_vec()
        };
        let delivery = colored_player_notice_message(0xffff_ffff, 0, &text)
            .send_to_player(self.net_server(), player_id);
        tracing::trace!(
            player_id,
            string_id,
            delivery,
            "отправлено уведомление соединения оборудования"
        );
    }

    fn record_equipment_compose_log(&self, log: &EquipmentComposeAuditLog) {
        if !self.log_system.equipment_compose_enabled() {
            return;
        }
        let Some(player) = self.find_player(log.player_id) else {
            return;
        };
        let mut message = CMessage::new(0x0006_0202);
        message.add_byte(log.reason);
        message.add_long(log.player_id);
        message.base_mut().add_short(player.pk_count() as i16);
        message.add_ulong(player.money());
        message.add_ulong(player.depot_money());
        message.base_mut().add_guid(log.goods.ex_id);
        message.add_ulong(log.price);
        add_legacy_c_string(message.base_mut(), &log.name);
        message.add_ulong(1);
        message.add_long(player.server_region_id().unwrap_or_default());
        message.add_ulong(player.shape().get_tile_x().unwrap_or_default() as u32);
        message.add_ulong(player.shape().get_tile_y().unwrap_or_default() as u32);
        message.add_ulong(player.client_ip());
        let deliveries = message.send(self, false);
        tracing::trace!(
            player_id = log.player_id,
            reason = log.reason,
            ?deliveries,
            "отправлен журнал соединения оборудования в World"
        );
    }

    fn consume_equipment_compose_source<Context: EquipmentComposeContext>(
        &mut self,
        player_id: i32,
        source: &EquipmentComposeSourceSnapshot,
        previous: &PreviousContainer,
        context: &mut Context,
    ) -> bool {
        let Some(mut player) = self.players.remove(&player_id) else {
            return false;
        };
        let goods_id = source.identity.ex_id;
        let removed = if player.packet().base().find(goods_id).is_some() {
            match player.remove_packet_goods_by_id(goods_id, source.amount) {
                Some(packet) => {
                    let deliveries = self.send_player_packet_consumption(&packet);
                    tracing::trace!(
                        player_id,
                        ?goods_id,
                        ?deliveries,
                        "опубликован расход источника соединения из инвентаря"
                    );
                    true
                }
                None => false,
            }
        } else if let Some(goods) = player.equipment().find(goods_id) {
            let facts = context.enhancement_equipment_remove_facts(
                &player,
                goods,
                self.globe_setup.pack_add_enabled(),
            );
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut equipment = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut equipment);
            if matches!(equipment.outcome, EquipmentRemoveOutcome::Removed(_)) {
                let delivery = self.send_container_object_delete(
                    player_id,
                    previous,
                    source.identity,
                    source.amount,
                );
                tracing::trace!(
                    player_id,
                    ?goods_id,
                    delivery,
                    "опубликован расход источника соединения из экипировки"
                );
            }
            matches!(equipment.outcome, EquipmentRemoveOutcome::Removed(_))
        } else {
            false
        };
        self.players.insert(player_id, player);
        removed
    }

    pub(crate) fn send_player_packet_addition(&self, addition: &CiQingPacketAddition) -> Vec<i32> {
        let Some(position) = addition.position else {
            return Vec::new();
        };
        match &addition.outcome {
            VolumeGoodsAddOutcome::Added(added) => {
                let mut message = CS2CContainerObjectMove::default();
                message.set_operation(ContainerObjectMoveOperation::NewObject);
                message.set_destination_container(PLAYER_TYPE, addition.player_id, position);
                message.set_destination_container_extend_id(1);
                message.set_destination_object(added.identity.object_type, added.identity.ex_id);
                message.set_object_stream(addition.old_client_payload.clone().unwrap_or_default());
                vec![message.send_to_player(self, addition.player_id)]
            }
            VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged { target, .. }) => {
                let Some(amount) = addition.resulting_amount else {
                    return Vec::new();
                };
                let mut message = CS2CContainerObjectAmountChange::default();
                message.set_source_container(PLAYER_TYPE, addition.player_id, position);
                message.set_source_container_extend_id(1);
                message.set_object(target.object_type, target.ex_id);
                message.set_object_amount(amount);
                vec![message.send_to_player(self, addition.player_id)]
            }
            _ => Vec::new(),
        }
    }

    pub(crate) fn close_equipment_da_kong<Runtime: GameGoodsMessageRuntime>(
        &mut self,
        player_id: i32,
        session_id: i32,
        requested_plug_id: i32,
        runtime: &mut Runtime,
    ) {
        if self.session_factory.query_session(session_id).is_none() {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                "закрываемая сессия DaKong не найдена"
            );
            return;
        }
        let actual_plug_id = self
            .session_factory
            .query_session_plug_by_owner(session_id, 400, player_id)
            .map(|plug| plug.id());
        let Some(actual_plug_id) = actual_plug_id else {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                "закрываемый plug DaKong не найден"
            );
            return;
        };
        if actual_plug_id != requested_plug_id {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                actual_plug_id,
                "закрываемый plug DaKong не совпал"
            );
            return;
        }
        let Some(last_equipment_id) = self
            .session_factory
            .query_equipment_da_kong_plug(actual_plug_id)
            .map(CEquipmentDaKong::last_equipment_id)
        else {
            tracing::trace!(
                player_id,
                session_id,
                actual_plug_id,
                "владелец закрываемого plug DaKong не найден"
            );
            return;
        };

        let session_end = self.session_factory.end_session(session_id);
        let previous_progress = self.find_player_mut(player_id).map(|player| {
            let previous = player.current_progress();
            player.set_current_progress_snapshot(PlayerProgress::None);
            previous
        });
        let plug_exit = self.session_factory.exit_plug(session_id, actual_plug_id);

        let Some(goods) = self
            .find_player(player_id)
            .and_then(|player| player.get_goods_by_id(last_equipment_id))
        else {
            tracing::trace!(
                player_id,
                session_id,
                actual_plug_id,
                ?last_equipment_id,
                ?session_end,
                ?previous_progress,
                ?plug_exit,
                "сессия DaKong закрыта без оборудования"
            );
            return;
        };
        let update = EquipmentDaKongClientUpdate {
            player_id,
            goods: goods.identity(),
            old_client_payload: runtime.encode_goods_for_old_client(goods),
        };
        let mut message = CMessage::new(0x0b_f918);
        message.add_long(update.player_id);
        message.base_mut().add_guid(update.goods.ex_id);
        message.add_ulong(update.old_client_payload.len() as u32);
        message.base_mut().add(&update.old_client_payload);
        let client_update_delivery = message.send_to_player(self.net_server(), update.player_id);
        tracing::trace!(
            player_id,
            session_id,
            actual_plug_id,
            ?last_equipment_id,
            ?session_end,
            ?previous_progress,
            ?plug_exit,
            client_update_delivery,
            "сессия DaKong закрыта с обновлением оборудования"
        );
    }

    pub(crate) fn process_equipment_da_kong<Context: ScriptFunctionRuntime>(
        &mut self,
        player_id: i32,
        session_id: i32,
        requested_plug_id: i32,
        operation: EquipmentDaKongOperation,
        context: &mut Context,
    ) {
        if self.session_factory.query_session(session_id).is_none() {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                ?operation,
                "сессия DaKong не найдена"
            );
            return;
        }
        let actual_plug_id = self
            .session_factory
            .query_session_plug_by_owner(session_id, 400, player_id)
            .map(|plug| plug.id());
        let Some(actual_plug_id) = actual_plug_id else {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                ?operation,
                "plug DaKong не найден"
            );
            return;
        };
        if actual_plug_id != requested_plug_id {
            tracing::trace!(
                player_id,
                session_id,
                requested_plug_id,
                actual_plug_id,
                ?operation,
                "plug DaKong не совпал"
            );
            return;
        }
        let Some(mut plug) = self
            .session_factory
            .take_equipment_da_kong_plug(actual_plug_id)
        else {
            tracing::trace!(
                player_id,
                session_id,
                actual_plug_id,
                ?operation,
                "владелец plug DaKong не найден"
            );
            return;
        };
        let Some(mut player) = self.players.remove(&player_id) else {
            self.session_factory
                .register_equipment_da_kong_plug(actual_plug_id, plug);
            tracing::trace!(
                player_id,
                session_id,
                actual_plug_id,
                ?operation,
                "игрок DaKong не найден"
            );
            return;
        };
        self.process_equipment_da_kong_inner(
            &mut player,
            &mut plug,
            session_id,
            operation,
            context,
        );
        self.players.insert(player_id, player);
        self.session_factory
            .register_equipment_da_kong_plug(actual_plug_id, plug);
    }

    pub(crate) fn reflush_equipment_da_kong_external_property<Context: EquipmentDaKongContext>(
        &mut self,
        player_id: i32,
        cost_original_name: &[u8],
        context: &mut Context,
    ) {
        if !self.da_kong_xiang_qian.key() {
            tracing::trace!(player_id, "обновление внешнего свойства DaKong отключено");
            return;
        }
        if cost_original_name.is_empty() {
            tracing::trace!(
                player_id,
                "не задан материал обновления внешнего свойства DaKong"
            );
            return;
        }
        let Some(mut player) = self.players.remove(&player_id) else {
            tracing::trace!(
                player_id,
                "игрок обновления внешнего свойства DaKong не найден"
            );
            return;
        };
        self.reflush_equipment_da_kong_external_property_inner(
            &mut player,
            cost_original_name,
            context,
        );
        self.players.insert(player_id, player);
    }

    /// Сценарии `9352/9353` используют выбранный предмет контейнера улучшения и
    /// общий пакет игрока, затем публикуют тот же `0xBF918`, что остальные
    /// операции DaKong.
    pub(crate) fn modify_script_equipment_da_kong<Context: EquipmentDaKongContext>(
        &mut self,
        player_id: i32,
        kind: EquipmentDaKongScriptModifyKind,
        context: &mut Context,
    ) {
        const COST_ORIGINAL_NAME: &[u8] = b"GMXF18";
        if !self.da_kong_xiang_qian.key() {
            tracing::trace!(player_id, ?kind, "сценарная модификация DaKong отключена");
            return;
        }
        let cost_base_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(COST_ORIGINAL_NAME));
        if self
            .goods_factory
            .query_goods_base_properties(cost_base_index)
            .is_none()
        {
            tracing::trace!(
                player_id,
                ?kind,
                cost_base_index,
                "описание материала сценарной модификации DaKong не найдено"
            );
            return;
        }
        let Some(mut player) = self.players.remove(&player_id) else {
            tracing::trace!(
                player_id,
                ?kind,
                "игрок сценарной модификации DaKong не найден"
            );
            return;
        };
        let Some(equipment_id) = player.enhancement_selected_goods_id() else {
            tracing::trace!(
                player_id,
                ?kind,
                "оборудование сценарной модификации DaKong не выбрано"
            );
            self.players.insert(player_id, player);
            return;
        };
        if player.get_goods_by_id(equipment_id).is_none() {
            tracing::trace!(
                player_id,
                ?kind,
                ?equipment_id,
                "оборудование сценарной модификации DaKong не найдено"
            );
            self.players.insert(player_id, player);
            return;
        }
        if player.check_item_in_packet(cost_base_index) == 0 {
            let text = self.get_string_by_id(b"GS1060");
            let notification_delivery =
                colored_player_notice_message(0xffff_ffff, 0xffff_0000, text)
                    .send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                ?kind,
                ?equipment_id,
                cost_base_index,
                notification_delivery,
                "материал сценарной модификации DaKong не найден"
            );
            self.players.insert(player_id, player);
            return;
        }

        let equipment = player
            .get_goods_by_id_mut(equipment_id)
            .expect("выбранный предмет DaKong проверен до мутации");
        match kind {
            EquipmentDaKongScriptModifyKind::ReapplyGemProperties => {
                self.goods_factory.da_kong_modify(equipment);
            }
            EquipmentDaKongScriptModifyKind::ClampDeluxProperties => {
                self.goods_factory
                    .da_kong_delux_modify(equipment, &self.da_kong_xiang_qian);
            }
        }
        if let Some(consumption) = player
            .remove_item_in_packet(cost_base_index, 1)
            .into_iter()
            .next()
        {
            let consumption_deliveries = self.send_player_packet_consumption(&consumption);
            tracing::trace!(
                player_id,
                ?kind,
                ?equipment_id,
                ?consumption_deliveries,
                "израсходован материал сценарной модификации DaKong"
            );
        }
        let equipment = player
            .get_goods_by_id(equipment_id)
            .expect("выбранный предмет DaKong сохраняется до обновления клиента");
        let update = EquipmentDaKongClientUpdate {
            player_id,
            goods: equipment.identity(),
            old_client_payload: context.encode_goods_for_old_client(equipment),
        };
        let client_update_delivery = self.send_equipment_da_kong_update(&update);
        let text = self.get_string_by_id(b"GS1059");
        let notification_delivery = colored_player_notice_message(0xffff_ffff, 0xffff_0000, text)
            .send_to_player(self.net_server(), player_id);
        tracing::trace!(
            player_id,
            ?kind,
            ?equipment_id,
            client_update_delivery,
            notification_delivery,
            "сценарная модификация DaKong завершена"
        );
        self.players.insert(player_id, player);
    }

    fn reflush_equipment_da_kong_external_property_inner<Context: EquipmentDaKongContext>(
        &mut self,
        player: &mut CPlayer,
        cost_original_name: &[u8],
        context: &mut Context,
    ) {
        use crate::gameserver::appserver::goods::cgoodsbaseproperties::{
            GAP_DAKONG_1, GAP_DAKONG_EXTERN_1, GAP_DAKONG_EXTERN_2, GAP_DAKONG_EXTERN_3,
        };

        let Some(equipment_id) = player.enhancement_selected_goods_id() else {
            tracing::trace!(
                player_id = player.player_id(),
                "оборудование обновления внешнего свойства DaKong не выбрано"
            );
            return;
        };
        let Some(equipment) = player.get_goods_by_id(equipment_id) else {
            tracing::trace!(
                player_id = player.player_id(),
                ?equipment_id,
                "оборудование обновления внешнего свойства DaKong не найдено"
            );
            return;
        };
        let old_seven = EquipmentDaKongGemSnapshot::from_catalog(
            equipment.addon_property_value(&self.goods_factory, GAP_DAKONG_1 + 6, 2) as u32,
            &self.goods_factory,
        );
        let equipment = player
            .get_goods_by_id_mut(equipment_id)
            .expect("external refresh equipment проверен до снятия бонусов");
        deal_with_da_kong_external_attributes(equipment, &self.goods_factory, old_seven, false);

        let refresh = match cost_original_name {
            b"FZ1052" => Some((0, GAP_DAKONG_EXTERN_1)),
            b"FZ1051" => Some((1, GAP_DAKONG_EXTERN_2)),
            b"FZ1050" => Some((2, GAP_DAKONG_EXTERN_3)),
            _ => None,
        };
        let mut refreshed = false;
        if let Some((group, property)) = refresh {
            let cost_base_index = self
                .goods_factory
                .query_goods_id_by_original_name(Some(cost_original_name));
            let can_refresh = self
                .goods_factory
                .query_goods_base_properties(cost_base_index)
                .is_some()
                && player.check_item_in_packet(cost_base_index) != 0
                && player
                    .get_goods_by_id(equipment_id)
                    .is_some_and(|equipment| {
                        equipment.addon_property_value(&self.goods_factory, property, 1) > 0
                            && equipment.addon_property_value(&self.goods_factory, property, 2) > 0
                    });
            if can_refresh {
                let (property_type, property_value) = {
                    let (setup, random_state) = (&self.da_kong_xiang_qian, &mut self.random_state);
                    setup
                        .make_sure_external_attribute(
                            group,
                            player
                                .get_goods_by_id(equipment_id)
                                .expect("external refresh equipment сохраняется до RNG")
                                .base_properties_index(),
                            |upper_bound| game_legacy_random(random_state, upper_bound),
                        )
                        .unwrap_or_default()
                };
                let equipment = player
                    .get_goods_by_id_mut(equipment_id)
                    .expect("external refresh equipment сохраняется до mutation");
                let _ = equipment.set_addon_property_value_first_core(property, 1, property_type);
                let _ = equipment.set_addon_property_modifier_core(property, 2, property_value);

                if let Some(cost) = self
                    .goods_factory
                    .query_goods_base_properties(cost_base_index)
                {
                    let log = EquipmentDaKongAuditLog {
                        player_id: player.player_id(),
                        reason: 4,
                        cost_base_index,
                        cost_price: cost.price(),
                        cost_name: cost.name().to_vec(),
                        equipment: EquipmentDaKongGoodsSnapshot::capture(
                            player
                                .get_goods_by_id(equipment_id)
                                .expect("external refresh equipment сохраняется до world log"),
                            &self.goods_factory,
                        ),
                    };
                    let log_deliveries = self.send_equipment_da_kong_log(player, &log);
                    tracing::trace!(
                        player_id = player.player_id(),
                        ?equipment_id,
                        ?log_deliveries,
                        "отправлен журнал обновления внешнего свойства DaKong"
                    );
                }
                if let Some(consumption) = player
                    .remove_item_in_packet(cost_base_index, 1)
                    .into_iter()
                    .next()
                {
                    let consumption_deliveries = self.send_player_packet_consumption(&consumption);
                    tracing::trace!(
                        player_id = player.player_id(),
                        ?equipment_id,
                        ?consumption_deliveries,
                        "израсходован материал обновления внешнего свойства DaKong"
                    );
                }
                if let (Some(region_id), Ok(tile_x), Ok(tile_y)) = (
                    player.server_region_id(),
                    player.shape().get_tile_x(),
                    player.shape().get_tile_y(),
                ) {
                    let effect = EquipmentDaKongAroundEffect {
                        effect_id: 11,
                        region_id,
                        tile_x,
                        tile_y,
                    };
                    let effect_delivery = self.send_equipment_da_kong_around_effect(&effect);
                    tracing::trace!(
                        player_id = player.player_id(),
                        ?equipment_id,
                        ?effect,
                        effect_delivery,
                        "отправлен эффект обновления внешнего свойства DaKong"
                    );
                }
                refreshed = true;
            }
        }

        let new_seven = player.get_goods_by_id(equipment_id).and_then(|equipment| {
            EquipmentDaKongGemSnapshot::from_catalog(
                equipment.addon_property_value(&self.goods_factory, GAP_DAKONG_1 + 6, 2) as u32,
                &self.goods_factory,
            )
        });
        let equipment = player
            .get_goods_by_id_mut(equipment_id)
            .expect("external refresh equipment сохраняется до возврата бонусов");
        deal_with_da_kong_external_attributes(equipment, &self.goods_factory, new_seven, true);
        let equipment = player
            .get_goods_by_id(equipment_id)
            .expect("external refresh equipment сохраняется до client update");
        let update = EquipmentDaKongClientUpdate {
            player_id: player.player_id(),
            goods: equipment.identity(),
            old_client_payload: context.encode_goods_for_old_client(equipment),
        };
        let client_update_delivery = self.send_equipment_da_kong_update(&update);
        tracing::trace!(
            player_id = player.player_id(),
            ?equipment_id,
            refreshed,
            client_update_delivery,
            "обновление внешнего свойства DaKong завершено"
        );
    }

    fn process_equipment_da_kong_inner<Context: ScriptFunctionRuntime>(
        &mut self,
        player: &mut CPlayer,
        plug: &mut CEquipmentDaKong,
        session_id: i32,
        operation: EquipmentDaKongOperation,
        context: &mut Context,
    ) {
        if player.server_region_id().is_none() {
            tracing::trace!(
                player_id = player.player_id(),
                session_id,
                ?operation,
                "регион игрока DaKong не найден"
            );
            return;
        }
        match operation {
            EquipmentDaKongOperation::DaKong { color_index } => {
                self.equipment_da_kong_create_socket(player, plug, color_index, context);
            }
            EquipmentDaKongOperation::ChangeRoleColor { socket } => {
                self.equipment_da_kong_change_color(player, plug, socket, context);
            }
            EquipmentDaKongOperation::QueryResult => {
                let published = self.equipment_da_kong_publish_preview(player, plug, context);
                tracing::trace!(
                    player_id = player.player_id(),
                    session_id,
                    published,
                    "обработан запрос результата DaKong"
                );
            }
            EquipmentDaKongOperation::EnchaseGem { parameter } => {
                self.equipment_da_kong_enchase(player, plug, parameter, context);
            }
            EquipmentDaKongOperation::DestroyGem { socket } => {
                self.equipment_da_kong_destroy_gem(player, plug, socket, context);
            }
        }
    }

    fn equipment_da_kong_equipment_id(plug: &CEquipmentDaKong) -> Option<CGuid> {
        plug.upgrade_container()
            .goods_id(crate::gameserver::appserver::container::cequipmentdakongcontainer::DaKongCell::Equipment)
    }

    fn equipment_da_kong_gems(
        &self,
        player: &CPlayer,
        plug: &CEquipmentDaKong,
    ) -> [Option<EquipmentDaKongGemSnapshot>; 7] {
        use crate::gameserver::appserver::container::cequipmentdakongcontainer::DaKongCell;
        let cells = [
            DaKongCell::GemOne,
            DaKongCell::GemTwo,
            DaKongCell::GemThree,
            DaKongCell::GemFour,
            DaKongCell::GemFive,
            DaKongCell::GemSix,
            DaKongCell::GemSeven,
        ];
        std::array::from_fn(|index| {
            plug.upgrade_container()
                .goods_id(cells[index])
                .and_then(|goods_id| player.get_goods_by_id(goods_id))
                .map(|goods| EquipmentDaKongGemSnapshot::capture(goods, &self.goods_factory))
        })
    }

    fn equipment_da_kong_notify(&self, player_id: i32, string_id: &'static str) {
        let text = self.get_string_by_id(string_id.as_bytes());
        let delivery = colored_player_notice_message(0xffff_ffff, 0xffff_0000, text)
            .send_to_player(self.net_server(), player_id);
        tracing::trace!(
            player_id,
            string_id,
            delivery,
            "отправлено уведомление DaKong"
        );
    }

    fn equipment_da_kong_publish_update<Context: EquipmentDaKongContext>(
        &self,
        context: &mut Context,
        player_id: i32,
        goods: &CGoods,
    ) {
        let update = EquipmentDaKongClientUpdate {
            player_id,
            goods: goods.identity(),
            old_client_payload: context.encode_goods_for_old_client(goods),
        };
        let delivery = self.send_equipment_da_kong_update(&update);
        tracing::trace!(player_id, goods = ?update.goods, delivery, "отправлено обновление оборудования DaKong");
    }

    fn equipment_da_kong_consume_packet(&self, player: &mut CPlayer, base_index: u32) {
        for consumption in player.remove_item_in_packet(base_index, 1) {
            let deliveries = self.send_player_packet_consumption(&consumption);
            tracing::trace!(player_id = player.player_id(), goods = ?consumption.goods, ?deliveries, "израсходован материал DaKong");
        }
    }

    fn equipment_da_kong_log(
        &self,
        player: &CPlayer,
        reason: u8,
        cost_base_index: u32,
        equipment: &CGoods,
    ) {
        self.equipment_da_kong_log_snapshot(
            player,
            reason,
            cost_base_index,
            EquipmentDaKongGoodsSnapshot::capture(equipment, &self.goods_factory),
        );
    }

    fn equipment_da_kong_log_snapshot(
        &self,
        player: &CPlayer,
        reason: u8,
        cost_base_index: u32,
        equipment: EquipmentDaKongGoodsSnapshot,
    ) {
        if !self.da_kong_xiang_qian.log_key() {
            return;
        }
        let Some(cost) = self
            .goods_factory
            .query_goods_base_properties(cost_base_index)
        else {
            return;
        };
        let log = EquipmentDaKongAuditLog {
            player_id: player.player_id(),
            reason,
            cost_base_index,
            cost_price: cost.price(),
            cost_name: cost.name().to_vec(),
            equipment,
        };
        let deliveries = self.send_equipment_da_kong_log(player, &log);
        tracing::trace!(
            player_id = player.player_id(),
            reason,
            ?deliveries,
            "отправлен журнал DaKong в World"
        );
    }

    fn send_equipment_da_kong_update(&self, update: &EquipmentDaKongClientUpdate) -> i32 {
        let mut message = CMessage::new(0x0b_f918);
        message.add_long(update.player_id);
        message.base_mut().add_guid(update.goods.ex_id);
        message.add_ulong(update.old_client_payload.len() as u32);
        message.base_mut().add(&update.old_client_payload);
        message.send_to_player(self.net_server(), update.player_id)
    }

    pub(crate) fn send_player_packet_consumption(
        &self,
        consumption: &CiQingPacketConsumption,
    ) -> Vec<i32> {
        if consumption.remaining_amount == 0 {
            let mut message = CS2CContainerObjectMove::default();
            message.set_operation(ContainerObjectMoveOperation::DeleteObject);
            message.set_source_container(PLAYER_TYPE, consumption.player_id, consumption.position);
            message.set_source_container_extend_id(1);
            message.set_source_object(
                consumption.goods.object_type,
                consumption.goods.ex_id,
                consumption.previous_amount,
            );
            return vec![message.send_to_player(self, consumption.player_id)];
        }
        let mut message = CS2CContainerObjectAmountChange::default();
        message.set_source_container(PLAYER_TYPE, consumption.player_id, consumption.position);
        message.set_source_container_extend_id(1);
        message.set_object(consumption.goods.object_type, consumption.goods.ex_id);
        message.set_object_amount(consumption.remaining_amount);
        vec![message.send_to_player(self, consumption.player_id)]
    }

    /// Точная сценарная функция `DelGoods(name, amount)` расходует стопки
    /// пакета в порядке вставки, затем снаряжение в порядке колонок. Каждая
    /// мутация сразу публикует обычное контейнерное сообщение; снаряжение также
    /// проходит полную цепочку свойств, навыков и уведомлений окружения игрока
    /// до перехода к следующему кандидату.
    pub(crate) fn delete_script_goods<Runtime: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        base_index: u32,
        requested: u32,
        runtime: &mut Runtime,
    ) -> u32 {
        if base_index == 0 || requested == 0 {
            return 0;
        }
        let Some(mut player) = self.players.remove(&player_id) else {
            return 0;
        };
        let mut removed = 0u32;
        for consumption in player.remove_item_in_packet(base_index, requested) {
            removed = removed.wrapping_add(
                consumption
                    .previous_amount
                    .wrapping_sub(consumption.remaining_amount),
            );
            let _ = self.send_player_packet_consumption(&consumption);
        }

        if removed < requested {
            let candidates: Vec<_> = player
                .equipment()
                .traversing_goods()
                .into_iter()
                .filter(|(_, goods)| goods.base_properties_index() == base_index)
                .map(|(column, goods)| (column.position(), goods.identity(), goods.amount()))
                .collect();
            for (position, identity, amount) in candidates {
                if removed >= requested {
                    break;
                }
                let remaining_request = requested.wrapping_sub(removed);
                if remaining_request < amount {
                    if let Some(goods) = player.equipment_mut().get_goods_mut(position) {
                        goods.set_amount(amount.wrapping_sub(remaining_request));
                        let mut message = CS2CContainerObjectAmountChange::default();
                        message.set_source_container(PLAYER_TYPE, player_id, position);
                        message.set_source_container_extend_id(2);
                        message.set_object(identity.object_type, identity.ex_id);
                        message.set_object_amount(amount.wrapping_sub(remaining_request));
                        let _ = message.send_to_player(self, player_id);
                        removed = requested;
                    }
                    break;
                }
                let Some(goods) = player.equipment().find(identity.ex_id) else {
                    continue;
                };
                let facts = runtime.enhancement_equipment_remove_facts(
                    &player,
                    goods,
                    self.globe_setup.pack_add_enabled(),
                );
                let mut recompute =
                    |player: &CPlayer| runtime.recompute_enhancement_player_properties(player);
                let mut report = player.remove_equipment_goods(
                    identity.ex_id,
                    &self.goods_factory,
                    &self.skill_factory,
                    facts,
                    &mut recompute,
                );
                drop(recompute);
                self.publish_player_equipment_remove_report(&mut report);
                if let EquipmentRemoveOutcome::Removed(result) = &report.outcome {
                    removed = removed.wrapping_add(amount);
                    let previous = PreviousContainer {
                        container_type: PLAYER_TYPE,
                        container_id: player_id,
                        container_extend_id: 2,
                        goods_position: position,
                    };
                    let _ = self.send_container_object_delete(
                        player_id,
                        &previous,
                        result.goods.identity(),
                        result.goods.amount(),
                    );
                }
            }
        }
        self.players.insert(player_id, player);
        removed
    }

    pub(crate) fn script_packet_goods_number(&self, player_id: i32) -> i32 {
        self.find_player(player_id)
            .map(|player| player.packet().goods_amount(&self.goods_factory) as i32)
            .unwrap_or(0)
    }

    pub(crate) fn script_container_free_space(&self, player_id: i32, depot: bool) -> i32 {
        self.find_player(player_id)
            .map(|player| {
                (if depot {
                    player.depot().base().space()
                } else {
                    player.packet().space()
                }) as i32
            })
            .unwrap_or(0)
    }

    pub(crate) fn script_depot_goods_amount(&self, player_id: i32, name: &[u8]) -> i32 {
        let base_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(name));
        if base_index == 0 {
            return 0;
        }
        self.find_player(player_id)
            .map(|player| {
                player
                    .depot()
                    .base()
                    .base()
                    .traversing_goods()
                    .filter(|goods| goods.base_properties_index() == base_index)
                    .fold(0u64, |total, goods| total + u64::from(goods.amount()))
                    .min(i32::MAX as u64) as i32
            })
            .unwrap_or(0)
    }

    /// Сценарные `AddDepotGoods` и `DelDepotGoods` используют пароль самого
    /// игрока: закрытый склад временно открывается и после мутации снова
    /// закрывается. Все изменения доходят до обычных складских владельцев,
    /// реестра `GoodsAI` и контейнерных сообщений клиента.
    pub(crate) fn add_script_depot_goods<Runtime: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        name: &[u8],
        amount: u32,
        runtime: &mut Runtime,
    ) -> i32 {
        let goods_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(name));
        let created = self.create_goods_batch(goods_index, amount);
        let Some(mut player) = self.players.remove(&player_id) else {
            return 0;
        };
        let was_locked = player.depot().is_locked();
        if was_locked {
            let _ = player.depot_mut().unlock_if_authenticated(true);
        }
        for goods in created {
            let mut incoming = Some(goods);
            let addition =
                self.add_depot_transfer_goods(&mut player, 9, u32::MAX, &mut incoming, runtime);
            let DepotStorageTransferAddition::Depot(DepotGoodsAddOutcome::Volume(outcome)) =
                addition
            else {
                continue;
            };
            match outcome {
                VolumeGoodsAddOutcome::Added(added) => {
                    let Some(position) = added.position else {
                        continue;
                    };
                    let Some(old_client_payload) = player
                        .depot()
                        .get_goods(position)
                        .map(|goods| runtime.encode_goods_for_old_client(goods))
                    else {
                        continue;
                    };
                    let mut message = CS2CContainerObjectMove::default();
                    message.set_operation(ContainerObjectMoveOperation::NewObject);
                    message.set_destination_container(PLAYER_TYPE, player_id, position);
                    message.set_destination_container_extend_id(9);
                    message
                        .set_destination_object(added.identity.object_type, added.identity.ex_id);
                    message.set_object_stream(old_client_payload);
                    let _ = message.send_to_player(self, player_id);
                }
                VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged { target, .. }) => {
                    let Some((position, resulting_amount)) = player
                        .depot()
                        .snapshot_goods()
                        .find(|(_, goods)| goods.identity().ex_id == target.ex_id)
                        .map(|(position, goods)| (position, goods.amount()))
                    else {
                        continue;
                    };
                    let mut message = CS2CContainerObjectAmountChange::default();
                    message.set_source_container(PLAYER_TYPE, player_id, position);
                    message.set_source_container_extend_id(9);
                    message.set_object(target.object_type, target.ex_id);
                    message.set_object_amount(resulting_amount);
                    let _ = message.send_to_player(self, player_id);
                }
                VolumeGoodsAddOutcome::Stack(_) | VolumeGoodsAddOutcome::Rejected(_) => {}
            }
        }
        if was_locked {
            let _ = player.depot_mut().lock();
        }
        self.players.insert(player_id, player);
        1
    }

    pub(crate) fn delete_script_depot_goods(
        &mut self,
        player_id: i32,
        name: &[u8],
        requested: u32,
    ) -> i32 {
        let base_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(name));
        if base_index == 0 || requested == 0 {
            return 0;
        }
        let Some(mut player) = self.players.remove(&player_id) else {
            return 0;
        };
        let was_locked = player.depot().is_locked();
        if was_locked {
            let _ = player.depot_mut().unlock_if_authenticated(true);
        }
        let candidates: Vec<_> = player
            .depot()
            .snapshot_goods()
            .filter(|(_, goods)| goods.base_properties_index() == base_index)
            .map(|(position, goods)| (position, goods.identity(), goods.amount()))
            .collect();
        let mut removed_amount = 0u32;
        for (position, identity, previous_amount) in candidates {
            if requested <= removed_amount {
                break;
            }
            let amount = requested.wrapping_sub(removed_amount).min(previous_amount);
            let mut split_goods = (amount < previous_amount)
                .then(|| self.create_goods_core(base_index))
                .flatten();
            let Some(outcome) =
                player
                    .depot_mut()
                    .take_goods(position, amount, &self.goods_factory, |_| {
                        split_goods.take()
                    })
            else {
                continue;
            };
            let taken = match outcome {
                VolumeGoodsRemoveOutcome::Removed(taken)
                | VolumeGoodsRemoveOutcome::RemovedButCellMissing(taken) => taken,
            };
            match taken {
                AmountLimitGoodsTaken::Removed(mut removed) => {
                    player.unregister_depot_goods_ai(
                        &mut removed.goods,
                        &self.goods_factory,
                        game_wall_time_seconds(),
                    );
                    let mut message = CS2CContainerObjectMove::default();
                    message.set_operation(ContainerObjectMoveOperation::DeleteObject);
                    message.set_source_container(PLAYER_TYPE, player_id, position);
                    message.set_source_container_extend_id(9);
                    message.set_source_object(
                        identity.object_type,
                        identity.ex_id,
                        previous_amount,
                    );
                    let _ = message.send_to_player(self, player_id);
                }
                AmountLimitGoodsTaken::Split(split) => {
                    let mut message = CS2CContainerObjectAmountChange::default();
                    message.set_source_container(PLAYER_TYPE, player_id, position);
                    message.set_source_container_extend_id(9);
                    message.set_object(split.source.object_type, split.source.ex_id);
                    message.set_object_amount(previous_amount.wrapping_sub(amount));
                    let _ = message.send_to_player(self, player_id);
                }
            }
            removed_amount = removed_amount.wrapping_add(amount);
        }
        if was_locked {
            let _ = player.depot_mut().lock();
        }
        self.players.insert(player_id, player);
        removed_amount.min(i32::MAX as u32) as i32
    }

    pub(crate) fn script_depot_space_for_goods(&mut self, player_id: i32, name: &[u8]) -> i32 {
        let goods_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(name));
        let Some(goods) = self.create_goods_core(goods_index) else {
            return 0;
        };
        let Some(player) = self.find_player(player_id) else {
            return 0;
        };
        let mut depot = player.depot().clone();
        let _ = depot.unlock_if_authenticated(true);
        let mut incoming = Some(goods);
        let outcome = depot.add_goods(&mut incoming, &self.goods_factory, true);
        i32::from(matches!(
            outcome,
            DepotGoodsAddOutcome::Volume(
                VolumeGoodsAddOutcome::Added(_)
                    | VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged { .. })
            )
        ))
    }

    pub(crate) fn script_depot_goods_number(&self, player_id: i32) -> i32 {
        self.find_player(player_id)
            .map(|player| player.depot().goods_amount(&self.goods_factory) as i32)
            .unwrap_or(0)
    }

    pub(crate) fn script_selected_container_item_type(&self, player_id: i32) -> i32 {
        self.find_player(player_id)
            .and_then(|player| {
                let goods_id = player.enhancement_selected_goods_id()?;
                let goods = player.get_goods_by_id(goods_id)?;
                self.goods_factory
                    .query_goods_base_properties(goods.base_properties_index())
            })
            .map(|properties| properties.goods_type() + properties.equip_place() - 1)
            .unwrap_or(-1)
    }

    pub(crate) fn script_selected_goods_property(
        &self,
        player_id: i32,
        property: i32,
        value_id: u32,
    ) -> i32 {
        let Some(goods) = self.find_player(player_id).and_then(|player| {
            let goods_id = player.enhancement_selected_goods_id()?;
            player.get_goods_by_id(goods_id)
        }) else {
            return -1;
        };
        let value = goods.addon_property_value(&self.goods_factory, property, value_id);
        if value != 0
            || self
                .goods_factory
                .query_goods_base_properties(goods.base_properties_index())
                .is_some_and(|base| base.has_addon_property(property))
        {
            value
        } else {
            -1
        }
    }

    pub(crate) fn script_selected_goods_price(&self, player_id: i32) -> i32 {
        self.find_player(player_id)
            .and_then(|player| {
                let goods_id = player.enhancement_selected_goods_id()?;
                let goods = player.get_goods_by_id(goods_id)?;
                self.goods_factory
                    .query_goods_base_properties(goods.base_properties_index())
            })
            .map(|base| base.price() as i32)
            .unwrap_or(0)
    }

    fn mutate_script_selected_goods<Context, ResultValue, Mutate>(
        &mut self,
        player_id: i32,
        context: &mut Context,
        mutate: Mutate,
    ) -> Option<ResultValue>
    where
        Context: OldClientGoodsCodec,
        Mutate: FnOnce(&CGoodsFactory, &mut u32, &mut CGoods) -> (ResultValue, bool),
    {
        let mut player = self.players.remove(&player_id)?;
        let outcome = (|| {
            let goods_id = player.enhancement_selected_goods_id()?;
            let goods = player.get_goods_by_id_mut(goods_id)?;
            let (result, publish) = mutate(&self.goods_factory, &mut self.random_state, goods);
            let update =
                publish.then(|| (goods.identity(), context.encode_goods_for_old_client(goods)));
            Some((result, update))
        })();
        self.players.insert(player_id, player);
        let (result, update) = outcome?;
        if let Some((identity, payload)) = update {
            let mut message = CMessage::new(0x000b_f918);
            message.add_long(player_id);
            message.base_mut().add_guid(identity.ex_id);
            message.add_ulong(payload.len() as u32);
            message.base_mut().add(&payload);
            let _ = message.send_to_player(self.net_server(), player_id);
        }
        Some(result)
    }

    /// Точный проход `ModifyGoodsTime`: временная регистрация `GoodsAI`
    /// снимается до изменения полей и восстанавливается после него. Для
    /// предмета, находящегося в своей ячейке экипировки, типы 2 и 4 начинают
    /// отсчёт заново с текущего серверного времени.
    pub(crate) fn modify_script_selected_goods_time<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        lifetime: u32,
        time_type: Option<u32>,
        context: &mut Context,
    ) {
        let Some(mut player) = self.players.remove(&player_id) else {
            return;
        };
        let update = (|| {
            let goods_id = player.enhancement_selected_goods_id()?;
            let now_seconds = game_wall_time_seconds();
            let _ = player.unregister_goods_ai_by_id(goods_id, &self.goods_factory, now_seconds);

            let (identity, resolved_time_type, equip_place) = {
                let goods = player.get_goods_by_id_mut(goods_id)?;
                goods.set_goods_lifetime(lifetime);
                if let Some(time_type) = time_type {
                    goods.set_goods_time_type(time_type);
                }
                let resolved_time_type = goods.goods_time_type(&self.goods_factory);
                let equip_place = self
                    .goods_factory
                    .query_goods_base_properties(goods.base_properties_index())
                    .map(|base| base.equip_place());
                (goods.identity(), resolved_time_type, equip_place)
            };

            let is_equipped = equip_place
                .and_then(|position| u32::try_from(position).ok())
                .and_then(|position| player.equipment().get_goods(position))
                .is_some_and(|goods| goods.identity().ex_id == goods_id);
            if matches!(resolved_time_type, 2 | 4)
                && is_equipped
                && let Some(goods) = player.get_goods_by_id_mut(goods_id)
            {
                goods.set_start_point(now_seconds);
            }
            let _ = player.register_goods_ai_by_id(goods_id, &self.goods_factory, now_seconds);
            let payload = player
                .get_goods_by_id(goods_id)
                .map(|goods| context.encode_goods_for_old_client(goods))?;
            Some((identity, payload))
        })();
        self.players.insert(player_id, player);

        if let Some((identity, payload)) = update {
            let mut message = CMessage::new(0x000b_f918);
            message.add_long(player_id);
            message.base_mut().add_guid(identity.ex_id);
            message.add_ulong(payload.len() as u32);
            message.base_mut().add(&payload);
            let _ = message.send_to_player(self.net_server(), player_id);
        }
    }

    pub(crate) fn upgrade_script_selected_equipment<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        level_delta: i32,
        context: &mut Context,
    ) -> i32 {
        self.mutate_script_selected_goods(player_id, context, |factory, random_state, goods| {
            let current = goods.addon_property_value(
                factory,
                crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_WEAPON_LEVEL,
                1,
            );
            let target = (current as u32).wrapping_add(level_delta as u32) as i32;
            let _ = factory.upgrade_equipment(goods, target, |maximum| {
                game_legacy_random(random_state, maximum)
            });
            (1, true)
        })
        .unwrap_or(0)
    }

    pub(crate) fn set_script_selected_goods_property<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        property: i32,
        value_id: u32,
        modifier: i32,
        context: &mut Context,
    ) -> i32 {
        self.mutate_script_selected_goods(player_id, context, |_, _, goods| {
            let changed = goods.set_addon_property_modifier_core(property, value_id, modifier);
            (i32::from(changed), changed)
        })
        .unwrap_or(0)
    }

    pub(crate) fn add_script_selected_fu_mo_property(
        &mut self,
        player_id: i32,
        property_type: i32,
        value: i32,
    ) -> i32 {
        let Some(player) = self.find_player_mut(player_id) else {
            return -1;
        };
        let Some(goods_id) = player.enhancement_selected_goods_id() else {
            return -1;
        };
        player
            .get_goods_by_id_mut(goods_id)
            .map_or(-1, |goods| goods.set_fu_mo_property(property_type, value))
    }

    pub(crate) fn recreate_script_selected_goods_addons<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) {
        let _ = self.mutate_script_selected_goods(
            player_id,
            context,
            |factory, random_state, goods| {
                factory.recreate_addon_properties(goods, |maximum| {
                    game_legacy_random(random_state, maximum)
                });
                ((), true)
            },
        );
    }

    pub(crate) fn delete_script_selected_goods<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) {
        let Some(mut player) = self.players.remove(&player_id) else {
            return;
        };
        let selected = player.enhancement_selected_goods_id().and_then(|goods_id| {
            let location = player.owned_goods_location(10, goods_id)?;
            let amount = player.get_goods_by_id(goods_id)?.amount();
            Some((goods_id, location, amount))
        });
        let Some((goods_id, location, amount)) = selected else {
            self.players.insert(player_id, player);
            return;
        };
        if location.extend_id == 2 {
            let Some(goods) = player.equipment().find(goods_id).cloned() else {
                self.players.insert(player_id, player);
                return;
            };
            let facts = context.enhancement_equipment_remove_facts(
                &player,
                &goods,
                self.globe_setup.pack_add_enabled(),
            );
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut report = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                facts,
                &mut recompute,
            );
            drop(recompute);
            if matches!(report.outcome, EquipmentRemoveOutcome::Removed(_)) {
                let _ = player.clear_all_enhancement_selection();
            }
            self.publish_player_equipment_remove_report(&mut report);
            self.players.insert(player_id, player);
            if self.globe_setup.tao_zhuang_modify_enabled() {
                let _ = self.done_player_tao_zhuang(player_id);
            }
            return;
        }
        let deletion = player.delete_owned_goods(location, goods_id, amount, &self.goods_factory);
        if deletion.is_some() {
            let _ = player.clear_all_enhancement_selection();
        }
        self.players.insert(player_id, player);
        if let Some(deletion) = deletion
            && let Some(player) = self.players.get(&player_id)
        {
            let _ = self.send_player_owned_goods_deletion(player, &deletion);
        }
    }

    pub(crate) fn delete_named_player_script_goods<Runtime: GameContainerMessageRuntime>(
        &mut self,
        player_name: &[u8],
        goods_name: &[u8],
        requested: u32,
        runtime: &mut Runtime,
    ) -> i32 {
        if let Some(player_id) = self
            .find_player_by_name(player_name)
            .map(CPlayer::player_id)
        {
            let base_index = self
                .goods_factory
                .query_goods_id_by_original_name(Some(goods_name));
            return self.delete_script_goods(player_id, base_index, requested, runtime) as i32;
        }
        let mut relay = CMessage::new(0x0005_fc03);
        add_legacy_c_string(relay.base_mut(), player_name);
        add_legacy_c_string(relay.base_mut(), goods_name);
        relay.add_ulong(requested);
        let _ = relay.send(self, false);
        0
    }

    pub(crate) fn open_script_goods_container(
        &mut self,
        player_id: i32,
        description: &[u8],
        execution_script: &[u8],
    ) -> bool {
        if self.find_player(player_id).is_none() {
            return false;
        }
        let mut message = CMessage::new(0x000b_f919);
        add_legacy_c_string(message.base_mut(), description);
        let _ = message.send_to_player(self.net_server(), player_id);
        self.find_player_mut(player_id)
            .expect("игрок контейнерного сценария сохранён после отправки")
            .set_last_container_script(execution_script);
        true
    }

    fn send_ci_qing_log(&self, log: &CiQingLog) {
        let mut message = CMessage::new(0x0006_0218);
        message.add_long(log.player_id);
        message.add_long(log.delta);
        message.add_ulong(log.operation);
        message.add_ulong(log.base_index);
        message.add_ulong(log.amount);
        let delivery = message.send(self, false);
        tracing::trace!(player_id = log.player_id, ?delivery, "журнал CiQing отправлен");
    }

    fn send_ci_qing_container_consumption(
        &self,
        consumption: &CiQingContainerConsumption,
    ) -> Vec<i32> {
        if consumption.remaining_amount == 0 {
            let mut message = CS2CContainerObjectMove::default();
            message.set_operation(ContainerObjectMoveOperation::DeleteObject);
            message.set_source_container(PLAYER_TYPE, consumption.player_id, consumption.position);
            message.set_source_container_extend_id(consumption.container_extend_id as i32);
            message.set_source_object(
                consumption.goods.object_type,
                consumption.goods.ex_id,
                consumption.previous_amount,
            );
            return vec![message.send_to_player(self, consumption.player_id)];
        }
        let mut message = CS2CContainerObjectAmountChange::default();
        message.set_source_container(PLAYER_TYPE, consumption.player_id, consumption.position);
        message.set_source_container_extend_id(consumption.container_extend_id as i32);
        message.set_object(consumption.goods.object_type, consumption.goods.ex_id);
        message.set_object_amount(consumption.remaining_amount);
        vec![message.send_to_player(self, consumption.player_id)]
    }

    fn send_ci_qing_container_addition(&self, addition: &CiQingContainerAddition) -> Vec<i32> {
        match &addition.outcome {
            VolumeGoodsAddOutcome::Added(added) => {
                let mut message = CS2CContainerObjectMove::default();
                message.set_operation(ContainerObjectMoveOperation::NewObject);
                message.set_destination_container(
                    PLAYER_TYPE,
                    addition.player_id,
                    addition.position,
                );
                message.set_destination_container_extend_id(addition.container_extend_id as i32);
                message.set_destination_object(added.identity.object_type, added.identity.ex_id);
                message.set_object_stream(addition.old_client_payload.clone().unwrap_or_default());
                vec![message.send_to_player(self, addition.player_id)]
            }
            VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged { target, .. }) => {
                let Some(amount) = addition.resulting_amount else {
                    return Vec::new();
                };
                let mut message = CS2CContainerObjectAmountChange::default();
                message.set_source_container(PLAYER_TYPE, addition.player_id, addition.position);
                message.set_source_container_extend_id(addition.container_extend_id as i32);
                message.set_object(target.object_type, target.ex_id);
                message.set_object_amount(amount);
                vec![message.send_to_player(self, addition.player_id)]
            }
            _ => Vec::new(),
        }
    }

    fn send_ci_qing_hand_consumption(&self, consumption: &CiQingHandConsumption) -> Vec<i32> {
        if consumption.remaining_amount == 0 {
            let mut message = CS2CContainerObjectMove::default();
            message.set_operation(ContainerObjectMoveOperation::DeleteObject);
            message.set_source_container(PLAYER_TYPE, consumption.player_id, 0);
            message.set_source_container_extend_id(3);
            message.set_source_object(
                consumption.goods.object_type,
                consumption.goods.ex_id,
                consumption.previous_amount,
            );
            return vec![message.send_to_player(self, consumption.player_id)];
        }
        let mut message = CS2CContainerObjectAmountChange::default();
        message.set_source_container(PLAYER_TYPE, consumption.player_id, 0);
        message.set_source_container_extend_id(3);
        message.set_object(consumption.goods.object_type, consumption.goods.ex_id);
        message.set_object_amount(consumption.remaining_amount);
        vec![message.send_to_player(self, consumption.player_id)]
    }

    fn send_equipment_da_kong_log(
        &self,
        player: &CPlayer,
        log: &EquipmentDaKongAuditLog,
    ) -> Vec<i32> {
        let mut message = CMessage::new(0x0006_0212);
        message.add_byte(log.reason);
        message.add_long(log.player_id);
        message.base_mut().add_short(player.pk_count() as i16);
        message.add_ulong(player.money());
        message.add_ulong(player.depot_money());
        add_legacy_c_string(message.base_mut(), &log.equipment.description);
        message.base_mut().add_guid(log.equipment.identity.ex_id);
        message.add_ulong(log.cost_price);
        add_legacy_c_string(message.base_mut(), &log.cost_name);
        message.add_ulong(1);
        message.add_long(player.server_region_id().unwrap_or_default());
        message.add_ulong(player.shape().get_tile_x().unwrap_or_default() as u32);
        message.add_ulong(player.shape().get_tile_y().unwrap_or_default() as u32);
        message.add_ulong(player.client_ip());
        for &(_, _, value) in &log.equipment.socket_and_external_values {
            message.add_ulong(value as u32);
        }
        message.send(self, false).into_iter().collect()
    }

    fn send_equipment_da_kong_around_effect(&self, effect: &EquipmentDaKongAroundEffect) -> i32 {
        let mut message = CMessage::new(0x000b_f50a);
        message.add_long(effect.effect_id);
        message.add_ulong((effect.tile_x as f32 + 0.5).to_bits());
        message.add_ulong((effect.tile_y as f32 + 0.5).to_bits());
        let Some(runtime) = GameServerAroundRuntime::new(
            self,
            &self.session_factory,
            self.globe_setup.area_width(),
            self.globe_setup.area_height(),
        ) else {
            return 0;
        };
        let region = self
            .find_region(effect.region_id)
            .map(ServerRegionOwner::base);
        message.send_to_around_position(region, effect.tile_x, effect.tile_y, None, &runtime)
    }

    /// `5404 / PlayEffect`: region-point effect использует тот же canonical
    /// around runtime, что equipment effects, но координаты принадлежат
    /// script expression либо текущей клетке player-а.
    pub(crate) fn script_play_region_effect(
        &self,
        player_id: i32,
        region_id: i32,
        effect_id: i32,
        coordinates: Option<(i32, i32)>,
    ) -> Option<i32> {
        let player = self.find_player(player_id)?;
        let (tile_x, tile_y) = coordinates.unwrap_or((
            player.shape().get_tile_x().ok()?,
            player.shape().get_tile_y().ok()?,
        ));
        let region = self.find_region(region_id)?.base();
        let runtime = GameServerAroundRuntime::new(
            self,
            &self.session_factory,
            self.globe_setup.area_width(),
            self.globe_setup.area_height(),
        )?;
        let mut message = CMessage::new(0x000b_f50a);
        message.add_long(effect_id);
        message.add_ulong((tile_x as f32 + 0.5).to_bits());
        message.add_ulong((tile_y as f32 + 0.5).to_bits());
        Some(message.send_to_around_position(Some(region), tile_x, tile_y, None, &runtime))
    }

    /// `5403 / Weather` меняет погоду текущего региона сценарного игрока и
    /// сразу публикует полный `0xBF507` всем игрокам этого региона.
    pub(crate) fn script_change_weather(
        &mut self,
        player_id: i32,
        weather_index: i32,
    ) -> Option<i32> {
        let region_id = self.find_player(player_id)?.server_region_id()?;
        let mut owner = self.take_region_owner(region_id)?;
        let weather = owner.base_mut().change_weather(weather_index).to_vec();
        let mut message = CMessage::new(0x000b_f507);
        message.add_ulong(weather.len() as u32);
        for ServerRegionWeather {
            weather_index,
            fog_color,
        } in weather
        {
            message.add_long(weather_index);
            message.add_ulong(fog_color);
        }
        let delivery = message.send_to_region(Some(owner.base()), None, self);
        self.restore_region_owner(owner);
        Some(delivery)
    }

    /// `5405 / PlayAction` не меняет серверное поле действия: исходный вызов
    /// только рассылает `0xBF508(тип, ID, 16-битное действие)` вокруг текущей
    /// клетки.
    pub(crate) fn script_play_action(&self, player_id: i32, action: i32) -> Option<i32> {
        let player = self.find_player(player_id)?;
        let region_id = player.server_region_id()?;
        let tile_x = player.shape().get_tile_x().ok()?;
        let tile_y = player.shape().get_tile_y().ok()?;
        let runtime = GameServerAroundRuntime::new(
            self,
            &self.session_factory,
            self.globe_setup.area_width(),
            self.globe_setup.area_height(),
        )?;
        let mut message = CMessage::new(0x000b_f508);
        message.add_long(PLAYER_TYPE);
        message.add_long(player_id);
        message.add_short(action as i16);
        Some(message.send_to_around_position(
            self.find_region(region_id).map(ServerRegionOwner::base),
            tile_x,
            tile_y,
            None,
            &runtime,
        ))
    }

    /// `5410 / PlaySound`: direct и spatial branches используют один exact
    /// BF509 payload; ненулевой legacy flag включает рассылку из клетки
    /// script-player-а всем зарегистрированным игрокам соседних area.
    pub(crate) fn script_play_sound(
        &self,
        player_id: i32,
        region_id: i32,
        sound_file: &[u8],
        send_around: bool,
    ) -> Option<i32> {
        let player = self.find_player(player_id)?;
        let region = self.find_region(region_id)?.base();
        let mut message = CMessage::new(0x000b_f509);
        add_legacy_c_string(message.base_mut(), sound_file);
        if !send_around {
            return Some(message.send_to_player(self.net_server(), player_id));
        }
        let tile_x = player.shape().get_tile_x().ok()?;
        let tile_y = player.shape().get_tile_y().ok()?;
        let runtime = GameServerAroundRuntime::new(
            self,
            &self.session_factory,
            self.globe_setup.area_width(),
            self.globe_setup.area_height(),
        )?;
        Some(message.send_to_around_position(Some(region), tile_x, tile_y, None, &runtime))
    }

    /// `2308 / PlayerTalk`: это script-authored local speech, поэтому здесь
    /// нет client chat cooldown/cost/log route; сообщение сразу публикуется
    /// из canonical player shape через обычный spatial around owner.
    pub(crate) fn script_player_talk(
        &mut self,
        player_id: i32,
        text: &[u8],
    ) -> Option<Result<i32, ShapeCoordinateBlock>> {
        let player = self.find_player(player_id)?;
        let player_name = player.player_name().to_vec();
        let mut message = CMessage::new(0x000b_f801);
        message.add_long(0);
        message.add_long(PLAYER_TYPE);
        message.add_long(player_id);
        add_legacy_c_string(message.base_mut(), &player_name);
        add_legacy_c_string(message.base_mut(), text);
        self.send_player_shape_around(player_id, None, &message)
    }

    /// `8100 / OpenChangePlayerNameUI` не вычисляет аргументы. Разрешение
    /// совпадает с `strstr(playerName, strSpeStr)` из исходного EXE;
    /// последующий запрос клиента уже проходит конкретный контур
    /// `0x8FB05 → World 0x5FD05 → 0x7FA0E`.
    pub(crate) fn open_script_player_rename(&self, player_id: i32) -> Option<i32> {
        let player = self.find_player(player_id)?;
        let name = player.player_name();
        let special = self.globe_setup.special_string();
        let allowed =
            special.is_empty() || name.windows(special.len()).any(|window| window == special);
        let mut message = CMessage::new(0x000b_f810);
        message.add_byte(u8::from(allowed));
        Some(message.send_to_player(self.net_server(), player_id))
    }

    /// Script `5402/5406` меняет тот же runtime-флаг, который проверяет
    /// ordinary attack owner; отсутствующий script-player сохраняет no-op.
    pub(crate) fn set_script_player_god_mode(&mut self, player_id: i32, enabled: bool) -> bool {
        let Some(player) = self.find_player_mut(player_id) else {
            return false;
        };
        player.set_god_mode(enabled);
        true
    }

    /// `CPlayer::GetGMLevel` требует записи в обеих startup maps и возвращает
    /// клиентский bool-level: любой non-player role в одной из записей даёт 1.
    pub(crate) fn script_player_gm_level(&self, player_id: i32) -> Option<i32> {
        let name = self.find_player(player_id)?.player_name();
        let gm = self.gm_list.gm_info().get(name)?;
        let player_gm = self.gm_list.player_gm_info().get(name)?;
        Some(i32::from(gm.level != 0 || player_gm.level != 0))
    }

    pub(crate) fn send_script_player_gm_mode(&self, player_id: i32) -> Option<i32> {
        let level = self.script_player_gm_level(player_id).unwrap_or(0);
        self.find_player(player_id)?;
        let mut message = CMessage::new(0x000b_fc01);
        message.add_long(level);
        message.add_long(player_id);
        Some(message.send_to_player(self.net_server(), player_id))
    }

    fn equipment_da_kong_run_script<Context: ScriptFunctionRuntime>(
        &mut self,
        context: &mut Context,
        player: &mut CPlayer,
        script: &'static [u8],
    ) {
        let player_id = player.player_id();
        let region_id = player.server_region_id();
        // В C++ player pointer остаётся в game map во время синхронного script
        // call. Rust-владелец извлекает player для equipment mutation, поэтому
        // на время dispatcher-а возвращаем исходный owned value, оставляя clone
        // только как безопасный placeholder для ссылки вызывающего кода.
        let attached_player = std::mem::replace(player, player.clone());
        let displaced = self.players.insert(player_id, attached_player);
        assert!(
            displaced.is_none(),
            "DaKong owner извлекает игрока перед script dispatch"
        );
        let _ = self.run_script_file(
            script,
            ScriptExecutionContext {
                player_id: Some(player_id),
                region_id,
                ..ScriptExecutionContext::default()
            },
            context,
        );
        *player = self
            .players
            .remove(&player_id)
            .expect("синхронный DaKong script сохраняет canonical player owner");
        tracing::trace!(player_id, script = ?script, "выполнен сценарий DaKong");
    }

    fn equipment_da_kong_create_socket<Context: ScriptFunctionRuntime>(
        &mut self,
        player: &mut CPlayer,
        plug: &CEquipmentDaKong,
        color_index: i32,
        context: &mut Context,
    ) {
        const STONES: [&[u8]; 7] = [
            b"FZ1042", b"FZ1043", b"FZ1044", b"FZ1045", b"FZ1046", b"FZ1047", b"FZ1048",
        ];
        let player_id = player.player_id();
        let Some(equipment_id) = Self::equipment_da_kong_equipment_id(plug) else {
            tracing::trace!(
                player_id,
                "оборудование для создания сокета DaKong не выбрано"
            );
            return;
        };
        let Some(equipment) = player.get_goods_by_id(equipment_id) else {
            tracing::trace!(
                player_id,
                ?equipment_id,
                "оборудование для создания сокета DaKong не найдено"
            );
            return;
        };
        let socket_count = equipment.da_kong_count(&self.goods_factory) as usize;
        if socket_count > 6 {
            tracing::trace!(
                player_id,
                ?equipment_id,
                socket_count,
                "число сокетов DaKong достигло предела"
            );
            return;
        }
        let stone_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(STONES[socket_count]));
        if player.check_item_in_packet(stone_index) == 0
            || equipment.addon_property_value(
                &self.goods_factory,
                crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_DAKONG_1
                    + socket_count as i32,
                1,
            ) != 1
        {
            self.equipment_da_kong_notify(player_id, "GS1166");
            tracing::trace!(
                player_id,
                ?equipment_id,
                stone_index,
                socket_count,
                "материал создания сокета DaKong отсутствует"
            );
            return;
        }
        let succeeded = {
            let (setup, random_state) = (&self.da_kong_xiang_qian, &mut self.random_state);
            setup.get_success_probability(socket_count as i32, |upper_bound| {
                game_legacy_random(random_state, upper_bound)
            })
        };
        if succeeded {
            let mut color = {
                let (setup, random_state) = (&self.da_kong_xiang_qian, &mut self.random_state);
                setup.get_color(color_index, |upper_bound| {
                    game_legacy_random(random_state, upper_bound)
                })
            };
            if socket_count == 6 {
                color = 6;
            }
            let (new_count, equipment_base_index) = {
                let equipment = player
                    .get_goods_by_id_mut(equipment_id)
                    .expect("DaKong equipment проверен до socket mutation");
                let _ = equipment.set_addon_property_modifier_core(
                    crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_DAKONG_1
                        + socket_count as i32,
                    1,
                    color.wrapping_add(1),
                );
                (
                    equipment.da_kong_count(&self.goods_factory),
                    equipment.base_properties_index(),
                )
            };
            if new_count == 6 {
                self.equipment_da_kong_run_script(
                    context,
                    player,
                    b"scripts/goods/hole06_gonggao.script",
                );
            } else if new_count == 7 {
                self.equipment_da_kong_run_script(
                    context,
                    player,
                    b"scripts/goods/hole07_gonggao.script",
                );
            }
            if matches!(new_count, 3 | 6 | 7) {
                let group = match new_count {
                    3 => 0,
                    6 => 1,
                    _ => 2,
                };
                let external = {
                    let (setup, random_state) = (&self.da_kong_xiang_qian, &mut self.random_state);
                    setup.make_sure_external_attribute(group, equipment_base_index, |upper_bound| {
                        game_legacy_random(random_state, upper_bound)
                    })
                };
                let property =
                    crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_DAKONG_EXTERN_1
                        + group;
                let equipment = player
                    .get_goods_by_id_mut(equipment_id)
                    .expect("DaKong equipment сохраняется после announcement script");
                let (external_type, external_value) = external.unwrap_or_default();
                let _ = equipment.set_addon_property_value_first_core(property, 1, external_type);
                let _ = equipment.set_addon_property_modifier_core(property, 2, external_value);
            }
            self.equipment_da_kong_notify(player_id, "GS1164");
        } else {
            self.equipment_da_kong_notify(player_id, "GS1165");
        }
        let equipment = player
            .get_goods_by_id(equipment_id)
            .expect("DaKong equipment сохраняется до audit");
        self.equipment_da_kong_log(player, 1, stone_index, equipment);
        self.equipment_da_kong_consume_packet(player, stone_index);
        let preview_published = self.equipment_da_kong_publish_preview(player, plug, context);
        tracing::trace!(
            player_id,
            ?equipment_id,
            socket_count,
            succeeded,
            preview_published,
            "создание сокета DaKong завершено"
        );
    }

    fn equipment_da_kong_publish_preview<Context: EquipmentDaKongContext>(
        &self,
        player: &CPlayer,
        plug: &CEquipmentDaKong,
        context: &mut Context,
    ) -> bool {
        let goods = Self::equipment_da_kong_equipment_id(plug)
            .and_then(|goods_id| player.get_goods_by_id(goods_id))
            .or_else(|| player.get_goods_by_id(plug.upgrade_container().last_goods()));
        let Some(mut preview) = goods.cloned() else {
            return false;
        };
        let gems = self.equipment_da_kong_gems(player, plug);
        let _ = deal_enchase_gems(&mut preview, &gems, &self.goods_factory, false);
        self.equipment_da_kong_publish_update(context, player.player_id(), &preview);
        true
    }

    fn equipment_da_kong_change_color<Context: EquipmentDaKongContext>(
        &mut self,
        player: &mut CPlayer,
        plug: &CEquipmentDaKong,
        socket: i32,
        context: &mut Context,
    ) {
        if !(1..=7).contains(&socket) {
            tracing::trace!(
                player_id = player.player_id(),
                socket,
                "неверный сокет смены цвета DaKong"
            );
            return;
        }
        let player_id = player.player_id();
        let Some(equipment_id) = Self::equipment_da_kong_equipment_id(plug) else {
            tracing::trace!(
                player_id,
                socket,
                "оборудование смены цвета DaKong не выбрано"
            );
            return;
        };
        let property =
            crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_DAKONG_1 + socket - 1;
        let Some(equipment) = player.get_goods_by_id(equipment_id) else {
            tracing::trace!(
                player_id,
                ?equipment_id,
                socket,
                "оборудование смены цвета DaKong не найдено"
            );
            return;
        };
        let color = equipment.addon_property_value(&self.goods_factory, property, 1);
        let gem_index = equipment.addon_property_value(&self.goods_factory, property, 2);
        if !(2..=8).contains(&color) || gem_index != 0 {
            self.equipment_da_kong_notify(player_id, "GS1170");
            tracing::trace!(
                player_id,
                ?equipment_id,
                socket,
                color,
                gem_index,
                "условие смены цвета DaKong отклонено"
            );
            return;
        }
        let stone_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(b"FZ1049"));
        if player.check_item_in_packet(stone_index) == 0 {
            self.equipment_da_kong_notify(player_id, "GS1171");
            tracing::trace!(
                player_id,
                ?equipment_id,
                socket,
                stone_index,
                "материал смены цвета DaKong отсутствует"
            );
            return;
        }
        self.equipment_da_kong_consume_packet(player, stone_index);
        if player
            .get_goods_by_id(equipment_id)
            .is_some_and(|equipment| {
                equipment.addon_property_value(&self.goods_factory, property, 2) >= 1
            })
        {
            self.equipment_da_kong_notify(player_id, "GS1172");
            tracing::trace!(
                player_id,
                ?equipment_id,
                socket,
                "сокет DaKong уже занят после расхода материала"
            );
            return;
        }
        let mut new_color = {
            let (setup, random_state) = (&self.da_kong_xiang_qian, &mut self.random_state);
            setup.get_color(socket - 1, |upper_bound| {
                game_legacy_random(random_state, upper_bound)
            })
        };
        if socket == 7 {
            new_color = 6;
        }
        let equipment = player
            .get_goods_by_id_mut(equipment_id)
            .expect("color equipment проверен до mutation");
        let _ = equipment.set_addon_property_modifier_core(property, 1, new_color.wrapping_add(1));
        self.equipment_da_kong_notify(player_id, "GS1173");
        let equipment = player
            .get_goods_by_id(equipment_id)
            .expect("color equipment сохраняется до audit/update");
        self.equipment_da_kong_log(player, 0, stone_index, equipment);
        self.equipment_da_kong_publish_update(context, player_id, equipment);
        tracing::trace!(
            player_id,
            ?equipment_id,
            socket,
            new_color,
            "цвет сокета DaKong изменён"
        );
    }

    fn equipment_da_kong_consume_shadow_gems(
        &self,
        player: &mut CPlayer,
        plug: &mut CEquipmentDaKong,
    ) {
        use crate::gameserver::appserver::container::cequipmentdakongcontainer::DaKongCell;
        let ledger = plug
            .upgrade_container()
            .equipment_goods()
            .iter()
            .map(|(&position, &goods_id)| (position, goods_id))
            .collect::<Vec<_>>();
        for (position, goods_id) in ledger {
            let Some(cell) = DaKongCell::from_position(position) else {
                continue;
            };
            if goods_id == CGuid::GUID_INVALID {
                continue;
            }
            let identity = player
                .get_goods_by_id(goods_id)
                .map(CGoods::identity)
                .unwrap_or(ShapeIdentity {
                    object_type: 700,
                    id: 0,
                    ex_id: goods_id,
                });
            if let Some(consumption) = player.remove_packet_goods_by_id(goods_id, 1) {
                let external_deliveries = self.send_player_packet_consumption(&consumption);
                let _ = plug
                    .upgrade_container_mut()
                    .on_source_removed(Some(goods_id), 1);
                tracing::trace!(
                    player_id = player.player_id(),
                    ?cell,
                    ?identity,
                    ?external_deliveries,
                    "израсходован shadow-камень DaKong"
                );
            } else {
                let _ = plug
                    .upgrade_container_mut()
                    .invalidate_equipment_goods(position);
                tracing::trace!(
                    player_id = player.player_id(),
                    ?cell,
                    ?identity,
                    "shadow-камень DaKong отсутствует в инвентаре"
                );
            }
        }
    }

    fn equipment_da_kong_enchase<Context: ScriptFunctionRuntime>(
        &mut self,
        player: &mut CPlayer,
        plug: &mut CEquipmentDaKong,
        _parameter: i32,
        context: &mut Context,
    ) {
        let player_id = player.player_id();
        let Some(equipment_id) = Self::equipment_da_kong_equipment_id(plug) else {
            tracing::trace!(player_id, "оборудование инкрустации DaKong не выбрано");
            return;
        };
        let gems = self.equipment_da_kong_gems(player, plug);
        let effects = {
            let Some(equipment) = player.get_goods_by_id_mut(equipment_id) else {
                tracing::trace!(
                    player_id,
                    ?equipment_id,
                    "оборудование инкрустации DaKong не найдено"
                );
                return;
            };
            deal_enchase_gems(equipment, &gems, &self.goods_factory, true)
        };
        let changed = effects
            .events
            .iter()
            .any(|event| matches!(event, EquipmentDaKongEnchaseEvent::GemApplied { .. }));
        for event in effects.events {
            match event {
                EquipmentDaKongEnchaseEvent::Notification(string_id) => {
                    self.equipment_da_kong_notify(player_id, string_id);
                }
                EquipmentDaKongEnchaseEvent::GemApplied {
                    gem,
                    equipment,
                    audit,
                } => {
                    if audit {
                        self.equipment_da_kong_log_snapshot(player, 2, gem.base_index, equipment);
                    }
                }
                EquipmentDaKongEnchaseEvent::Script(script) => {
                    self.equipment_da_kong_run_script(context, player, script);
                }
            }
        }
        if changed {
            self.equipment_da_kong_notify(player_id, "GS1167");
        }
        self.equipment_da_kong_consume_shadow_gems(player, plug);
        let equipment = player
            .get_goods_by_id(equipment_id)
            .expect("enchase equipment сохраняется после gem consumption");
        self.equipment_da_kong_publish_update(context, player_id, equipment);
        tracing::trace!(
            player_id,
            ?equipment_id,
            changed,
            "инкрустация DaKong завершена"
        );
    }

    fn equipment_da_kong_destroy_gem<Context: EquipmentDaKongContext>(
        &mut self,
        player: &mut CPlayer,
        plug: &CEquipmentDaKong,
        socket: u32,
        context: &mut Context,
    ) {
        let player_id = player.player_id();
        let Some(equipment_id) = Self::equipment_da_kong_equipment_id(plug) else {
            tracing::trace!(
                player_id,
                socket,
                "оборудование удаления камня DaKong не выбрано"
            );
            return;
        };
        if player.check_item_in_packet(DA_KONG_USE_SINKER_INDEX) == 0 {
            self.equipment_da_kong_notify(player_id, "GS1174");
            tracing::trace!(
                player_id,
                ?equipment_id,
                socket,
                "инструмент удаления камня DaKong отсутствует"
            );
            return;
        }
        let gems = self.equipment_da_kong_gems(player, plug);
        let mut removed = false;
        let mut new_seven_after_removal = None;
        if (1..=7).contains(&socket) {
            let property = crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_DAKONG_1
                + socket as i32
                - 1;
            let (socket_color, gem_index) = player
                .get_goods_by_id(equipment_id)
                .map(|equipment| {
                    (
                        equipment.addon_property_value(&self.goods_factory, property, 1),
                        equipment.addon_property_value(&self.goods_factory, property, 2) as u32,
                    )
                })
                .unwrap_or_default();
            if !(2..=8).contains(&socket_color) || gem_index == 0 {
                self.equipment_da_kong_notify(player_id, "GS1175");
            } else {
                let slot_seven = gems[6].or_else(|| {
                    player.get_goods_by_id(equipment_id).and_then(|equipment| {
                        EquipmentDaKongGemSnapshot::from_catalog(
                            equipment.addon_property_value(
                                &self.goods_factory,
                                crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_DAKONG_1 + 6,
                                2,
                            ) as u32,
                            &self.goods_factory,
                        )
                    })
                });
                let equipment = player
                    .get_goods_by_id_mut(equipment_id)
                    .expect("destroy equipment проверен до mutation");
                deal_with_da_kong_external_attributes(
                    equipment,
                    &self.goods_factory,
                    slot_seven,
                    false,
                );
                if socket != 7 {
                    deal_with_da_kong_seven(equipment, &self.goods_factory, false);
                }
                let mut add_types = BTreeSet::new();
                CDaKongXiangQian::get_add_type(&mut add_types);
                if let Some(base) = self.goods_factory.query_goods_base_properties(gem_index) {
                    let gem =
                        EquipmentDaKongGemSnapshot::from_catalog(gem_index, &self.goods_factory);
                    let gem_color = base
                        .get_addon_property_values(
                            crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_BAOSHI_COLOR,
                        )
                        .iter()
                        .find(|value| value.id == 1)
                        .map_or(0, |value| value.base_value);
                    for addon in base.addon_properties() {
                        if !add_types.contains(&addon.property_type) {
                            continue;
                        }
                        let mut value = addon
                            .values
                            .iter()
                            .find(|value| value.id == 1)
                            .or_else(|| addon.values.first())
                            .map_or(0, |value| value.base_value);
                        if socket < 7 && gem_color == 8 {
                            value = 0;
                        }
                        if socket == 7 && gem_color != 8 {
                            value /= 2;
                        }
                        if socket == 7
                            && gem_color == 8
                            && !gem.is_some_and(|gem| {
                                equipment_da_kong_condition(gem, equipment, &self.goods_factory)
                            })
                        {
                            value = 0;
                        }
                        let _ = equipment.cut_addon_property_value(
                            &self.goods_factory,
                            addon.property_type,
                            1,
                            value,
                            gem_index,
                        );
                    }
                }
                let _ = equipment.set_addon_property_modifier_core(property, 2, 0);
                deal_with_da_kong_seven(equipment, &self.goods_factory, true);
                let new_seven_index = equipment.addon_property_value(
                    &self.goods_factory,
                    crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_DAKONG_1 + 6,
                    2,
                ) as u32;
                new_seven_after_removal = gems[6].or_else(|| {
                    EquipmentDaKongGemSnapshot::from_catalog(new_seven_index, &self.goods_factory)
                });
                removed = true;
            }
        }
        if removed {
            self.equipment_da_kong_consume_packet(player, DA_KONG_USE_SINKER_INDEX);
            let equipment = player
                .get_goods_by_id_mut(equipment_id)
                .expect("destroy equipment сохраняется до extern restore");
            deal_with_da_kong_external_attributes(
                equipment,
                &self.goods_factory,
                new_seven_after_removal,
                true,
            );
            let equipment = player
                .get_goods_by_id(equipment_id)
                .expect("destroy equipment сохраняется до audit");
            self.equipment_da_kong_log(player, 3, DA_KONG_USE_SINKER_INDEX, equipment);
        }
        let mut preview = player
            .get_goods_by_id(equipment_id)
            .expect("destroy equipment сохраняется до preview")
            .clone();
        let _ = deal_enchase_gems(&mut preview, &gems, &self.goods_factory, false);
        self.equipment_da_kong_publish_update(context, player_id, &preview);
        tracing::trace!(
            player_id,
            ?equipment_id,
            socket,
            removed,
            "удаление камня DaKong завершено"
        );
    }

