    /// Полный player query `goodsmessage 0x8FC2F`. Первый непустой old-client
    /// preview сохраняет подтверждённый ранний return EXE; create miss либо
    /// пустой payload позволяют перейти к следующему ordered set entry.
    pub(crate) fn query_ci_qing_goods<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) -> Option<()> {
        let base_indices: Vec<_> = self.find_player(player_id)?.ci_qing_list().collect();
        let mut sent = 0_usize;
        for base_index in base_indices {
            let created = {
                let (random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
                    &mut self.random_state,
                    &self.goods_factory,
                    &self.fairy_exp_conf,
                    &self.battle_fairy_exp_config,
                );
                let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
                goods_factory.create_goods(
                    base_index,
                    &mut random,
                    || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                    |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                    |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
                )
            };
            let Some(goods) = created else {
                continue;
            };
            let old_client_payload = context.encode_goods_for_old_client(&goods);
            let mut message = CMessage::new(0x0c_010c);
            message.base_mut().add(&old_client_payload);
            let delivery = message.send_to_player(self.net_server(), player_id);
            let stop = !old_client_payload.is_empty();
            sent += 1;
            tracing::trace!(
                player_id,
                base_index,
                payload_len = old_client_payload.len(),
                delivery,
                "предпросмотр CiQing отправлен"
            );
            if stop {
                break;
            }
        }
        tracing::debug!(player_id, sent, "список предметов CiQing обработан");
        Some(())
    }

    /// Сценарный `PushItemToCiQing` добавляет только подтверждённый базовый
    /// предмет татуировки и затем заново публикует весь упорядоченный список.
    pub(crate) fn push_script_ci_qing_item<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        original_name: &[u8],
        context: &mut Context,
    ) -> Option<()> {
        let base_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(original_name));
        if base_index == 0
            || !self
                .goods_factory
                .query_goods_base_properties(base_index)
                .is_some_and(|properties| properties.has_addon_property(GAP_CIQING_PROPERTY1))
        {
            return None;
        }
        let inserted = self
            .find_player_mut(player_id)?
            .restore_ci_qing_entry(base_index);
        let base_indices: Vec<_> = self.find_player(player_id)?.ci_qing_list().collect();
        let mut sent = 0_usize;
        for base_index in base_indices {
            let created = {
                let (random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
                    &mut self.random_state,
                    &self.goods_factory,
                    &self.fairy_exp_conf,
                    &self.battle_fairy_exp_config,
                );
                let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
                goods_factory.create_goods(
                    base_index,
                    &mut random,
                    || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                    |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                    |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
                )
            };
            let Some(goods) = created else {
                continue;
            };
            let old_client_payload = context.encode_goods_for_old_client(&goods);
            let mut message = CMessage::new(0x0c_010c);
            message.base_mut().add(&old_client_payload);
            let delivery = message.send_to_player(self.net_server(), player_id);
            sent += 1;
            tracing::trace!(
                player_id,
                base_index,
                payload_len = old_client_payload.len(),
                delivery,
                "сценарный предпросмотр CiQing отправлен"
            );
        }
        tracing::debug!(
            player_id,
            base_index,
            inserted,
            sent,
            "сценарный предмет CiQing обработан"
        );
        Some(())
    }

    pub(crate) fn open_script_ci_qing_page(&mut self, player_id: i32) -> Option<i32> {
        self.find_player_mut(player_id)?.set_ci_qing_open(true);
        let mut message = CMessage::new(0x000c_0112);
        message.add_long(1);
        Some(message.send_to_player(self.net_server(), player_id))
    }

    /// Global setup query `goodsmessage 0x8FC30`; serialization block не
    /// превращается в пустой успешный packet.
    pub(crate) fn query_ci_qing_setup(&self, player_id: i32) {
        let mut payload = Vec::new();
        let payload = self
            .ci_qing_setup
            .add_byte_to_array(&mut payload)
            .map(|()| payload);
        match payload {
            Ok(payload) => {
                let payload_len = payload.len();
                let mut message = CMessage::new(0x0c_010d);
                message.base_mut().add(&payload);
                let delivery = message.send_to_player(self.net_server(), player_id);
                tracing::trace!(
                    player_id,
                    payload_len,
                    delivery,
                    "настройки CiQing отправлены"
                );
            }
            Err(error) => tracing::warn!(player_id, ?error, "настройки CiQing не сериализованы"),
        }
    }

