    /// Полный `CPlayer::MakeCiQingNode` и его `goodsmessage 0x8FC31` tail.
    /// Resource logs предшествуют каждому DeleteGoods-effect; финальный
    /// positive log сохраняет странный native count оставшихся в vector-е
    /// (то есть не добавленных), после чего всегда отправляется `0xBF932`.
    pub(crate) fn make_ci_qing_node<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        base_index: u32,
        amount: u32,
        context: &mut Context,
    ) -> Option<()> {
        let player = self.find_player(player_id)?;
        if !player.ci_qing_list().any(|entry| entry == base_index) {
            let delivery = self.finish_ci_qing_make(player_id, 0);
            tracing::trace!(
                player_id,
                base_index,
                amount,
                delivery,
                "узел CiQing не открыт"
            );
            return Some(());
        }
        if amount >= 10 {
            let delivery = self.finish_ci_qing_make(player_id, 0);
            tracing::trace!(
                player_id,
                base_index,
                amount,
                delivery,
                "количество создаваемых узлов CiQing вне диапазона"
            );
            return Some(());
        }
        let Some(recipe) = self
            .ci_qing_setup
            .make()
            .iter()
            .find(|node| node.destination_base_index == base_index)
            .copied()
        else {
            let delivery = self.finish_ci_qing_make(player_id, 0);
            tracing::trace!(
                player_id,
                base_index,
                amount,
                delivery,
                "рецепт узла CiQing не найден"
            );
            return Some(());
        };
        let need_a = recipe.source_a_count.wrapping_mul(amount);
        let need_b = recipe.source_b_count.wrapping_mul(amount);
        if player.check_item_in_packet(recipe.source_a_base_index) < need_a {
            let delivery = self.finish_ci_qing_make(player_id, 0);
            tracing::trace!(
                player_id,
                base_index,
                amount,
                delivery,
                "не хватает первого материала узла CiQing"
            );
            return Some(());
        }
        if player.check_item_in_packet(recipe.source_b_base_index) < need_b {
            let delivery = self.finish_ci_qing_make(player_id, 0);
            tracing::trace!(
                player_id,
                base_index,
                amount,
                delivery,
                "не хватает второго материала узла CiQing"
            );
            return Some(());
        }
        if !player.packet().check_space(amount) {
            let delivery = self.finish_ci_qing_make(player_id, 0);
            tracing::trace!(
                player_id,
                base_index,
                amount,
                delivery,
                "для узла CiQing не хватает места"
            );
            return Some(());
        }

        for (source_base_index, required) in [
            (recipe.source_a_base_index, need_a),
            (recipe.source_b_base_index, need_b),
        ] {
            let log = CiQingLog {
                player_id,
                delta: -1,
                operation: 1,
                base_index: source_base_index,
                amount: required,
            };
            self.send_ci_qing_log(&log);
            tracing::trace!(
                player_id,
                source_base_index,
                required,
                "аудит расхода материала CiQing отправлен"
            );
            let consumptions = self
                .players
                .get_mut(&player_id)
                .expect("player проверен до CiQing resource removal")
                .remove_item_in_packet(source_base_index, required);
            for consumption in consumptions {
                let deliveries = self.send_player_packet_consumption(&consumption);
                tracing::trace!(
                    player_id,
                    source_base_index,
                    ?deliveries,
                    "расход материала CiQing отправлен"
                );
            }
        }

        let created = {
            let (random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
                &mut self.random_state,
                &self.goods_factory,
                &self.fairy_exp_conf,
                &self.battle_fairy_exp_config,
            );
            let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
            goods_factory.create_goods_batch(
                recipe.destination_base_index,
                amount,
                &mut random,
                || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
            )
        };
        let (additions, rejected) = {
            let goods_factory = &self.goods_factory;
            let player = self
                .players
                .get_mut(&player_id)
                .expect("player проверен до CiQing packet add");
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.add_goods_to_packet(created, goods_factory, &mut encode)
        };
        for addition in additions {
            if addition.resulting_amount.is_some() {
                let deliveries = self.send_player_packet_addition(&addition);
                tracing::trace!(
                    player_id,
                    base_index = recipe.destination_base_index,
                    ?deliveries,
                    "созданный узел CiQing отправлен"
                );
            }
        }
        let log = CiQingLog {
            player_id,
            delta: 1,
            operation: 1,
            base_index: recipe.destination_base_index,
            amount: rejected.len() as u32,
        };
        self.send_ci_qing_log(&log);
        let delivery = self.finish_ci_qing_make(player_id, recipe.destination_base_index);
        tracing::debug!(
            player_id,
            base_index,
            amount,
            rejected_count = rejected.len(),
            delivery,
            "создание узла CiQing завершено"
        );
        Some(())
    }

    fn finish_ci_qing_make(&self, player_id: i32, result_base_index: u32) -> i32 {
        let mut message = CMessage::new(0x0b_f932);
        message.add_ulong(result_base_index);
        message.send_to_player(self.net_server(), player_id)
    }

    pub(crate) fn compose_ci_qing_node<Context: CiQingComposeContext>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) -> Option<()> {
        let slots = self.find_player(player_id).map(|player| {
            (
                player
                    .ci_qing_compose_goods(0)
                    .map(|goods| (goods.base_properties_index(), goods.amount())),
                player
                    .ci_qing_compose_goods(1)
                    .map(|goods| (goods.base_properties_index(), goods.amount())),
                player.ci_qing_compose_goods(2).is_some(),
            )
        })?;
        let (Some(slot_zero), Some(slot_one)) = (slots.0, slots.1) else {
            let delivery = colored_player_notice_message(
                0xffff_ffff,
                0,
                self.get_string_by_id(b"PLAYER001006"),
            )
            .send_to_player(self.net_server(), player_id);
            tracing::trace!(player_id, delivery, "исходные узлы CiQing отсутствуют");
            return Some(());
        };
        let (source_a_index, source_b_index) = if slot_zero.0 < slot_one.0 {
            (slot_zero.0, slot_one.0)
        } else {
            (slot_one.0, slot_zero.0)
        };
        if slots.2 {
            let delivery = colored_player_notice_message(
                0xffff_ffff,
                0,
                self.get_string_by_id(b"PLAYER001005"),
            )
            .send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                source_a_index,
                source_b_index,
                delivery,
                "позиция результата соединения CiQing занята"
            );
            return Some(());
        }

        let recipe = self
            .ci_qing_setup
            .compute_node(source_a_index, source_b_index)
            .or_else(|| self.ci_qing_setup.compute_node(0, 0));
        let recipe_found = recipe.is_some();
        let required_crystal = recipe.as_ref().map_or(100, |node| node.crystal_count);
        let required_money = recipe.as_ref().map_or(100, |node| node.money);
        let crystal_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(b"FZ0965"));
        let player = self
            .find_player(player_id)
            .expect("player snapshot получен перед CiQing compose");
        if player.money() < required_money
            || player.check_item_in_packet(crystal_index) < required_crystal
        {
            let delivery = colored_player_notice_message(
                0xffff_0000,
                0xffff_ff00,
                self.get_string_by_id(b"PLAYER001001"),
            )
            .send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                source_a_index,
                source_b_index,
                required_crystal,
                required_money,
                delivery,
                "для соединения CiQing не хватает оплаты"
            );
            return Some(());
        }

        let roll = game_legacy_random(&mut self.random_state, 10_000) as u32;
        let mut result_index = None;
        if let Some(recipe) = recipe.as_ref() {
            let money_change = {
                let (players, goods_factory) = (&mut self.players, &self.goods_factory);
                players
                    .get_mut(&player_id)
                    .expect("player проверен до CiQing money mutation")
                    .decrease_money(required_money, goods_factory)
            };
            let money_deliveries =
                self.send_player_money_decrease(player_id, &money_change.outcome);
            tracing::trace!(
                player_id,
                ?money_deliveries,
                "уменьшение денег за соединение CiQing отправлено"
            );
            let crystal_log = CiQingLog {
                player_id,
                delta: -1,
                operation: 2,
                base_index: crystal_index,
                amount: required_crystal,
            };
            self.send_ci_qing_log(&crystal_log);
            tracing::trace!(
                player_id,
                "аудит кристаллов соединения CiQing отправлен"
            );
            let consumptions = self
                .players
                .get_mut(&player_id)
                .expect("player проверен до crystal removal")
                .remove_item_in_packet(crystal_index, required_crystal);
            for consumption in consumptions {
                let deliveries = self.send_player_packet_consumption(&consumption);
                tracing::trace!(
                    player_id,
                    ?deliveries,
                    "расход кристаллов соединения CiQing отправлен"
                );
            }
            if roll < recipe.compose_probability {
                let selected = CCiQingSetup::random_choice(recipe, |upper_bound| {
                    game_legacy_random(&mut self.random_state, upper_bound)
                });
                result_index = Some(if selected == 0 {
                    source_a_index
                } else {
                    selected
                });
            }
        } else if roll < 8000 {
            result_index = Some(source_a_index);
        }
        if let Some(result_index) = result_index {
            let created = {
                let (random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
                    &mut self.random_state,
                    &self.goods_factory,
                    &self.fairy_exp_conf,
                    &self.battle_fairy_exp_config,
                );
                let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
                goods_factory.create_goods(
                    result_index,
                    &mut random,
                    || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                    |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                    |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
                )
            };
            if let Some(created) = created {
                let (addition, rejected) = {
                    let goods_factory = &self.goods_factory;
                    let player = self
                        .players
                        .get_mut(&player_id)
                        .expect("player проверен до CiQing result add");
                    let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
                    player.add_goods_to_ci_qing(created, 2, true, goods_factory, &mut encode)
                };
                if addition.resulting_amount.is_some() {
                    let deliveries = self.send_ci_qing_container_addition(&addition);
                    tracing::trace!(
                        player_id,
                        result_index,
                        ?deliveries,
                        "результат соединения CiQing добавлен"
                    );
                }
                tracing::trace!(
                    player_id,
                    result_index,
                    rejected = rejected.is_some(),
                    "создание результата соединения CiQing обработано"
                );
            }
        }

        for (position, source) in [(0, slot_zero), (1, slot_one)] {
            let log = CiQingLog {
                player_id,
                delta: -1,
                operation: 2,
                base_index: source.0,
                amount: source.1,
            };
            self.send_ci_qing_log(&log);
            tracing::trace!(
                player_id,
                position,
                source_index = source.0,
                "аудит исходного узла CiQing отправлен"
            );
            if let Some(consumption) = self
                .players
                .get_mut(&player_id)
                .expect("player проверен до CiQing source removal")
                .remove_ci_qing_compose_goods(position)
            {
                let deliveries = self.send_ci_qing_container_consumption(&consumption);
                tracing::trace!(
                    player_id,
                    position,
                    ?deliveries,
                    "расход исходного узла CiQing отправлен"
                );
            }
        }

        let result = self
            .find_player(player_id)
            .and_then(|player| player.ci_qing_compose_goods(2))
            .map(|goods| (goods.base_properties_index(), goods.amount()));
        let string_id = if result.is_some() {
            b"PLAYER001002".as_slice()
        } else {
            b"PLAYER001003".as_slice()
        };
        let mut message = CMessage::new(0x0b_f81b);
        add_legacy_c_string(message.base_mut(), self.get_string_by_id(string_id));
        message.add_ulong(0);
        let result_delivery = message.send_to_player(self.net_server(), player_id);
        if let Some((result_index, _)) = result {
            // Native добавляет index уже после SendToPlayer; mutation остаётся
            // намеренно невидимой клиенту.
            message.add_ulong(result_index);
        }
        if let Some((result_index, result_amount)) = result {
            self.players
                .get_mut(&player_id)
                .expect("player проверен до CiQing unlock")
                .restore_ci_qing_entry(result_index);
            let _ = self.query_ci_qing_goods(player_id, context);
            let log = CiQingLog {
                player_id,
                delta: 1,
                operation: 2,
                base_index: result_index,
                amount: result_amount,
            };
            self.send_ci_qing_log(&log);
            tracing::debug!(
                player_id,
                source_a_index,
                source_b_index,
                recipe_found,
                roll,
                result_index,
                result_amount,
                result_delivery,
                "соединение CiQing завершено успешно"
            );
        } else {
            tracing::debug!(
                player_id,
                source_a_index,
                source_b_index,
                recipe_found,
                roll,
                result_delivery,
                "соединение CiQing завершилось неудачей"
            );
        }
        Some(())
    }

    pub(crate) fn delete_goods_from_ci_qing<Context: CiQingComposeContext>(
        &mut self,
        player_id: i32,
        position: u32,
        context: &mut Context,
    ) -> Option<()> {
        let reset_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(b"CQ0008"));
        let can_delete = self.find_player(player_id).is_some_and(|player| {
            player.ci_qing_goods(position).is_some()
                && player.check_item_in_packet(reset_index) != 0
        });
        if !can_delete {
            let delivery = colored_player_notice_message(
                0xffff_ffff,
                0,
                self.get_string_by_id(b"PLAYER001004"),
            )
            .send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                position,
                reset_index,
                delivery,
                "удаление CiQing отклонено"
            );
            return self.find_player(player_id).map(|_| ());
        }
        let reset_log = CiQingLog {
            player_id,
            delta: -1,
            operation: 4,
            base_index: reset_index,
            amount: 1,
        };
        self.send_ci_qing_log(&reset_log);
        tracing::trace!(
            player_id,
            position,
            "аудит предмета сброса CiQing отправлен"
        );
        let reset_consumptions = self
            .players
            .get_mut(&player_id)
            .expect("player проверен до CiQing reset-item removal")
            .remove_item_in_packet(reset_index, 1);
        for consumption in reset_consumptions {
            let deliveries = self.send_player_packet_consumption(&consumption);
            tracing::trace!(
                player_id,
                position,
                ?deliveries,
                "расход предмета сброса CiQing отправлен"
            );
        }
        if let Some(consumption) = self
            .players
            .get_mut(&player_id)
            .expect("player проверен до CiQing goods removal")
            .remove_ci_qing_goods(position, 1)
        {
            let deliveries = self.send_ci_qing_container_consumption(&consumption);
            tracing::trace!(
                player_id,
                position,
                ?deliveries,
                "удаление узла CiQing отправлено"
            );
        }
        self.refresh_ci_qing_player_property(player_id, context);
        tracing::debug!(player_id, position, "узел CiQing удалён");
        Some(())
    }

    pub(crate) fn mount_ci_qing_from_hand<Context: CiQingComposeContext>(
        &mut self,
        player_id: i32,
        amount: u32,
        context: &mut Context,
    ) -> Option<()> {
        let player = self.find_player(player_id)?;
        let Some((position, improve_level, base_chance)) =
            player.ci_qing_mount_facts(&self.goods_factory)
        else {
            tracing::trace!(
                player_id,
                amount,
                "предмет в руке нельзя установить как CiQing"
            );
            return Some(());
        };
        if player.ci_qing_goods(position).is_some() {
            tracing::trace!(player_id, amount, position, "позиция CiQing уже занята");
            return Some(());
        }
        let Some(node) = self.ci_qing_setup.improve_node(improve_level) else {
            tracing::trace!(
                player_id,
                amount,
                position,
                improve_level,
                "настройка улучшения CiQing не найдена"
            );
            return Some(());
        };
        if player.check_item_in_packet(node.base_index) < amount {
            tracing::trace!(
                player_id,
                amount,
                position,
                material_index = node.base_index,
                "материала для установки CiQing недостаточно"
            );
            return Some(());
        }
        let chance = base_chance
            .wrapping_add(node.probability.wrapping_mul(amount))
            .min(10_000);
        let roll = game_legacy_random(&mut self.random_state, 0x2711) as u32;
        let succeeded = roll < chance;
        let hand_goods = self
            .find_player(player_id)
            .and_then(CPlayer::ci_qing_hand_goods)
            .expect("mount facts подтверждают hand goods");
        let hand_base_index = hand_goods.base_properties_index();
        let cloned_hand_goods = if succeeded {
            let Some(cloned) = context.clone_ci_qing_hand_goods(hand_goods) else {
                tracing::warn!(
                    player_id,
                    amount,
                    position,
                    "не удалось клонировать предмет для установки CiQing"
                );
                return Some(());
            };
            Some(cloned)
        } else {
            None
        };

        if !succeeded {
            let log = CiQingLog {
                player_id,
                delta: -1,
                operation: 3,
                base_index: hand_base_index,
                amount: 1,
            };
            self.send_ci_qing_log(&log);
            tracing::trace!(
                player_id,
                position,
                "аудит неудачной установки CiQing отправлен"
            );
        }
        if let Some(consumption) = self
            .players
            .get_mut(&player_id)
            .expect("player проверен до CiQing hand removal")
            .remove_ci_qing_hand_goods()
        {
            let deliveries = self.send_ci_qing_hand_consumption(&consumption);
            tracing::trace!(
                player_id,
                position,
                ?deliveries,
                "расход предмета в руке для CiQing отправлен"
            );
        }

        if succeeded {
            let (addition, rejected) = {
                let goods_factory = &self.goods_factory;
                let player = self
                    .players
                    .get_mut(&player_id)
                    .expect("player проверен до CiQing mounted clone add");
                let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
                player.add_goods_to_ci_qing(
                    cloned_hand_goods.expect("успешная ветвь проверила native Clone"),
                    position,
                    false,
                    goods_factory,
                    &mut encode,
                )
            };
            if addition.resulting_amount.is_some() {
                let deliveries = self.send_ci_qing_container_addition(&addition);
                tracing::trace!(
                    player_id,
                    position,
                    ?deliveries,
                    "установленный CiQing добавлен"
                );
            }
            self.refresh_ci_qing_player_property(player_id, context);
            tracing::trace!(
                player_id,
                position,
                rejected = rejected.is_some(),
                "свойства установленного CiQing обновлены"
            );
        }

        let material_log = CiQingLog {
            player_id,
            delta: -1,
            operation: 3,
            base_index: node.base_index,
            amount,
        };
        self.send_ci_qing_log(&material_log);
        let consumptions = self
            .players
            .get_mut(&player_id)
            .expect("player проверен до CiQing mount material removal")
            .remove_item_in_packet(node.base_index, amount);
        for consumption in consumptions {
            let deliveries = self.send_player_packet_consumption(&consumption);
            tracing::trace!(
                player_id,
                position,
                ?deliveries,
                "расход материала установки CiQing отправлен"
            );
        }
        let mut message = CMessage::new(0x0c_0111);
        message.add_ulong(u32::from(succeeded));
        let result_delivery = message.send_to_player(self.net_server(), player_id);
        tracing::debug!(
            player_id,
            amount,
            position,
            chance,
            roll,
            succeeded,
            result_delivery,
            "установка CiQing завершена"
        );
        Some(())
    }

    pub(crate) fn query_ci_qing_other_person<Context: CiQingComposeContext>(
        &mut self,
        requester_id: i32,
        target: CiQingOtherPersonTarget,
        context: &mut Context,
    ) {
        let target_player_id = match &target {
            CiQingOtherPersonTarget::Id(player_id) => {
                self.find_player(*player_id).map(CPlayer::player_id)
            }
            CiQingOtherPersonTarget::Name(name) => {
                self.find_player_by_name(name).map(CPlayer::player_id)
            }
            CiQingOtherPersonTarget::UnsupportedMode(_) => None,
        };
        let Some(target_player_id) = target_player_id else {
            tracing::trace!(requester_id, ?target, "цель просмотра CiQing не найдена");
            return;
        };
        let player = self
            .find_player(target_player_id)
            .expect("target ID разрешён через canonical player map");
        let merged = player.ci_qing_property_result();
        let mut payload = Vec::new();
        let mut writer = LegacyWriter::new(&mut payload);
        writer.write_i32(player.shape().identity().object_type);
        writer.write_i32(player.player_id());
        for value in merged.values() {
            writer.write_u32(*value);
        }
        writer.write_u32(player.ci_qing_goods_amount(&self.goods_factory));
        for position in 0..8 {
            if let Some(goods) = player.ci_qing_goods(position) {
                writer.write_bytes(&context.encode_goods_for_old_client(goods));
            }
        }
        writer.write_u32(player.ci_qing_property_snapshot().2);
        let mut message = CMessage::new(0x0c_010f);
        message.base_mut().add(&payload);
        let delivery = message.send_to_player(self.net_server(), requester_id);
        tracing::debug!(
            requester_id,
            target_player_id,
            payload_len = payload.len(),
            delivery,
            "данные CiQing другого игрока отправлены"
        );
    }

    fn refresh_ci_qing_player_property<Context: CiQingComposeContext>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) {
        let snapshot = context.mount_ci_qing_equipment(self, player_id);
        let add_values = CPlayer::update_ci_qing_property_difference(
            &snapshot.previous_type_values,
            &snapshot.current_type_values,
        );
        let (changed, result_values) = {
            let player = self
                .players
                .get_mut(&player_id)
                .expect("property runtime получает canonical player");
            let previous_add_values = player.ci_qing_property_snapshot().0;
            let changed = add_values
                .as_ref()
                .is_some_and(|add_values| previous_add_values != add_values);
            let stored_add_values =
                add_values.unwrap_or_else(|| player.ci_qing_property_snapshot().0.clone());
            player.apply_ci_qing_property_snapshot(
                stored_add_values,
                snapshot.tao_zhuang_add_values,
                snapshot.tao_zhuang_id,
            );
            (changed, player.ci_qing_property_result())
        };
        if changed {
            let mut message = CMessage::new(0x0c_0110);
            message.add_long(player_id);
            message.add_long(player_id);
            for value in result_values.values() {
                message.add_ulong(*value);
            }
            let delivery = message.send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                delivery,
                "изменение свойств CiQing отправлено игроку"
            );
        }
    }

    pub(crate) const fn ling_bao_setup(&self) -> &CLingBaoSetup {
        &self.ling_bao_setup
    }

    pub(crate) const fn ling_bao_setup_mut(&mut self) -> &mut CLingBaoSetup {
        &mut self.ling_bao_setup
    }

    pub(crate) const fn gods_battle_mgr(&self) -> &CGodsBattleMgr {
        &self.gods_battle_mgr
    }

    pub(crate) const fn gods_battle_mgr_mut(&mut self) -> &mut CGodsBattleMgr {
        &mut self.gods_battle_mgr
    }

    /// Script primitive at call-site `0x4C3D96`: пустой `0x5FA10` сначала
    /// уходит WorldServer-у, затем single pending requester перезаписывается.
    pub(crate) fn request_gods_battle_top_ten(&mut self, player_id: i32) {
        let request = CMessage::new(0x5fa10);
        let delivery = request.send(self, false);
        self.gods_battle_mgr.record_top_ten_request(player_id);
        tracing::trace!(
            player_id,
            ?delivery,
            "запрошена десятка лидеров битвы богов"
        );
    }

    /// Script producer at `0x4C3C11/0x4C3C2E`: factions 5/6 преобразуются
    /// в World indices 1/2; local XYD меняется только обратным `0x7F80E`.
    pub(crate) fn request_gods_battle_faction_xyd(&self, faction: i32, xyd: u32) -> bool {
        let world_faction = match faction {
            5 => 1,
            6 => 2,
            _ => {
                tracing::debug!(
                    faction,
                    xyd,
                    "запрос XYD отклонён: фракция не поддерживается"
                );
                return false;
            }
        };
        let mut request = CMessage::new(0x5fa0f);
        request.add_byte(1);
        request.add_long(world_faction);
        request.add_ulong(xyd);
        let delivery = request.send(self, false);
        tracing::trace!(faction, xyd, ?delivery, "изменение XYD отправлено World");
        true
    }

    /// Декодирует GodsBattle-регион так, чтобы производная завершающая часть
    /// `AddObject` выполнялась после каждого созданного NPC, а не поздним
    /// повторным проходом. Тем самым сохраняется взаимный порядок обращений к
    /// генератору случайных чисел для NPC региона и порождаемых ими монстров.
    pub(crate) fn decode_initial_gods_battle_region<Context>(
        &mut self,
        region: &mut CServerGodsBattleRegion,
        source: &[u8],
        cursor: &mut usize,
        include_child: bool,
        context: &mut Context,
    ) -> Result<bool, WarRegionDecodeError<ServerRegionDecodeError<Context::RuntimeError>>>
    where
        Context: WarRegionDecodeContext + GodsBattleNpcContendContext,
    {
        region.decord_from_byte_array_with_npc_entry(
            source,
            cursor,
            include_child,
            context,
            |base, faction_npcs, npc_id, context| {
                self.finish_gods_battle_npc_entry(
                    base,
                    faction_npcs,
                    npc_id,
                    context,
                );
            },
        )
    }

    fn finish_gods_battle_npc_entry<Context: GodsBattleNpcContendContext>(
        &mut self,
        region: &mut CServerRegion,
        faction_npcs: &mut [BTreeSet<i32>; 3],
        npc_id: i32,
        context: &mut Context,
    ) {
        let Some((npc_name, configuration)) = region.find_npc_by_id(npc_id).and_then(|npc| {
            let name = npc.name().to_vec();
            self.gods_battle_mgr
                .npc_configuration(&name)
                .cloned()
                .map(|configuration| (name, configuration))
        }) else {
            return;
        };
        let faction = configuration.faction;
        if !CServerGodsBattleRegion::add_faction_npc_membership(
            faction_npcs,
            npc_id,
            faction,
        ) {
            return;
        }
        let (spawned_monsters, blocked_spawns) =
            self.spawn_gods_battle_npc_monsters(region, &configuration, faction, context);
        self.gods_battle_mgr
            .reset_npc_killed_monster_count(&npc_name);
        tracing::debug!(
            region_id = region.id,
            npc_id,
            faction,
            spawned_monsters,
            blocked_spawns,
            npc_name_bytes = npc_name.len(),
            "NPC добавлен во фракцию битвы богов"
        );
    }

    /// Создаёт NPC через конкретного владельца региона. Для битвы богов
    /// производное завершение `AddObject` остаётся внутри базовой операции и
    /// предшествует круговой публикации созданного NPC.
    pub(crate) fn add_region_npc_with_clock<Context: GodsBattleNpcContendContext>(
        &mut self,
        owner: &mut ServerRegionOwner,
        setup: &ServerRegionNpcSetup,
        remember_setup: bool,
        send_around: bool,
        context: &mut Context,
        now_ms: impl FnMut(&mut Context) -> u32,
    ) -> Result<ServerRegionNpcSpawnOutcome, ServerRegionNpcSpawnBlock> {
        let (area_width, area_height) = self.area_dimensions();
        match owner {
            ServerRegionOwner::GodsBattle(region) => region.add_npc_with_clock_and_entry(
                setup,
                remember_setup,
                send_around,
                area_width,
                area_height,
                context,
                now_ms,
                |base, faction_npcs, npc_id, context| {
                    self.finish_gods_battle_npc_entry(
                        base,
                        faction_npcs,
                        npc_id,
                        context,
                    );
                },
            ),
            _ => owner.base_mut().add_npc_with_clock(
                setup,
                remember_setup,
                send_around,
                area_width,
                area_height,
                context,
                now_ms,
            ),
        }
    }

    /// Точный player-tail после успешного base `CServerRegion::AddObject`.
    pub(crate) fn enter_gods_battle_player(&mut self, region_id: i32, player_id: i32) -> bool {
        let Some((country, previous_faction)) = self
            .find_player(player_id)
            .map(|player| (player.country(), player.gods_battle_faction()))
        else {
            return false;
        };
        let Some(owner) = self.take_region_owner(region_id) else {
            return false;
        };
        let ServerRegionOwner::GodsBattle(mut region) = owner else {
            self.restore_region_owner(owner);
            return false;
        };
        let assigned_faction = (previous_faction == 0).then(|| {
            self.gods_battle_mgr
                .faction_for_country(country)
                .unwrap_or(0)
        });
        let faction = assigned_faction.unwrap_or(previous_faction);
        let faction_delivery = if let Some(assigned_faction) = assigned_faction {
            self.find_player_mut(player_id)
                .expect("player сохранён после preflight")
                .set_gods_battle_faction(assigned_faction);
            let message =
                gods_battle_property_message(player_id, b"lGodsBattleFaciton", assigned_faction);
            let player = self
                .find_player(player_id)
                .expect("player сохранён после mutation");
            Some(self.send_game_shape_around(&region.war.base, player.shape(), None, &message))
        } else {
            None
        };
        let membership_changed = region.add_faction_player(player_id, faction);
        let region_state_delivery = gods_battle_property_message(player_id, b"m_lIsInGodRegion", 1)
            .send_to_player(self.net_server(), player_id);
        self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
        tracing::trace!(
            region_id,
            player_id,
            ?assigned_faction,
            ?faction_delivery,
            membership_changed,
            region_state_delivery,
            "игрок добавлен во фракцию битвы богов"
        );
        true
    }

    /// Завершает удаление из `CServerGodsBattleRegion` после пространственной
    /// части базового региона и до дальнейших действий вызывающей стороны.
    fn finish_gods_battle_player_leave(
        &mut self,
        region_id: i32,
        region: &mut CServerGodsBattleRegion,
        player_id: i32,
    ) {
        let membership_changed = region.remove_faction_player(player_id);
        let region_state_delivery = gods_battle_property_message(player_id, b"m_lIsInGodRegion", 0)
            .send_to_player(self.net_server(), player_id);
        tracing::trace!(
            region_id,
            player_id,
            membership_changed,
            region_state_delivery,
            "игрок удалён из фракции битвы богов"
        );
    }

    fn spawn_gods_battle_npc_monsters<Context: GodsBattleNpcContendContext>(
        &mut self,
        region: &mut CServerRegion,
        configuration: &crate::setup::godsbattleconf::GodsBattleFactionNpcName,
        faction: i32,
        context: &mut Context,
    ) -> (usize, usize) {
        let (area_width, area_height) = self.area_dimensions();
        let mut spawned_monsters = 0usize;
        let mut blocked_spawns = 0usize;
        for token in configuration
            .monsters
            .split(|byte| *byte == b',')
            .filter(|token| !token.is_empty())
        {
            let fields = token
                .split(|byte| *byte == b'|')
                .filter(|field| !field.is_empty())
                .collect::<Vec<_>>();
            if fields.len() != 3 {
                record_gods_battle_log(GodsBattleNpcLog::InvalidMonsterToken {
                    token: token.to_vec(),
                });
                blocked_spawns = blocked_spawns.wrapping_add(1);
                tracing::warn!(
                    fields = fields.len(),
                    token_bytes = token.len(),
                    "некорректное описание монстра NPC битвы богов"
                );
                break;
            }
            let original_name = fields[0];
            let Some(property) = self
                .find_monster_property_by_origin_name(original_name)
                .cloned()
            else {
                record_gods_battle_log(GodsBattleNpcLog::MonsterSpawnFailed {
                    npc_name: configuration.name.clone(),
                    monster: original_name.to_vec(),
                });
                blocked_spawns = blocked_spawns.wrapping_add(1);
                tracing::warn!(
                    original_name_bytes = original_name.len(),
                    "свойства монстра NPC битвы богов отсутствуют"
                );
                continue;
            };
            let spawn = region.add_monster(
                &property,
                legacy_atoi_i32(fields[1]),
                legacy_atoi_i32(fields[2]),
                -1,
                true,
                false,
                context.now_milliseconds(),
                area_width,
                area_height,
                context,
            );
            if let Err(block) = spawn {
                record_gods_battle_log(GodsBattleNpcLog::MonsterSpawnFailed {
                    npc_name: configuration.name.clone(),
                    monster: original_name.to_vec(),
                });
                blocked_spawns = blocked_spawns.wrapping_add(1);
                tracing::warn!(?block, "создание монстра NPC битвы богов заблокировано");
                continue;
            }
            if let Some(property) = self.find_monster_property_by_origin_name_mut(original_name) {
                property.race = faction as u32;
            }
            record_gods_battle_log(GodsBattleNpcLog::MonsterSpawned {
                npc_name: configuration.name.clone(),
                monster: original_name.to_vec(),
                faction,
            });
            spawned_monsters = spawned_monsters.wrapping_add(1);
        }
        (spawned_monsters, blocked_spawns)
    }

    pub(crate) fn change_gods_battle_npc_faction<Context: GodsBattleNpcContendContext>(
        &mut self,
        region_id: i32,
        npc_id: i32,
        faction: i32,
        context: &mut Context,
    ) -> bool {
        let Some(owner) = self.take_region_owner(region_id) else {
            return false;
        };
        let ServerRegionOwner::GodsBattle(mut region) = owner else {
            self.restore_region_owner(owner);
            return false;
        };
        let Some((npc_name, configuration)) =
            region.war.base.find_npc_by_id(npc_id).and_then(|npc| {
                let name = npc.name().to_vec();
                self.gods_battle_mgr
                    .npc_configuration(&name)
                    .cloned()
                    .map(|configuration| (name, configuration))
            })
        else {
            self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
            return false;
        };
        if !region.change_npc_faction(npc_id, faction) {
            self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
            return false;
        }
        let (spawned_monsters, blocked_spawns) =
            self.spawn_gods_battle_npc_monsters(
                &mut region.war.base,
                &configuration,
                faction,
                context,
            );
        self.gods_battle_mgr
            .reset_npc_killed_monster_count(&npc_name);
        let world_delivery = self
            .gods_battle_mgr
            .update_npc_faction(&npc_name, faction)
            .map(|_| {
                let mut message = CMessage::new(0x5fa0f);
                message.add_byte(2);
                add_legacy_c_string(message.base_mut(), &npc_name);
                message.add_ulong(faction as u32);
                record_gods_battle_log(GodsBattleNpcLog::FactionUpdated {
                    npc_name: npc_name.clone(),
                    faction,
                });
                message.send(self, false)
            });
        self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
        tracing::debug!(
            region_id,
            npc_id,
            faction,
            spawned_monsters,
            blocked_spawns,
            npc_name_bytes = npc_name.len(),
            ?world_delivery,
            "фракция NPC битвы богов изменена"
        );
        true
    }

    fn finish_gods_battle_npc_leave(
        region: &mut CServerGodsBattleRegion,
        npc_id: i32,
    ) -> bool {
        region.remove_faction_npc(npc_id)
    }

    /// Concrete GodsBattle virtual `GetReturnPoint`: faction-specific entry
    /// wins; a miss delegates to the already materialized base-region rule.
    pub(crate) fn gods_battle_return_point(
        &mut self,
        region_id: i32,
        player_id: i32,
    ) -> Result<Option<RegionReturnPoint>, ServerReturnSetupBlock> {
        let Some(player) = self.find_player(player_id) else {
            return Ok(None);
        };
        let faction = player.gods_battle_faction();
        let player_facts = ServerReturnPlayer {
            id: player_id,
            country: player.country(),
            faction_id: player.faction_id(),
        };
        let owner = match self.take_region_owner(region_id) {
            Some(owner) => owner,
            None => return Ok(None),
        };
        let ServerRegionOwner::GodsBattle(region) = owner else {
            self.restore_region_owner(owner);
            return Ok(None);
        };
        if let Some(point) = self.gods_battle_mgr.return_point(region_id, faction) {
            record_gods_battle_log(GodsBattleNpcLog::ReturnPointSelected {
                player_id,
                faction,
                point,
            });
            self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
            tracing::trace!(
                player_id,
                faction,
                ?point,
                "выбрана точка возврата конфигурации битвы богов"
            );
            return Ok(Some(point));
        }
        let fallback = region
            .war
            .base
            .get_return_point(Some(player_facts), &mut self.country_param);
        self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
        fallback.map(|point| {
            tracing::trace!(
                player_id,
                faction,
                ?point,
                "выбрана базовая точка возврата из битвы богов"
            );
            Some(point)
        })
    }

    /// Полный достигнутый путь `CPlayer::OnRelive`. Только ещё не
    /// материализованные владельцы пассивных навыков и виртуального
    /// `OnEnterRegion` остаются обратными вызовами среды; очистку спутников,
    /// пересчёт свойств, движение, `OnChangeStates`, состояния покоя и мира,
    /// виртуальный `GetReturnPoint`, смену региона и клиентские сообщения
    /// исполняют владельцы `CPlayer` и `CGame`.
    pub(crate) fn relive_player<Context: PlayerReliveContext>(
        &mut self,
        player_id: i32,
        relive_type: i32,
        context: &mut Context,
    ) {
        let Some(player) = self.find_player(player_id) else {
            tracing::trace!(player_id, relive_type, "игрок для воскрешения не найден");
            return;
        };
        if !CMoveShape::is_died(player.health()) {
            let answer_delivery = self.send_player_relive_answer(player_id);
            tracing::trace!(player_id, relive_type, answer_delivery, "игрок уже жив");
            return;
        }
        let (cleared_uncreated_pets, cleared_uncreated_carriage) = {
            let player = self
                .find_player_mut(player_id)
                .expect("игрок сохранён после синхронной проверки смерти");
            context.auto_start_player_passive_skills(player);
            let cleared = player.clear_relive_uncreated_companions();
            context.player_enter_region_after_relive(player);
            cleared
        };
        let (combat_property_delivery, tao_zhuang_ran) = self
            .update_player_properties(player_id, context)
            .expect("игрок сохранён после OnEnterRegion");
        let (owned, mutation) = {
            let player = self
                .find_player_mut(player_id)
                .expect("игрок сохранён после пересчёта свойств");
            let owned = player
                .unlock_movement_after_relive(cleared_uncreated_pets, cleared_uncreated_carriage);
            let mutation = player.apply_relive_scalars();
            (owned, mutation)
        };
        let states_published = mutation
            .as_ref()
            .ok()
            .and_then(|_| self.publish_player_states(player_id));
        tracing::trace!(
            player_id,
            relive_type,
            ?owned,
            combat_property_delivery,
            tao_zhuang_ran,
            states_published = states_published.is_some(),
            "начальная часть воскрешения выполнена"
        );
        let mutation = match mutation {
            Ok(mutation) => mutation,
            Err(block) => {
                tracing::warn!(
                    player_id,
                    relive_type,
                    ?block,
                    "позиция игрока при воскрешении недоступна"
                );
                return;
            }
        };

        if relive_type == 1 {
            let resident_delivery = self.enter_player_resident_state(player_id);
            let peace_entered = self.enter_player_peace_state(player_id).is_some();
            let answer_delivery = self.send_player_relive_answer(player_id);
            let region_id = self
                .find_player(player_id)
                .and_then(CPlayer::server_region_id);
            if self
                .find_player(player_id)
                .is_some_and(|player| player.city_war_died_state_time_ms() > 0)
            {
                let _ = self.publish_relive_died_state(region_id, player_id);
            }
            let shape_delivery = region_id
                .and_then(|region_id| self.take_region_owner(region_id))
                .map(|owner| {
                    let mut message = CMessage::new(0xbf613);
                    message.add_long(player_id);
                    message.add_long(player_id);
                    let player = self
                        .find_player(player_id)
                        .expect("игрок сохранён до публикации формы");
                    let delivery = self.send_shape_around_in_region(
                        owner.base(),
                        player.shape(),
                        Some(player_id),
                        &message,
                    );
                    self.restore_region_owner(owner);
                    delivery
                });
            let region_change = region_id.map(|region_id| {
                self.change_player_region(
                    player_id,
                    region_id,
                    mutation.previous_x,
                    mutation.previous_y,
                    mutation.direction,
                    0,
                    3,
                    0,
                    context,
                )
            });
            let cannot_move_delivery = region_change.as_ref().and_then(|_| {
                self.restore_relive_origin_after_change(
                    player_id,
                    mutation.previous_x,
                    mutation.previous_y,
                )
            });
            let region_change = region_change.unwrap_or(PlayerRegionChangeOutcome::MissingPlayer);
            tracing::debug!(
                player_id,
                relive_type,
                ?mutation,
                answer_delivery,
                ?resident_delivery,
                peace_entered,
                ?shape_delivery,
                ?region_change,
                ?cannot_move_delivery,
                "игрок воскрешён на месте"
            );
            return;
        }

        let region_id = self
            .find_player(player_id)
            .and_then(CPlayer::server_region_id);
        let return_point = match region_id {
            Some(region_id) => {
                let source_is_gods_battle = self
                    .find_region(region_id)
                    .is_some_and(ServerRegionOwner::is_gods_battle);
                match self.select_player_return_point(region_id, player_id, source_is_gods_battle) {
                    Ok(point) => point,
                    Err(block) => {
                        tracing::warn!(
                            player_id,
                            relive_type,
                            ?block,
                            "точка возврата для воскрешения недоступна"
                        );
                        return;
                    }
                }
            }
            None => {
                tracing::warn!(
                    player_id,
                    relive_type,
                    ?mutation,
                    "текущий регион игрока для воскрешения не найден"
                );
                return;
            }
        };
        let mut x = return_point
            .left
            .wrapping_add(return_point.right.wrapping_sub(return_point.left) / 2);
        let mut y = return_point
            .top
            .wrapping_add(return_point.bottom.wrapping_sub(return_point.top) / 2);
        let width = return_point.right.wrapping_sub(return_point.left);
        let height = return_point.bottom.wrapping_sub(return_point.top);
        if width > 0 && height > 0 {
            if let Some(owner) = self.find_region(return_point.region_id) {
                match owner.base().region.get_random_pos_in_range(
                    return_point.left,
                    return_point.top,
                    width,
                    height,
                    context,
                ) {
                    Ok(position) => {
                        x = position.x;
                        y = position.y;
                    }
                    Err(block) => {
                        tracing::warn!(
                            player_id,
                            relive_type,
                            ?block,
                            "случайная позиция воскрешения недоступна"
                        );
                        return;
                    }
                }
            }
        }
        let resident_delivery = self.enter_player_resident_state(player_id);
        let peace_entered = self.enter_player_peace_state(player_id).is_some();
        let region_change = self.change_player_region(
            player_id,
            return_point.region_id,
            x,
            y,
            return_point.direction,
            0,
            0,
            0,
            context,
        );
        let changed_region = region_change.succeeded();
        let answer_delivery = changed_region.then(|| self.send_player_relive_answer(player_id));
        let died_state_deliveries = if self
            .find_player(player_id)
            .is_some_and(|player| player.city_war_died_state_time_ms() > 0)
        {
            let destination_region_id = self
                .find_player(player_id)
                .and_then(CPlayer::server_region_id)
                .or(Some(return_point.region_id));
            self.publish_relive_died_state(destination_region_id, player_id)
        } else {
            None
        };
        tracing::debug!(
            player_id,
            relive_type,
            ?mutation,
            ?return_point,
            x,
            y,
            changed_region,
            ?answer_delivery,
            ?resident_delivery,
            peace_entered,
            died_state_published = died_state_deliveries.is_some(),
            ?region_change,
            "игрок воскрешён в точке возврата"
        );
    }

    fn send_player_relive_answer(&self, player_id: i32) -> i32 {
        let Some(player) = self.find_player(player_id) else {
            return 0;
        };
        let mut message = CMessage::new(0xbf703);
        message
            .base_mut()
            .add_short(player.shape().get_action() as i16);
        message.add_ulong(player.health());
        message.send_to_player(self.net_server(), player_id)
    }

    /// Exact scalar/wire `EnterResidentState`: murderer timer сбрасывается до
    /// `0xBF60E(player, 0)`, опубликованного всем around-получателям.
    fn enter_player_resident_state(
        &mut self,
        player_id: i32,
    ) -> Option<Result<i32, ShapeCoordinateBlock>> {
        self.find_player_mut(player_id)?.enter_resident_state();
        let mut message = CMessage::new(0x000b_f60e);
        message.add_long(player_id);
        message.add_byte(0);
        self.send_player_shape_around(player_id, None, &message)
    }

    /// Native in-place relive вызывает `OnCannotMove(old_x, old_y)`, если
    /// смена позиции сохранила старую клетку либо её уже занял живой
    /// `CMoveShape` (goods type 700 намеренно исключён).
    fn restore_relive_origin_after_change(
        &self,
        player_id: i32,
        origin_x: i32,
        origin_y: i32,
    ) -> Option<i32> {
        let player = self.find_player(player_id)?;
        let current = (
            player.shape().get_tile_x().ok()?,
            player.shape().get_tile_y().ok()?,
        );
        let occupied = if current == (origin_x, origin_y) {
            true
        } else {
            let region = self.find_region(player.server_region_id()?)?.base();
            let shape = region
                .get_shape(
                    origin_x,
                    origin_y,
                    self.globe_setup.area_width(),
                    self.globe_setup.area_height(),
                    self,
                )
                .ok()
                .flatten();
            shape.is_some_and(|shape| match shape.identity.object_type {
                PLAYER_TYPE => self
                    .find_player(shape.identity.id)
                    .is_some_and(|player| !player.is_dead()),
                MONSTER_TYPE => region
                    .find_monster_by_id(shape.identity.id)
                    .is_some_and(|monster| !CMoveShape::is_died(monster.hit_points())),
                NPC_TYPE => true,
                GOODS_TYPE => false,
                _ => false,
            })
        };
        occupied.then(|| {
            let mut response = CMessage::new(0x000b_f605);
            response.add_long(0);
            response.add_long(0);
            response.add_long(current.0);
            response.add_long(current.1);
            response.send_to_player(self.net_server(), player_id)
        })
    }

    fn publish_player_fight_state(
        &mut self,
        phase: GamePlayerFightStatePhase,
        transition: PlayerFightStateTransition,
    ) {
        let around_delivery = transition
            .entered_peace
            .then(|| {
                let mut message = CMessage::new(0x000b_f607);
                message.add_long(transition.player_id);
                message.add_long(0);
                self.send_player_shape_around(transition.player_id, None, &message)
            })
            .flatten();
        tracing::trace!(
            ?phase,
            ?transition,
            ?around_delivery,
            "обновлено боевое состояние игрока"
        );
    }

    /// Достигнутый `EnterPeaceState`, общий для воскрешения и перехода
    /// счётчика `UpdateCurrentState`.
    fn enter_player_peace_state(&mut self, player_id: i32) -> Option<()> {
        let transition = self.find_player_mut(player_id)?.enter_peace_state();
        self.publish_player_fight_state(GamePlayerFightStatePhase::Relive, transition);
        Some(())
    }

    pub(crate) fn update_player_current_state(
        &mut self,
        player_id: i32,
        phase: GamePlayerFightStatePhase,
    ) -> Option<()> {
        let transition = self.find_player_mut(player_id)?.update_fight_state()?;
        self.publish_player_fight_state(phase, transition);
        Some(())
    }

    /// Exact criminal half `UpdateCurrentState`, вызываемый следом за combat
    /// countdown в обоих native callers. Clock sampled только при active
    /// `m_dwSinStateTimeStamp`; terminal transition делегирует concrete
    /// `EnterResidentState` с around `0xBF60E`.
    pub(crate) fn update_player_criminal_state<Runtime: GameMainLoopRuntime>(
        &mut self,
        player_id: i32,
        phase: GamePlayerFightStatePhase,
        runtime: &mut Runtime,
    ) -> Option<()> {
        if !self
            .find_player(player_id)
            .is_some_and(CPlayer::criminal_state_active)
        {
            return None;
        }
        let checked_at_ms = runtime.now_milliseconds();
        let criminal_time_ms = self.globe_setup.criminal_time_ms();
        let pk_count_per_kill = self.globe_setup.pk_count_per_kill();
        let transition = self.find_player(player_id)?.criminal_state_end_due(
            checked_at_ms,
            criminal_time_ms,
            pk_count_per_kill,
        )?;
        let around_delivery = self.enter_player_resident_state(player_id);
        tracing::trace!(
            ?phase,
            ?transition,
            ?around_delivery,
            "завершено преступное состояние игрока"
        );
        Some(())
    }

    fn publish_relive_died_state(&mut self, region_id: Option<i32>, player_id: i32) -> Option<()> {
        let player = self.find_player_mut(player_id)?;
        player.set_city_war_died_state(true);
        let mut message = CMessage::new(0xbff2a);
        message.add_long(player_id);
        message.add_byte(1);
        let self_delivery = message.send_to_player(self.net_server(), player_id);
        let mut around_delivery = None;
        if let Some(owner) = region_id.and_then(|region_id| self.take_region_owner(region_id)) {
            if let Some(player) = self.find_player(player_id) {
                around_delivery = Some(self.send_shape_around_in_region(
                    owner.base(),
                    player.shape(),
                    None,
                    &message,
                ));
            }
            self.restore_region_owner(owner);
        }
        tracing::trace!(
            player_id,
            self_delivery,
            ?around_delivery,
            "опубликовано состояние смерти после воскрешения"
        );
        Some(())
    }

    pub(crate) fn gods_battle_monster_died(
        &mut self,
        region_id: i32,
        monster_id: i32,
        killer_type: i32,
        killer_id: i32,
    ) -> Option<()> {
        let (original_name, display_name) = self
            .find_region(region_id)
            .and_then(|owner| match owner {
                ServerRegionOwner::GodsBattle(region) => {
                    region.war.base.find_monster_by_id(monster_id)
                }
                _ => None,
            })
            .map(|monster| {
                (
                    monster.original_name().to_vec(),
                    monster.display_name().to_vec(),
                )
            })?;
        if self
            .find_monster_property_by_origin_name(&original_name)
            .is_none_or(|property| property.ai != 0x17)
        {
            return None;
        }
        let Some(npc_name) = self
            .gods_battle_mgr
            .npc_name_by_monster(&original_name)
            .map(ToOwned::to_owned)
        else {
            record_gods_battle_log(GodsBattleNpcLog::MonsterWithoutNpc {
                monster: display_name,
            });
            tracing::debug!(
                region_id,
                monster_id,
                "для погибшего стража битвы богов не найден NPC"
            );
            return Some(());
        };
        let Some(killed) = self
            .gods_battle_mgr
            .increment_npc_killed_monster_count(&npc_name)
        else {
            record_gods_battle_log(GodsBattleNpcLog::MissingKillCounter {
                npc_name: npc_name.clone(),
            });
            tracing::debug!(region_id, monster_id, npc_name = %String::from_utf8_lossy(&npc_name), "для NPC битвы богов не найден счётчик убийств");
            return Some(());
        };
        record_gods_battle_log(GodsBattleNpcLog::MonsterKilled {
            npc_name: npc_name.clone(),
            monster: display_name.clone(),
            killer_type,
            killer_id,
        });
        let total = self.gods_battle_mgr.npc_monster_count(&npc_name);
        if total == 0 {
            record_gods_battle_log(GodsBattleNpcLog::NoConfiguredMonsters {
                npc_name: npc_name.clone(),
            });
            tracing::debug!(region_id, monster_id, npc_name = %String::from_utf8_lossy(&npc_name), killed, total, "для NPC битвы богов не настроены стражи");
            return Some(());
        }
        let remaining = (total as i32).wrapping_sub(killed as i32);
        let player_notice_delivery =
            if killer_type == PLAYER_TYPE && self.find_player(killer_id).is_some() {
                let text = if remaining > 0 {
                    format_legacy_mixed(
                        self.get_string_by_id(b"SZLGS8"),
                        &[
                            LegacyFormatArgument::Bytes(&display_name),
                            LegacyFormatArgument::Signed(remaining),
                            LegacyFormatArgument::Bytes(&npc_name),
                        ],
                        0xff,
                    )
                } else if remaining == 0 {
                    format_legacy_mixed(
                        self.get_string_by_id(b"SZLGS9"),
                        &[LegacyFormatArgument::Bytes(&npc_name)],
                        0xff,
                    )
                } else {
                    record_gods_battle_log(GodsBattleNpcLog::KillCountExceeded {
                        npc_name: npc_name.clone(),
                    });
                    Vec::new()
                };
                (!text.is_empty()).then(|| {
                    colored_player_notice_message(0xffff_ffff, 0, &text)
                        .send_to_player(self.net_server(), killer_id)
                })
            } else {
                None
            };
        tracing::debug!(region_id, monster_id, npc_name = %String::from_utf8_lossy(&npc_name), killed, total, ?player_notice_delivery, "учтена смерть стража битвы богов");
        Some(())
    }

    pub(crate) fn enter_gods_battle_contend<Context: GodsBattleNpcContendContext>(
        &mut self,
        region_id: i32,
        player_id: i32,
        npc_id: i32,
        max_time: i32,
        context: &mut Context,
    ) -> Option<()> {
        let player_facts = self.find_player(player_id).map(|player| {
            (
                player.can_enter_gods_battle_contend(),
                player.faction_id(),
                player.gods_battle_faction(),
            )
        });
        let owner = self.take_region_owner(region_id)?;
        let ServerRegionOwner::GodsBattle(mut region) = owner else {
            self.restore_region_owner(owner);
            return None;
        };
        let npc_name = region
            .war
            .base
            .find_npc_by_id(npc_id)
            .map(|npc| npc.name().to_vec());
        let outcome = match (player_facts, npc_name) {
            (None, _) => "игрок не найден",
            (_, None) => "NPC не найден",
            (Some((false, _, _)), Some(_)) => "игрок недоступен",
            (Some((_, _, gods_faction)), Some(_)) if !matches!(gods_faction, 5 | 6) => {
                "недопустимая сторона игрока"
            }
            (Some((_, _, _)), Some(_)) if region.npc_faction(npc_id).is_none() => {
                "недопустимая сторона NPC"
            }
            (Some((_, normal_faction, gods_faction)), Some(npc_name)) => {
                let total = self.gods_battle_mgr.npc_monster_count(&npc_name);
                let killed = self.gods_battle_mgr.npc_killed_monster_count(&npc_name);
                if killed != total {
                    let remaining = total.wrapping_sub(killed);
                    let text = format_legacy_mixed(
                        self.get_string_by_id(b"SZLGS6"),
                        &[LegacyFormatArgument::Bytes(&npc_name)],
                        0xff,
                    );
                    let delivery = colored_player_notice_message(0xffff_ffff, 0xffff_0000, &text)
                        .send_to_player(self.net_server(), player_id);
                    tracing::trace!(
                        region_id,
                        player_id,
                        npc_id,
                        remaining,
                        delivery,
                        "захват битвы богов заблокирован оставшимися стражами"
                    );
                    "остались стражи"
                } else if region.npc_faction(npc_id) == Some(gods_faction) {
                    let text = format_legacy_mixed(
                        self.get_string_by_id(b"SZLGS7"),
                        &[LegacyFormatArgument::Bytes(&npc_name)],
                        0xff,
                    );
                    let delivery = colored_player_notice_message(0xffff_ffff, 0xffff_0000, &text)
                        .send_to_player(self.net_server(), player_id);
                    tracing::trace!(
                        region_id,
                        player_id,
                        npc_id,
                        delivery,
                        "сторона игрока уже владеет NPC битвы богов"
                    );
                    "сторона уже владеет NPC"
                } else if region.is_player_contending_symbol(player_id, npc_id) {
                    "игрок уже захватывает NPC"
                } else {
                    if matches!(
                        region.cancel_contend_by_player_id(player_id),
                        GodsBattleCancelByPlayer::MissingReset
                    ) {
                        if let Some(delivery) = self.set_gods_battle_player_contend_state(
                            &region.war.base,
                            player_id,
                            false,
                        ) {
                            tracing::trace!(
                                region_id,
                                player_id,
                                delivery,
                                "сброшено прежнее состояние захвата битвы богов"
                            );
                        }
                        let delivery = self.send_gods_battle_contend_time(player_id, 0);
                        tracing::trace!(
                            region_id,
                            player_id,
                            delivery,
                            "сброшено прежнее время захвата битвы богов"
                        );
                    }
                    let first_for_legacy_faction = region.add_contender(
                        player_id,
                        normal_faction,
                        gods_faction,
                        npc_id,
                        &npc_name,
                        max_time,
                        context.now_milliseconds(),
                    );
                    if let Some(delivery) =
                        self.set_gods_battle_player_contend_state(&region.war.base, player_id, true)
                    {
                        tracing::trace!(
                            region_id,
                            player_id,
                            delivery,
                            "опубликовано состояние захвата битвы богов"
                        );
                    }
                    let time_delivery = self.send_gods_battle_contend_time(player_id, 0);
                    if first_for_legacy_faction {
                        let faction_text = match gods_faction {
                            5 => self.get_string_by_id(b"SZLGS1"),
                            6 => self.get_string_by_id(b"SZLGS2"),
                            _ => &[],
                        };
                        let text =
                            format_legacy_text_fields(b"%s%s", &[faction_text, &npc_name], 0xff);
                        let delivery =
                            nation_colored_text_message(0xbf806, 0xffff_ffff, 0xffff_0000, &text)
                                .send_to_region(Some(&region.war.base), None, self);
                        tracing::trace!(
                            region_id,
                            player_id,
                            npc_id,
                            delivery,
                            "опубликован первый претендент стороны битвы богов"
                        );
                    }
                    let notice_delivery = colored_player_notice_message(
                        0xffff_ffff,
                        0xffff_0000,
                        self.get_string_by_id(b"SZLGS3"),
                    )
                    .send_to_player(self.net_server(), player_id);
                    tracing::trace!(
                        region_id,
                        player_id,
                        npc_id,
                        first_for_legacy_faction,
                        time_delivery,
                        notice_delivery,
                        "начат захват NPC битвы богов"
                    );
                    "захват начат"
                }
            }
        };
        self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
        tracing::debug!(
            region_id,
            player_id,
            npc_id,
            outcome,
            "обработан вход в захват битвы богов"
        );
        Some(())
    }

    pub(crate) fn gods_battle_contend_ai<Runtime: GameMainLoopRuntime>(
        &mut self,
        region_id: i32,
        ai_tick: i32,
        tick_interval_ms: i32,
        runtime: &mut Runtime,
    ) -> Option<()> {
        let owner = self.take_region_owner(region_id)?;
        let ServerRegionOwner::GodsBattle(mut region) = owner else {
            self.restore_region_owner(owner);
            return None;
        };
        let removed_npcs = match self.run_server_region_base_ai(
            &mut region.war.base,
            ai_tick,
            tick_interval_ms,
            runtime,
        ) {
            Ok(removed_npcs) => removed_npcs,
            Err(error) => {
                self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
                tracing::warn!(
                    region_id,
                    ai_tick,
                    ?error,
                    "базовый проход ИИ битвы богов заблокирован"
                );
                return Some(());
            }
        };
        for npc_id in removed_npcs {
            Self::finish_gods_battle_npc_leave(&mut region, npc_id);
        }
        let advance = region.advance_contenders(runtime.now_milliseconds());
        let progress_count = advance.progress.len();
        let completion_count = advance.completed.len();
        for (player_id, percentage) in advance.progress {
            let delivery = self.send_gods_battle_contend_time(player_id, percentage);
            tracing::trace!(
                region_id,
                player_id,
                percentage,
                delivery,
                "отправлено время захвата в битве богов"
            );
        }
        self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
        for contender in advance.completed {
            self.complete_gods_battle_contend(region_id, contender, runtime);
        }
        tracing::trace!(
            region_id,
            progress_count,
            completion_count,
            "завершён проход захватов битвы богов"
        );
        Some(())
    }

    fn complete_gods_battle_contend<Context: GodsBattleNpcContendContext>(
        &mut self,
        region_id: i32,
        contender: GodsBattleContender,
        context: &mut Context,
    ) {
        let Some(faction) = self
            .find_player(contender.player_id)
            .map(CPlayer::gods_battle_faction)
        else {
            tracing::warn!(
                region_id,
                player_id = contender.player_id,
                symbol_id = contender.symbol_id,
                "игрок завершённого захвата битвы богов не найден"
            );
            return;
        };
        let changed =
            self.change_gods_battle_npc_faction(region_id, contender.symbol_id, faction, context);
        let mut deliveries = self.cancel_gods_battle_contend_symbol(region_id, contender.symbol_id);
        if !changed {
            tracing::warn!(
                region_id,
                player_id = contender.player_id,
                symbol_id = contender.symbol_id,
                deliveries,
                "смена фракции символа битвы богов отклонена"
            );
            return;
        }
        let capture_text = match faction {
            5 => self.get_string_by_id(b"SZLGS4").to_vec(),
            6 => self.get_string_by_id(b"SZLGS5").to_vec(),
            _ => Vec::new(),
        };
        if let Some(owner) = self.take_region_owner(region_id) {
            if let ServerRegionOwner::GodsBattle(region) = &owner {
                let delivery =
                    nation_colored_text_message(0xbf806, 0xffff_ffff, 0xffff_0000, &capture_text)
                        .send_to_region(Some(&region.war.base), None, self);
                deliveries = deliveries.wrapping_add(1);
                tracing::trace!(
                    region_id,
                    delivery,
                    "отправлено уведомление о захвате символа битвы богов"
                );
            }
            self.restore_region_owner(owner);
        }
        let award_variable_result = self
            .find_player_mut(contender.player_id)
            .map(|player| {
                match player.set_string_variable(b"#fengyinNpc", &contender.symbol_name) {
                    GameVariableMutationOutcome::UpdatedString { .. } => 1,
                    GameVariableMutationOutcome::NameNotFound => -99_999_999,
                    GameVariableMutationOutcome::UpdatedInteger { .. }
                    | GameVariableMutationOutcome::UpdatedArrayElement { .. }
                    | GameVariableMutationOutcome::TypeMismatch { .. } => 0,
                }
            })
            .unwrap_or(-99_999_999);
        let award_script_result = if award_variable_result == 1 {
            let result = self
                .run_script_file(
                    b"scripts/npc/awardgoods.script",
                    ScriptExecutionContext {
                        player_id: Some(contender.player_id),
                        region_id: Some(region_id),
                        ..ScriptExecutionContext::default()
                    },
                    context,
                )
                .map_or(0, |_| 1);
            if result == 0 {
                record_gods_battle_log(GodsBattleNpcLog::AwardScriptFailed {
                    player_id: contender.player_id,
                    npc_name: contender.symbol_name.clone(),
                });
            }
            Some(result)
        } else {
            if award_variable_result == -99_999_999 {
                record_gods_battle_log(GodsBattleNpcLog::AwardVariableMissing {
                    player_id: contender.player_id,
                    npc_name: contender.symbol_name.clone(),
                });
            }
            None
        };
        let top_info_delivery = self.send_top_info_to_client(-1, 0, 1, 1, &capture_text);
        record_gods_battle_log(GodsBattleNpcLog::NpcCaptured {
            player_id: contender.player_id,
            npc_name: contender.symbol_name.clone(),
            faction,
        });
        tracing::debug!(
            region_id,
            player_id = contender.player_id,
            symbol_id = contender.symbol_id,
            faction,
            award_variable_result,
            ?award_script_result,
            ?top_info_delivery,
            deliveries,
            "завершён захват символа битвы богов"
        );
    }

    fn cancel_gods_battle_contend_symbol(&mut self, region_id: i32, symbol_id: i32) -> usize {
        let Some(owner) = self.take_region_owner(region_id) else {
            return 0;
        };
        let ServerRegionOwner::GodsBattle(mut region) = owner else {
            self.restore_region_owner(owner);
            return 0;
        };
        let mut deliveries = 0usize;
        if let Some(contender) = region.cancel_contend_by_symbol(symbol_id) {
            let time_delivery = self.send_gods_battle_contend_time(contender.player_id, 0);
            deliveries = deliveries.wrapping_add(1);
            if let Some(delivery) = self.set_gods_battle_player_contend_state(
                &region.war.base,
                contender.player_id,
                false,
            ) {
                deliveries = deliveries.wrapping_add(1);
                tracing::trace!(
                    region_id,
                    symbol_id,
                    player_id = contender.player_id,
                    time_delivery,
                    delivery,
                    "отменён захват символа битвы богов"
                );
            } else {
                tracing::trace!(
                    region_id,
                    symbol_id,
                    player_id = contender.player_id,
                    time_delivery,
                    "отменён захват символа битвы богов без смены состояния"
                );
            }
        }
        self.restore_region_owner(ServerRegionOwner::GodsBattle(region));
        deliveries
    }

    fn set_gods_battle_player_contend_state(
        &mut self,
        region: &CServerRegion,
        player_id: i32,
        state: bool,
    ) -> Option<i32> {
        let player = self.find_player_mut(player_id)?;
        if !player.set_contend_state(state) {
            return None;
        }
        let mut message = CMessage::new(0xbff28);
        message.add_long(player_id);
        message.add_byte(u8::from(state));
        let player = self
            .find_player(player_id)
            .expect("GodsBattle player сохранён до synchronous around-send");
        self.send_game_shape_around(region, player.shape(), None, &message)
            .ok()
    }

    fn send_gods_battle_contend_time(&self, player_id: i32, percentage: i32) -> i32 {
        let mut message = CMessage::new(0xbff29);
        message.add_long(percentage);
        message.send_to_player(self.net_server(), player_id)
    }

    pub(crate) fn send_top_info_to_client(
        &self,
        first: i32,
        target_player_id: i32,
        third: i32,
        fourth: i32,
        text: &[u8],
    ) -> Result<i32, SendMessageError> {
        let mut message = CMessage::new(0xbf804);
        message.add_long(target_player_id);
        message.add_long(first);
        message.add_long(third);
        message.add_long(fourth);
        add_legacy_c_string(message.base_mut(), text);
        if target_player_id == 0 {
            message.send_all(Some(self.net_server()))
        } else {
            Ok(message.send_to_player(self.net_server(), target_player_id))
        }
    }

    pub(crate) fn apply_gods_battle_xyd(&mut self, faction_a: u32, faction_b: u32) {
        let updates = self.gods_battle_mgr.set_xyd(faction_a, faction_b);
        let region_ids = self.gods_battle_mgr.region_ids();
        let mut deliveries = 0usize;
        for update in &updates {
            let (faction, xyd, changed) = match update {
                GodsBattleFactionXydUpdate::FactionA { previous, current } => {
                    (5, *current, previous != current)
                }
                GodsBattleFactionXydUpdate::FactionB { previous, current } => {
                    (6, *current, previous != current)
                }
                GodsBattleFactionXydUpdate::IgnoredFaction { .. } => unreachable!(),
            };
            if !changed {
                continue;
            }
            for region_id in &region_ids {
                let Some(ServerRegionOwner::GodsBattle(region)) = self.find_region(*region_id)
                else {
                    continue;
                };
                let Some(player_ids) = region.faction_player_ids(faction) else {
                    continue;
                };
                for player_id in player_ids {
                    if self.find_player(player_id).is_none() {
                        continue;
                    }
                    let delivery = gods_battle_property_message(player_id, b"dwXYD", xyd as i32)
                        .send_to_player(self.net_server(), player_id);
                    deliveries = deliveries.wrapping_add(1);
                    tracing::trace!(
                        region_id,
                        player_id,
                        faction,
                        xyd,
                        delivery,
                        "XYD битвы богов отправлен игроку"
                    );
                }
            }
        }
        tracing::debug!(
            faction_a,
            faction_b,
            ?updates,
            deliveries,
            "значения XYD битвы богов применены"
        );
    }

    /// Достигнутый GodsBattle-tail `CPlayer::OnDied` после общих death effects.
    pub(crate) fn apply_gods_battle_death_szl<
        Context: GodsBattleDeathContext + RealmAppellationScriptContext,
    >(
        &mut self,
        killer_id: i32,
        victim_id: i32,
        context: &mut Context,
    ) -> Option<()> {
        let (killer_level, killer_szl, killer_faction, killer_team, killer_region) =
            self.find_player(killer_id).map(|player| {
                (
                    player.level(),
                    player.szl(),
                    player.gods_battle_faction(),
                    player.team_id(),
                    player.server_region_id(),
                )
            })?;
        let (victim_level, victim_szl, victim_faction, victim_region) =
            self.find_player(victim_id).map(|player| {
                (
                    player.level(),
                    player.szl(),
                    player.gods_battle_faction(),
                    player.server_region_id(),
                )
            })?;
        let victim_region = victim_region?;
        let killer_region = killer_region?;
        if !self.gods_battle_mgr.contains_region(victim_region) || killer_faction == victim_faction
        {
            return None;
        }

        let gain = if victim_szl == 0 {
            GodsBattleSzlCalculation::default()
        } else {
            self.gods_battle_mgr.calculate_szl_gain(
                killer_level,
                killer_szl,
                victim_level,
                victim_szl,
            )
        };
        let loss = self.gods_battle_mgr.calculate_szl_loss(
            killer_level,
            killer_szl,
            victim_level,
            victim_szl,
        );
        let team = (killer_team != 0)
            .then(|| context.gods_battle_team_snapshot(killer_team))
            .flatten();
        let mut updates = 0usize;
        if let Some(team) = &team {
            if team.teammate_amount != 0 {
                let share = gods_battle_team_szl_share(gain.value, team.teammate_amount);
                if share != 0 {
                    for player_id in &team.player_ids {
                        let eligible = self.find_player(*player_id).is_some_and(|player| {
                            player.gods_battle_faction() != victim_faction
                                && player.server_region_id() == Some(killer_region)
                        });
                        if eligible {
                            let current = self
                                .find_player(*player_id)
                                .expect("проверенный GodsBattle teammate")
                                .szl();
                            self.update_gods_battle_player_szl(
                                *player_id,
                                current.wrapping_add(share),
                                context,
                            );
                            updates = updates.wrapping_add(1);
                        }
                    }
                }
            }
        } else if gain.value != 0 {
            self.update_gods_battle_player_szl(
                killer_id,
                killer_szl.wrapping_add(gain.value),
                context,
            );
            updates = updates.wrapping_add(1);
        }

        if victim_szl < loss.value {
            if victim_szl != 0 {
                self.update_gods_battle_player_szl(victim_id, 0, context);
                updates = updates.wrapping_add(1);
            }
        } else {
            self.update_gods_battle_player_szl(
                victim_id,
                victim_szl.wrapping_sub(loss.value),
                context,
            );
            updates = updates.wrapping_add(1);
        }

        let region_notice_delivery = (|| {
            let template_id = match (killer_faction, victim_faction) {
                (5, 6) => b"SZLGS11".as_slice(),
                (6, 5) => b"SZLGS12".as_slice(),
                _ => return None,
            };
            let text = legacy_c_string_prefix(self.get_string_by_id(template_id));
            let region = self.find_region(killer_region)?;
            let mut message = CMessage::new(0xbf816);
            message.add_byte(2);
            add_legacy_c_string(message.base_mut(), &text[..text.len().min(0xff)]);
            Some(message.send_to_region(Some(region.base()), None, self))
        })();
        tracing::debug!(
            killer_id,
            victim_id,
            ?gain,
            ?loss,
            team_players = team.as_ref().map_or(0, |team| team.player_ids.len()),
            updates,
            ?region_notice_delivery,
            "SZL после смерти в битве богов применён"
        );
        Some(())
    }

    fn update_gods_battle_player_szl<Context: GodsBattleDeathContext>(
        &mut self,
        player_id: i32,
        current: u32,
        context: &mut Context,
    ) {
        let (previous, attempt_appellation_id) = {
            let player = self
                .find_player_mut(player_id)
                .expect("SZL update получает canonical player");
            let previous = player.szl();
            player.set_szl(current);
            (previous, player.attempt_appellation_id())
        };
        let property_delivery = gods_battle_property_message(player_id, b"dwSZL", current as i32)
            .send_to_player(self.net_server(), player_id);
        let text = format_single_legacy_u32(self.get_string_by_id(b"SZLGS13"), current, 0xff);
        let notice_delivery = colored_player_notice_message(0xffff_ffff, 0xffa8_069c, &text)
            .send_to_player(self.net_server(), player_id);

        let removed_attempt_appellation = if current < previous
            && (40_001..50_000).contains(&attempt_appellation_id)
            && self.gods_battle_mgr.szl_level(current).unwrap_or(0)
                < attempt_appellation_id % 40_000
        {
            self.find_player_mut(player_id)
                .expect("player сохранён после SZL publication")
                .clear_attempt_appellation();
            context.request_gods_battle_change_appellation(player_id, 0);
            Some(attempt_appellation_id)
        } else {
            None
        };
        let appellation_notice_delivery = removed_attempt_appellation.map(|_| {
            colored_player_notice_message(0xffff_ffff, 0, self.get_string_by_id(b"SZLGS10"))
                .send_to_player(self.net_server(), player_id)
        });
        tracing::trace!(
            player_id,
            previous,
            current,
            property_delivery,
            notice_delivery,
            ?removed_attempt_appellation,
            ?appellation_notice_delivery,
            "SZL игрока битвы богов обновлён"
        );
    }

    /// Script scalar `11128 / ChangePlayerSZL`: вычисляется только первый
    /// аргумент; negative и parser sentinel являются успешным no-op.
    pub(crate) fn script_change_player_szl<Context: GodsBattleDeathContext>(
        &mut self,
        player_id: i32,
        value: i32,
        context: &mut Context,
    ) -> Option<()> {
        if value < 0 || value == SCRIPT_SCALAR_ERROR || self.find_player(player_id).is_none() {
            return None;
        }
        self.update_gods_battle_player_szl(player_id, value as u32, context);
        Some(())
    }

    pub(crate) const fn synthesis_mut(&mut self) -> &mut CSynthesis {
        &mut self.synthesis
    }

    pub(crate) const fn synthesis(&self) -> &CSynthesis {
        &self.synthesis
    }

    pub(crate) fn query_player_equipment<Context: PlayerEquipmentInspectionContext>(
        &self,
        requester_id: i32,
        target_id: i32,
        context: &mut Context,
    ) {
        let Some(target) = self.find_player(target_id) else {
            tracing::trace!(
                requester_id,
                target_id,
                "игрок для просмотра экипировки не найден"
            );
            return;
        };
        let (head_picture, face_picture, mode) = target.appearance_and_mode();
        if mode != 0 {
            let delivery =
                colored_player_notice_message(0xffff_0000, 0, self.get_string_by_id(b"GSN0336"))
                    .send_to_player(self.net_server(), requester_id);
            tracing::trace!(
                requester_id,
                target_id,
                mode,
                delivery,
                "режим игрока запрещает просмотр экипировки"
            );
            return;
        }

        let equipment_count = target.equipment().goods_amount(&self.goods_factory) as u8;
        let mut response = CMessage::new(0x0b_f911);
        response.add_long(target_id);
        response.add_long(head_picture);
        response.add_long(face_picture);
        response.add_byte(equipment_count);
        for slot in 0..EQUIPMENT_COLUMN_LIMIT {
            let Some(goods) = target.equipment().get_goods(slot) else {
                continue;
            };
            response.add_byte(slot as u8);
            response
                .base_mut()
                .add(&context.encode_goods_for_old_client(goods));
        }
        let delivery = response.send_to_player(self.net_server(), requester_id);
        tracing::trace!(
            requester_id,
            target_id,
            equipment_count,
            delivery,
            "экипировка игрока отправлена"
        );
    }

    pub(crate) fn handle_container_script_action<Runtime: ScriptFunctionRuntime>(
        &mut self,
        player_id: i32,
        region_id: Option<i32>,
        action: i8,
        runtime: &mut Runtime,
    ) -> Option<()> {
        if action == 0 {
            let shadows = self
                .find_player_mut(player_id)?
                .clear_all_enhancement_selection();
            tracing::trace!(
                player_id,
                action,
                shadows,
                "выбор контейнерного сценария очищен"
            );
            return Some(());
        }
        if action != 1 {
            tracing::trace!(
                player_id,
                action,
                "неверное действие контейнерного сценария"
            );
            return Some(());
        }
        self.run_last_container_script(player_id, region_id, Some(action), runtime)
    }

    pub(crate) fn run_precious_box_item_script<Runtime: ScriptFunctionRuntime>(
        &mut self,
        player_id: i32,
        region_id: Option<i32>,
        runtime: &mut Runtime,
    ) -> Option<()> {
        self.run_last_container_script(player_id, region_id, None, runtime)
    }

    pub(crate) fn open_precious_box(&mut self, player_id: i32, script: &[u8]) -> i32 {
        if self.find_player(player_id).is_none() {
            return 0;
        }
        let mut message = CMessage::new(0x000b_f91a);
        message.add_long(player_id);
        let _ = message.send_to_player(self.net_server(), player_id);
        self.find_player_mut(player_id)
            .expect("PreciousBox player сохраняется после synchronous send")
            .set_last_container_script(script);
        1
    }

    pub(crate) fn close_precious_box(&self, player_id: i32) {
        if self.find_player(player_id).is_none() {
            return;
        }
        let mut message = CMessage::new(0x000b_f91c);
        message.add_long(player_id);
        let _ = message.send_to_player(self.net_server(), player_id);
    }

    fn roll_precious_box_item(&mut self, box_id: i32) -> Option<PreciousBoxItem> {
        let (configuration, random_state) = (&self.precious_box_conf, &mut self.random_state);
        configuration.random_item(box_id, |upper_bound| {
            game_legacy_random(random_state, upper_bound)
        })
    }

    pub(crate) fn get_precious_box_item<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        box_id: i32,
        context: &mut Context,
    ) -> i32 {
        if self.find_player(player_id).is_none() {
            return -1;
        }
        let Some(item) = self.roll_precious_box_item(box_id) else {
            self.send_precious_box_result(player_id, -1, 0);
            return -1;
        };
        if item.item_idx <= 0 || item.amount <= 0 {
            self.send_precious_box_result(player_id, -1, 0);
            return -1;
        }
        let mut created = self.create_goods_batch(item.item_idx as u32, item.amount as u32);
        if item.min_level != 0 {
            let (factory, random_state) = (&self.goods_factory, &mut self.random_state);
            for goods in &mut created {
                let _ = factory.upgrade_equipment(goods, item.min_level, |upper_bound| {
                    game_legacy_random(random_state, upper_bound)
                });
            }
        }
        let (additions, _rejected) = {
            let (players, factory) = (&mut self.players, &self.goods_factory);
            let player = players
                .get_mut(&player_id)
                .expect("PreciousBox player проверен до packet add");
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.add_precious_box_goods_to_packet(created, factory, &mut encode)
        };
        let mut result_position = -1;
        for addition in additions {
            if addition.resulting_amount.is_some() {
                result_position = addition.position.map_or(-1, |position| position as i32);
                let _ = self.send_player_packet_addition(&addition);
            }
        }
        self.send_precious_box_result(player_id, result_position, item.amount);
        if result_position != -1 && item.broadcast {
            if let Some(goods) = u32::try_from(result_position).ok().and_then(|position| {
                self.find_player(player_id)
                    .and_then(|player| player.packet().get_goods(position))
            }) {
                let player_name = self
                    .find_player(player_id)
                    .map(CPlayer::player_name)
                    .unwrap_or_default();
                let template = self.get_string_by_id(if item.min_level == 0 {
                    b"GS0185"
                } else {
                    b"GS0184"
                });
                let arguments = if item.min_level == 0 {
                    vec![
                        LegacyFormatArgument::Bytes(player_name),
                        LegacyFormatArgument::Bytes(goods.name()),
                        LegacyFormatArgument::Signed(item.amount),
                    ]
                } else {
                    vec![
                        LegacyFormatArgument::Bytes(player_name),
                        LegacyFormatArgument::Bytes(goods.name()),
                        LegacyFormatArgument::Signed(item.min_level),
                        LegacyFormatArgument::Signed(item.amount),
                    ]
                };
                let text = format_legacy_mixed(template, &arguments, 1023);
                let mut message = CMessage::new(0x0005_ff0e);
                message.add_long(player_id);
                add_legacy_c_string(message.base_mut(), &text);
                message.add_ulong(0xffff_ff00);
                message.add_ulong(0xffff_0000);
                let _ = message.send(self, false);
            }
        }
        result_position
    }

    fn send_precious_box_result(&self, player_id: i32, position: i32, amount: i32) {
        let mut message = CMessage::new(0x000b_f91b);
        message.add_ulong(position as u32);
        if position != -1 {
            message.add_ulong(amount as u32);
        }
        let _ = message.send_to_player(self.net_server(), player_id);
    }

    fn run_last_container_script<Runtime: ScriptFunctionRuntime>(
        &mut self,
        player_id: i32,
        region_id: Option<i32>,
        action: Option<i8>,
        runtime: &mut Runtime,
    ) -> Option<()> {
        let script_name = self
            .find_player(player_id)?
            .last_container_script()
            .to_vec();
        if script_name.is_empty() {
            tracing::trace!(player_id, ?action, "имя контейнерного сценария пусто");
            return Some(());
        }
        let script_data_found = self.script_file_data(&script_name).is_some();
        let _ = self.run_script_file(
            &script_name,
            ScriptExecutionContext {
                player_id: Some(player_id),
                region_id,
                ..ScriptExecutionContext::default()
            },
            runtime,
        );
        tracing::trace!(
            player_id,
            ?action,
            ?script_name,
            script_data_found,
            "контейнерный сценарий выполнен"
        );
        Some(())
    }

    fn send_hotkey_hand_transfer(
        &self,
        player: &CPlayer,
        transfer: &HotkeyHandTransferReport,
    ) -> Option<i32> {
        use crate::gameserver::appserver::container::cwallet::CurrencyGoodsAddOutcome;

        let (Some(goods), Some(removal)) = (transfer.goods, transfer.hand_removal.as_ref()) else {
            return None;
        };
        let mut message = CS2CContainerObjectMove::default();
        message.set_source_container(removal.owner_type, removal.owner_id, 0);
        message.set_source_container_extend_id(3);
        message.set_source_object(goods.object_type, goods.ex_id, removal.amount);
        match transfer.outcome {
            HotkeyHandTransferOutcome::Moved => {
                let destination = match transfer.source_container_extend_id {
                    1 => transfer
                        .packet_adds
                        .iter()
                        .rev()
                        .find_map(|outcome| match outcome {
                            VolumeGoodsAddOutcome::Added(added) => {
                                let position = added.position?;
                                let stored = player.packet().base().find(added.identity.ex_id)?;
                                Some((position, added.identity, stored.amount()))
                            }
                            VolumeGoodsAddOutcome::Stack(GoodsStackMergeOutcome::Merged {
                                target,
                                ..
                            }) => {
                                let position =
                                    player.packet().query_goods_position(target.ex_id)?;
                                let stored = player.packet().base().find(target.ex_id)?;
                                Some((position, *target, stored.amount()))
                            }
                            _ => None,
                        }),
                    3 => transfer
                        .hand_rollback
                        .as_ref()
                        .and_then(|added| Some((added.position?, added.identity, added.amount))),
                    4 | 5 => {
                        transfer
                            .currency_adds
                            .iter()
                            .rev()
                            .find_map(|outcome| match outcome {
                                CurrencyGoodsAddOutcome::Added(added) => {
                                    Some((added.position, added.identity, added.amount))
                                }
                                CurrencyGoodsAddOutcome::Stack(
                                    GoodsStackMergeOutcome::Merged { target, .. },
                                ) => Some((
                                    0,
                                    *target,
                                    if transfer.source_container_extend_id == 4 {
                                        player.money()
                                    } else {
                                        player.yuan_bao()
                                    },
                                )),
                                _ => None,
                            })
                    }
                    _ => None,
                };
                let Some((position, identity, amount)) = destination else {
                    return None;
                };
                message.set_operation(ContainerObjectMoveOperation::MoveObject);
                message.set_destination_container(PLAYER_TYPE, player.player_id(), position);
                message.set_destination_container_extend_id(
                    transfer.source_container_extend_id as i32,
                );
                message.set_destination_object(identity.object_type, identity.ex_id);
                message.set_destination_object_amount(amount);
            }
            HotkeyHandTransferOutcome::RolledBack => {
                message.set_operation(ContainerObjectMoveOperation::RollBack);
            }
            HotkeyHandTransferOutcome::GarbageCollected => {
                message.set_operation(ContainerObjectMoveOperation::DeleteObject);
            }
            HotkeyHandTransferOutcome::MissingHandGoods
            | HotkeyHandTransferOutcome::NotConsumable
            | HotkeyHandTransferOutcome::UnsupportedSource => {
                return None;
            }
        }
        Some(message.send_to_player(self, player.player_id()))
    }

    pub(crate) fn assign_hotkey(&mut self, player_id: i32, slot: u8, value: u32) -> Option<()> {
        if usize::from(slot) >= 24 {
            // Старый negative-value path писал за `dwHotKey[24]`; это UB без
            // подтверждённого wire-эффекта, поэтому malformed slot получает
            // тот же безопасный reject, что и обычная out-of-range ветвь.
            let delivery = send_hotkey_response(self, player_id, 0x0b_f908, b'.', None);
            tracing::trace!(
                player_id,
                slot,
                value,
                delivery,
                "назначение горячей клавиши отклонено из-за номера ячейки"
            );
            return Some(());
        }
        if (value as i32) < 0 {
            self.find_player_mut(player_id)?.set_hotkey(slot, value);
            let delivery =
                send_hotkey_response(self, player_id, 0x0b_f908, b'-', Some((slot, Some(value))));
            tracing::trace!(
                player_id,
                slot,
                value,
                delivery,
                "назначена горячая клавиша с отрицательным значением"
            );
            return Some(());
        }
        let hand_missing = self.find_player(player_id)?.ci_qing_hand_goods().is_none();
        if hand_missing {
            self.find_player_mut(player_id)?.set_hotkey(slot, value);
            let delivery =
                send_hotkey_response(self, player_id, 0x0b_f908, b'-', Some((slot, Some(value))));
            tracing::trace!(
                player_id,
                slot,
                value,
                delivery,
                "назначена горячая клавиша без предмета в руке"
            );
            return Some(());
        }

        let transfer = {
            let (players, factory) = (&mut self.players, &self.goods_factory);
            players
                .get_mut(&player_id)?
                .return_hotkey_hand_goods(factory)
        };
        let assigned = transfer.outcome == HotkeyHandTransferOutcome::Moved;
        let response_delivery = if assigned {
            self.find_player_mut(player_id)?.set_hotkey(slot, value);
            Some(send_hotkey_response(
                self,
                player_id,
                0x0b_f908,
                b'-',
                Some((slot, Some(value))),
            ))
        } else {
            None
        };
        let transfer_delivery = if transfer.hand_removal.is_some() || assigned {
            self.find_player(player_id)
                .map(|player| self.send_hotkey_hand_transfer(player, &transfer))
                .flatten()
        } else {
            None
        };
        let rejection_delivery = transfer
            .hand_removal
            .is_none()
            .then(|| send_hotkey_response(self, player_id, 0x0b_f908, b'.', None));
        tracing::trace!(player_id, slot, value, assigned, transfer = ?transfer, ?transfer_delivery, ?response_delivery, ?rejection_delivery, "обработано назначение горячей клавиши");
        Some(())
    }

    pub(crate) fn remove_hotkey(&mut self, player_id: i32, slot: u8) -> Option<()> {
        let removed = self
            .find_player(player_id)?
            .hotkey(slot)
            .is_some_and(|value| value != 0);
        if removed {
            self.find_player_mut(player_id)?.set_hotkey(slot, 0);
        }
        let delivery = send_hotkey_response(
            self,
            player_id,
            0x0b_f909,
            if removed { b'/' } else { b'0' },
            removed.then_some((slot, None)),
        );
        tracing::trace!(
            player_id,
            slot,
            removed,
            delivery,
            "обработано удаление горячей клавиши"
        );
        Some(())
    }

    pub(crate) fn change_hotkey(&mut self, player_id: i32, slot: u8, value: u32) -> Option<()> {
        let changed = self
            .find_player(player_id)?
            .hotkey(slot)
            .is_some_and(|current| current != 0);
        let delivery = if changed {
            self.find_player_mut(player_id)?.set_hotkey(slot, value);
            Some(send_hotkey_response(
                self,
                player_id,
                0x0b_f90a,
                b'1',
                Some((slot, Some(value))),
            ))
        } else {
            None
        };
        tracing::trace!(
            player_id,
            slot,
            value,
            changed,
            ?delivery,
            "обработано изменение горячей клавиши"
        );
        Some(())
    }

    fn send_fairy_state_effect(&self, effect: &FairyStateChangeEffect) -> Vec<i32> {
        let FairyStateChangeEffect::ObjectMove(object_move) = effect else {
            return Vec::new();
        };
        let Some(position) = object_move.position else {
            return Vec::new();
        };
        let mut message = CS2CContainerObjectMove::default();
        match object_move.operation {
            FairyContainerMoveOperation::DeleteObject => {
                message.set_operation(ContainerObjectMoveOperation::DeleteObject);
                message.set_source_container(
                    object_move.owner_type,
                    object_move.owner_id,
                    position,
                );
                message.set_source_container_extend_id(object_move.container_extend_id as i32);
                message.set_source_object(
                    object_move.goods.object_type,
                    object_move.goods.ex_id,
                    object_move.amount,
                );
            }
            FairyContainerMoveOperation::NewObject => {
                message.set_operation(ContainerObjectMoveOperation::NewObject);
                message.set_destination_container(
                    object_move.owner_type,
                    object_move.owner_id,
                    position,
                );
                message.set_destination_container_extend_id(object_move.container_extend_id as i32);
                message
                    .set_destination_object(object_move.goods.object_type, object_move.goods.ex_id);
                message.set_object_stream(object_move.old_client_payload.clone());
            }
        }
        vec![message.send_to_player(self, object_move.owner_id)]
    }

    fn send_fairy_amount_change(&self, change: &FairyContainerAmountChange) -> Vec<i32> {
        let mut message = CS2CContainerObjectAmountChange::default();
        message.set_source_container(change.owner_type, change.owner_id, change.position);
        message.set_source_container_extend_id(change.container_extend_id as i32);
        message.set_object(change.goods.object_type, change.goods.ex_id);
        message.set_object_amount(change.amount);
        vec![message.send_to_player(self, change.owner_id)]
    }

    fn send_fairy_player_update(&self, update: &FairySyncretizePlayerUpdate) -> Vec<i32> {
        let mut message = CMessage::new(0x0b_f704);
        message.add_ulong(update.experience);
        message.add_ulong(update.vigour);
        vec![message.send_to_player(self.net_server(), update.player_id)]
    }

    fn send_fairy_grow_log(&self, log: &FairyGrowLog) {
        let mut message = CMessage::new(0x0006_0210);
        message.add_long(0);
        message.add_long(log.player_id);
        message.add_long(log.log_value);
        add_legacy_c_string(message.base_mut(), &log.fairy_guid);
        add_legacy_c_string(message.base_mut(), &log.fairy_name);
        message.add_ulong(log.level);
        let delivery = message.send(self, false);
        tracing::trace!(player_id = log.player_id, ?delivery, "журнал роста феи отправлен");
    }

    fn deliver_fairy_exp_effects(&self, journal: &mut GameEffectJournal) {
        for effect in journal.take_all() {
            let GameEffect::FairyGrowLog(log) = effect else {
                tracing::error!(?effect, "неверный эффект передан владельцу роста феи");
                continue;
            };
            self.send_fairy_grow_log(&log);
        }
    }

    fn send_fairy_incubate_log(&self, log: &FairyIncubateLog) {
        let mut message = CMessage::new(log.message_type as i32);
        message.add_long(log.log_type);
        message.add_long(log.player_id);
        message.base_mut().add_guid(log.goods.ex_id);
        add_legacy_c_string(message.base_mut(), &log.goods_name);
        let delivery = message.send(self, false);
        tracing::trace!(player_id = log.player_id, ?delivery, "журнал инкубации феи отправлен");
    }

    fn send_fairy_implantation_log(&self, log: &FairyImplantationLog) {
        let mut message = CMessage::new(0x0006_0210);
        message.add_long(2);
        message.add_long(log.player_id);
        add_legacy_c_string(message.base_mut(), &log.goods_name);
        message.base_mut().add_guid(log.goods.ex_id);
        message.add_ulong(log.old_level);
        message.add_ulong(log.resulting_level);
        message.add_ulong(log.crystal_amount);
        let delivery = message.send(self, false);
        tracing::trace!(player_id = log.player_id, ?delivery, "журнал имплантации феи отправлен");
    }

    fn send_fairy_syncretize_log(&self, log: &FairySyncretizeLog) {
        let mut message = CMessage::new(log.message_type as i32);
        message.add_long(log.log_type);
        message.add_long(log.player_id);
        message.base_mut().add_guid(log.primary_guid);
        add_legacy_c_string(message.base_mut(), &log.primary_name);
        message.add_ulong(log.primary_level);
        message.add_ulong(log.primary_growing_rate);
        message.base_mut().add_guid(log.secondary_guid);
        add_legacy_c_string(message.base_mut(), &log.secondary_name);
        message.add_ulong(log.secondary_level);
        message.add_ulong(log.secondary_growing_rate);
        message.add_ulong(log.needed_goods);
        message.base_mut().add_guid(log.result_guid);
        add_legacy_c_string(message.base_mut(), &log.result_name);
        message.add_ulong(log.main_ability);
        message.add_ulong(log.combinated_times);
        message.add_ulong(log.growing_rate);
        let delivery = message.send(self, false);
        tracing::trace!(player_id = log.player_id, ?delivery, "журнал соединения фей отправлен");
    }

    pub(crate) fn update_fairy_hatch_state<Context: FairyContext>(
        &mut self,
        player_id: i32,
        slot: u32,
        action: i8,
        context: &mut Context,
    ) {
        let Some(player) = self.find_player(player_id) else {
            tracing::trace!(
                player_id,
                slot,
                action,
                "игрок для управления инкубатором не найден"
            );
            return;
        };
        if !player.fairy_container_enabled() {
            tracing::trace!(player_id, slot, action, "контейнер феи отключён");
            return;
        }
        if !(5..=9).contains(&slot) {
            tracing::trace!(player_id, slot, action, "неверная позиция инкубатора");
            return;
        }
        if action != b'b' as i8 && action != b's' as i8 {
            tracing::trace!(player_id, slot, action, "неверное действие инкубатора");
            return;
        }
        let now = (action == b'b' as i8).then(|| context.now_milliseconds());
        let egg_max_level = self.globe_setup.fairy_egg_max_level();
        let Some(goods) = self
            .find_player_mut(player_id)
            .and_then(|player| player.fairy_container_mut().base_mut().get_goods_mut(slot))
        else {
            tracing::trace!(player_id, slot, action, "предмет в инкубаторе не найден");
            return;
        };
        let changed = if let Some(now) = now {
            goods.hatch_begin(now, egg_max_level)
        } else {
            goods.hatch_stop()
        };
        if !changed {
            tracing::trace!(
                player_id,
                slot,
                action,
                "состояние инкубатора не изменилось"
            );
            return;
        }
        let mut response = CMessage::new(0x0b_f91d);
        response.add_ulong(slot);
        response.add_byte(action as u8);
        if action == b'b' as i8 {
            response.add_ulong(self.globe_setup.fairy_hatch_time());
        }
        let delivery = response.send_to_player(self.net_server(), player_id);
        tracing::debug!(
            player_id,
            slot,
            action,
            delivery,
            "состояние инкубатора изменено"
        );
    }

    /// Конкретный хвост `CPlayer::PeriodicalUpdate -> CFairyContainer::CheckHatcher`.
    /// Вызывающая сторона передаёт ровно текущего игрока после проверки связи
    /// и счётчика смерти на войне наций, сохраняя таймер, замену, перемещение
    /// объекта и журнал инкубации в том же проходе ИИ игрока.
    pub(crate) fn run_fairy_hatcher<Context: FairyContext>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) -> Option<()> {
        if !self
            .players
            .get(&player_id)
            .is_some_and(CPlayer::fairy_container_enabled)
        {
            return None;
        }
        let hatch_duration = self.globe_setup.fairy_hatch_time();
        let incubate_log_enabled = self.log_system.fairy_incubate_enabled();
        let entries = {
            let (players, random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
                &mut self.players,
                &mut self.random_state,
                &self.goods_factory,
                &self.fairy_exp_conf,
                &self.battle_fairy_exp_config,
            );
            let player = players
                .get_mut(&player_id)
                .expect("fairy hatcher player проверен в live map");
            let owner_progress_allows = player.current_progress() == PlayerProgress::None;
            let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
            let mut create_goods = |goods_index| {
                goods_factory
                    .create_goods_batch(
                        goods_index,
                        1,
                        &mut random,
                        || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                        |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                        |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
                    )
                    .into_iter()
                    .next()
            };
            let mut threshold = |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level);
            let context_cell = std::cell::RefCell::new(&mut *context);
            let mut current_tick = || context_cell.borrow_mut().now_milliseconds();
            let mut encode =
                |goods: &CGoods| context_cell.borrow_mut().encode_goods_for_old_client(goods);
            player.fairy_container_mut().check_hatcher(
                &mut current_tick,
                hatch_duration,
                incubate_log_enabled,
                goods_factory,
                owner_progress_allows,
                &mut threshold,
                &mut create_goods,
                &mut encode,
            )
        };
        let mut state_effects = 0usize;
        for entry in &entries {
            state_effects =
                state_effects.wrapping_add(deliver_fairy_state_change(&entry.transition, self));
            if let Some(log) = &entry.incubate_log {
                self.send_fairy_incubate_log(log);
            }
        }
        tracing::trace!(
            player_id,
            entries = entries.len(),
            state_effects,
            "завершена проверка инкубатора феи"
        );
        Some(())
    }

    pub(crate) fn implant_fairy_experience<Context: FairyContext>(
        &mut self,
        player_id: i32,
        requested_vigour: u32,
        context: &mut Context,
    ) {
        let Some(player) = self.find_player(player_id) else {
            tracing::trace!(
                player_id,
                requested_vigour,
                "игрок для имплантации опыта феи не найден"
            );
            return;
        };
        if !player.fairy_container_enabled() {
            tracing::trace!(player_id, requested_vigour, "контейнер феи отключён");
            return;
        }
        let Some(fairy) = player
            .fairy_container()
            .base()
            .get_goods(0)
            .and_then(CGoods::fairy_properties)
        else {
            let delivery = send_fairy_long(self, player_id, 0x0b_f91e, 1);
            tracing::trace!(
                player_id,
                requested_vigour,
                delivery,
                "фея для имплантации не найдена"
            );
            return;
        };
        if (fairy.fairy_state == 0 && self.globe_setup.fairy_egg_max_level() <= fairy.level)
            || fairy.ripe_max_level <= fairy.level
        {
            let delivery = send_fairy_long(self, player_id, 0x0b_f91e, 2);
            tracing::trace!(
                player_id,
                requested_vigour,
                delivery,
                "фея достигла максимального уровня"
            );
            return;
        }
        if requested_vigour == 0 || 0x98_9681 <= requested_vigour {
            tracing::trace!(
                player_id,
                requested_vigour,
                "неверное количество энергии для имплантации"
            );
            return;
        }
        if player.vigour() < requested_vigour {
            let delivery = send_fairy_long(self, player_id, 0x0b_f91e, 3);
            tracing::trace!(
                player_id,
                requested_vigour,
                delivery,
                "недостаточно энергии для имплантации"
            );
            return;
        }
        let crystal_scale = self.globe_setup.fairy_vigour_crystal_scale();
        let exp_scale = self.globe_setup.fairy_exp_vigour_scale();
        let initial_crystals = round_fairy_value(requested_vigour as f32 * crystal_scale + 0.999);
        let crystal_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(b"FZ0965"));
        if crystal_index == 0 || player.check_item_in_packet(crystal_index) < initial_crystals {
            let delivery = send_fairy_long(self, player_id, 0x0b_f91e, 4);
            tracing::trace!(
                player_id,
                requested_vigour,
                crystal_index,
                initial_crystals,
                delivery,
                "недостаточно кристаллов для имплантации"
            );
            return;
        }

        let experience = round_fairy_value(requested_vigour as f32 * exp_scale);
        let egg_max_level = self.globe_setup.fairy_egg_max_level();
        let upgrade_rate = self.globe_setup.fairy_upgrade_rate();
        let grow_log_enabled = self.log_system.fairy_grow_enabled();
        let implantation_log_enabled = self.log_system.fairy_implantation_enabled();
        let implantation = {
            let (players, random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
                &mut self.players,
                &mut self.random_state,
                &self.goods_factory,
                &self.fairy_exp_conf,
                &self.battle_fairy_exp_config,
            );
            let player = players
                .get_mut(&player_id)
                .expect("implantation player проверен до mutation");
            let owner_progress_allows = player.current_progress() == PlayerProgress::None;
            let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
            let mut create_goods = |goods_index| {
                goods_factory
                    .create_goods_batch(
                        goods_index,
                        1,
                        &mut random,
                        || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                        |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                        |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
                    )
                    .into_iter()
                    .next()
            };
            let mut threshold = |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level);
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.fairy_container_mut().implant_exp(
                experience,
                grow_log_enabled,
                egg_max_level,
                upgrade_rate,
                goods_factory,
                owner_progress_allows,
                &mut threshold,
                &mut create_goods,
                &mut encode,
            )
        };
        let Ok(Some(mut implantation)) = implantation else {
            tracing::trace!(
                player_id,
                requested_vigour,
                "имплантация заблокирована свойствами феи"
            );
            return;
        };
        self.deliver_fairy_exp_effects(&mut implantation.exp.effects);
        if let FairyImplantDelivery::StateChanged(transition) = &implantation.delivery {
            let effects = deliver_fairy_state_change(transition, self);
            tracing::trace!(player_id, effects, "эффекты смены состояния феи отправлены");
        }
        if implantation_log_enabled {
            let log = FairyImplantationLog {
                player_id,
                goods: implantation.goods,
                goods_name: implantation.goods_name.clone(),
                old_level: implantation.old_level,
                resulting_level: implantation.resulting_level,
                crystal_amount: initial_crystals,
            };
            self.send_fairy_implantation_log(&log);
        }
        let consumed_vigour = if implantation.exp.remaining_experience != 0 && exp_scale != 0.0 {
            requested_vigour.wrapping_sub(round_fairy_value(
                implantation.exp.remaining_experience as f32 / exp_scale,
            ))
        } else {
            requested_vigour
        };
        let crystal_amount = if consumed_vigour == requested_vigour {
            initial_crystals
        } else {
            round_fairy_value(consumed_vigour as f32 * crystal_scale + 1.0)
        };
        {
            let player = self
                .find_player_mut(player_id)
                .expect("implantation player остаётся зарегистрирован");
            player.set_vigour(player.vigour().wrapping_sub(consumed_vigour));
        }
        let property_delivery = self
            .find_player(player_id)
            .map(|player| self.send_player_properties_changed(player));
        let consumptions = self
            .find_player_mut(player_id)
            .expect("implantation player остаётся зарегистрирован")
            .remove_item_in_packet(crystal_index, crystal_amount);
        for consumption in consumptions {
            let deliveries = self.send_player_packet_consumption(&consumption);
            tracing::trace!(
                player_id,
                ?deliveries,
                "расход кристаллов имплантации отправлен"
            );
        }
        let goods_update_delivery = send_fairy_goods_update(
            self,
            &FairyContainerGoodsUpdate {
                message_type: 0x0b_f918,
                player_id,
                goods: implantation.goods,
                old_client_payload: implantation.old_client_payload.clone(),
            },
        );
        let result_delivery = send_fairy_long(self, player_id, 0x0b_f91e, 5);
        tracing::debug!(
            player_id,
            requested_vigour,
            consumed_vigour,
            crystal_amount,
            ?property_delivery,
            goods_update_delivery,
            result_delivery,
            "имплантация опыта феи завершена"
        );
    }

    pub(crate) fn syncretize_fairy<Context: FairyContext>(
        &mut self,
        player_id: i32,
        property: FairySyncreticProperty,
        context: &mut Context,
    ) -> Option<()> {
        let (experience, money, vigour) = {
            let player = self.find_player(player_id)?;
            if !player.fairy_container_enabled() {
                return None;
            }
            (player.experience(), player.money(), player.vigour())
        };
        let successful_roll = (game_legacy_random(&mut self.random_state, 10_000) as f32)
            < self.globe_setup.fairy_syncretic_success_rate() * 10_000.0;
        let config = FairySyncretizeConfig {
            needed_goods: self.globe_setup.fairy_syncretic_needed_goods(),
            needed_experience: self.globe_setup.fairy_syncretic_needed_experience(),
            needed_money: self.globe_setup.fairy_syncretic_needed_money(),
            rate_a: self.globe_setup.fairy_syncretic_rate(0),
            rate_b: self.globe_setup.fairy_syncretic_rate(1),
            rate_c: self.globe_setup.fairy_syncretic_rate(2),
            rate_d: self.globe_setup.fairy_syncretic_rate(3),
            rate_e: self.globe_setup.fairy_syncretic_rate(4),
            rate_f: self.globe_setup.fairy_syncretic_rate(5),
            rate_g: self.globe_setup.fairy_syncretic_rate(6),
            rate_h: self.globe_setup.fairy_syncretic_rate(7),
            rate_n: self.globe_setup.fairy_syncretic_rate_n(),
            rate_y: self.globe_setup.fairy_syncretic_rate_y(),
            log_enabled: self.log_system.fairy_syncretize_enabled(),
        };
        let mut player_snapshot = FairySyncretizePlayer {
            id: player_id,
            experience,
            money,
            vigour,
        };
        let mut report = {
            let (players, random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
                &mut self.players,
                &mut self.random_state,
                &self.goods_factory,
                &self.fairy_exp_conf,
                &self.battle_fairy_exp_config,
            );
            let player = players.get_mut(&player_id)?;
            let owner_progress_allows = player.current_progress() == PlayerProgress::None;
            let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
            let mut create_goods = |goods_index| {
                goods_factory
                    .create_goods_batch(
                        goods_index,
                        1,
                        &mut random,
                        || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                        |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                        |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
                    )
                    .into_iter()
                    .next()
            };
            let mut threshold = |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level);
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.fairy_container_mut().fairy_syncretize(
                property,
                successful_roll,
                Some(&mut player_snapshot),
                config,
                goods_factory,
                owner_progress_allows,
                &mut threshold,
                &mut create_goods,
                &mut encode,
            )
        };
        let money_change = if let Some(mut update) = report.player_update {
            let (players, goods_factory) = (&mut self.players, &self.goods_factory);
            let player = players.get_mut(&player_id)?;
            player.set_experience(update.experience);
            player.set_vigour(update.vigour);
            let decrease = player.decrease_money(money.wrapping_sub(update.money), goods_factory);
            update.money = decrease.current;
            report.player_update = Some(update);
            Some(decrease)
        } else {
            None
        };
        let (state_effects, amount_changes) = deliver_fairy_syncretize_effects(&report, self);
        tracing::trace!(
            player_id,
            state_effects,
            amount_changes,
            "эффекты соединения фей отправлены"
        );
        let money_deliveries = money_change
            .as_ref()
            .map(|change| self.send_player_money_decrease(player_id, &change.outcome))
            .unwrap_or_default();
        let player_update_deliveries = report
            .player_update
            .map(|update| self.send_fairy_player_update(&update))
            .unwrap_or_default();
        if let Some(log) = &report.log {
            self.send_fairy_syncretize_log(log);
        }
        let result_delivery = send_fairy_long(self, player_id, 0x0b_f91f, report.result as u32);
        tracing::debug!(player_id, ?property, ?report.result, ?money_deliveries, ?player_update_deliveries, result_delivery, "соединение фей завершено");
        Some(())
    }

    pub(crate) fn query_fairy_setup(&self, player_id: i32) {
        let enabled = self
            .find_player(player_id)
            .is_some_and(CPlayer::fairy_container_enabled);
        if enabled {
            let mut response = CMessage::new(0x0b_f920);
            response.add_ulong(self.globe_setup.fairy_vigour_crystal_scale().to_bits());
            response.add_ulong(self.globe_setup.fairy_exp_vigour_scale().to_bits());
            response.add_ulong(self.globe_setup.fairy_syncretic_needed_goods());
            response.add_ulong(self.globe_setup.fairy_syncretic_needed_experience());
            response.add_ulong(self.globe_setup.fairy_syncretic_needed_money());
            response.add_ulong(self.globe_setup.fairy_syncretic_rate_n().to_bits());
            response.add_ulong(self.globe_setup.fairy_syncretic_rate_y().to_bits());
            let delivery = response.send_to_player(self.net_server(), player_id);
            tracing::trace!(player_id, delivery, "настройки феи отправлены");
        } else {
            tracing::trace!(player_id, "настройки феи не отправлены: контейнер отключён");
        }
    }

    pub(crate) fn open_synthesis(&mut self, player_id: i32) -> Option<()> {
        let (region_id, tile_x, tile_y, progress, fight_state_count) = {
            let player = self.find_player(player_id)?;
            (
                player.server_region_id()?,
                player.shape().get_tile_x().ok()?,
                player.shape().get_tile_y().ok()?,
                player.current_progress(),
                player.fight_state_count(),
            )
        };
        let safe_region_cell = self
            .find_region(region_id)?
            .get_security(tile_x, tile_y)
            .ok()?
            == RegionSecurity::SAFE;
        let outcome = if !safe_region_cell {
            SynthesisOpenOutcome::UnsafeRegion
        } else if progress == PlayerProgress::Trading {
            SynthesisOpenOutcome::Trading
        } else if fight_state_count > 0 {
            SynthesisOpenOutcome::Fighting
        } else if progress == PlayerProgress::OpenStall {
            SynthesisOpenOutcome::StallOpen
        } else if self
            .find_player(player_id)
            .is_some_and(CPlayer::has_team_recruitment_state)
        {
            SynthesisOpenOutcome::TeamState
        } else {
            SynthesisOpenOutcome::Opened
        };
        let mut response = CMessage::new(0x0b_f922);
        response.base_mut().add_byte(outcome as u8);
        let delivery = response.send_to_player(self.net_server(), player_id);
        let player_mutation = (outcome == SynthesisOpenOutcome::Opened)
            .then(|| {
                self.find_player_mut(player_id)
                    .map(CPlayer::begin_synthesis)
            })
            .flatten();
        tracing::debug!(
            player_id,
            ?outcome,
            delivery,
            player_mutated = player_mutation.is_some(),
            "открытие синтеза обработано"
        );
        Some(())
    }

    /// Сценарный `OpenSynthesis` открывает только клиентскую страницу.
    /// Проверки безопасной клетки и перевод в `PlayerProgress::Synthesis`
    /// остаются за последующим клиентским запросом `0x8FC17`.
    pub(crate) fn open_script_synthesis_page(&self, player_id: i32) -> Option<(bool, i32)> {
        self.find_player(player_id)?;
        let enabled = self.globe_setup.synthesis_enabled();
        let delivery = if enabled {
            CMessage::new(0x000b_f921).send_to_player(self.net_server(), player_id)
        } else {
            colored_player_notice_message(
                0xffff_0000,
                0xffff_ffff,
                self.get_string_by_id(b"GS1052"),
            )
            .send_to_player(self.net_server(), player_id)
        };
        Some((enabled, delivery))
    }

    pub(crate) fn close_synthesis(&mut self, player_id: i32) -> Option<()> {
        let release = self.find_player_mut(player_id)?.close_synthesis();
        tracing::trace!(player_id, ?release, "сессия синтеза закрыта");
        Some(())
    }

    fn synthesis_result_fits_packet(&self, player_id: i32, goods: &[CGoods]) -> bool {
        self.find_player(player_id).is_some_and(|player| {
            player
                .packet()
                .is_space_enough_for_goods(goods, &self.goods_factory)
        })
    }

    pub(crate) fn compose_synthesis<Context: SynthesisContext>(
        &mut self,
        player_id: i32,
        synthesis_index: u32,
        amount: u32,
        context: &mut Context,
    ) -> Option<()> {
        let mut result_amount = amount;
        let Some(recipe) = self
            .synthesis
            .recipe(synthesis_index)
            .filter(|recipe| {
                recipe.coins != -1
                    && recipe.prestige != -1
                    && recipe.probability != u16::MAX
                    && !recipe.formulas.is_empty()
            })
            .cloned()
        else {
            tracing::trace!(
                player_id,
                synthesis_index,
                amount,
                "рецепт синтеза не найден"
            );
            return Some(());
        };
        let required = |formula: &SynthesisFormula| u64::from(formula.amount) * u64::from(amount);
        let (missing_ingredients, player_money, player_contribution) = {
            let player = self.find_player(player_id)?;
            (
                recipe.formulas.iter().any(|formula| {
                    u64::from(player.check_item_in_packet(formula.goods_index)) < required(formula)
                }),
                player.money(),
                player.contribution(),
            )
        };
        if missing_ingredients {
            let delivery = send_synthesis_result(self, player_id, 0);
            tracing::trace!(
                player_id,
                synthesis_index,
                amount,
                delivery,
                "для синтеза не хватает ингредиентов"
            );
            return Some(());
        }
        let total_coins = u64::from(recipe.coins as u32) * u64::from(amount);
        if u64::from(player_money) < total_coins {
            let delivery = send_synthesis_result(self, player_id, 1);
            tracing::trace!(
                player_id,
                synthesis_index,
                amount,
                delivery,
                "для синтеза не хватает денег"
            );
            return Some(());
        }
        if player_contribution < recipe.prestige {
            let delivery = send_synthesis_result(self, player_id, 2);
            tracing::trace!(
                player_id,
                synthesis_index,
                amount,
                delivery,
                "для синтеза не хватает вклада"
            );
            return Some(());
        }
        if recipe.probability != 100
            && game_legacy_random(&mut self.random_state, 100).wrapping_add(1)
                > i32::from(recipe.probability)
        {
            result_amount = 0;
        }
        let created = if result_amount == 0 {
            Vec::new()
        } else {
            let (random_state, goods_factory, fairy_exp_conf, battle_fairy_exp_config) = (
                &mut self.random_state,
                &self.goods_factory,
                &self.fairy_exp_conf,
                &self.battle_fairy_exp_config,
            );
            let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
            goods_factory.create_goods_batch(
                recipe.goods_index,
                result_amount,
                &mut random,
                || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
            )
        };
        if !created.is_empty() && !self.synthesis_result_fits_packet(player_id, &created) {
            let delivery = send_synthesis_result(self, player_id, 3);
            tracing::trace!(
                player_id,
                synthesis_index,
                amount,
                delivery,
                "для результата синтеза не хватает места"
            );
            return Some(());
        }

        let money_change = {
            let (players, goods_factory) = (&mut self.players, &self.goods_factory);
            players
                .get_mut(&player_id)?
                .decrease_money(total_coins as u32, goods_factory)
        };
        let money_delivery = self.send_player_money_decrease(player_id, &money_change.outcome);
        tracing::trace!(
            player_id,
            synthesis_index,
            ?money_delivery,
            "уменьшение денег за синтез отправлено"
        );
        for formula in &recipe.formulas {
            let consumptions = self.find_player_mut(player_id)?.remove_item_in_packet(
                formula.goods_index,
                required(formula).min(u64::from(u32::MAX)) as u32,
            );
            for consumption in consumptions {
                let deliveries = self.send_player_packet_consumption(&consumption);
                tracing::trace!(
                    player_id,
                    synthesis_index,
                    ?deliveries,
                    "расход ингредиента синтеза отправлен"
                );
            }
        }
        if result_amount == 0 {
            let result_delivery = send_synthesis_result(self, player_id, 5);
            let text = self.get_string_by_id(b"GS1017");
            let notice_delivery = colored_player_notice_message(0xffff_ffff, 0, text)
                .send_to_player(self.net_server(), player_id);
            tracing::debug!(
                player_id,
                synthesis_index,
                amount,
                result_delivery,
                notice_delivery,
                "синтез завершился случайной неудачей"
            );
            return Some(());
        }
        let (additions, rejected) = {
            let (players, goods_factory) = (&mut self.players, &self.goods_factory);
            let player = players.get_mut(&player_id)?;
            let mut encode = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.add_goods_to_packet(created, goods_factory, &mut encode)
        };
        for addition in additions {
            let deliveries = self.send_player_packet_addition(&addition);
            tracing::trace!(
                player_id,
                synthesis_index,
                ?deliveries,
                "результат синтеза отправлен в инвентарь"
            );
        }
        let rejected_count = rejected.len();
        let result_delivery = send_synthesis_result(self, player_id, 4);
        let text = self.get_string_by_id(b"GS1016");
        let notice_delivery = colored_player_notice_message(0xffff_ffff, 0, text)
            .send_to_player(self.net_server(), player_id);
        let broadcast_delivery = synthesis_broadcast_message(self, player_id, &recipe, amount)
            .map(|message| message.send(self, false));
        tracing::debug!(
            player_id,
            synthesis_index,
            amount,
            rejected_count,
            result_delivery,
            notice_delivery,
            ?broadcast_delivery,
            "синтез завершён"
        );
        Some(())
    }

