    fn send_goods_destroy_hand_consumption(&self, consumption: &GoodsDestroyHandConsumption) {
        if consumption.removed_amount == 0 {
            return;
        }
        if consumption.remaining_amount == 0 {
            let mut message = CS2CContainerObjectMove::default();
            message.set_operation(ContainerObjectMoveOperation::DeleteObject);
            message.set_source_container(PLAYER_TYPE, consumption.player_id, 0);
            message.set_source_container_extend_id(3);
            message.set_source_object(
                consumption.goods.object_type,
                consumption.goods.ex_id,
                consumption.previous_amount,
            );
            let delivery = message.send_to_player(self, consumption.player_id);
            tracing::trace!(
                player_id = consumption.player_id,
                delivery,
                "удаление уничтоженного предмета отправлено игроку"
            );
            return;
        }
        let mut message = CS2CContainerObjectAmountChange::default();
        message.set_source_container(PLAYER_TYPE, consumption.player_id, 0);
        message.set_source_container_extend_id(3);
        message.set_object(consumption.goods.object_type, consumption.goods.ex_id);
        message.set_object_amount(consumption.remaining_amount);
        let delivery = message.send_to_player(self, consumption.player_id);
        tracing::trace!(
            player_id = consumption.player_id,
            delivery,
            "остаток уничтоженного предмета отправлен игроку"
        );
    }

    fn send_goods_destroy_log(&self, player: &CPlayer, log: &GoodsDestroyAuditLog) {
        let mut message = CMessage::new(0x0006_0202);
        message.add_byte(log.reason);
        message.add_long(log.player_id);
        message.base_mut().add_short(log.pk_count as i16);
        message.add_ulong(log.money);
        message.add_ulong(player.depot_money());
        message.base_mut().add_guid(log.goods.ex_id);
        message.add_ulong(log.price);
        add_legacy_c_string(message.base_mut(), &log.name);
        message.add_ulong(log.removed_amount);
        message.add_long(log.region_id.unwrap_or_default());
        message.add_ulong(log.tile_x.unwrap_or_default() as u32);
        message.add_ulong(log.tile_y.unwrap_or_default() as u32);
        message.add_ulong(player.client_ip());
        let delivery = message.send(self, false);
        tracing::trace!(player_id = log.player_id, goods_id = ?log.goods.ex_id, removed_amount = log.removed_amount, ?delivery, "журнал уничтожения предмета отправлен");
    }

    fn delete_goods_for_destroy_open<Context: GameContainerMessageRuntime>(
        &mut self,
        request: GoodsDestroyDeleteRequest,
        context: &mut Context,
    ) {
        let Some(location) = self.players.get(&request.player_id).and_then(|player| {
            player.owned_goods_location(request.container_extend_id, request.goods_id)
        }) else {
            tracing::trace!(player_id = request.player_id, container_extend_id = request.container_extend_id, ?request.goods_id, "предмет для удаления не найден");
            return;
        };
        let deletion = if location.extend_id == 2 {
            let mut player = self
                .players
                .remove(&request.player_id)
                .expect("goods location проверяет canonical player");
            let goods = player
                .equipment()
                .find(request.goods_id)
                .expect("equipment location проверена")
                .clone();
            if request.requested_amount < goods.amount() {
                let mut deletion = player.delete_owned_goods(
                    location,
                    request.goods_id,
                    request.requested_amount,
                    &self.goods_factory,
                );
                if request.container_extend_id == 10
                    && let Some(deletion) = &mut deletion
                {
                    deletion.location.extend_id = 10;
                    deletion.location.position = 0;
                }
                self.players.insert(request.player_id, player);
                deletion
            } else {
                let facts = context.enhancement_equipment_remove_facts(
                    &player,
                    &goods,
                    self.globe_setup.pack_add_enabled(),
                );
                let mut recompute =
                    |player: &CPlayer| context.recompute_enhancement_player_properties(player);
                let mut report = player.remove_equipment_goods(
                    request.goods_id,
                    &self.goods_factory,
                    &self.skill_factory,
                    facts,
                    &mut recompute,
                );
                drop(recompute);
                self.publish_player_equipment_remove_report(&mut report);
                let deletion = match &report.outcome {
                    EquipmentRemoveOutcome::Removed(removed) => Some(PlayerGoodsAiDeletion {
                        location,
                        goods: removed.goods.clone(),
                        previous_amount: removed.goods.amount(),
                        removed_amount: removed.goods.amount(),
                        remaining_amount: 0,
                        listeners: removed.event.listeners.clone(),
                    }),
                    _ => None,
                };
                self.players.insert(request.player_id, player);
                if self.globe_setup.tao_zhuang_modify_enabled() {
                    let _ = self.done_player_tao_zhuang(request.player_id);
                }
                deletion
            }
        } else {
            self.players.get_mut(&request.player_id).and_then(|player| {
                player.delete_owned_goods(
                    location,
                    request.goods_id,
                    request.requested_amount,
                    &self.goods_factory,
                )
            })
        };
        let Some(deletion) = deletion else {
            tracing::trace!(player_id = request.player_id, container_extend_id = request.container_extend_id, ?request.goods_id, "удаление предмета не выполнено");
            return;
        };
        let player = self
            .players
            .get(&request.player_id)
            .expect("delete owner возвращён до wire");
        let client_delivery = self.send_player_owned_goods_deletion(player, &deletion);
        let mut audit_delivery = None;
        if request.write_delete_log && deletion.remaining_amount == 0 {
            let world = self.send_goods_deletion_audit(player, &deletion);
            if let Ok(delivery) = world {
                audit_delivery = Some(delivery);
            }
        }
        tracing::debug!(player_id = request.player_id, ?request.goods_id, removed_amount = deletion.removed_amount, client_delivery, ?audit_delivery, "предмет удалён");
    }

    pub(crate) fn open_goods_destroy<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        container_extend_id: i32,
        goods_id: Option<CGuid>,
        requested_amount: u32,
        context: &mut Context,
    ) {
        if container_extend_id != 0 {
            if let Some(goods_id) = goods_id {
                self.delete_goods_for_destroy_open(
                    GoodsDestroyDeleteRequest {
                        player_id,
                        container_extend_id,
                        goods_id,
                        requested_amount,
                        write_delete_log: false,
                    },
                    context,
                );
            } else {
                tracing::trace!(
                    player_id,
                    container_extend_id,
                    requested_amount,
                    "идентификатор удаляемого предмета отсутствует"
                );
            }
            return;
        }

        let enabled = self.goods_destroy_setup.enabled();
        let notice_delivery = if enabled {
            None
        } else {
            let text = self.get_string_by_id(b"GS1014");
            Some(
                colored_player_notice_message(0xffff_ffff, 0xffff_0000, text)
                    .send_to_player(self.net_server(), player_id),
            )
        };
        let mut response = CMessage::new(0x0b_f926);
        response.base_mut().add_byte(u8::from(enabled));
        let response_delivery = response.send_to_player(self.net_server(), player_id);
        tracing::debug!(
            player_id,
            enabled,
            ?notice_delivery,
            response_delivery,
            "страница уничтожения предметов обработана"
        );
    }

    pub(crate) fn confirm_goods_destroy(&mut self, player_id: i32) {
        if !self.goods_destroy_setup.enabled() {
            tracing::trace!(player_id, "уничтожение предметов отключено");
            return;
        }

        let Some(hand_goods) = self
            .find_player(player_id)
            .and_then(CPlayer::ci_qing_hand_goods)
        else {
            tracing::trace!(player_id, "предмет в руке для уничтожения не найден");
            return;
        };
        let identity = hand_goods.identity();
        let Some(properties) = self
            .goods_factory
            .query_goods_base_properties(hand_goods.base_properties_index())
        else {
            tracing::warn!(
                player_id,
                ?identity,
                "базовые свойства уничтожаемого предмета не найдены"
            );
            return;
        };
        if self
            .goods_destroy_setup
            .original_names()
            .iter()
            .any(|name| name.as_slice() == properties.original_name())
        {
            let text = self.get_string_by_id(b"GS1015");
            let delivery = colored_player_notice_message(0xffff_ffff, 0xffff_0000, text)
                .send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                ?identity,
                delivery,
                "уничтожение предмета запрещено по исходному имени"
            );
            return;
        }
        let type_key = if properties.goods_type() == GOODS_TYPE_EQUIPMENT {
            properties.equip_place().wrapping_add(1) as u16
        } else {
            properties.goods_type() as u16
        };
        if !self.goods_destroy_setup.goods_types().contains(&type_key) {
            let text = self.get_string_by_id(b"GS1014");
            let delivery = colored_player_notice_message(0xffff_ffff, 0xffff_0000, text)
                .send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                ?identity,
                type_key,
                delivery,
                "тип предмета запрещён для уничтожения"
            );
            return;
        }
        let equipment_state =
            hand_goods.addon_property_value(&self.goods_factory, GAP_EQUIP_STATE, 1);
        if matches!(equipment_state, 1 | 2) {
            let text = self.get_string_by_id(b"GSN1014");
            let delivery = colored_player_notice_message(0xffff_ffff, 0xffff_0000, text)
                .send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                ?identity,
                equipment_state,
                delivery,
                "состояние экипировки запрещает уничтожение"
            );
            return;
        }

        let price = hand_goods.price();
        let name = hand_goods.name().to_vec();
        let amount = hand_goods.amount();
        let consumption = self
            .find_player_mut(player_id)
            .and_then(|player| player.destroy_hand_goods(identity.ex_id, amount));
        let removed_amount = consumption.as_ref().map_or(0, |value| value.removed_amount);
        if let Some(consumption) = consumption.as_ref() {
            self.send_goods_destroy_hand_consumption(consumption);
        }

        if removed_amount != 0 && self.log_system.goods_destroy_enabled() {
            let player = self
                .find_player(player_id)
                .expect("player с hand goods остаётся в CGame после synchronous удаления");
            let audit = GoodsDestroyAuditLog {
                reason: 0x15,
                player_id,
                pk_count: player.pk_count(),
                money: player.money(),
                goods: identity,
                price,
                name,
                removed_amount,
                region_id: player.server_region_id(),
                tile_x: player.shape().get_tile_x(),
                tile_y: player.shape().get_tile_y(),
            };
            self.send_goods_destroy_log(player, &audit);
        }
        let mut response = CMessage::new(0x0b_f927);
        response.add_ulong(removed_amount);
        let result_delivery = response.send_to_player(self.net_server(), player_id);
        tracing::debug!(
            player_id,
            ?identity,
            type_key,
            equipment_state,
            amount,
            removed_amount,
            result_delivery,
            "уничтожение предмета завершено"
        );
    }

