    pub(crate) fn restore_goods_war(&mut self, goods_war: CGoodsWarMember) {
        self.goods_war = Some(goods_war);
    }

    /// Публикует listener-owner до `Host`, затем сохраняет setup-порядок.
    pub(crate) fn init_net_server(
        &mut self,
        now_ms: u32,
    ) -> Result<(), GameNetworkInitializationError> {
        let setup = self
            .network_setup
            .as_ref()
            .cloned()
            .ok_or(GameNetworkInitializationError::MissingNetworkSetup)?;
        self.net_server = Some(CMyNetServer::new(now_ms));
        let server = self
            .net_server
            .as_mut()
            .expect("Game server owner только что опубликован");
        server
            .host(setup.listener.listen_port, None, DEFAULT_SOCKET_TYPE, true)
            .map_err(GameNetworkInitializationError::Host)?;

        if let Some(address) = resolve_first_local_ipv4() {
            let dotted = address.to_string();
            server.set_local_identity(dotted.as_bytes(), legacy_ipv4_word(address));
        }
        server.configure_after_host(
            setup.listener.check_network,
            setup.listener.maximum_in_flight_sends,
            setup.listener.maximum_bytes_per_second,
            setup.listener.maximum_clients,
            setup.check_message_content,
            setup.listener.forbid_time_ms,
            setup.listener.maximum_message_length,
            setup.listener.permitted_send_bytes,
        );
        server.configure_accept_limits_after_host(
            setup.listener.maximum_block_connections,
            setup.listener.first_receive_timeout_ms,
        );
        Ok(())
    }

    /// Пересоздаёт initial World client и ставит исходную регистрацию.
    pub(crate) async fn init_world_client(&mut self) -> GameClientInitialization {
        let Some(setup) = self.network_setup.as_ref().cloned() else {
            return GameClientInitialization::Failed {
                attempts: vec![GameConnectAttempt {
                    direction: GameUpstreamDirection::World,
                    failure: Some(GameClientInitializationFailure::MissingNetworkSetup),
                }],
            };
        };
        self.close_and_remove_world_client();
        self.attach_world_client(CMyNetClient::new());

        let mut attempts = Vec::with_capacity(1);
        let result = connect_game_client(
            self.world_client
                .as_mut()
                .expect("World client только что опубликован"),
            &setup.world,
            GameUpstreamDirection::World,
            None,
            0,
        )
        .await;
        let endpoint = match result {
            Ok(endpoint) => {
                attempts.push(GameConnectAttempt {
                    direction: GameUpstreamDirection::World,
                    failure: None,
                });
                endpoint
            }
            Err(failure) => {
                attempts.push(GameConnectAttempt {
                    direction: GameUpstreamDirection::World,
                    failure: Some(failure),
                });
                self.close_and_remove_world_client();
                return GameClientInitialization::Failed { attempts };
            }
        };

        self.world_client
            .as_mut()
            .expect("подключённый World client остаётся опубликованным")
            .enable_control_send();
        let mut registration = CMessage::new(WORLD_REGISTRATION);
        registration.add_byte(0);
        registration.add_ulong(setup.listener.listen_port);
        add_legacy_c_string(registration.base_mut(), &setup.local_ip);
        let registration = registration.send(self, false);
        GameClientInitialization::Connected {
            endpoint,
            used_billing_backup: false,
            registration,
            attempts,
        }
    }

    /// Пересоздаёт Billing client, пробуя master и затем backup endpoint.
    pub(crate) async fn init_billing_client(&mut self) -> GameClientInitialization {
        let Some(setup) = self.network_setup.as_ref().cloned() else {
            return GameClientInitialization::Failed {
                attempts: vec![GameConnectAttempt {
                    direction: GameUpstreamDirection::BillingPrimary,
                    failure: Some(GameClientInitializationFailure::MissingNetworkSetup),
                }],
            };
        };
        self.close_and_remove_billing_client();
        self.attach_billing_client(CMyNetClient::new());

        let bind_ip = match resolve_billing_bind_ipv4(&setup.billing.bind_ip) {
            Ok(address) => address,
            Err(failure) => {
                self.close_and_remove_billing_client();
                return GameClientInitialization::Failed {
                    attempts: vec![GameConnectAttempt {
                        direction: GameUpstreamDirection::BillingPrimary,
                        failure: Some(failure),
                    }],
                };
            }
        };
        let mut attempts = Vec::with_capacity(2);
        let plans = [
            (
                &setup.billing.primary,
                GameUpstreamDirection::BillingPrimary,
            ),
            (&setup.billing.backup, GameUpstreamDirection::BillingBackup),
        ];
        let mut connected = None;
        for (endpoint_plan, direction) in plans {
            let result = connect_game_client(
                self.billing_client
                    .as_mut()
                    .expect("Billing client остаётся опубликованным между попытками"),
                endpoint_plan,
                direction,
                Some(bind_ip),
                setup.billing.bind_port,
            )
            .await;
            match result {
                Ok(endpoint) => {
                    attempts.push(GameConnectAttempt {
                        direction,
                        failure: None,
                    });
                    connected = Some((endpoint, direction));
                    break;
                }
                Err(failure) => attempts.push(GameConnectAttempt {
                    direction,
                    failure: Some(failure),
                }),
            }
        }
        let Some((endpoint, direction)) = connected else {
            self.close_and_remove_billing_client();
            return GameClientInitialization::Failed { attempts };
        };

        self.billing_client
            .as_mut()
            .expect("подключённый Billing client остаётся опубликованным")
            .enable_control_send();
        let registration = CMessage::new(BILLING_REGISTRATION).send_to_bs(self, false);
        GameClientInitialization::Connected {
            endpoint,
            used_billing_backup: direction == GameUpstreamDirection::BillingBackup,
            registration,
            attempts,
        }
    }

    /// Подключает новый World owner и публикует typed reconnect event.
    pub(crate) async fn reconnect_world_server(&self) -> GameReconnectPublication {
        let Some(setup) = self.network_setup.as_ref().cloned() else {
            return missing_setup_reconnect(GameUpstreamDirection::World);
        };
        let publisher = self.net_server.as_ref().map(CMyNetServer::event_publisher);
        reconnect_world_with(setup, publisher).await
    }

    /// Полный reached tail внутреннего события `0x6F902`: новый transport
    /// заменяет прежний World owner, после чего `0x5FA01` несёт признак
    /// reconnect и ordered snapshot всех live players вместе с region id.
    pub(crate) fn accept_reconnected_world_client<Context: ScriptRegionChangeContext>(
        &mut self,
        client: CMyNetClient,
        context: &mut Context,
    ) {
        let previous_client_closed = self.close_and_remove_world_client();
        self.attach_world_client(client);

        let player_count = self.player_count();
        let mut encoded_players = 0usize;
        let mut failed_players = 0usize;
        let mut registration = CMessage::new(WORLD_REGISTRATION);
        registration.add_byte(1);
        let setup = self
            .network_setup
            .as_ref()
            .expect("reconnect event создаётся только из опубликованного network setup");
        registration.add_ulong(setup.listener.listen_port);
        add_legacy_c_string(registration.base_mut(), &setup.local_ip);
        registration.add_ulong(player_count);
        for player_id in self.ordered_player_ids() {
            let Some(player) = self.find_player(player_id) else {
                registration.add_long(0);
                failed_players = failed_players.wrapping_add(1);
                continue;
            };
            let mut snapshot = Vec::new();
            if !self.encode_player_game_save(player, &mut snapshot, context) {
                registration.add_long(0);
                failed_players = failed_players.wrapping_add(1);
                continue;
            }
            registration.add_long(1);
            registration.add_long(player_id);
            registration.base_mut().add(&snapshot);
            registration.add_long(player.server_region_id().unwrap_or_default());
            registration.base_mut().update();
            encoded_players = encoded_players.wrapping_add(1);
        }
        let registration = registration.send(self, true);
        self.world_client
            .as_mut()
            .expect("reconnected World client опубликован до registration")
            .enable_control_send();
        add_game_log_text(b"Reconnect to WorldServer Success!");
        tracing::info!(
            previous_client_closed,
            player_count,
            encoded_players,
            failed_players,
            ?registration,
            "принято повторное подключение World"
        );
    }

    /// Подключает новый Billing owner и публикует typed reconnect event.
    pub(crate) async fn reconnect_billing_server(&self) -> GameReconnectPublication {
        let Some(setup) = self.network_setup.as_ref().cloned() else {
            return missing_setup_reconnect(GameUpstreamDirection::BillingPrimary);
        };
        let publisher = self.net_server.as_ref().map(CMyNetServer::event_publisher);
        reconnect_billing_with(setup, publisher).await
    }

    /// Останавливает прежний World worker, закрывает текущий канал и запускает retry entry.
    pub(crate) async fn create_connect_world_task(
        &mut self,
    ) -> Result<(), GameReconnectTaskStartError> {
        let setup = self
            .network_setup
            .as_ref()
            .cloned()
            .ok_or(GameReconnectTaskStartError::MissingNetworkSetup)?;
        let publisher = self
            .net_server
            .as_ref()
            .map(CMyNetServer::event_publisher)
            .ok_or(GameReconnectTaskStartError::MissingNetworkServerOwner)?;

        stop_reconnect_task(&mut self.world_reconnect_task).await;
        if let Some(client) = self.world_client.as_mut() {
            client.disable_control_send();
            let _legacy_result = client.close();
        }

        let exit_requested = Arc::new(AtomicBool::new(false));
        let worker_exit = Arc::clone(&exit_requested);
        let handle =
            tokio::spawn(
                async move { run_world_reconnect_task(setup, publisher, worker_exit).await },
            );
        self.world_reconnect_task = Some(GameReconnectTask {
            exit_requested,
            handle,
        });
        Ok(())
    }

    /// Synchronous message-loop entry эквивалента `CreateConnectWorldThread`.
    /// Если прежний worker ещё жив, новый task сначала выставляет ему exit и
    /// await-ит handle, затем начинает исходный трёхсекундный retry loop.
    pub(crate) fn schedule_world_reconnect_task(
        &mut self,
    ) -> Result<(), GameReconnectTaskStartError> {
        let setup = self
            .network_setup
            .as_ref()
            .cloned()
            .ok_or(GameReconnectTaskStartError::MissingNetworkSetup)?;
        let publisher = self
            .net_server
            .as_ref()
            .map(CMyNetServer::event_publisher)
            .ok_or(GameReconnectTaskStartError::MissingNetworkServerOwner)?;
        if let Some(client) = self.world_client.as_mut() {
            client.disable_control_send();
            let _legacy_result = client.close();
        }

        let previous = self.world_reconnect_task.take();
        let exit_requested = Arc::new(AtomicBool::new(false));
        let worker_exit = Arc::clone(&exit_requested);
        let handle = tokio::spawn(async move {
            if let Some(previous) = previous {
                previous.exit_requested.store(true, Ordering::Release);
                let _legacy_ignored = previous.handle.await;
            }
            if worker_exit.load(Ordering::Acquire) {
                return GameReconnectWorkerEnd::ExitRequested;
            }
            run_world_reconnect_task(setup, publisher, worker_exit).await
        });
        self.world_reconnect_task = Some(GameReconnectTask {
            exit_requested,
            handle,
        });
        Ok(())
    }

    /// Останавливает прежний Billing worker, закрывает текущий канал и запускает retry entry.
    pub(crate) async fn create_connect_billing_task(
        &mut self,
    ) -> Result<(), GameReconnectTaskStartError> {
        let setup = self
            .network_setup
            .as_ref()
            .cloned()
            .ok_or(GameReconnectTaskStartError::MissingNetworkSetup)?;
        let publisher = self
            .net_server
            .as_ref()
            .map(CMyNetServer::event_publisher)
            .ok_or(GameReconnectTaskStartError::MissingNetworkServerOwner)?;

        stop_reconnect_task(&mut self.billing_reconnect_task).await;
        if let Some(client) = self.billing_client.as_mut() {
            client.disable_control_send();
            let _legacy_result = client.close();
        }

        let exit_requested = Arc::new(AtomicBool::new(false));
        let worker_exit = Arc::clone(&exit_requested);
        let handle =
            tokio::spawn(
                async move { run_billing_reconnect_task(setup, publisher, worker_exit).await },
            );
        self.billing_reconnect_task = Some(GameReconnectTask {
            exit_requested,
            handle,
        });
        Ok(())
    }

    /// Message-loop entry `CreateConnectBillingThread`; сохраняет stop-before-
    /// retry и primary→backup connect policy без блокировки Game main loop.
    pub(crate) fn schedule_billing_reconnect_task(
        &mut self,
    ) -> Result<(), GameReconnectTaskStartError> {
        let setup = self
            .network_setup
            .as_ref()
            .cloned()
            .ok_or(GameReconnectTaskStartError::MissingNetworkSetup)?;
        let publisher = self
            .net_server
            .as_ref()
            .map(CMyNetServer::event_publisher)
            .ok_or(GameReconnectTaskStartError::MissingNetworkServerOwner)?;
        if let Some(client) = self.billing_client.as_mut() {
            client.disable_control_send();
            let _legacy_result = client.close();
        }

        let previous = self.billing_reconnect_task.take();
        let exit_requested = Arc::new(AtomicBool::new(false));
        let worker_exit = Arc::clone(&exit_requested);
        let handle = tokio::spawn(async move {
            if let Some(previous) = previous {
                previous.exit_requested.store(true, Ordering::Release);
                let _legacy_ignored = previous.handle.await;
            }
            if worker_exit.load(Ordering::Acquire) {
                return GameReconnectWorkerEnd::ExitRequested;
            }
            run_billing_reconnect_task(setup, publisher, worker_exit).await
        });
        self.billing_reconnect_task = Some(GameReconnectTask {
            exit_requested,
            handle,
        });
        Ok(())
    }

    /// Материализует начальный порядок остановки reconnect workers из `Release`.
    pub(crate) async fn stop_reconnect_tasks(&mut self) {
        stop_reconnect_task(&mut self.world_reconnect_task).await;
        stop_reconnect_task(&mut self.billing_reconnect_task).await;
    }

    /// Полное достигнутое освобождение `Release`. Ручные удаления заменены на
    /// `Drop` и `take/clear`; порядок владельцев и внешних отправок сохранён.
    /// Диагностика публикуется в точке действия и не повторяет teardown в
    /// возвращаемом дереве.
    pub(crate) async fn release<Runtime: GameThreadRuntime>(&mut self, runtime: &mut Runtime) {
        tracing::info!("GameServer начинает завершение");

        self.stop_reconnect_tasks().await;
        tracing::debug!("остановлены задачи переподключения GameServer");

        let player_ids: Vec<i32> = self.players.keys().copied().collect();
        let total_players = player_ids.len();
        for (index, player_id) in player_ids.into_iter().enumerate() {
            let mut snapshot = Vec::new();
            let encoded = self
                .players
                .get(&player_id)
                .is_some_and(|player| self.encode_player_game_save(player, &mut snapshot, runtime));
            let delivery = encoded.then(|| {
                let mut save = CMessage::new(GAME_RELEASE_PLAYER_SAVE_MESSAGE);
                save.add_long(player_id);
                save.add_long(1);
                save.base_mut().add(&snapshot);
                save.send(self, false)
            });
            // Native Release не проверял return CMessage::Send: `Ok(0)` при
            // уже отсутствующем World owner-е не становится codec exception.
            let saved = encoded && delivery.as_ref().is_some_and(Result::is_ok);
            if !saved {
                tracing::warn!(
                    player_id,
                    processed = index,
                    total = total_players,
                    encoded,
                    delivery = ?delivery,
                    "не удалось сохранить игрока при завершении GameServer"
                );
                // Safe Result-граница заменяет native exception catch, который
                // немедленно erase-ил проблемный map node и продолжал обход.
                self.players.remove(&player_id);
            }
        }
        tracing::debug!(
            processed = total_players,
            total = total_players,
            "завершена отправка данных игроков"
        );

        runtime.save_city_region(self, 0);
        tracing::debug!(region_id = 0, "сохранён городской регион");

        let players = self.players.len();
        self.players.clear();
        let regions = self.regions.len();
        self.regions.clear();
        tracing::debug!(players, regions, "очищены игроки и регионы");

        let proxy_regions = self.proxy_regions.len();
        self.proxy_regions.clear();
        tracing::debug!(proxy_regions, "очищены proxy-регионы");

        let function_list = self.function_list_file_data.take().is_some();
        let variable_list = self.variable_list_file_data.take().is_some();
        let script_files = self.script_file_data.len();
        self.script_file_data.clear();
        let active_scripts = self.active_scripts.len();
        self.active_scripts.clear();
        let function_registry = self.script_functions.release();
        let general_variables = self.general_variables.release();
        tracing::debug!(
            function_list,
            variable_list,
            files = script_files,
            active_scripts,
            function_registry,
            general_variables,
            "очищены script-данные"
        );

        self.skill_factory.clear_skill_cache();
        self.goods_factory.release();
        tracing::debug!("очищены фабрики навыков и предметов");

        let network_server_present = self.net_server.is_some();
        if let Some(server) = self.net_server.as_mut() {
            runtime.exit_network_server_worker(server);
        }
        tracing::debug!(
            network_server_present,
            "остановлен сетевой worker GameServer"
        );

        let world_client_present = self.world_client.is_some();
        if let Some(client) = self.world_client.as_mut() {
            client.disable_control_send();
            let _legacy_result = client.close();
        }
        let billing_client_present = self.billing_client.is_some();
        if let Some(client) = self.billing_client.as_mut() {
            client.disable_control_send();
            let _legacy_result = client.close();
        }
        self.world_client = None;
        self.billing_client = None;
        let network_server_present = self.net_server.take().is_some();
        tracing::debug!(
            world_client_present,
            billing_client_present,
            network_server_present,
            "освобождены сетевые владельцы GameServer"
        );

        let released_net_sessions = self.net_session_manager.release();

        self.increment_shop_list.release();
        self.quest_system = CQuestSystem::default();
        tracing::debug!(
            released_net_sessions,
            "освобождены сессии, магазин улучшений и система заданий"
        );

        let login_sequences = self.login_sequences.len();
        let login_validate_times = self.login_validate_times.len();
        self.login_sequences.clear();
        self.login_validate_times.clear();
        let sequence_count = self.sequence_registry.len();
        self.sequence_registry.clear();
        let player_ranks_present = self.player_ranks.take().is_some();
        self.words_filter.clear();
        self.honor_ranks = CHonorRanks::default();
        let goods_war_present = self.goods_war.take().is_some();
        self.country_handler = CCountryHandler::default();
        self.country_param = CCountryParam::default();
        tracing::debug!(
            login_sequences,
            login_validate_times,
            sequence_count,
            player_ranks_present,
            goods_war_present,
            "освобождены реестры и глобальные игровые владельцы"
        );

        let attack_city_schedules = self.attack_city_sys.attacks.len();
        self.attack_city_sys = CAttackCitySys::default();
        let village_war_schedules = self.village_war_sys.village_wars.len();
        self.village_war_sys = CVillageWarSys::default();
        tracing::debug!(
            attack_city_schedules,
            village_war_schedules,
            "освобождены расписания войн"
        );

        tracing::info!("GameServer завершён");
    }

    /// Выполняет один awaitable I/O шаг текущего World направления.
    pub(crate) async fn run_world_io_once(
        &mut self,
    ) -> Result<GameClientIoStep, GameClientIoError> {
        self.world_client
            .as_mut()
            .ok_or(GameClientIoError::NotConnected)?
            .run_io_once()
            .await
    }

    /// Выполняет один awaitable I/O шаг текущего Billing направления.
    pub(crate) async fn run_billing_io_once(
        &mut self,
    ) -> Result<GameClientIoStep, GameClientIoError> {
        self.billing_client
            .as_mut()
            .ok_or(GameClientIoError::NotConnected)?
            .run_io_once()
            .await
    }

    fn close_and_remove_world_client(&mut self) -> bool {
        let mut client = self.world_client.take();
        if let Some(client) = client.as_mut() {
            let _legacy_result = client.close();
        }
        client.is_some()
    }

    fn close_and_remove_billing_client(&mut self) -> bool {
        let mut client = self.billing_client.take();
        if let Some(client) = client.as_mut() {
            let _legacy_result = client.close();
        }
        client.is_some()
    }

    pub(crate) fn register_player(&mut self, mut player: CPlayer) -> Option<CPlayer> {
        player.initialize_variable_list(self.variable_list_file_data.as_deref());
        self.players.insert(player.player_id(), player)
    }

    pub(crate) fn discard_player_login(&mut self, player_id: i32) -> (bool, i32) {
        let removed = self.players.remove(&player_id).is_some();
        self.login_sequences.remove(&player_id);
        self.login_validate_times.remove(&player_id);
        let route_command = self.net_server().clear_player_map_id(player_id);
        (removed, route_command)
    }

    /// Exact login prefix после успешного World status: optional validation
    /// clock и sequence выдаются клиенту до decode player snapshot. Оба owner-а
    /// остаются привязаны к player ID до OnLost/reject, как native maps.
    pub(crate) fn begin_player_login_validation(
        &mut self,
        player_id: i32,
        issued_tick_ms: u32,
        issued_wall_seconds: u32,
    ) -> Result<(), GamePlayerLoginPreludeError> {
        let validate_time =
            (self.setup.message_validate_time_ms != 0).then(|| PlayerLoginValidateTime {
                issued_tick_ms,
                issued_wall_seconds,
                timeout_ms: self.setup.message_validate_time_ms,
            });
        let validate_delivery = validate_time.map(|validation| {
            self.login_validate_times.insert(player_id, true);
            let mut message = CMessage::new(0x000b_f402);
            message.add_long(player_id);
            message.add_ulong(validation.issued_tick_ms);
            message.add_ulong(validation.issued_wall_seconds);
            message.send_to_player(self.net_server(), player_id)
        });

        let mut sequence_position = None;
        let mut sequence_elements = 0usize;
        let mut sequence_delivery = None;
        if !self.sequence_registry.is_empty() {
            if self.login_sequences.remove(&player_id).is_some() {
                return Err(GamePlayerLoginPreludeError::DuplicateSequenceOwner { player_id });
            }
            let (registry, random_state) = (&self.sequence_registry, &mut self.random_state);
            let mut sequence = CSequenceString::new();
            let payload = sequence
                .serialize(registry, || next_msvc_rand(random_state))
                .map_err(GamePlayerLoginPreludeError::Sequence)?;
            sequence_position = Some(sequence.position());
            sequence_elements = registry.len();
            self.login_sequences.insert(player_id, sequence);

            let mut message = CMessage::new(0x000b_f403);
            message.add_long(player_id);
            message.base_mut().add(&payload);
            sequence_delivery = Some(message.send_to_player(self.net_server(), player_id));
        }

        tracing::trace!(
            player_id,
            ?validate_time,
            ?validate_delivery,
            ?sequence_position,
            sequence_elements,
            ?sequence_delivery,
            "предварительная проверка входа игрока завершена"
        );
        Ok(())
    }

    pub(crate) fn clear_player_login_validation(&mut self, player_id: i32) {
        self.login_sequences.remove(&player_id);
        self.login_validate_times.remove(&player_id);
    }

    fn restore_player_login_pets<Context: ServerRegionMonsterContext>(
        &mut self,
        player_id: i32,
        region_id: i32,
        context: &mut Context,
    ) {
        let records = self
            .players
            .get_mut(&player_id)
            .map(CPlayer::take_uncreated_pets)
            .unwrap_or_default();
        if records.is_empty() {
            return;
        }
        let notice_delivery =
            colored_player_notice_message(0xffff_ffff, 0, self.get_string_by_id(b"GS0156"))
                .send_to_player(self.net_server(), player_id);
        tracing::trace!(
            player_id,
            notice_delivery,
            "уведомление о восстановлении питомцев отправлено"
        );
        let (taming_level, current_pets) = self.players.get(&player_id).map_or((0, 0), |player| {
            (
                player.learned_skill_level(0xd4),
                player.active_pets().len() as u32,
            )
        });
        let amount = if taming_level == 0 {
            records.len()
        } else {
            let limit = self
                .skill_factory
                .query_skill_base_properties(0xd4, taming_level)
                .map_or(records.len() as u32, |properties| {
                    properties.query_property(31_001)
                });
            records
                .len()
                .min(limit.saturating_sub(current_pets) as usize)
        };
        let player_name = self
            .players
            .get(&player_id)
            .map(|player| player.player_name().to_vec())
            .unwrap_or_default();
        let (player_tile_x, player_tile_y) = self
            .players
            .get(&player_id)
            .map(|player| {
                (
                    player.shape().get_tile_x().unwrap_or_default(),
                    player.shape().get_tile_y().unwrap_or_default(),
                )
            })
            .unwrap_or_default();
        let Some(mut owner) = self.take_region_owner(region_id) else {
            tracing::warn!(
                player_id,
                region_id,
                "питомцы при входе не восстановлены: регион отсутствует"
            );
            return;
        };
        let (area_width, area_height) = self.area_dimensions();
        for record in records.into_iter().take(amount) {
            let Some(property) = self
                .find_monster_property_by_origin_name(&record.original_name)
                .cloned()
            else {
                tracing::warn!(
                    player_id,
                    original_name_bytes = record.original_name.len(),
                    "питомец при входе не восстановлен: свойства отсутствуют"
                );
                continue;
            };
            let position = owner
                .base()
                .region
                .get_random_pos_in_range(player_tile_x - 3, player_tile_y - 3, 7, 7, context)
                .unwrap_or(RegionRandomPosition {
                    x: player_tile_x,
                    y: player_tile_y,
                    found: false,
                });
            let monster_id = match owner.base_mut().add_monster(
                &property,
                position.x,
                position.y,
                -1,
                true,
                false,
                context.now_milliseconds(),
                area_width,
                area_height,
                context,
            ) {
                Ok(monster_id) => monster_id,
                Err(_) => {
                    tracing::warn!(
                        player_id,
                        original_name_bytes = record.original_name.len(),
                        "питомец при входе не создан"
                    );
                    continue;
                }
            };
            let factors = self
                .globe_setup
                .pet_progression(record.level)
                .map(|(_, factors)| factors);
            let (shape, maximum_hp) = {
                let pet = owner
                    .base_mut()
                    .find_monster_by_id_mut(monster_id)
                    .expect("add_monster публикует owned monster до возврата ID");
                pet.set_tamed(property.tamable == 1 && property.maximum_tame_attempt_count > 0);
                pet.set_master_info(crate::gameserver::appserver::masterinfo::MasterInfo {
                    master_type: 400,
                    master_id: player_id,
                    ..crate::gameserver::appserver::masterinfo::MasterInfo::default()
                });
                pet.set_pet_mode(1);
                pet.set_pet_progress(record.level, record.experience);
                if let Some(factors) = factors {
                    pet.adjust_pet_factors(factors);
                }
                pet.set_hit_points(record.health);
                (
                    pet.move_shape().shape().clone(),
                    pet.pet_maximum_hp(&property),
                )
            };
            if let Some(player) = self.players.get_mut(&player_id) {
                player.add_active_pet(600, monster_id, property.figure as u8 as i32);
            }
            let mut message = CMessage::new(0x000c_0201);
            message.add_long(600);
            message.add_long(monster_id);
            message.add_long(400);
            message.add_long(player_id);
            add_legacy_c_string(message.base_mut(), &player_name);
            message.add_ulong(record.level);
            message.add_ulong(record.experience);
            message.add_ulong(record.health);
            message.add_ulong(maximum_hp);
            let around_delivery = self
                .send_game_shape_around(owner.base(), &shape, None, &message)
                .ok();
            tracing::trace!(
                player_id,
                monster_id,
                original_name_bytes = record.original_name.len(),
                ?around_delivery,
                "питомец при входе восстановлен"
            );
        }
        self.restore_region_owner(owner);
    }

    fn restore_player_login_carriage<Context: ServerRegionMonsterContext>(
        &mut self,
        player_id: i32,
        region_id: i32,
        context: &mut Context,
    ) -> Option<()> {
        let (record, recreate, player_name, player_x, player_y, player_direction) =
            self.find_player(player_id).and_then(|player| {
                let (record, recreate) = player.login_carriage();
                Some((
                    record.clone(),
                    recreate,
                    player.player_name().to_vec(),
                    player.shape().get_tile_x().ok()?,
                    player.shape().get_tile_y().ok()?,
                    player.shape().get_direction(),
                ))
            })?;
        if recreate && record.original_name.is_empty() {
            self.find_player_mut(player_id)?
                .finish_empty_login_carriage_recreation();
            return None;
        }
        let mut owner = self.take_region_owner(region_id)?;

        let existing = if !recreate {
            owner
                .base()
                .area_monster_ids()
                .into_iter()
                .find_map(|monster_id| {
                    let monster = owner.base().find_monster_by_id(monster_id)?;
                    let property =
                        self.find_monster_property_by_origin_name(monster.base_property_key()?)?;
                    (monster.is_carriage(property)
                        && monster.master_info().master_type == PLAYER_TYPE
                        && monster.master_info().master_id == player_id)
                        .then_some((
                            monster_id,
                            monster.move_shape().shape().clone(),
                            monster.hit_points(),
                            property.maximum_hp,
                            monster.original_name().to_vec(),
                            property.index,
                        ))
                })
        } else {
            None
        };

        let carriage = if let Some(existing) = existing {
            Some(existing)
        } else if recreate && !record.original_name.is_empty() {
            let Some(property) = self
                .find_monster_property_by_origin_name(&record.original_name)
                .cloned()
            else {
                self.restore_region_owner(owner);
                tracing::warn!(
                    player_id,
                    original_name_bytes = record.original_name.len(),
                    "повозка при входе не восстановлена: свойства отсутствуют"
                );
                return Some(());
            };
            if !(property.tamable == 1 && property.maximum_tame_attempt_count == 0) {
                self.restore_region_owner(owner);
                tracing::warn!(
                    player_id,
                    original_name_bytes = record.original_name.len(),
                    "повозка при входе не восстановлена: свойства несовместимы"
                );
                return Some(());
            }
            let Some(position) = owner
                .base()
                .region
                .get_random_pos_in_range(player_x, player_y, 10, 10, context)
                .ok()
            else {
                self.restore_region_owner(owner);
                tracing::warn!(
                    player_id,
                    region_id,
                    "повозка при входе не восстановлена: позиция недоступна"
                );
                return Some(());
            };
            let Some(monster_id) = owner
                .base_mut()
                .add_monster(
                    &property,
                    position.x,
                    position.y,
                    -1,
                    true,
                    false,
                    context.now_milliseconds(),
                    self.area_width,
                    self.area_height,
                    context,
                )
                .ok()
            else {
                self.restore_region_owner(owner);
                tracing::warn!(player_id, region_id, "повозка при входе не создана");
                return Some(());
            };
            let monster = owner
                .base_mut()
                .find_monster_by_id_mut(monster_id)
                .expect("carriage AddMonster публикует concrete owner");
            monster.set_master_info(crate::gameserver::appserver::masterinfo::MasterInfo {
                master_type: PLAYER_TYPE,
                master_id: player_id,
                ..crate::gameserver::appserver::masterinfo::MasterInfo::default()
            });
            monster
                .move_shape_mut()
                .shape_mut()
                .set_direction(player_direction);
            monster.set_hit_points(record.health);
            monster.set_script_file(&record.script);
            Some((
                monster_id,
                monster.move_shape().shape().clone(),
                monster.hit_points(),
                property.maximum_hp,
                monster.original_name().to_vec(),
                property.index,
            ))
        } else {
            None
        };

        let Some((monster_id, shape, health, maximum_hp, original_name, carriage_index)) = carriage
        else {
            self.restore_region_owner(owner);
            return None;
        };
        if let Some(player) = self.find_player_mut(player_id) {
            if recreate {
                player.finish_login_carriage_recreation(monster_id);
            } else {
                player.bind_active_carriage(monster_id);
            }
        }
        let mut entered = CMessage::new(0x000c_0205);
        entered.add_long(MONSTER_TYPE);
        entered.add_long(monster_id);
        entered.add_long(PLAYER_TYPE);
        entered.add_long(player_id);
        add_legacy_c_string(entered.base_mut(), &player_name);
        entered.add_ulong(health);
        entered.add_ulong(maximum_hp);
        let around_delivery = self
            .send_game_shape_around(owner.base(), &shape, None, &entered)
            .ok();
        if recreate {
            let _ = self.send_carriage_log_snapshot(
                player_id,
                carriage_index,
                region_id,
                shape.get_tile_x().unwrap_or_default(),
                shape.get_tile_y().unwrap_or_default(),
                7,
            );
        }
        self.restore_region_owner(owner);
        tracing::trace!(
            player_id,
            monster_id,
            original_name_bytes = original_name.len(),
            ?around_delivery,
            "повозка при входе восстановлена"
        );
        Some(())
    }

    fn send_carriage_log_snapshot(
        &self,
        player_id: i32,
        carriage_index: u32,
        region_id: i32,
        tile_x: i32,
        tile_y: i32,
        reason: i32,
    ) -> Option<Result<i32, SendMessageError>> {
        if !self.log_system.carriage_enabled() {
            return None;
        }
        let mut audit = CMessage::new(0x0006_020e);
        audit.add_long(player_id);
        audit.add_long(carriage_index as i32);
        audit.add_long(region_id);
        audit.base_mut().add_short(tile_x as i16);
        audit.base_mut().add_short(tile_y as i16);
        audit.add_long(reason);
        Some(audit.send(self, false))
    }

    /// Сценарная функция `3504 / AddCarriage`: вычисленные имена доходят до
    /// канонических свойств, размещения в регионе, привязки к игроку,
    /// публикации `C0205` и журналирования в World.
    pub(crate) fn add_script_player_carriage<Context: ServerRegionMonsterContext>(
        &mut self,
        player_id: i32,
        original_name: &[u8],
        script_file: Option<&[u8]>,
        context: &mut Context,
    ) -> i32 {
        let Some((region_id, player_name, player_x, player_y)) =
            self.find_player(player_id).map(|player| {
                (
                    player.server_region_id(),
                    player.player_name().to_vec(),
                    player.shape().get_tile_x(),
                    player.shape().get_tile_y(),
                )
            })
        else {
            return 0;
        };
        let Some(region_id) = region_id else {
            // Исходный `AddCarriage` сообщает об успехе, когда у формы нет
            // родителя `CServerRegion`, и не изменяет состояние.
            return 1;
        };
        let (Ok(player_x), Ok(player_y)) = (player_x, player_y) else {
            return 0;
        };
        let Some(property) = self
            .find_monster_property_by_origin_name(original_name)
            .filter(|property| property.tamable == 1 && property.maximum_tame_attempt_count == 0)
            .cloned()
        else {
            return 0;
        };
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return 0;
        };
        let position = owner
            .base()
            .region
            .get_random_pos_in_range(
                player_x.wrapping_sub(3),
                player_y.wrapping_sub(3),
                7,
                7,
                context,
            )
            .ok();
        let Some(position) = position else {
            self.restore_region_owner(owner);
            return 0;
        };
        let monster_id = owner
            .base_mut()
            .add_monster(
                &property,
                position.x,
                position.y,
                -1,
                true,
                false,
                context.now_milliseconds(),
                self.area_width,
                self.area_height,
                context,
            )
            .ok();
        let Some(monster_id) = monster_id else {
            self.restore_region_owner(owner);
            return 0;
        };
        let (shape, health) = {
            let carriage = owner
                .base_mut()
                .find_monster_by_id_mut(monster_id)
                .expect("script AddCarriage сохраняет spawned owner");
            carriage.set_master_info(crate::gameserver::appserver::masterinfo::MasterInfo {
                master_type: PLAYER_TYPE,
                master_id: player_id,
                ..crate::gameserver::appserver::masterinfo::MasterInfo::default()
            });
            carriage.set_carriage_action(0);
            if let Some(script_file) = script_file.filter(|script| *script != b"0") {
                carriage.set_script_file(script_file);
            }
            (carriage.move_shape().shape().clone(), carriage.hit_points())
        };
        if let Some(player) = self.find_player_mut(player_id) {
            player.bind_active_carriage(monster_id);
        }
        let mut entered = CMessage::new(0x000c_0205);
        entered.add_long(MONSTER_TYPE);
        entered.add_long(monster_id);
        entered.add_long(PLAYER_TYPE);
        entered.add_long(player_id);
        add_legacy_c_string(entered.base_mut(), &player_name);
        entered.add_ulong(health);
        entered.add_ulong(property.maximum_hp);
        let _ = self.send_game_shape_around(owner.base(), &shape, None, &entered);
        let _ = self.send_carriage_log_snapshot(
            player_id,
            property.index,
            region_id,
            shape.get_tile_x().unwrap_or_default(),
            shape.get_tile_y().unwrap_or_default(),
            1,
        );
        self.restore_region_owner(owner);
        1
    }

    pub(crate) fn delete_script_player_carriage(&mut self, player_id: i32) -> i32 {
        let Some((region_id, carriage_id)) = self
            .find_player(player_id)
            .map(|player| (player.server_region_id(), player.active_carriage_id()))
        else {
            return 0;
        };
        if let Some(player) = self.find_player_mut(player_id) {
            player.bind_active_carriage(0);
        }
        let Some(region_id) = region_id else {
            return 0;
        };
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return 0;
        };
        let snapshot = owner
            .base()
            .find_monster_by_id(carriage_id)
            .and_then(|carriage| {
                let property =
                    self.find_monster_property_by_origin_name(carriage.base_property_key()?)?;
                let master = carriage.master_info();
                (carriage.is_carriage(property)
                    && master.master_type == PLAYER_TYPE
                    && master.master_id == player_id)
                    .then(|| (property.index, carriage.move_shape().shape().clone()))
            });
        if let Some((index, shape)) = snapshot {
            let _ = self.send_carriage_log_snapshot(
                player_id,
                index,
                region_id,
                shape.get_tile_x().unwrap_or_default(),
                shape.get_tile_y().unwrap_or_default(),
                2,
            );
            let mut vanished = CMessage::new(0x000b_f504);
            vanished.add_long(MONSTER_TYPE);
            vanished.add_long(carriage_id);
            vanished.add_long(0);
            let _ = self.send_game_shape_around(owner.base(), &shape, None, &vanished);
            if let Some(carriage) = owner.base_mut().find_monster_by_id_mut(carriage_id) {
                carriage.stage_for_delete();
            }
        }
        self.restore_region_owner(owner);
        0
    }

    pub(crate) fn script_player_carriage_distance(&self, player_id: i32) -> i32 {
        let Some(player) = self.find_player(player_id) else {
            return 0;
        };
        let Some(region_id) = player.server_region_id() else {
            return 0;
        };
        let Some(carriage) = self
            .find_region(region_id)
            .and_then(|owner| owner.base().find_monster_by_id(player.active_carriage_id()))
        else {
            return 0;
        };
        let Some(property) = carriage
            .base_property_key()
            .and_then(|key| self.find_monster_property_by_origin_name(key))
        else {
            return 0;
        };
        let master = carriage.master_info();
        if !carriage.is_carriage(property)
            || master.master_type != PLAYER_TYPE
            || master.master_id != player_id
        {
            return 0;
        }
        let Some((px, py, cx, cy)) = player
            .shape()
            .get_tile_x()
            .ok()
            .zip(player.shape().get_tile_y().ok())
            .zip(
                carriage
                    .move_shape()
                    .shape()
                    .get_tile_x()
                    .ok()
                    .zip(carriage.move_shape().shape().get_tile_y().ok()),
            )
            .map(|((px, py), (cx, cy))| (px, py, cx, cy))
        else {
            return 0;
        };
        real_distance(px, py, cx, cy)
    }

    pub(crate) fn script_player_carriage_index(&self, player_id: i32) -> i32 {
        let Some(player) = self.find_player(player_id) else {
            return 0;
        };
        player
            .server_region_id()
            .and_then(|region_id| self.find_region(region_id))
            .and_then(|owner| owner.base().find_monster_by_id(player.active_carriage_id()))
            .and_then(CMonster::base_property_key)
            .and_then(|key| self.find_monster_property_by_origin_name(key))
            .map_or(0, |property| property.index as i32)
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn complete_world_player_login<
        Context: GamePlayerLoginContext + ScriptFunctionRuntime,
    >(
        &mut self,
        expected_player_id: i32,
        mut player: CPlayer,
        captain: bool,
        team_id: i32,
        context: &mut Context,
    ) -> Result<(), GamePlayerLoginBlock> {
        let decoded = player.player_id();
        if decoded != expected_player_id {
            return Err(GamePlayerLoginBlock::PlayerIdMismatch {
                expected: expected_player_id,
                decoded,
            });
        }
        if self.players.contains_key(&expected_player_id) {
            return Err(GamePlayerLoginBlock::AlreadyRegistered {
                player_id: expected_player_id,
            });
        }
        player.restore_login_team(captain, team_id);
        let team_session_id = (team_id != 0)
            .then(|| self.get_team_session_id(team_id as u32))
            .unwrap_or_default();
        let team_session_found = team_session_id != 0
            && self
                .session_factory
                .query_session(team_session_id)
                .is_some();
        let region_id = player.server_region_id().unwrap_or_default();
        self.players.insert(expected_player_id, player);

        let mut player = self
            .players
            .remove(&expected_player_id)
            .expect("login player только что зарегистрирован");
        let Some(mut owner) = self.take_region_owner(region_id) else {
            self.players.insert(expected_player_id, player);
            return Err(GamePlayerLoginBlock::MissingRegion { region_id });
        };
        let mut relocation = None;
        if player.shape().get_pos_x() == -0.5 && player.shape().get_pos_y() == -0.5 {
            if let Ok(position) = owner.base().region.get_random_pos(context) {
                player
                    .movement_shape_mut()
                    .set_pos_xy_base(position.x as f32 + 0.5, position.y as f32 + 0.5);
                relocation = Some((position.x, position.y));
            }
        }
        let tile = (
            player.shape().get_tile_x().unwrap_or_default(),
            player.shape().get_tile_y().unwrap_or_default(),
        );
        if owner
            .base()
            .region
            .get_block(tile.0, tile.1)
            .unwrap_or_default()
            != 0
            && let Ok(position) = owner
                .base()
                .region
                .get_random_pos_in_range(tile.0, tile.1, 3, 3, context)
        {
            player
                .movement_shape_mut()
                .set_pos_xy_base(position.x as f32 + 0.5, position.y as f32 + 0.5);
            relocation = Some((position.x, position.y));
        }
        let facts = ShapeRuntimeFacts {
            is_player: true,
            monster: None,
            is_npc: false,
            goods: None,
            is_move_shape: true,
            figure: player.figure(),
        };
        let membership = owner.base_mut().add_object_with_area_entry(
            player.movement_shape_mut(),
            facts,
            self.globe_setup.area_width(),
            self.globe_setup.area_height(),
            context.now_milliseconds(),
            context,
            |region, area_index, context| {
                self.wake_owned_monsters_around_area(region, area_index, || {
                    context.now_milliseconds()
                });
            },
        );
        self.restore_region_owner(owner);
        self.players.insert(expected_player_id, player);
        membership.map_err(GamePlayerLoginBlock::Membership)?;
        let _ = self.enter_gods_battle_player(region_id, expected_player_id);
        let team_snapshot_queued = team_id != 0 && !team_session_found;
        if team_snapshot_queued {
            self.team_snapshot_queries
                .insert(team_id as u32, GameTeamSnapshotQuery::default());
        }

        let login_tick_ms = context.now_milliseconds();
        let loaded_change_body_states = self
            .players
            .get_mut(&expected_player_id)
            .expect("spatial login сохраняет player map owner")
            .activate_loaded_change_body_states(login_tick_ms);
        let loaded_ride_state = self
            .players
            .get_mut(&expected_player_id)
            .expect("spatial login сохраняет player map owner")
            .activate_loaded_ride_state();
        let loaded_extended_states = self
            .players
            .get_mut(&expected_player_id)
            .expect("spatial login сохраняет player map owner")
            .activate_loaded_extended_states(login_tick_ms);
        let loaded_appellation_states = self
            .players
            .get_mut(&expected_player_id)
            .expect("spatial login сохраняет player map owner")
            .activate_loaded_appellation_states(login_tick_ms);
        let loaded_leaf_cut_state = self
            .players
            .get_mut(&expected_player_id)
            .expect("spatial login сохраняет player map owner")
            .activate_loaded_leaf_cut_state(login_tick_ms);
        let loaded_leaf_cut_3_state = self
            .players
            .get_mut(&expected_player_id)
            .expect("spatial login сохраняет player map owner")
            .activate_loaded_leaf_cut_3_state(login_tick_ms);
        let loaded_kerosene_state = self.players.get_mut(&expected_player_id).expect("spatial login сохраняет player map owner").activate_loaded_kerosene_state(login_tick_ms);
        let loaded_poison_fog_state = self.players.get_mut(&expected_player_id).expect("spatial login сохраняет player map owner").activate_loaded_poison_fog_state(login_tick_ms);
        for state in &loaded_appellation_states {
            self.send_appellation_visual(expected_player_id, state, true, login_tick_ms);
        }
        for state in &loaded_extended_states {
            self.send_extended_state_visual(expected_player_id, state, true, login_tick_ms);
        }
        for state in &loaded_change_body_states {
            self.send_change_body_visual(expected_player_id, state, true);
        }
        if let Some(state) = &loaded_ride_state {
            self.send_ride_visual(expected_player_id, state, true);
        }
        if let Some(state) = loaded_leaf_cut_state
            && let Some(player) = self.find_player(expected_player_id)
            && let (Ok(x), Ok(y)) = (player.shape().get_tile_x(), player.shape().get_tile_y())
        {
            send_leaf_cut_state_visual(
                self,
                region_id,
                ShapeIdentity { object_type: PLAYER_TYPE, id: expected_player_id, ex_id: CGuid::GUID_INVALID },
                x,
                y,
                state,
                true,
                login_tick_ms,
            );
        }
        if let Some(state) = loaded_leaf_cut_3_state
            && let Some(player) = self.find_player(expected_player_id)
            && let (Ok(x), Ok(y)) = (player.shape().get_tile_x(), player.shape().get_tile_y())
        {
            send_leaf_cut_3_state_visual(
                self,
                region_id,
                ShapeIdentity { object_type: PLAYER_TYPE, id: expected_player_id, ex_id: CGuid::GUID_INVALID },
                x,
                y,
                state,
                true,
                login_tick_ms,
            );
        }
        if let Some(state) = loaded_poison_fog_state
            && let Some(player) = self.find_player(expected_player_id)
            && let (Ok(x), Ok(y)) = (player.shape().get_tile_x(), player.shape().get_tile_y())
        { crate::gameserver::appserver::skills::poisonfogstate::send_poison_fog_state_visual(self, region_id, ShapeIdentity { object_type: PLAYER_TYPE, id: expected_player_id, ex_id: CGuid::GUID_INVALID }, x, y, state, true, login_tick_ms); }
        if let Some(state) = loaded_kerosene_state
            && let Some(player) = self.find_player(expected_player_id)
            && let (Ok(x), Ok(y)) = (player.shape().get_tile_x(), player.shape().get_tile_y())
        { crate::gameserver::appserver::skills::kerosenestate::send_kerosene_state_visual(self, region_id, ShapeIdentity { object_type: PLAYER_TYPE, id: expected_player_id, ex_id: CGuid::GUID_INVALID }, x, y, state, true, login_tick_ms); }
        self.restore_player_login_pets(expected_player_id, region_id, context);
        self.restore_player_login_carriage(expected_player_id, region_id, context);

        let first_login = self
            .players
            .get_mut(&expected_player_id)
            .expect("spatial login сохраняет player map owner")
            .mark_login_script_started();
        let login_script_id = if first_login {
            let path = self.quest_system.player_login_script.clone();
            self.run_script_file(
                &path,
                ScriptExecutionContext {
                    player_id: Some(expected_player_id),
                    region_id: Some(region_id),
                    ..ScriptExecutionContext::default()
                },
                context,
            )
        } else {
            None
        };
        let recomputed = context.recompute_enhancement_player_properties(
            self.players
                .get(&expected_player_id)
                .expect("login script не удаляет player owner"),
        );
        let coefficients = self.globe_setup.player_property_coefficients();
        let goods_factory = self.goods_factory.clone();
        self.players
            .get_mut(&expected_player_id)
            .expect("login property callback не удаляет player owner")
            .apply_change_body_properties(recomputed, coefficients, &goods_factory);
        context.publish_initial_player_client_snapshot(self, expected_player_id, first_login);
        let mut billing = CMessage::new(0x000e_f201);
        add_legacy_c_string(
            billing.base_mut(),
            self.players
                .get(&expected_player_id)
                .expect("client snapshot сохраняет player owner")
                .account(),
        );
        billing.add_long(expected_player_id);
        let billing_delivery = billing.send_to_bs(self, false).unwrap_or_default();
        let adjust_honor = self.globe_setup.use_appellation_function()
            && self
                .players
                .get(&expected_player_id)
                .is_some_and(|player| player.honor_snapshot().rank_of_nobility_id != 0);
        let honor_script_id = adjust_honor
            .then(|| {
                self.run_script_file(
                    b"scripts/circle/honorrank/adjusthonorrank.script",
                    ScriptExecutionContext {
                        player_id: Some(expected_player_id),
                        region_id: Some(region_id),
                        ..ScriptExecutionContext::default()
                    },
                    context,
                )
            })
            .flatten();

        let mut goods_ai_registrations = 0usize;
        let mut goods_ai_entries = Vec::new();
        let mut pending_equipment_state_updates = Vec::new();
        {
            let (players, goods_factory) = (&mut self.players, &self.goods_factory);
            let player = players
                .get_mut(&expected_player_id)
                .expect("honor script scheduling сохраняет player owner");
            let current_ticket = player.current_ticket();
            player.visit_login_goods_mut(|location, goods| {
                let now_seconds = game_wall_time_seconds();
                if let Some(entry) = CPlayer::prepare_goods_ai_registration(
                    current_ticket,
                    goods,
                    goods_factory,
                    now_seconds,
                ) {
                    goods_ai_entries.push(entry);
                }
                goods_ai_registrations += 1;
                if !matches!(
                    location,
                    PlayerLoginGoodsLocation::Equipment
                        | PlayerLoginGoodsLocation::Packet
                        | PlayerLoginGoodsLocation::Depot
                ) || goods.addon_property_value(goods_factory, GAP_EQUIP_STATE, 1) != 2
                {
                    return true;
                }
                let packed_expiration =
                    goods.addon_property_value(goods_factory, GAP_EQUIP_STATE, 2);
                if packed_expiration == 0 {
                    return false;
                }
                if equipment_state_elapsed_seconds(packed_expiration)
                    .is_some_and(|elapsed| elapsed / 60.0 > 10_079.0)
                {
                    let _ = goods.set_addon_property_modifier_core(GAP_EQUIP_STATE, 1, 3);
                    pending_equipment_state_updates.push((
                        location,
                        goods.identity(),
                        context.encode_goods_for_old_client(goods),
                    ));
                }
                true
            });
            for (ticket, goods_id) in goods_ai_entries.drain(..) {
                player.record_goods_ai_registration(ticket, goods_id);
            }
        }
        for (location, goods, payload) in pending_equipment_state_updates {
            let mut update = CMessage::new(0x000b_f928);
            update.add_long(expected_player_id);
            update.base_mut().add_guid(goods.ex_id);
            update.add_ulong(payload.len() as u32);
            update.base_mut().add(&payload);
            let delivery = if location == PlayerLoginGoodsLocation::Depot {
                self.send_player_shape_around(expected_player_id, None, &update)
                    .and_then(Result::ok)
                    .unwrap_or_default()
            } else {
                update.send_to_player(self.net_server(), expected_player_id)
            };
            tracing::trace!(
                player_id = expected_player_id,
                ?location,
                ?goods,
                delivery,
                "состояние снаряжения обновлено при входе"
            );
        }

        tracing::trace!(
            player_id = expected_player_id,
            team_id,
            captain,
            region_id,
            first_login,
            ?relocation,
            ?login_script_id,
            billing_delivery,
            ?honor_script_id,
            goods_ai_registrations,
            team_session_found,
            team_snapshot_queued,
            "вход игрока завершён владельцем CGame"
        );
        Ok(())
    }

    /// Exact `s_mapPlayer.size()` для GMA `0x80002`; x86 `size_type` — DWORD.
    pub(crate) fn player_count(&self) -> u32 {
        u32::try_from(self.players.len()).expect("x86 player map не может превысить DWORD")
    }

    /// Снимок ordered ключей `s_mapPlayer` для WorldServer snapshot-обходов.
    /// В safe owner-е отсутствуют nullable map values исходного C++.
    pub(crate) fn ordered_player_ids(&self) -> Vec<i32> {
        self.players.keys().copied().collect()
    }

    pub(crate) fn reset_total_honor_eliminate(&mut self, reset_mask: u32) {
        for player in self.players.values_mut() {
            player.reset_total_honor_eliminate(reset_mask);
        }
    }

    pub(crate) fn register_team_session(&mut self, team_id: u32, session_id: i32) -> Option<i32> {
        self.team_session_ids.insert(team_id, session_id)
    }

    pub(crate) fn get_team_session_id(&self, team_id: u32) -> i32 {
        self.team_session_ids.get(&team_id).copied().unwrap_or(0)
    }

    fn script_team_session_id(&self, player_id: i32) -> Option<i32> {
        let team_id = self.find_player(player_id)?.team_id();
        if team_id == 0 {
            return None;
        }
        let session_id = self.get_team_session_id(team_id as u32);
        (session_id != 0 && self.session_factory.query_team(session_id).is_some())
            .then_some(session_id)
    }

    pub(crate) fn script_team_member_count(&self, player_id: i32) -> i32 {
        self.script_team_session_id(player_id)
            .and_then(|session_id| self.session_factory.team_member_count(session_id))
            .map(|count| i32::try_from(count).unwrap_or(i32::MAX))
            .unwrap_or_default()
    }

    pub(crate) fn script_team_member_name(&self, player_id: i32, position: i32) -> Vec<u8> {
        if position < 0 {
            return Vec::new();
        }
        self.script_team_session_id(player_id)
            .and_then(|session_id| self.session_factory.team_member_descriptors(session_id))
            .and_then(|members| members.get(position as usize).copied())
            .filter(|(owner_type, _, _)| *owner_type == 400)
            .and_then(|(_, teammate_id, _)| self.find_player(teammate_id))
            .map(|player| player.shape().base_object().get_name().to_vec())
            .unwrap_or_default()
    }

    pub(crate) fn script_is_team_captain(&self, player_id: i32) -> i32 {
        self.script_team_session_id(player_id)
            .and_then(|session_id| self.session_factory.query_team(session_id))
            .map_or(-1, |team| i32::from(team.leader_id() == player_id))
    }

    fn script_team_quest_targets(
        &self,
        player_id: i32,
        distance: i32,
        require_alive: bool,
    ) -> Option<Vec<(i32, bool)>> {
        let session_id = self.script_team_session_id(player_id)?;
        let members = self.session_factory.team_member_descriptors(session_id)?;
        let source_shape = (distance != 0)
            .then(|| self.find_player(player_id).and_then(CPlayer::shape_view))
            .flatten();
        Some(
            members
                .into_iter()
                .filter_map(|(owner_type, member_id, _)| {
                    if owner_type != 400 {
                        return None;
                    }
                    let Some(member) = self.find_player(member_id) else {
                        return (distance == 0).then_some((member_id, false));
                    };
                    if require_alive && member.is_dead() {
                        return None;
                    }
                    if distance != 0
                        && !source_shape
                            .zip(member.shape_view())
                            .is_some_and(|(source, target)| source.distance(target) <= distance)
                    {
                        return None;
                    }
                    Some((member_id, true))
                })
                .collect(),
        )
    }

    pub(crate) fn add_script_quest_for_team(
        &mut self,
        player_id: i32,
        quest_id: u16,
        distance: i32,
    ) {
        let Some(targets) = self.script_team_quest_targets(player_id, distance, false) else {
            return;
        };
        for (target_id, _) in targets {
            self.add_script_player_quest(target_id, quest_id);
        }
    }

    pub(crate) fn run_script_for_team(&mut self, player_id: i32, script: &[u8], distance: i32) {
        let Some(targets) = self.script_team_quest_targets(player_id, distance, true) else {
            return;
        };
        for (target_id, local) in targets {
            if local {
                let _ = self.queue_player_script(target_id, script);
            } else {
                let mut request = CMessage::new(0x0006_013d);
                request.add_long(target_id);
                request.base_mut().add(script);
                request.add_byte(0);
                let _ = request.send(self, false);
            }
        }
    }

    pub(crate) fn valid_script_quest_count(&self, player_id: i32) -> i32 {
        self.find_player(player_id).map_or(-1, |player| {
            player.valid_script_quest_count(|quest_id| {
                self.quest_system
                    .quest_data_by_id(quest_id)
                    .is_some_and(|quest| quest.display)
            })
        })
    }

    fn script_player_is_in_area(&self, player_id: i32, x: i32, y: i32, range: i32) -> bool {
        let Some(player) = self.find_player(player_id) else {
            return false;
        };
        let Some(region) = player
            .server_region_id()
            .and_then(|region_id| self.find_region(region_id))
        else {
            return false;
        };
        let (Ok(tile_x), Ok(tile_y)) = (player.shape().get_tile_x(), player.shape().get_tile_y())
        else {
            return false;
        };
        let range = i64::from(range);
        let offset_x = i64::from(x) - range;
        let offset_y = i64::from(y) - range;
        let center_x = if offset_x < 0 {
            0
        } else if offset_x > i64::from(region.base().region.width) {
            i64::from(region.base().region.width)
        } else {
            i64::from(x)
        };
        let center_y = if offset_y < 0 {
            0
        } else if offset_y > i64::from(region.base().region.height) {
            i64::from(region.base().region.height)
        } else {
            i64::from(y)
        };
        let tile_x = i64::from(tile_x);
        let tile_y = i64::from(tile_y);
        tile_x >= center_x - range
            && tile_x <= center_x + range
            && tile_y >= center_y - range
            && tile_y <= center_y + range
    }

    pub(crate) fn script_are_teammates_around(
        &self,
        player_id: i32,
        check_type: i32,
        radius: i32,
    ) -> bool {
        if !(0..=2).contains(&check_type) {
            return false;
        }
        let Some(session_id) = self.script_team_session_id(player_id) else {
            return false;
        };
        let Some(members) = self.session_factory.team_member_descriptors(session_id) else {
            return false;
        };
        let local_count = members
            .iter()
            .filter(|(owner_type, owner_id, _)| {
                *owner_type == 400 && self.find_player(*owner_id).is_some()
            })
            .count();
        if local_count != members.len() {
            return false;
        }
        if check_type == 2 {
            return true;
        }
        let Some(source) = self.find_player(player_id) else {
            return false;
        };
        let Some(source_region_id) = source.server_region_id() else {
            return false;
        };
        let (Ok(source_x), Ok(source_y)) =
            (source.shape().get_tile_x(), source.shape().get_tile_y())
        else {
            return false;
        };
        members.into_iter().all(|(owner_type, teammate_id, _)| {
            if owner_type != 400 {
                return false;
            }
            if teammate_id == player_id {
                return true;
            }
            self.find_player(teammate_id)
                .is_some_and(|teammate| teammate.server_region_id() == Some(source_region_id))
                && (check_type != 0
                    || self.script_player_is_in_area(teammate_id, source_x, source_y, radius))
        })
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn script_set_region_for_team<
        Context: ScriptRegionChangeContext + RealmAppellationScriptContext,
    >(
        &mut self,
        player_id: i32,
        mut transfer_type: i32,
        region_id: i32,
        mut tile_x: i32,
        mut tile_y: i32,
        mut direction: i32,
        mut range: i32,
        context: &mut Context,
    ) -> i32 {
        if !(0..=3).contains(&transfer_type) {
            transfer_type = 0;
        }
        if tile_x == SCRIPT_SCALAR_ERROR
            || tile_y == SCRIPT_SCALAR_ERROR
            || tile_x == 0
            || tile_y == 0
        {
            tile_x = -1;
            tile_y = -1;
        }
        let Some(player) = self.find_player(player_id) else {
            return 0;
        };
        if direction == SCRIPT_SCALAR_ERROR {
            direction = player.shape().get_direction();
        }
        if range == SCRIPT_SCALAR_ERROR {
            range = 2;
        }
        let Some(session_id) = self.script_team_session_id(player_id) else {
            return 1;
        };
        let Some(members) = self.session_factory.team_member_descriptors(session_id) else {
            return 1;
        };
        let teammate_count = members.len();
        let local_player_ids = members
            .iter()
            .filter_map(|(owner_type, owner_id, _)| {
                (*owner_type == 400 && self.find_player(*owner_id).is_some()).then_some(*owner_id)
            })
            .collect::<Vec<_>>();
        if transfer_type <= 2 && local_player_ids.len() != teammate_count {
            return 2;
        }
        let source_region_id = player.server_region_id().unwrap_or_default();
        if transfer_type <= 1
            && members
                .iter()
                .filter(|(_, _, owner_region_id)| *owner_region_id == source_region_id)
                .count()
                != teammate_count
        {
            return 3;
        }
        if transfer_type == 0 {
            let Some(source_region) = self.find_region(source_region_id) else {
                return 4;
            };
            let (Ok(source_x), Ok(source_y)) =
                (player.shape().get_tile_x(), player.shape().get_tile_y())
            else {
                return 4;
            };
            let mut start_x = source_x - 3;
            let mut start_y = source_y - 3;
            if source_x + 3 >= source_region.base().region.width {
                start_x = source_region.base().region.width - 7;
            } else if source_x - 3 <= 0 {
                start_x = 0;
            }
            if source_y + 3 >= source_region.base().region.height {
                start_y = source_region.base().region.height - 7;
            } else if source_y - 3 <= 0 {
                start_y = 0;
            }
            let all_inside = local_player_ids.iter().all(|teammate_id| {
                self.find_player(*teammate_id).is_some_and(|teammate| {
                    let (Ok(x), Ok(y)) =
                        (teammate.shape().get_tile_x(), teammate.shape().get_tile_y())
                    else {
                        return false;
                    };
                    x >= start_x && x <= start_x + 7 && y >= start_y && y <= start_y + 7
                })
            });
            if !all_inside {
                return 4;
            }
        }
        if transfer_type != 3 {
            for teammate_id in local_player_ids {
                let _ = self.change_player_region(
                    teammate_id,
                    region_id,
                    tile_x,
                    tile_y,
                    direction,
                    0,
                    range,
                    0,
                    context,
                );
            }
        }
        0
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn script_set_team_region<
        Context: ScriptRegionChangeContext + RealmAppellationScriptContext,
    >(
        &mut self,
        player_id: i32,
        region_id: i32,
        mut tile_x: i32,
        mut tile_y: i32,
        mut radius: i32,
        mut direction: i32,
        mut range: i32,
        context: &mut Context,
    ) {
        if tile_x == SCRIPT_SCALAR_ERROR
            || tile_y == SCRIPT_SCALAR_ERROR
            || tile_x == 0
            || tile_y == 0
        {
            tile_x = -1;
            tile_y = -1;
        }
        let Some(player) = self.find_player(player_id) else {
            return;
        };
        if radius == SCRIPT_SCALAR_ERROR {
            radius = 3;
        }
        if direction == SCRIPT_SCALAR_ERROR {
            direction = player.shape().get_direction();
        }
        if range == SCRIPT_SCALAR_ERROR {
            range = 2;
        }
        let Some(session_id) = self.script_team_session_id(player_id) else {
            return;
        };
        let Some(members) = self.session_factory.team_member_descriptors(session_id) else {
            return;
        };
        let Some(source_region_id) = player.server_region_id() else {
            return;
        };
        let (Ok(source_x), Ok(source_y)) =
            (player.shape().get_tile_x(), player.shape().get_tile_y())
        else {
            return;
        };
        let selected = members
            .into_iter()
            .filter_map(|(owner_type, teammate_id, _)| {
                if owner_type != 400 || self.find_player(teammate_id).is_none() {
                    return None;
                }
                (teammate_id == player_id
                    || (self.find_player(teammate_id).is_some_and(|teammate| {
                        teammate.server_region_id() == Some(source_region_id)
                    }) && self.script_player_is_in_area(
                        teammate_id,
                        source_x,
                        source_y,
                        radius,
                    )))
                .then_some(teammate_id)
            })
            .collect::<Vec<_>>();
        for teammate_id in selected {
            let _ = self.change_player_region(
                teammate_id,
                region_id,
                tile_x,
                tile_y,
                direction,
                0,
                range,
                0,
                context,
            );
        }
    }

    fn run_team_snapshot_queries(
        &mut self,
        now_ms: u32,
    ) -> Vec<(u32, Result<i32, SendMessageError>)> {
        let completed = self
            .team_snapshot_queries
            .keys()
            .copied()
            .filter(|team_id| self.get_team_session_id(*team_id) != 0)
            .collect::<Vec<_>>();
        for team_id in completed {
            self.team_snapshot_queries.remove(&team_id);
        }
        let due = self
            .team_snapshot_queries
            .iter()
            .filter_map(|(team_id, query)| {
                (!query.requested || query.last_request_ms.wrapping_add(60_000) <= now_ms)
                    .then_some(*team_id)
            })
            .collect::<Vec<_>>();
        due.into_iter()
            .map(|team_id| {
                let mut message = CMessage::new(0x0006_0008);
                message.add_ulong(team_id);
                let delivery = message.send(self, false);
                let query = self
                    .team_snapshot_queries
                    .get_mut(&team_id)
                    .expect("due team snapshot query остаётся в canonical queue");
                query.last_request_ms = now_ms;
                query.requested = true;
                (team_id, delivery)
            })
            .collect()
    }

    pub(crate) fn check_team_join(&self, leader_id: i32, candidate_id: i32) -> GameTeamJoinResult {
        if leader_id == candidate_id {
            return GameTeamJoinResult::SamePlayer;
        }
        let Some(leader) = self.players.get(&leader_id) else {
            return GameTeamJoinResult::PlayerNotExist;
        };
        let Some(candidate) = self.players.get(&candidate_id) else {
            return GameTeamJoinResult::PlayerNotExist;
        };
        if leader.team_id() != 0 {
            let session_id = self.get_team_session_id(leader.team_id() as u32);
            let Some(team) = self.session_factory.query_team(session_id) else {
                return GameTeamJoinResult::NoPermission;
            };
            if team.leader_id() != leader_id {
                return GameTeamJoinResult::NoPermission;
            }
            if self
                .session_factory
                .query_session_plug_by_owner(session_id, 400, candidate_id)
                .is_some()
            {
                return GameTeamJoinResult::SamePlayer;
            }
            let Some(count) = self.session_factory.team_member_count(session_id) else {
                return GameTeamJoinResult::UnknownError;
            };
            if count > 7 {
                return GameTeamJoinResult::MaxMemberLimit;
            }
        }
        if candidate.team_id() != 0 {
            GameTeamJoinResult::PlayerAlreadyInTeam
        } else {
            GameTeamJoinResult::Succeed
        }
    }

    fn send_team_snapshot(&self, player_id: i32, snapshot: &[u8]) {
        let mut message = CMessage::new(0x000b_fd03);
        message.base_mut().add(snapshot);
        let delivery = message.send_to_player(self.net_server(), player_id);
        tracing::trace!(player_id, delivery, "снимок группы отправлен игроку");
    }

    fn publish_team_member_region(
        &self,
        team_id: u32,
        owner_type: i32,
        owner_id: i32,
        owner_region_id: i32,
        recipients: impl IntoIterator<Item = i32>,
    ) {
        let mut message = CMessage::new(0x000b_fd06);
        message.add_ulong(team_id);
        message.add_long(owner_type);
        message.add_long(owner_id);
        message.add_long(owner_region_id);
        for recipient in recipients {
            let delivery = message.send_to_player(self.net_server(), recipient);
            tracing::trace!(
                team_id,
                owner_type,
                owner_id,
                owner_region_id,
                recipient,
                delivery,
                "регион участника группы опубликован"
            );
        }
    }

    fn publish_team_member_joined(
        &self,
        team_id: u32,
        owner_type: i32,
        owner_id: i32,
        owner_region_id: i32,
        owner_name: &[u8],
        hp_ratio_bits: u32,
        recipients: impl IntoIterator<Item = i32>,
    ) {
        let mut message = CMessage::new(0x000b_fd04);
        message.add_ulong(team_id);
        message.add_long(owner_type);
        message.add_long(owner_id);
        message.add_long(owner_region_id);
        message.add_ulong(hp_ratio_bits);
        add_legacy_c_string(message.base_mut(), owner_name);
        for recipient in recipients {
            let delivery = message.send_to_player(self.net_server(), recipient);
            tracing::trace!(
                team_id,
                owner_type,
                owner_id,
                owner_region_id,
                recipient,
                delivery,
                "вступление участника группы опубликовано"
            );
        }
    }

    fn publish_world_team_member_joined(
        &self,
        team_id: u32,
        owner_type: i32,
        owner_id: i32,
        owner_region_id: i32,
        owner_name: &[u8],
    ) {
        let mut message = CMessage::new(0x0006_0003);
        message.add_ulong(team_id);
        message.add_long(owner_type);
        message.add_long(owner_id);
        message.add_long(owner_region_id);
        add_legacy_c_string(message.base_mut(), owner_name);
        let delivery = message.send(self, false);
        tracing::trace!(
            team_id,
            owner_type,
            owner_id,
            owner_region_id,
            ?delivery,
            "вступление участника группы отправлено WorldServer"
        );
    }

    fn player_team_hp_ratio_bits(&self, player_id: i32) -> u32 {
        let Some(player) = self.players.get(&player_id) else {
            return 1.0_f32.to_bits();
        };
        ((player.health() as f32) / (player.maximum_health() as f32)).to_bits()
    }

    fn publish_team_recruitment_count(&mut self, leader_id: i32, teammate_count: usize) {
        let Some(state) = self
            .players
            .get(&leader_id)
            .and_then(CPlayer::first_team_recruitment_state)
        else {
            return;
        };
        let mut message = CMessage::new(0x000b_fe05);
        message.add_long(leader_id);
        message.add_long(leader_id);
        message.add_long(state.state_id());
        message.add_ulong(state.additional_data(teammate_count));
        let delivery = self.send_player_shape_around(leader_id, None, &message);
        tracing::trace!(
            leader_id,
            teammate_count,
            ?delivery,
            "число участников набора опубликовано вокруг лидера"
        );
    }

    pub(crate) fn join_team_accepted(
        &mut self,
        leader_id: i32,
        candidate_id: i32,
        audit_join: bool,
    ) -> Option<()> {
        let leader_team_id = self.players.get(&leader_id)?.team_id();
        let leader_region_id = self
            .players
            .get(&leader_id)?
            .server_region_id()
            .unwrap_or_default();
        let leader_name = self.players.get(&leader_id)?.player_name().to_vec();
        let candidate_region_id = self
            .players
            .get(&candidate_id)?
            .server_region_id()
            .unwrap_or_default();
        let candidate_name = self.players.get(&candidate_id)?.player_name().to_vec();

        let (session_id, team_id, teammate_count) = if leader_team_id == 0 {
            let team_id = self.get_team_id(1);
            let created: TeamSessionCreated = self.session_factory.create_team_session(
                team_id,
                (leader_id, leader_region_id, &leader_name),
                (candidate_id, candidate_region_id, &candidate_name),
            )?;
            self.team_session_ids.insert(team_id, created.session_id);
            self.players
                .get_mut(&leader_id)?
                .set_team_membership(team_id as i32);
            self.players.get_mut(&leader_id)?.set_team_captain(true);
            self.players
                .get_mut(&candidate_id)?
                .set_team_membership(team_id as i32);
            self.players.get_mut(&candidate_id)?.set_team_captain(false);

            let mut started = CMessage::new(0x0006_0001);
            started.base_mut().add(&created.empty_snapshot);
            let started_delivery = started.send(self, false);
            tracing::trace!(
                team_id,
                ?started_delivery,
                "создание группы отправлено WorldServer"
            );

            self.send_team_snapshot(leader_id, &created.leader_snapshot);
            self.publish_world_team_member_joined(
                team_id,
                400,
                leader_id,
                leader_region_id,
                &leader_name,
            );

            self.publish_team_member_region(
                team_id,
                400,
                candidate_id,
                candidate_region_id,
                [leader_id],
            );
            self.send_team_snapshot(candidate_id, &created.candidate_snapshot);
            self.publish_team_member_joined(
                team_id,
                400,
                candidate_id,
                candidate_region_id,
                &candidate_name,
                self.player_team_hp_ratio_bits(candidate_id),
                [leader_id],
            );
            self.publish_world_team_member_joined(
                team_id,
                400,
                candidate_id,
                candidate_region_id,
                &candidate_name,
            );

            for player_id in &created.teammate_ids {
                let mut changed = CMessage::new(0x000b_fd07);
                changed.add_ulong(team_id);
                changed.add_long(leader_id);
                let delivery = changed.send_to_player(self.net_server(), *player_id);
                tracing::trace!(
                    team_id,
                    leader_id,
                    player_id,
                    delivery,
                    "смена лидера отправлена участнику группы"
                );
            }
            let mut leader_changed = CMessage::new(0x0006_0006);
            leader_changed.add_ulong(team_id);
            leader_changed.add_long(leader_id);
            let delivery = leader_changed.send(self, false);
            tracing::trace!(
                team_id,
                leader_id,
                ?delivery,
                "смена лидера отправлена WorldServer"
            );
            (created.session_id, team_id, created.teammate_ids.len())
        } else {
            let session_id = self.get_team_session_id(leader_team_id as u32);
            let inserted: TeamMemberInserted = self.session_factory.insert_team_member(
                session_id,
                candidate_id,
                candidate_region_id,
                &candidate_name,
            )?;
            self.players
                .get_mut(&candidate_id)?
                .set_team_membership(inserted.team_id as i32);
            self.players.get_mut(&candidate_id)?.set_team_captain(false);
            self.publish_team_member_region(
                inserted.team_id,
                400,
                candidate_id,
                candidate_region_id,
                inserted
                    .teammate_ids
                    .iter()
                    .copied()
                    .filter(|player_id| *player_id != candidate_id),
            );
            self.send_team_snapshot(candidate_id, &inserted.snapshot);
            self.publish_team_member_joined(
                inserted.team_id,
                400,
                candidate_id,
                candidate_region_id,
                &candidate_name,
                self.player_team_hp_ratio_bits(candidate_id),
                inserted
                    .teammate_ids
                    .iter()
                    .copied()
                    .filter(|player_id| *player_id != candidate_id),
            );
            self.publish_world_team_member_joined(
                inserted.team_id,
                400,
                candidate_id,
                candidate_region_id,
                &candidate_name,
            );
            (
                inserted.session_id,
                inserted.team_id,
                inserted.teammate_count,
            )
        };
        self.publish_team_recruitment_count(leader_id, teammate_count);

        if audit_join && self.log_system.team_join_log_enabled() {
            let leader = self.players.get(&leader_id)?;
            let mut audit = CMessage::new(0x0006_0209);
            audit.add_byte(0);
            audit.add_long(leader_id);
            audit.add_long(candidate_id);
            audit.add_long(leader.server_region_id().unwrap_or_default());
            audit.add_long(leader.shape().get_tile_x().unwrap_or_default());
            audit.add_long(leader.shape().get_tile_y().unwrap_or_default());
            let delivery = audit.send(self, false);
            tracing::trace!(
                leader_id,
                candidate_id,
                ?delivery,
                "аудит вступления в группу отправлен"
            );
        }

        tracing::trace!(
            leader_id,
            candidate_id,
            session_id,
            team_id,
            teammate_count,
            "участник добавлен в группу"
        );
        Some(())
    }

    fn publish_team_member_left(
        &self,
        team_id: u32,
        player_id: i32,
        recipients: impl IntoIterator<Item = i32>,
    ) {
        let mut left = CMessage::new(0x000b_fd05);
        left.add_ulong(team_id);
        left.add_long(400);
        left.add_long(player_id);
        for recipient in recipients {
            let delivery = left.send_to_player(self.net_server(), recipient);
            tracing::trace!(
                team_id,
                player_id,
                recipient,
                delivery,
                "выход участника группы опубликован"
            );
        }
    }

    fn remove_local_team_member(&mut self, session_id: i32, player_id: i32) -> Option<()> {
        let removed: TeamMemberRemoved = self
            .session_factory
            .remove_team_member(session_id, player_id)?;
        self.players.get_mut(&player_id)?.set_team_membership(0);
        let recipients =
            std::iter::once(player_id).chain(removed.remaining_player_ids.iter().copied());
        self.publish_team_member_left(removed.team_id, player_id, recipients);
        let mut changed = CMessage::new(0x0006_0004);
        changed.add_ulong(removed.team_id);
        changed.add_long(400);
        changed.add_long(player_id);
        let world_delivery = changed.send(self, false);
        self.publish_team_recruitment_count(removed.leader_id, removed.remaining_player_ids.len());
        tracing::trace!(
            player_id,
            session_id = removed.session_id,
            team_id = removed.team_id,
            ?world_delivery,
            "локальный участник удалён из группы"
        );
        Some(())
    }

    pub(crate) fn leave_team(&mut self, player_id: i32) -> Option<()> {
        let team_id = self.players.get(&player_id)?.team_id();
        if team_id == 0 {
            return None;
        }
        let session_id = self.get_team_session_id(team_id as u32);
        self.remove_local_team_member(session_id, player_id)
    }

    pub(crate) fn change_team_leader(&mut self, actor_id: i32, new_leader_id: i32) -> Option<()> {
        let team_id = self.players.get(&actor_id)?.team_id();
        let session_id = self.get_team_session_id(team_id as u32);
        if self.session_factory.query_team(session_id)?.leader_id() != actor_id {
            return None;
        }
        let previous = self
            .session_factory
            .set_team_leader(session_id, new_leader_id)?;
        if let Some(player) = self.players.get_mut(&previous) {
            player.set_team_captain(false);
        }
        if let Some(player) = self.players.get_mut(&new_leader_id) {
            player.set_team_captain(true);
        }
        let recipients: Vec<i32> = self
            .session_factory
            .query_session(session_id)?
            .plug_ids_storage()
            .iter()
            .filter_map(|id| {
                self.session_factory
                    .query_plug(*id)
                    .map(|plug| plug.owner_id())
            })
            .collect();
        let mut client = CMessage::new(0x000b_fd07);
        client.add_ulong(team_id as u32);
        client.add_long(new_leader_id);
        for recipient in recipients {
            let delivery = client.send_to_player(self.net_server(), recipient);
            tracing::trace!(
                team_id,
                new_leader_id,
                recipient,
                delivery,
                "смена лидера отправлена участнику группы"
            );
        }
        let mut world = CMessage::new(0x0006_0006);
        world.add_ulong(team_id as u32);
        world.add_long(new_leader_id);
        let world_delivery = world.send(self, false);
        tracing::trace!(
            session_id,
            team_id,
            previous_leader_id = previous,
            new_leader_id,
            ?world_delivery,
            "лидер группы изменён"
        );
        Some(())
    }

    pub(crate) fn kick_team_member(&mut self, actor_id: i32, kicked_id: i32) -> Option<()> {
        let team_id = self.players.get(&actor_id)?.team_id();
        let session_id = self.get_team_session_id(team_id as u32);
        if self.session_factory.query_team(session_id)?.leader_id() != actor_id {
            return None;
        }
        if self.players.contains_key(&kicked_id) {
            return self.remove_local_team_member(session_id, kicked_id);
        }
        self.session_factory
            .query_session_plug_by_owner(session_id, 400, kicked_id)?;
        let mut world = CMessage::new(0x0006_0007);
        world.add_ulong(team_id as u32);
        world.add_long(kicked_id);
        let world_delivery = world.send(self, false);
        tracing::trace!(
            session_id,
            team_id,
            kicked_id,
            ?world_delivery,
            "запрошено удалённое исключение участника группы"
        );
        Some(())
    }

    pub(crate) fn disband_team(&mut self, actor_id: i32) -> Option<()> {
        let team_id = self.players.get(&actor_id)?.team_id();
        let session_id = self.get_team_session_id(team_id as u32);
        if self.session_factory.query_team(session_id)?.leader_id() != actor_id {
            return None;
        }
        let disbanded: TeamSessionDisbanded = self.session_factory.disband_team(session_id)?;
        let mut ended = CMessage::new(0x0006_0002);
        ended.add_ulong(disbanded.team_id);
        let world_delivery = ended.send(self, false);
        for (index, player_id) in disbanded.player_ids.iter().enumerate() {
            if let Some(player) = self.players.get_mut(player_id) {
                player.set_team_membership(0);
            }
            let recipients = std::iter::once(*player_id)
                .chain(disbanded.player_ids[index + 1..].iter().copied())
                .filter(|recipient| self.players.contains_key(recipient));
            self.publish_team_member_left(disbanded.team_id, *player_id, recipients);
        }
        self.team_session_ids.remove(&disbanded.team_id);
        self.publish_team_recruitment_count(disbanded.leader_id, 1);
        tracing::trace!(actor_id, session_id = disbanded.session_id, team_id = disbanded.team_id, affected_player_ids = ?disbanded.player_ids, ?world_delivery, "группа распущена");
        Some(())
    }

    pub(crate) fn change_team_allocation_scheme(
        &mut self,
        actor_id: i32,
        allocation_scheme: i32,
    ) -> Option<()> {
        let team_id = self.players.get(&actor_id)?.team_id();
        if team_id == 0 {
            return None;
        }
        let session_id = self.get_team_session_id(team_id as u32);
        let (team_id, recipients) = self.session_factory.set_team_allocation_scheme(
            session_id,
            actor_id,
            allocation_scheme,
        )?;
        let mut client = CMessage::new(0x000b_fd08);
        client.add_ulong(team_id);
        client.add_long(allocation_scheme);
        for player_id in recipients {
            let delivery = client.send_to_player(self.net_server(), player_id);
            tracing::trace!(
                team_id,
                allocation_scheme,
                player_id,
                delivery,
                "схема распределения отправлена участнику группы"
            );
        }
        let mut world = CMessage::new(0x0006_000a);
        world.add_ulong(team_id);
        world.add_long(allocation_scheme);
        let world_delivery = world.send(self, false);
        tracing::trace!(
            actor_id,
            session_id,
            team_id,
            allocation_scheme,
            ?world_delivery,
            "схема распределения группы изменена"
        );
        Some(())
    }

    pub(crate) fn send_team_chat(
        &mut self,
        actor_id: i32,
        text: Vec<u8>,
        now_ms: u32,
    ) -> GameTeamChatResult {
        let Some(team_id) = self.players.get(&actor_id).map(CPlayer::team_id) else {
            return GameTeamChatResult::MissingContext;
        };
        if team_id == 0 {
            return GameTeamChatResult::MissingContext;
        }
        let interval_ms = self.globe_setup.team_talk_interval_ms();
        if !self
            .players
            .get_mut(&actor_id)
            .expect("team chat actor разрешён до cooldown mutation")
            .begin_talk(PlayerTalkChannel::Team, now_ms, interval_ms)
        {
            return GameTeamChatResult::Cooldown;
        }
        let session_id = self.get_team_session_id(team_id as u32);
        if self
            .session_factory
            .query_session_plug_by_owner(session_id, 400, actor_id)
            .is_none()
        {
            return GameTeamChatResult::MissingContext;
        }
        let Some(recipients) = self.session_factory.team_player_ids(session_id) else {
            return GameTeamChatResult::MissingContext;
        };
        let team_id = team_id as u32;
        let mut client = CMessage::new(0x000b_fd09);
        client.add_ulong(team_id);
        client.add_long(400);
        client.add_long(actor_id);
        add_legacy_c_string(client.base_mut(), &text);
        for player_id in recipients {
            let delivery = client.send_to_player(self.net_server(), player_id);
            tracing::trace!(
                team_id,
                actor_id,
                player_id,
                delivery,
                "сообщение группы отправлено участнику"
            );
        }
        let mut world = CMessage::new(0x0006_000b);
        world.add_ulong(team_id);
        world.add_long(400);
        world.add_long(actor_id);
        add_legacy_c_string(world.base_mut(), &text);
        let world_delivery = world.send(self, false);
        tracing::trace!(
            actor_id,
            session_id,
            team_id,
            text_len = text.len(),
            ?world_delivery,
            "сообщение группы отправлено"
        );
        GameTeamChatResult::Sent
    }

    pub(crate) fn abort_remote_team(&mut self, team_id: u32) -> Option<()> {
        let session_id = self.get_team_session_id(team_id);
        let disbanded = self.session_factory.disband_team(session_id)?;
        for (index, player_id) in disbanded.player_ids.iter().copied().enumerate() {
            if let Some(player) = self.players.get_mut(&player_id) {
                player.set_team_membership(0);
            }
            let recipients = std::iter::once(player_id)
                .chain(disbanded.player_ids[index + 1..].iter().copied())
                .filter(|recipient| self.players.contains_key(recipient));
            self.publish_team_member_left(team_id, player_id, recipients);
        }
        self.team_session_ids.remove(&team_id);
        self.team_snapshot_queries.remove(&team_id);
        tracing::trace!(session_id, team_id, affected_player_ids = ?disbanded.player_ids, "удалённая группа завершена");
        Some(())
    }

    pub(crate) fn insert_remote_team_member(
        &mut self,
        team_id: u32,
        owner_type: i32,
        owner_id: i32,
        mut owner_region_id: i32,
        mut owner_name: Vec<u8>,
    ) -> Option<()> {
        let session_id = self.get_team_session_id(team_id);
        let source_local = owner_type == 400 && self.players.contains_key(&owner_id);
        if source_local {
            let player = self
                .players
                .get(&owner_id)
                .expect("remote insert source-local player остаётся canonical");
            owner_region_id = player.server_region_id().unwrap_or_default();
            owner_name = player.player_name().to_vec();
        }
        let inserted = self.session_factory.insert_team_member_owned(
            session_id,
            owner_type,
            owner_id,
            owner_region_id,
            &owner_name,
        )?;
        let local_recipients = inserted
            .teammate_ids
            .iter()
            .copied()
            .filter(|player_id| self.players.contains_key(player_id))
            .collect::<Vec<_>>();
        if source_local {
            let player = self
                .players
                .get_mut(&owner_id)
                .expect("remote insert source-local player остаётся canonical");
            player.set_team_membership(team_id as i32);
            self.publish_team_member_region(
                team_id,
                owner_type,
                owner_id,
                owner_region_id,
                local_recipients
                    .iter()
                    .copied()
                    .filter(|recipient| *recipient != owner_id),
            );
            self.send_team_snapshot(owner_id, &inserted.snapshot);
        }
        self.publish_team_member_joined(
            team_id,
            owner_type,
            owner_id,
            owner_region_id,
            &owner_name,
            self.player_team_hp_ratio_bits(owner_id),
            local_recipients
                .iter()
                .copied()
                .filter(|recipient| *recipient != owner_id),
        );
        if source_local {
            self.publish_world_team_member_joined(
                team_id,
                owner_type,
                owner_id,
                owner_region_id,
                &owner_name,
            );
        }
        tracing::trace!(
            session_id,
            team_id,
            owner_type,
            owner_id,
            owner_region_id,
            source_local,
            "удалённый участник добавлен в группу"
        );
        Some(())
    }

    pub(crate) fn remove_remote_team_member(
        &mut self,
        team_id: u32,
        owner_type: i32,
        owner_id: i32,
    ) -> Option<()> {
        let session_id = self.get_team_session_id(team_id);
        self.session_factory
            .query_session_plug_by_owner(session_id, owner_type, owner_id)?;
        let removed = self
            .session_factory
            .remove_team_member(session_id, owner_id)?;
        let source_local = owner_type == 400 && self.players.contains_key(&owner_id);
        if source_local {
            self.players
                .get_mut(&owner_id)
                .expect("remote exit source-local player остаётся canonical")
                .set_team_membership(0);
        }
        let recipients = std::iter::once(owner_id).filter(|_| source_local).chain(
            removed
                .remaining_player_ids
                .iter()
                .copied()
                .filter(|player_id| self.players.contains_key(player_id)),
        );
        self.publish_team_member_left(team_id, owner_id, recipients);
        if source_local {
            let mut world = CMessage::new(0x0006_0004);
            world.add_ulong(team_id);
            world.add_long(owner_type);
            world.add_long(owner_id);
            let delivery = world.send(self, false);
            tracing::trace!(
                team_id,
                owner_type,
                owner_id,
                ?delivery,
                "удаление участника группы отправлено WorldServer"
            );
        }
        tracing::trace!(
            session_id,
            team_id,
            owner_type,
            owner_id,
            source_local,
            "удалённый участник исключён из группы"
        );
        Some(())
    }

    pub(crate) fn change_remote_team_region(
        &mut self,
        team_id: u32,
        owner_type: i32,
        owner_id: i32,
        owner_region_id: i32,
    ) -> Option<()> {
        let session_id = self.get_team_session_id(team_id);
        let recipients = self.session_factory.update_team_member_region(
            session_id,
            owner_type,
            owner_id,
            owner_region_id,
        )?;
        let recipients = recipients
            .into_iter()
            .filter(|player_id| *player_id != owner_id && self.players.contains_key(player_id));
        self.publish_team_member_region(team_id, owner_type, owner_id, owner_region_id, recipients);
        tracing::trace!(
            session_id,
            team_id,
            owner_type,
            owner_id,
            owner_region_id,
            "регион удалённого участника группы изменён"
        );
        Some(())
    }

    pub(crate) fn kick_remote_team_player(&mut self, team_id: u32, player_id: i32) -> Option<()> {
        if self.players.contains_key(&player_id) {
            return self.remove_remote_team_member(team_id, 400, player_id);
        }
        let session_id = self.get_team_session_id(team_id);
        self.session_factory
            .query_session_plug_by_owner(session_id, 400, player_id)?;
        let mut world = CMessage::new(0x0006_0007);
        world.add_ulong(team_id);
        world.add_long(player_id);
        let delivery = world.send(self, false);
        tracing::trace!(
            session_id,
            team_id,
            player_id,
            ?delivery,
            "удалённое исключение участника группы запрошено"
        );
        Some(())
    }

    pub(crate) fn change_remote_team_leader(&mut self, team_id: u32, player_id: i32) -> Option<()> {
        let session_id = self.get_team_session_id(team_id);
        let previous = self.session_factory.query_team(session_id)?.leader_id();
        if previous == player_id {
            return None;
        }
        self.session_factory
            .set_team_leader(session_id, player_id)?;
        if let Some(player) = self.players.get_mut(&previous) {
            player.set_team_captain(false);
        }
        if let Some(player) = self.players.get_mut(&player_id) {
            player.set_team_captain(true);
        }
        let recipients = self
            .session_factory
            .team_player_ids(session_id)?
            .into_iter()
            .filter(|id| self.players.contains_key(id));
        let mut client = CMessage::new(0x000b_fd07);
        client.add_ulong(team_id);
        client.add_long(player_id);
        for recipient in recipients {
            let delivery = client.send_to_player(self.net_server(), recipient);
            tracing::trace!(
                team_id,
                player_id,
                recipient,
                delivery,
                "новый лидер удалённой группы опубликован"
            );
        }
        if self.players.contains_key(&previous) {
            let mut world = CMessage::new(0x0006_0006);
            world.add_ulong(team_id);
            world.add_long(player_id);
            let delivery = world.send(self, false);
            tracing::trace!(
                team_id,
                player_id,
                ?delivery,
                "новый лидер группы отправлен WorldServer"
            );
        }
        tracing::trace!(
            session_id,
            team_id,
            previous_leader_id = previous,
            player_id,
            "лидер удалённой группы изменён"
        );
        Some(())
    }

    pub(crate) fn restore_remote_team(&mut self, mut snapshot: TeamSessionSnapshot) -> Option<()> {
        if self.get_team_session_id(snapshot.team_id) != 0 {
            return None;
        }
        for member in &mut snapshot.members {
            if member.owner_type == 400 {
                if let Some(player) = self.players.get(&member.owner_id) {
                    member.owner_region_id = player.server_region_id().unwrap_or_default();
                    member.owner_name = player.player_name().to_vec();
                }
            }
        }
        let members = snapshot.members.clone();
        let leader_id = snapshot.leader_id;
        let restored: TeamSessionRestored = self.session_factory.restore_team_session(snapshot)?;
        self.team_session_ids
            .insert(restored.team_id, restored.session_id);
        self.team_snapshot_queries.remove(&restored.team_id);
        let mut inserted_ids = Vec::new();
        for (index, member) in members.iter().enumerate() {
            inserted_ids.push(member.owner_id);
            let local_recipients = inserted_ids
                .iter()
                .copied()
                .filter(|player_id| self.players.contains_key(player_id))
                .collect::<Vec<_>>();
            let source_local =
                member.owner_type == 400 && self.players.contains_key(&member.owner_id);
            if source_local {
                let player = self
                    .players
                    .get_mut(&member.owner_id)
                    .expect("restored source-local player остаётся canonical");
                player.set_team_membership(restored.team_id as i32);
                player.set_team_captain(member.owner_id == leader_id);
                self.publish_team_member_region(
                    restored.team_id,
                    member.owner_type,
                    member.owner_id,
                    member.owner_region_id,
                    local_recipients
                        .iter()
                        .copied()
                        .filter(|recipient| *recipient != member.owner_id),
                );
                self.send_team_snapshot(member.owner_id, restored.insertion_snapshots.get(index)?);
            }
            self.publish_team_member_joined(
                restored.team_id,
                member.owner_type,
                member.owner_id,
                member.owner_region_id,
                &member.owner_name,
                self.player_team_hp_ratio_bits(member.owner_id),
                local_recipients
                    .iter()
                    .copied()
                    .filter(|recipient| *recipient != member.owner_id),
            );
            if source_local {
                self.publish_world_team_member_joined(
                    restored.team_id,
                    member.owner_type,
                    member.owner_id,
                    member.owner_region_id,
                    &member.owner_name,
                );
            }
        }
        tracing::trace!(session_id = restored.session_id, team_id = restored.team_id, affected_player_ids = ?restored.player_ids, "снимок удалённой группы восстановлен");
        Some(())
    }

    pub(crate) fn answer_remote_team_online_query(&self, first: i32, second: i32, player_id: i32) {
        let mut world = CMessage::new(0x0006_0009);
        world.add_long(first);
        world.add_long(second);
        world.add_long(player_id);
        world.add_long(i32::from(self.players.contains_key(&player_id)));
        let delivery = world.send(self, false);
        tracing::trace!(
            first,
            second,
            player_id,
            ?delivery,
            "ответ о присутствии участника группы отправлен"
        );
    }

    pub(crate) fn change_remote_team_allocation(
        &mut self,
        team_id: u32,
        allocation_scheme: i32,
    ) -> Option<()> {
        let session_id = self.get_team_session_id(team_id);
        let leader_id = self.session_factory.query_team(session_id)?.leader_id();
        let (team_id, recipients) = self.session_factory.set_team_allocation_scheme(
            session_id,
            leader_id,
            allocation_scheme,
        )?;
        let mut client = CMessage::new(0x000b_fd08);
        client.add_ulong(team_id);
        client.add_long(allocation_scheme);
        for recipient in recipients
            .into_iter()
            .filter(|id| self.players.contains_key(id))
        {
            let delivery = client.send_to_player(self.net_server(), recipient);
            tracing::trace!(
                team_id,
                allocation_scheme,
                recipient,
                delivery,
                "удалённая схема распределения отправлена участнику группы"
            );
        }
        if self.players.contains_key(&leader_id) {
            let mut world = CMessage::new(0x0006_000a);
            world.add_ulong(team_id);
            world.add_long(allocation_scheme);
            let delivery = world.send(self, false);
            tracing::trace!(
                team_id,
                allocation_scheme,
                ?delivery,
                "удалённая схема распределения отправлена WorldServer"
            );
        }
        tracing::trace!(
            session_id,
            team_id,
            leader_id,
            allocation_scheme,
            "удалённая схема распределения изменена"
        );
        Some(())
    }

    pub(crate) fn relay_remote_team_chat(
        &self,
        team_id: u32,
        owner_type: i32,
        owner_id: i32,
        text: &[u8],
    ) -> Option<()> {
        let session_id = self.get_team_session_id(team_id);
        self.session_factory
            .team_member(session_id, owner_type, owner_id)?;
        let recipients = self
            .session_factory
            .team_player_ids(session_id)?
            .into_iter()
            .filter(|id| self.players.contains_key(id));
        let mut client = CMessage::new(0x000b_fd09);
        client.add_ulong(team_id);
        client.add_long(owner_type);
        client.add_long(owner_id);
        add_legacy_c_string(client.base_mut(), text);
        for recipient in recipients {
            let delivery = client.send_to_player(self.net_server(), recipient);
            tracing::trace!(
                team_id,
                owner_type,
                owner_id,
                recipient,
                delivery,
                "удалённое сообщение группы передано участнику"
            );
        }
        if owner_type == 400 && self.players.contains_key(&owner_id) {
            let mut world = CMessage::new(0x0006_000b);
            world.add_ulong(team_id);
            world.add_long(owner_type);
            world.add_long(owner_id);
            add_legacy_c_string(world.base_mut(), text);
            let delivery = world.send(self, false);
            tracing::trace!(
                team_id,
                owner_type,
                owner_id,
                ?delivery,
                "удалённое сообщение группы отправлено WorldServer"
            );
        }
        tracing::trace!(
            session_id,
            team_id,
            owner_type,
            owner_id,
            text_len = text.len(),
            "удалённое сообщение группы передано"
        );
        Some(())
    }

    pub(crate) fn relay_remote_team_state(
        &self,
        team_id: u32,
        owner_type: i32,
        owner_id: i32,
        state: f32,
    ) -> Option<()> {
        let session_id = self.get_team_session_id(team_id);
        self.session_factory
            .team_member(session_id, owner_type, owner_id)?;
        let recipients = self
            .session_factory
            .team_player_ids(session_id)?
            .into_iter()
            .filter(|id| *id != owner_id && self.players.contains_key(id));
        let mut client = CMessage::new(0x000b_fd0a);
        client.add_ulong(team_id);
        client.add_long(owner_type);
        client.add_long(owner_id);
        client.add_ulong(state.to_bits());
        for recipient in recipients {
            let delivery = client.send_to_player(self.net_server(), recipient);
            tracing::trace!(
                team_id,
                owner_type,
                owner_id,
                recipient,
                delivery,
                "состояние участника группы передано локальному участнику"
            );
        }
        if owner_type == 400 && self.players.contains_key(&owner_id) {
            let mut world = CMessage::new(0x0006_000c);
            world.add_ulong(team_id);
            world.add_long(owner_type);
            world.add_long(owner_id);
            world.add_ulong(state.to_bits());
            let delivery = world.send(self, false);
            tracing::trace!(
                team_id,
                owner_type,
                owner_id,
                ?delivery,
                "состояние участника группы отправлено WorldServer"
            );
        }
        tracing::trace!(
            session_id,
            team_id,
            owner_type,
            owner_id,
            state_bits = state.to_bits(),
            "состояние участника группы передано"
        );
        Some(())
    }

    /// Exact reached `CPlayer::OnChangeStates`: полный player snapshot сначала
    /// уходит самому игроку, затем состояние `9` его типизированного team plug
    /// публикует долю HP локальным участникам команды и WorldServer. Вычисление
    /// сохраняет в том числе унаследованный NaN при нулевом максимальном HP.
    pub(crate) fn publish_player_states(&self, player_id: i32) -> Option<()> {
        let player = self.find_player(player_id)?;
        let health = player.health();
        let mana = player.mana();
        let rp = player.rp();
        let yp = player.yp();
        let team_id = player.team_id();
        let health_ratio = health as f32 / player.maximum_health() as f32;

        let mut client = CMessage::new(0x000b_fe02);
        client.add_long(400);
        client.add_long(player_id);
        client.add_ulong(health);
        client.add_ulong(mana);
        client.base_mut().add_short(rp as i16);
        client.base_mut().add_short(yp as i16);
        let player_delivery = client.send_to_player(self.net_server(), player_id);

        let team = (team_id != 0)
            .then(|| self.relay_remote_team_state(team_id as u32, 400, player_id, health_ratio))
            .flatten();
        tracing::trace!(
            player_id,
            health,
            mana,
            rp,
            yp,
            health_ratio_bits = health_ratio.to_bits(),
            player_delivery,
            ?team,
            "состояние игрока опубликовано"
        );
        Some(())
    }

