    pub(crate) fn increase_player_money<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        amount: u32,
        context: &mut Context,
    ) -> Option<()> {
        let created = self.create_goods_batch(self.goods_factory.get_gold_coin_index(), amount);
        let outcome = {
            let (players, goods_factory) = (&mut self.players, &self.goods_factory);
            players
                .get_mut(&player_id)?
                .increase_money(amount, goods_factory, created)
        };
        self.send_player_money_increase(player_id, &outcome, context);
        tracing::trace!(player_id, amount, ?outcome, "деньги игрока увеличены");
        Some(())
    }

    pub(crate) fn add_region_tax(&mut self, region_id: i32, amount: u32) {
        let mut pending = vec![(region_id, amount)];
        let mut visited = BTreeSet::new();
        let mut updates = Vec::new();
        while let Some((current_id, current_amount)) = pending.pop() {
            if !visited.insert(current_id) {
                let mut transfer = CMessage::new(0x0006_012e);
                transfer.add_long(current_id);
                transfer.add_ulong(current_amount);
                let delivery = transfer.send(self, false);
                tracing::trace!(
                    region_id = current_id,
                    amount = current_amount,
                    ?delivery,
                    "налог передан внешнему владельцу после обнаружения цикла"
                );
                continue;
            }
            let Some(stage) = self
                .find_region_mut(current_id)
                .map(|region| region.base_mut().add_tax_money(current_amount))
            else {
                let mut transfer = CMessage::new(0x0006_012e);
                transfer.add_long(current_id);
                transfer.add_ulong(current_amount);
                let delivery = transfer.send(self, false);
                tracing::trace!(
                    region_id = current_id,
                    amount = current_amount,
                    ?delivery,
                    "налог передан внешнему владельцу региона"
                );
                continue;
            };
            updates.push(stage);
            if let Some(parent_id) = stage
                .superior_region_id
                .filter(|_| stage.superior_share != 0)
            {
                if self.find_region(parent_id).is_some() && !visited.contains(&parent_id) {
                    pending.push((parent_id, stage.superior_share));
                } else {
                    let mut transfer = CMessage::new(0x0006_012e);
                    transfer.add_long(parent_id);
                    transfer.add_ulong(stage.superior_share);
                    let delivery = transfer.send(self, false);
                    tracing::trace!(
                        region_id = parent_id,
                        amount = stage.superior_share,
                        ?delivery,
                        "доля налога передана внешнему владельцу региона"
                    );
                }
            }
        }
        for stage in updates.into_iter().rev() {
            let mut update = CMessage::new(0x0006_012d);
            update.add_long(stage.region_id);
            update.add_ulong(stage.today_total_tax);
            update.add_ulong(stage.total_tax);
            update.add_long(stage.current_tax_rate);
            let delivery = update.send(self, false);
            tracing::trace!(
                region_id = stage.region_id,
                today_total_tax = stage.today_total_tax,
                total_tax = stage.total_tax,
                current_tax_rate = stage.current_tax_rate,
                ?delivery,
                "изменение налога региона отправлено WorldServer"
            );
        }
    }

    pub(crate) fn request_script_region_tax_operation(
        &self,
        player_id: i32,
        region_id: i32,
        kind: RegionTaxSessionKind,
    ) -> Option<Result<i32, SendMessageError>> {
        let player = self.find_player(player_id)?;
        if player.server_region_id() != Some(region_id) {
            return None;
        }
        let region = self.find_region(region_id)?.base();
        let owned_faction_id = region.owned_faction_id();
        if owned_faction_id == 0 || player.faction_id() != owned_faction_id {
            return None;
        }
        let mut request = CMessage::new(match kind {
            RegionTaxSessionKind::ObtainPayment => 0x0006_012b,
            RegionTaxSessionKind::AdjustRate => 0x0006_012c,
        });
        request.add_long(player_id);
        request.add_long(region_id);
        Some(request.send(self, false))
    }

    pub(crate) fn start_region_tax_session(
        &mut self,
        player_id: i32,
        region_id: i32,
        kind: RegionTaxSessionKind,
        mut random_below: impl FnMut(i32) -> i32,
    ) -> Option<i64> {
        let player = self.find_player(player_id)?;
        if player.server_region_id() != Some(region_id) {
            return None;
        }
        let region = self.find_region(region_id)?.base();
        let owned_faction_id = region.owned_faction_id();
        if owned_faction_id != 0 && player.faction_id() != owned_faction_id {
            return None;
        }
        let begin = RegionTaxSessionBegin {
            player_id,
            total_tax: region.total_tax_payment(),
            player_money: player.money(),
            current_tax_rate: region.tax_rate(),
            max_tax_rate: region.max_tax_rate(),
        };
        let created = self
            .net_session_manager
            .create_session(player_id, 0, &mut random_below)
            .ok()?;
        let endpoint = Box::new(RegionTaxSessionEndpoint::new(
            kind,
            player_id,
            region_id,
            begin,
            Arc::clone(&self.effect_journal),
        ));
        if self
            .net_session_manager
            .set_callback_handle(created.id, endpoint)
            .is_err()
        {
            return None;
        }
        if self.net_session_manager.beging(created.id, 2_000).is_err() {
            return None;
        }
        self.apply_region_tax_session_effects_no_result();
        Some(created.id)
    }

    pub(crate) fn submit_region_tax_session_result<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        session_id: i64,
        password: i32,
        value: i32,
        context: &mut Context,
    ) -> NetSessionCallbackOutcome {
        let outcome = self
            .net_session_manager
            .on_sync_callback_result(session_id, player_id, password, value);
        self.apply_region_tax_session_effects(context);
        outcome
    }

    pub(crate) fn apply_proxy_region_tax_snapshot(
        &mut self,
        region_id: i32,
        today_total_tax: u32,
        total_tax: u32,
        current_tax_rate: i32,
    ) -> bool {
        let Some(region) = self.find_proxy_region_mut(region_id) else {
            return false;
        };
        region.set_tax_snapshot(today_total_tax, total_tax, current_tax_rate);
        true
    }

    pub(crate) fn script_region_tax_value(&self, region_id: i32, today: bool) -> Option<u32> {
        self.find_region(region_id).map(|region| {
            if today {
                region.base().today_tax_payment()
            } else {
                region.base().total_tax_payment()
            }
        })
    }

    pub(crate) fn set_script_region_tax_value(
        &mut self,
        region_id: i32,
        today: bool,
        value: u32,
    ) -> bool {
        let Some(region) = self.find_region_mut(region_id) else {
            return false;
        };
        if today {
            region.base_mut().set_today_tax_payment(value);
        } else {
            region.base_mut().set_total_tax_payment(value);
        }
        true
    }

    fn apply_region_tax_session_effects_no_result(&self) {
        let mut deferred = Vec::new();
        for effect in self.effect_journal.take_all() {
            let GameEffect::RegionTaxPrompt {
                kind,
                player_id,
                session_id,
                password,
                first_value,
                second_value,
            } = effect
            else {
                deferred.push(effect);
                continue;
            };
            self.send_region_tax_prompt(
                kind,
                player_id,
                session_id,
                password,
                first_value,
                second_value,
            );
        }
        self.effect_journal.extend(deferred);
    }

    fn send_region_tax_prompt(
        &self,
        kind: RegionTaxSessionKind,
        player_id: i32,
        session_id: i64,
        password: i32,
        first_value: u32,
        second_value: Option<u32>,
    ) {
        let mut prompt = CMessage::new(match kind {
            RegionTaxSessionKind::ObtainPayment => 0x000b_ff24,
            RegionTaxSessionKind::AdjustRate => 0x000b_ff25,
        });
        prompt.base_mut().add_long64(session_id);
        prompt.add_long(password);
        prompt.add_ulong(first_value);
        if let Some(second_value) = second_value {
            prompt.add_ulong(second_value);
        }
        let _ = prompt.send_to_player(self.net_server(), player_id);
    }

    fn apply_region_tax_session_effects<Context: OldClientGoodsCodec>(
        &mut self,
        context: &mut Context,
    ) {
        let effects = self.effect_journal.take_all();
        for effect in effects {
            match effect {
                GameEffect::RegionTaxPrompt {
                    kind,
                    player_id,
                    session_id,
                    password,
                    first_value,
                    second_value,
                } => self.send_region_tax_prompt(
                    kind,
                    player_id,
                    session_id,
                    password,
                    first_value,
                    second_value,
                ),
                GameEffect::RegionTaxResult {
                    kind: RegionTaxSessionKind::ObtainPayment,
                    player_id,
                    region_id,
                    value,
                } => self.apply_region_tax_payment(player_id, region_id, value, context),
                GameEffect::RegionTaxResult {
                    kind: RegionTaxSessionKind::AdjustRate,
                    player_id,
                    region_id,
                    value,
                } => self.apply_region_tax_rate(player_id, region_id, value),
                GameEffect::SkillNotification { .. }
                | GameEffect::ClearPlayerEmotion { .. }
                | GameEffect::SkillSocketReject { .. }
                | GameEffect::QueuePlayerSkill { .. }
                | GameEffect::QueueBattleFairySkill { .. }
                | GameEffect::BattleFairyCombine(_)
                | GameEffect::BattleFairySummon(_)
                | GameEffect::BattleFairyFollow(_)
                | GameEffect::PlayerEquipmentRemove(_)
                | GameEffect::PlayerEquipmentAdd(_)
                | GameEffect::BattleFairyEquipmentMutation(_)
                | GameEffect::BattleFairyPotentialAllocation(_)
                | GameEffect::BattleFairyUpgrade(_)
                | GameEffect::BattleFairyPotentialReset(_)
                | GameEffect::BattleFairySkillReset(_)
                | GameEffect::FairyGrowLog(_) => {
                    warn!("Неналоговый эффект попал в разделяемый налоговый журнал");
                }
            }
        }
    }

    fn apply_region_tax_payment<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        region_id: i32,
        value: i32,
        context: &mut Context,
    ) {
        let amount = value as u32;
        let Some((total_tax, region_name)) = self.find_region(region_id).map(|region| {
            (
                region.base().total_tax_payment(),
                region.base().name.as_bytes().to_vec(),
            )
        }) else {
            return;
        };
        if amount == 0 || amount > total_tax {
            return;
        }
        let Some((money, faction_name, player_name)) =
            self.find_player(player_id).and_then(|player| {
                (player.server_region_id() == Some(region_id)).then(|| {
                    (
                        player.money(),
                        player.faction_name().to_vec(),
                        player.player_name().to_vec(),
                    )
                })
            })
        else {
            return;
        };
        let resulting_money = money.wrapping_add(amount);
        if resulting_money >= 999_999_999 {
            return;
        }
        let Some(()) = self.increase_player_money(player_id, amount, context) else {
            return;
        };
        if self.find_player(player_id).map(CPlayer::money) != Some(resulting_money) {
            return;
        }
        let Some(region) = self.find_region_mut(region_id) else {
            return;
        };
        region
            .base_mut()
            .set_total_tax_payment(total_tax.wrapping_sub(amount));
        self.send_region_tax_snapshot(region_id);

        let amount_text = amount.to_string().into_bytes();
        let text = format_legacy_text_fields(
            self.get_string_by_id(b"GS0237"),
            &[&faction_name, &player_name, &region_name, &amount_text],
            0xff,
        );
        put_string_to_file("war", &text);
        let mut world_log = CMessage::new(0x0005_fd06);
        world_log.add_long(0);
        world_log.add_long(0);
        world_log.add_long(-1);
        world_log.add_ulong(0xff00_6ee1);
        world_log.base_mut().add(&text);
        world_log.add_byte(0);
        let _ = world_log.send(self, false);
    }

    fn apply_region_tax_rate(&mut self, player_id: i32, region_id: i32, value: i32) {
        let Some((max_tax_rate, region_name)) = self.find_region(region_id).map(|region| {
            (
                region.base().max_tax_rate(),
                region.base().name.as_bytes().to_vec(),
            )
        }) else {
            return;
        };
        if value < 0 || value > max_tax_rate {
            return;
        }
        let changed = self
            .find_region(region_id)
            .is_some_and(|region| region.base().tax_rate() != value);
        if changed {
            if let Some(region) = self.find_region_mut(region_id) {
                region.base_mut().set_tax_rate(value);
            }
            let mut update = CMessage::new(0x000b_ff26);
            update.add_long(region_id);
            update.add_long(value);
            if let Some(region) = self.find_region(region_id) {
                let _ = update.send_to_region(Some(region.base()), None, self);
            }
            self.send_region_tax_snapshot(region_id);
        }

        let value_text = value.to_string().into_bytes();
        let notice = format_legacy_text_fields(
            self.get_string_by_id(b"GS0234"),
            &[&region_name, &value_text],
            0xff,
        );
        let message = colored_player_notice_message(0xffda_edfe, 0, &notice);
        if let Some(region) = self.find_region(region_id) {
            let _ = message.send_to_region(Some(region.base()), None, self);
        }

        let Some((faction_name, player_name)) = self.find_player(player_id).and_then(|player| {
            (player.server_region_id() == Some(region_id)).then(|| {
                (
                    player.faction_name().to_vec(),
                    player.player_name().to_vec(),
                )
            })
        }) else {
            return;
        };
        let text = format_legacy_text_fields(
            self.get_string_by_id(b"GS0235"),
            &[&faction_name, &player_name, &region_name, &value_text],
            0xff,
        );
        put_string_to_file("war", &text);
    }

    fn send_region_tax_snapshot(&self, region_id: i32) {
        let Some(region) = self.find_region(region_id) else {
            return;
        };
        let region = region.base();
        let mut update = CMessage::new(0x0006_012d);
        update.add_long(region_id);
        update.add_ulong(region.today_tax_payment());
        update.add_ulong(region.total_tax_payment());
        update.add_long(region.tax_rate());
        let _ = update.send(self, false);
    }

    pub(crate) fn add_goods_to_player_packet(
        &mut self,
        player_id: i32,
        goods: Vec<CGoods>,
        encode_old_client: &mut dyn FnMut(&CGoods) -> Vec<u8>,
    ) -> Option<(Vec<CiQingPacketAddition>, Vec<CGoods>)> {
        let (players, goods_factory) = (&mut self.players, &self.goods_factory);
        players
            .get_mut(&player_id)
            .map(|player| player.add_goods_to_packet(goods, goods_factory, encode_old_client))
    }

    /// Точный `CGame::KickPlayer`: команда отключения ставится в очередь,
    /// исходное возвращаемое логическое значение всегда равно `false`.
    pub(crate) fn kick_player(&self, player_id: i32) {
        let command_result = self.net_server().command_handle().quit_by_map_id(player_id);
        tracing::trace!(
            player_id,
            command_result,
            legacy_return = false,
            "поставлено отключение игрока"
        );
    }

    /// Exact `OnGMMessage 0x7FC09` recipient pass: requester остаётся,
    /// остальные canonical player ID закрываются в signed map-order.
    pub(crate) fn kick_players_except(&self, preserved_player_id: i32) -> usize {
        let mut kicked = 0usize;
        for player_id in self
            .players
            .keys()
            .copied()
            .filter(|player_id| *player_id != preserved_player_id)
        {
            self.kick_player(player_id);
            kicked = kicked.wrapping_add(1);
        }
        kicked
    }

    /// Exact `OnOtherMessage 0x7FA0C`: snapshot signed player-map order и
    /// отдельный `KickPlayer` network command для каждого текущего owner-а.
    pub(crate) fn kick_all_players(&self) -> usize {
        let kicked = self.players.len();
        for player_id in self.players.keys().copied() {
            self.kick_player(player_id);
        }
        kicked
    }

    /// Exact `OnGMMessage 0x7FC0A`: region последовательно обходит все area,
    /// а найденные `CPlayer` передаются в `KickPlayer` в исходном порядке.
    pub(crate) fn kick_players_in_region_except(
        &self,
        region_id: i32,
        preserved_player_id: i32,
    ) -> usize {
        let Some(region) = self.regions.get(&region_id) else {
            return 0;
        };
        let mut player_ids = Vec::new();
        region.base().find_all_player_ids(&mut player_ids);
        let mut kicked = 0usize;
        for player_id in player_ids
            .into_iter()
            .filter(|player_id| *player_id != preserved_player_id)
        {
            self.kick_player(player_id);
            kicked = kicked.wrapping_add(1);
        }
        kicked
    }

    /// Exact `OnGMMessage 0x7FC07` до network response: X-major 7×7 scan
    /// использует region `GetShape`, а `Vec::dedup` повторяет именно
    /// consecutive-only семантику исходного `std::list::unique`.
    pub(crate) fn kick_players_around_name(&self, name: &[u8]) -> GameKickAroundOutcome {
        let Some(player) = self.find_player_by_name(name) else {
            return GameKickAroundOutcome::TargetMissing;
        };
        let target_player_id = player.player_id();
        let Some(server_region_id) = player.server_region_id() else {
            tracing::debug!(
                target_player_id,
                "массовое отключение вокруг заблокировано: регион игрока отсутствует"
            );
            return GameKickAroundOutcome::Blocked;
        };
        let tile_x = match player.shape().get_tile_x() {
            Ok(tile_x) => tile_x,
            Err(block) => {
                tracing::debug!(
                    target_player_id,
                    server_region_id,
                    ?block,
                    "массовое отключение вокруг заблокировано координатой X"
                );
                return GameKickAroundOutcome::Blocked;
            }
        };
        let tile_y = match player.shape().get_tile_y() {
            Ok(tile_y) => tile_y,
            Err(block) => {
                tracing::debug!(
                    target_player_id,
                    server_region_id,
                    ?block,
                    "массовое отключение вокруг заблокировано координатой Y"
                );
                return GameKickAroundOutcome::Blocked;
            }
        };
        let Some(region) = self.regions.get(&server_region_id) else {
            tracing::debug!(
                target_player_id,
                server_region_id,
                "массовое отключение вокруг заблокировано: владелец региона отсутствует"
            );
            return GameKickAroundOutcome::Blocked;
        };
        let region = region.base();
        if let Some(identity) = region
            .registered_shape_identities()
            .into_iter()
            .find(|identity| self.resolve_shape(*identity).is_none())
        {
            tracing::warn!(
                target_player_id,
                server_region_id,
                ?identity,
                "массовое отключение вокруг заблокировано неразрешённой формой"
            );
            return GameKickAroundOutcome::Blocked;
        }
        let window_x = gm_kick_window_origin(tile_x, region.region.width);
        let window_y = gm_kick_window_origin(tile_y, region.region.height);
        let (area_width, area_height) = self.area_dimensions();
        let mut matched_player_ids = Vec::new();
        let window_end_x = window_x.wrapping_add(7);
        let window_end_y = window_y.wrapping_add(7);
        let mut scan_x = window_x;
        while scan_x < window_end_x {
            let mut scan_y = window_y;
            while scan_y < window_end_y {
                let shape = match region.get_shape(scan_x, scan_y, area_width, area_height, self) {
                    Ok(shape) => shape,
                    Err(block) => {
                        tracing::debug!(
                            target_player_id,
                            server_region_id,
                            window_x,
                            window_y,
                            ?block,
                            matched_players = matched_player_ids.len(),
                            "массовое отключение вокруг заблокировано пространственным поиском"
                        );
                        return GameKickAroundOutcome::Blocked;
                    }
                };
                if let Some(shape) = shape.filter(|shape| shape.identity.object_type == PLAYER_TYPE)
                {
                    matched_player_ids.push(shape.identity.id);
                }
                scan_y = scan_y.wrapping_add(1);
            }
            scan_x = scan_x.wrapping_add(1);
        }
        matched_player_ids.dedup();
        let matched_players = matched_player_ids.len();
        for player_id in matched_player_ids {
            self.kick_player(player_id);
        }
        GameKickAroundOutcome::Completed { matched_players }
    }

    /// Exact X-major 7×7 `SetPlayerRegionEx` target snapshot. Как исходный
    /// `GetShape`, каждая клетка даёт не более одного player; consecutive
    /// повторы снимаются до последующих `ChangeRegion` side effects.
    pub(crate) fn script_players_around_name(&self, name: &[u8]) -> Vec<i32> {
        let Some(player) = self.find_player_by_name(name) else {
            return Vec::new();
        };
        let (Some(region_id), Ok(tile_x), Ok(tile_y)) = (
            player.server_region_id(),
            player.shape().get_tile_x(),
            player.shape().get_tile_y(),
        ) else {
            return Vec::new();
        };
        let Some(region) = self.regions.get(&region_id).map(ServerRegionOwner::base) else {
            return Vec::new();
        };
        let window_x = gm_kick_window_origin(tile_x, region.region.width);
        let window_y = gm_kick_window_origin(tile_y, region.region.height);
        let (area_width, area_height) = self.area_dimensions();
        let mut player_ids = Vec::new();
        let mut scan_x = window_x;
        while scan_x < window_x.wrapping_add(7) {
            let mut scan_y = window_y;
            while scan_y < window_y.wrapping_add(7) {
                let Ok(shape) = region.get_shape(scan_x, scan_y, area_width, area_height, self)
                else {
                    return Vec::new();
                };
                if let Some(shape) = shape.filter(|shape| shape.identity.object_type == PLAYER_TYPE)
                {
                    player_ids.push(shape.identity.id);
                }
                scan_y = scan_y.wrapping_add(1);
            }
            scan_x = scan_x.wrapping_add(1);
        }
        player_ids.dedup();
        player_ids
    }

    /// Exact name lookup + `KickPlayer` side effect для GM `0x7FC06`.
    pub(crate) fn kick_player_by_name(&self, name: &[u8]) -> bool {
        let Some(player_id) = self.find_player_by_name(name).map(CPlayer::player_id) else {
            return false;
        };
        self.kick_player(player_id);
        true
    }

    fn send_shape_exit_around(&self, region: &CServerRegion, shape: &CShape) -> Option<i32> {
        let runtime = GameServerAroundRuntime::new(
            self,
            &self.session_factory,
            self.globe_setup.area_width(),
            self.globe_setup.area_height(),
        )?;
        let identity = shape.identity();
        let mut message = CMessage::new(0x000b_f504);
        message.add_long(identity.object_type);
        message.add_long(identity.id);
        message.add_long(0);
        message
            .send_to_around(Some(region), shape, None, &runtime)
            .ok()
    }

    /// Exact script `3303 / DeleteNpc`: current player region lookup,
    /// `0xBF504(type,id,0)` around publication и только затем spatial removal.
    pub(crate) fn delete_script_npc(&mut self, player_id: i32, npc_id: i32) -> Option<i32> {
        let region_id = self.find_player(player_id)?.server_region_id()?;
        let mut owner = self.take_region_owner(region_id)?;
        let result = (|| {
            let npc = owner.base().find_npc_by_id(npc_id)?;
            let delivery = self.send_shape_exit_around(owner.base(), npc.move_shape().shape())?;
            let removed = owner
                .base_mut()
                .remove_owned_npc_by_id(npc_id)
                .ok()?;
            if removed
                && let ServerRegionOwner::GodsBattle(region) = &mut owner
            {
                Self::finish_gods_battle_npc_leave(region, npc_id);
            }
            removed.then_some(delivery)
        })();
        self.restore_region_owner(owner);
        result
    }

    fn send_script_monster_kill_phrase(&self, region_id: i32, monster_id: i32) {
        const PHRASE: &[u8] = b"\xbf\xbf\xa1\xa3\xa1\xa3\xcb\xa3\xce\xde\xc1\xc4\xb9\xfe\xa1\xa3";
        let Some(region) = self.find_region(region_id).map(ServerRegionOwner::base) else {
            return;
        };
        let Some(monster) = region.find_monster_by_id(monster_id) else {
            return;
        };
        let shape = monster.move_shape().shape();
        let (Ok(tile_x), Ok(tile_y)) = (shape.get_tile_x(), shape.get_tile_y()) else {
            return;
        };
        let area_width = self.globe_setup.area_width();
        let area_height = self.globe_setup.area_height();
        if area_width <= 0 || area_height <= 0 {
            return;
        }
        let mut player_ids = Vec::new();
        for offset_x in -1..=1 {
            for offset_y in -1..=1 {
                region.find_player_ids_in_area(
                    tile_x / area_width + offset_x,
                    tile_y / area_height + offset_y,
                    &mut player_ids,
                );
            }
        }
        let mut message = CMessage::new(0x000b_f801);
        message.add_long(0);
        message.add_long(MONSTER_TYPE);
        message.add_long(monster_id);
        message.base_mut().add(monster.display_name());
        message.add_byte(0);
        message.base_mut().add(PHRASE);
        message.add_byte(0);
        for player_id in player_ids {
            let Some(player) = self.find_player(player_id) else {
                continue;
            };
            let (Ok(player_x), Ok(player_y)) =
                (player.shape().get_tile_x(), player.shape().get_tile_y())
            else {
                continue;
            };
            if i64::from(player_x).abs_diff(i64::from(tile_x)) < area_width as u64
                && i64::from(player_y).abs_diff(i64::from(tile_y)) < area_height as u64
            {
                let _ = message.send_to_player(self.net_server(), player_id);
            }
        }
    }

    pub(crate) fn kill_script_monster<Runtime: MonsterDeathContext>(
        &mut self,
        player_id: i32,
        monster_id: i32,
        runtime: &mut Runtime,
    ) -> bool {
        let Some(region_id) = self
            .find_player(player_id)
            .and_then(CPlayer::server_region_id)
        else {
            return false;
        };
        let snapshot = self.find_region(region_id).and_then(|owner| {
            let monster = owner.base().find_monster_by_id(monster_id)?;
            let property = self
                .find_monster_property_by_origin_name(monster.base_property_key()?)?
                .clone();
            let shape = monster.move_shape().shape();
            let carriage = monster.is_carriage(&property);
            Some((
                property,
                monster.hit_points(),
                monster.is_tamed(),
                carriage,
                monster.move_shape().is_god(),
                monster.master_info(),
                shape.get_tile_x().ok()?,
                shape.get_tile_y().ok()?,
                shape.get_pos_x() as u32,
                shape.get_pos_y() as u32,
            ))
        });
        let Some((property, health, tamed, carriage, god, master, tile_x, tile_y, pos_x, pos_y)) =
            snapshot
        else {
            return false;
        };
        self.send_script_monster_kill_phrase(region_id, monster_id);
        if health == 0 || god {
            return false;
        }
        let damage = health.min(i32::MAX as u32);
        let current_health = health.wrapping_sub(damage);
        let now_ms = runtime.now_milliseconds();
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return false;
        };
        if let Some(monster) = owner.base_mut().find_monster_by_id_mut(monster_id) {
            let _ = monster.register_attacking_player(
                player_id,
                now_ms,
                self.globe_setup.attack_monster_protection_ms(),
            );
            monster.set_hit_points(current_health);
            monster
                .move_shape_mut()
                .shape_mut()
                .set_action(if current_health == 0 { 6 } else { 5 });
            if current_health == 0 {
                monster.when_been_killed(now_ms);
                monster.set_killed_by(MonsterKillingAttack {
                    attacker_type: PLAYER_TYPE,
                    attacker_id: player_id,
                    skill_id: 0,
                    skill_level: 0,
                    critical: false,
                    blast_attack: false,
                });
            } else {
                monster.when_been_hurted_by(
                    ShapeIdentity {
                        object_type: PLAYER_TYPE,
                        id: player_id,
                        ex_id: CGuid::GUID_INVALID,
                    },
                    false,
                    now_ms,
                );
            }
        }
        self.restore_region_owner(owner);
        if current_health != 0 {
            let mut hurt = CMessage::new(0x000b_f60a);
            hurt.add_long(PLAYER_TYPE);
            hurt.add_long(player_id);
            hurt.add_long(MONSTER_TYPE);
            hurt.add_long(monster_id);
            hurt.add_byte(1);
            hurt.add_byte(0);
            hurt.add_ulong(damage);
            hurt.add_ulong(current_health);
            hurt.base_mut().add_char(0);
            hurt.base_mut().add_char(0);
            hurt.add_long(0);
            hurt.add_byte(0);
            let _ = self.send_shape_position_around(region_id, tile_x, tile_y, &hurt);
            let _ = self.monster_on_been_hurted(region_id, monster_id, PLAYER_TYPE, player_id);
            return false;
        }

        let mut died = CMessage::new(0x000b_f60b);
        died.add_long(PLAYER_TYPE);
        died.add_long(player_id);
        died.add_long(MONSTER_TYPE);
        died.add_long(monster_id);
        died.add_ulong(damage);
        died.base_mut().add_char(1);
        died.base_mut().add_char(0);
        died.base_mut().add_char(0);
        died.add_long(0);
        died.add_byte(0);
        let _ = self.send_shape_position_around(region_id, tile_x, tile_y, &died);
        let _ = self.gods_battle_monster_died(region_id, monster_id, PLAYER_TYPE, player_id);
        let _ = self.monster_on_died(region_id, monster_id, player_id, runtime);
        if carriage {
            let _ = self.send_carriage_log_snapshot(
                master.master_id,
                property.index,
                region_id,
                tile_x,
                tile_y,
                3,
            );
            if master.master_type == PLAYER_TYPE
                && let Some(master_player) = self.find_player_mut(master.master_id)
            {
                master_player.clear_active_carriage(monster_id);
            }
        } else if !tamed {
            self.finish_monster_kill_effects(
                region_id, monster_id, player_id, tile_x, tile_y, &property, runtime,
            );
        } else if master.master_type == PLAYER_TYPE
            && let Some(master_player) = self.find_player_mut(master.master_id)
        {
            master_player.remove_active_pet(MONSTER_TYPE, monster_id);
        }
        let mut exit = CMessage::new(0x000b_f504);
        exit.add_long(MONSTER_TYPE);
        exit.add_long(monster_id);
        exit.add_long(0);
        exit.add_ulong(pos_x);
        exit.add_ulong(pos_y);
        let _ = self.send_shape_position_around(region_id, tile_x, tile_y, &exit);
        if let Some(mut owner) = self.take_region_owner(region_id) {
            owner.base_mut().finish_owned_monster_death(monster_id);
            self.restore_region_owner(owner);
        }
        true
    }

    pub(crate) fn drop_script_goods<Runtime: MonsterDeathContext>(
        &mut self,
        player_id: i32,
        region_id: i32,
        original_name: &[u8],
        amount: u32,
        origin_x: i32,
        origin_y: i32,
        runtime: &mut Runtime,
    ) {
        let goods_index = self
            .goods_factory
            .query_goods_id_by_original_name(Some(original_name));
        let mut created = self.create_goods_batch(goods_index, amount);
        let created_amount = created.len();
        let mut placed_amount = 0usize;
        for goods in created.drain(..) {
            let old_client_payload = runtime.encode_goods_for_old_client(&goods);
            let item_amount = goods.amount();
            let particular_attribute =
                goods.addon_property_value(&self.goods_factory, GAP_PARTICULAR_ATTRIBUTE, 1) as u32;
            let identity = goods.identity();
            let Some(mut owner) = self.take_region_owner(region_id) else {
                break;
            };
            let position = owner.base().get_drop_goods_position(origin_x, origin_y, 0);
            let Ok(Some((tile_x, tile_y, destination_position))) = position else {
                self.restore_region_owner(owner);
                break;
            };
            let (area_width, area_height) = self.area_dimensions();
            let added = owner.base_mut().add_owned_ground_goods(
                goods,
                tile_x,
                tile_y,
                particular_attribute,
                runtime.now_milliseconds(),
                area_width,
                area_height,
                runtime,
            );
            self.restore_region_owner(owner);
            if added.is_err() {
                continue;
            }
            let mut appeared = CS2CContainerObjectMove::default();
            appeared.set_operation(ContainerObjectMoveOperation::NewObject);
            appeared.set_destination_container(200, region_id, destination_position);
            appeared.set_destination_object(GOODS_TYPE, identity.ex_id);
            appeared.set_destination_object_amount(item_amount);
            appeared.set_object_stream(old_client_payload);
            let around = appeared.message();
            let player_delivery = appeared.send_to_player(self, player_id);
            let around_delivery = self.send_player_shape_around(player_id, None, &around);
            placed_amount += 1;
            tracing::trace!(player_id, region_id, goods_id = identity.id, goods_ex_id = ?identity.ex_id, player_delivery, ?around_delivery, "сценарный товар размещён в регионе");
        }
        tracing::trace!(
            player_id,
            region_id,
            requested = amount,
            created = created_amount,
            placed = placed_amount,
            "сценарное выпадение товаров завершено"
        );
    }

    /// Точная сценарная функция `3306 / DeleteMonster` не запускает владельца
    /// смерти: после публикации выхода окружающим монстр лишь получает
    /// `CS_DELETE` для обычной очистки искусственным интеллектом.
    pub(crate) fn delete_script_monster(&mut self, player_id: i32, monster_id: i32) -> Option<i32> {
        let region_id = self.find_player(player_id)?.server_region_id()?;
        let mut owner = self.take_region_owner(region_id)?;
        let result = (|| {
            let monster = owner.base().find_monster_by_id(monster_id)?;
            let delivery =
                self.send_shape_exit_around(owner.base(), monster.move_shape().shape())?;
            owner
                .base_mut()
                .find_monster_by_id_mut(monster_id)
                .expect("around publication сохраняет owned monster")
                .stage_for_delete();
            Some(delivery)
        })();
        self.restore_region_owner(owner);
        result
    }

    /// Сценарий `3315` использует явно заданный либо исходный регион уже после
    /// вычисления имени; неоднозначный поиск повторяющегося имени безопасно
    /// остаётся без побочного эффекта.
    pub(crate) fn delete_script_npc_by_name(&mut self, region_id: i32, name: &[u8]) -> Option<i32> {
        let mut owner = self.take_region_owner(region_id)?;
        let result = (|| {
            let npc = owner.base().find_npc_by_name(name).ok()??;
            let npc_id = npc.move_shape().shape().identity().id;
            let delivery = self.send_shape_exit_around(owner.base(), npc.move_shape().shape())?;
            let removed = owner
                .base_mut()
                .remove_owned_npc_by_id(npc_id)
                .ok()?;
            if removed
                && let ServerRegionOwner::GodsBattle(region) = &mut owner
            {
                Self::finish_gods_battle_npc_leave(region, npc_id);
            }
            removed.then_some(delivery)
        })();
        self.restore_region_owner(owner);
        result
    }

    /// Сценарий `3313` сначала фиксирует упорядоченный снимок прямоугольника,
    /// затем для каждого совпадения публикует выход и ставит `CS_DELETE`.
    pub(crate) fn delete_script_monsters_in_rect(
        &mut self,
        region_id: i32,
        rectangle: [i32; 4],
        original_name: Option<&[u8]>,
    ) {
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return;
        };
        let monster_ids = owner.base().script_monster_ids_in_rect(
            rectangle[0],
            rectangle[1],
            rectangle[2],
            rectangle[3],
            original_name,
        );
        for monster_id in monster_ids {
            let delivery = owner
                .base()
                .find_monster_by_id(monster_id)
                .and_then(|monster| {
                    self.send_shape_exit_around(owner.base(), monster.move_shape().shape())
                });
            let Some(delivery) = delivery else {
                continue;
            };
            owner
                .base_mut()
                .find_monster_by_id_mut(monster_id)
                .expect("rectangle snapshot сохраняет owned monster")
                .stage_for_delete();
            tracing::trace!(
                region_id,
                monster_id,
                delivery,
                "сценарный монстр удалён из прямоугольника"
            );
        }
        self.restore_region_owner(owner);
    }

    /// `3301 / NpcTalk` сохраняет переданное вызывающей стороной отображаемое
    /// имя и публикует один кадр локального чата через обычную рассылку вокруг
    /// игрового объекта.
    pub(crate) fn script_npc_talk(
        &mut self,
        region_id: i32,
        npc_id: i32,
        name: &[u8],
        text: &[u8],
    ) -> Option<i32> {
        let owner = self.take_region_owner(region_id)?;
        let result = (|| {
            let npc = owner.base().find_npc_by_id(npc_id)?;
            let shape = npc.move_shape().shape();
            let mut message = CMessage::new(0x000b_f801);
            message.add_long(0);
            message.add_long(shape.identity().object_type);
            message.add_long(shape.identity().id);
            message.base_mut().add(name);
            message.add_byte(0);
            message.base_mut().add(text);
            message.add_byte(0);
            let runtime = GameServerAroundRuntime::new(
                self,
                &self.session_factory,
                self.globe_setup.area_width(),
                self.globe_setup.area_height(),
            )?;
            message
                .send_to_around(Some(owner.base()), shape, None, &runtime)
                .ok()
        })();
        self.restore_region_owner(owner);
        result
    }

    /// `3304 / MonsterTalk` сначала выбирает монстров с точным совпадением
    /// имени в девяти областях игрока, затем каждый монстр независимо
    /// фильтрует получателей по строгому
    /// `abs(dx/dy) < AREA_WIDTH/HEIGHT` и отправляет `0xBF801`.
    pub(crate) fn script_monsters_talk(&mut self, player_id: i32, name: &[u8], text: &[u8]) {
        let Some((region_id, player_area_index)) = self
            .find_player(player_id)
            .and_then(|player| Some((player.server_region_id()?, player.shape().area_index()?)))
        else {
            return;
        };
        let Some(owner) = self.take_region_owner(region_id) else {
            return;
        };
        let monster_ids = owner
            .base()
            .script_monster_ids_around_area(player_area_index);
        let area_width = self.globe_setup.area_width();
        let area_height = self.globe_setup.area_height();
        if area_width > 0 && area_height > 0 {
            for monster_id in monster_ids {
                let Some(monster) = owner
                    .base()
                    .find_monster_by_id(monster_id)
                    .filter(|monster| monster.display_name() == name)
                else {
                    continue;
                };
                let shape = monster.move_shape().shape();
                let (Ok(tile_x), Ok(tile_y)) = (shape.get_tile_x(), shape.get_tile_y()) else {
                    continue;
                };
                let mut player_ids = Vec::new();
                for offset_x in -1..=1 {
                    for offset_y in -1..=1 {
                        owner.base().find_player_ids_in_area(
                            tile_x / area_width + offset_x,
                            tile_y / area_height + offset_y,
                            &mut player_ids,
                        );
                    }
                }
                let mut message = CMessage::new(0x000b_f801);
                message.add_long(0);
                message.add_long(shape.identity().object_type);
                message.add_long(shape.identity().id);
                message.base_mut().add(monster.display_name());
                message.add_byte(0);
                message.base_mut().add(text);
                message.add_byte(0);
                for target_id in player_ids {
                    let Some(target) = self.find_player(target_id) else {
                        continue;
                    };
                    let (Ok(target_x), Ok(target_y)) =
                        (target.shape().get_tile_x(), target.shape().get_tile_y())
                    else {
                        continue;
                    };
                    if i64::from(target_x).abs_diff(i64::from(tile_x)) < area_width as u64
                        && i64::from(target_y).abs_diff(i64::from(tile_y)) < area_height as u64
                    {
                        let delivery = message.send_to_player(self.net_server(), target_id);
                        tracing::trace!(
                            player_id,
                            monster_id,
                            target_id,
                            delivery,
                            "реплика сценарного монстра отправлена игроку"
                        );
                    }
                }
            }
        }
        self.restore_region_owner(owner);
    }

    /// `3312 / AttackPlayer` повторяет два последовательных обхода девяти
    /// областей вокруг сценарного игрока: сначала находит игрока по точному
    /// имени, затем назначает его целью всем монстрам того же окна. Дальнейшие
    /// движение, атака и сетевые сообщения принадлежат обычному циклу
    /// искусственного интеллекта монстров.
    pub(crate) fn script_monsters_attack_player(
        &mut self,
        player_id: i32,
        target_name: &[u8],
    ) -> usize {
        let Some((region_id, area_index)) = self
            .find_player(player_id)
            .and_then(|player| Some((player.server_region_id()?, player.shape().area_index()?)))
        else {
            return 0;
        };
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return 0;
        };
        let target = owner
            .base()
            .player_ids_around_area(area_index)
            .into_iter()
            .find_map(|candidate_id| {
                self.find_player(candidate_id).and_then(|candidate| {
                    (candidate.server_region_id() == Some(region_id)
                        && candidate.player_name() == target_name)
                        .then(|| candidate.shape().identity())
                })
            });
        let Some(target) = target else {
            self.restore_region_owner(owner);
            return 0;
        };
        let monster_ids = owner.base().script_monster_ids_around_area(area_index);
        let mut affected = 0usize;
        for monster_id in monster_ids {
            let Some(monster) = owner.base_mut().find_monster_by_id_mut(monster_id) else {
                continue;
            };
            monster.set_ai_target(target);
            affected = affected.wrapping_add(1);
        }
        self.restore_region_owner(owner);
        affected
    }

    /// Точный проход получателей `OnGMMessage 0x7FC13`: беззнаковая страна
    /// типа `long` сравнивается с расширенным байтом игрока, обход сохраняет
    /// знаковый порядок идентификаторов.
    pub(crate) fn player_ids_in_country(&self, country: u32) -> Vec<i32> {
        self.players
            .iter()
            .filter_map(|(player_id, player)| {
                (u32::from(player.country()) == country).then_some(*player_id)
            })
            .collect()
    }

    /// `5109 / ListOnlinePlayer` обходит все области текущего региона в
    /// порядке `CArea::FindShapes(400)` и возвращает имена найденных игроков.
    /// Снимок отделяет пространственный проход от последующих адресных
    /// сообщений запросившему игроку.
    pub(crate) fn script_region_player_names(&self, player_id: i32) -> Vec<Vec<u8>> {
        let Some(region_id) = self
            .find_player(player_id)
            .and_then(|player| player.server_region_id())
        else {
            return Vec::new();
        };
        let Some(region) = self.find_region(region_id) else {
            return Vec::new();
        };
        let mut player_ids = Vec::new();
        region.base().find_all_player_ids(&mut player_ids);
        player_ids
            .into_iter()
            .filter_map(|listed_player_id| {
                self.find_player(listed_player_id)
                    .map(|player| player.player_name().to_vec())
            })
            .collect()
    }

    /// CountryWar start обходит canonical player map один раз и выбирает обе
    /// участвующие страны, не группируя получателей по стране.
    pub(crate) fn player_ids_in_countries(&self, countries: [u8; 2]) -> Vec<i32> {
        self.players
            .iter()
            .filter_map(|(player_id, player)| {
                countries.contains(&player.country()).then_some(*player_id)
            })
            .collect()
    }

    /// Exact `FindPlayer(char const*)`: обходит canonical player map по
    /// signed ID-order и сравнивает byte-exact C-string имя.
    pub(crate) fn find_player_by_name(&self, name: &[u8]) -> Option<&CPlayer> {
        let name = legacy_c_string_prefix(name);
        self.players
            .values()
            .find(|player| legacy_c_string_prefix(player.shape().base_object().get_name()) == name)
    }

    /// Exact `FindPlayerByAccount(char*)`: canonical player map в signed
    /// ID-order и byte-exact C-string comparison загруженного account.
    pub(crate) fn find_player_by_account(&self, account: &[u8]) -> Option<&CPlayer> {
        let account = legacy_c_string_prefix(account);
        self.players
            .values()
            .find(|player| legacy_c_string_prefix(player.account()) == account)
    }

    /// Замыкает GM silence mutation от ordered name lookup до exact
    /// `SetSilence` timestamp. Отсутствующий player не создаёт state.
    pub(crate) fn silence_player_by_name(
        &mut self,
        name: &[u8],
        minutes: i32,
        now_milliseconds: impl FnOnce() -> u32,
    ) -> Option<i32> {
        let player_id = self.find_player_by_name(name)?.player_id();
        self.players
            .get_mut(&player_id)
            .expect("FindPlayer name lookup вернул canonical player")
            .set_silence(minutes, now_milliseconds());
        Some(player_id)
    }

    /// Один ordered pass исходного GM silence query. Clock читается
    /// только для player-а с ненулевым silence, как в `IsInSilence`.
    /// Caller выполняет два pass-а: сначала capacity, затем payload.
    pub(crate) fn silenced_player_names_pass(
        &mut self,
        mut now_milliseconds: impl FnMut() -> u32,
    ) -> Vec<Vec<u8>> {
        let player_ids: Vec<i32> = self.players.keys().copied().collect();
        let mut names = Vec::new();
        for player_id in player_ids {
            let player = self
                .players
                .get_mut(&player_id)
                .expect("snapshot ID принадлежит canonical player map");
            if player.silence_minutes() == 0 {
                continue;
            }
            if player.is_in_silence(now_milliseconds()) {
                names.push(player.shape().base_object().get_name().to_vec());
            }
        }
        names
    }

    /// Замыкает caller `goodsmessage` с runtime player-map и рецептом,
    /// опубликованным WorldServer selector-ом `SI_BATLLE_FAIRY_COMBINE`.
    /// Отсутствующий player не создаёт уведомления или пакет, как outer
    /// lookup исходного `CheckBattleFairyCombine`.
    pub(crate) fn check_battle_fairy_combine(&self, player_id: i32) {
        let check =
            self.find_player(player_id)
                .map_or_else(BattleFairyCombineCheck::default, |player| {
                    player.check_battle_fairy_combine(
                        &self.goods_factory,
                        self.battle_fairy_property.compose(),
                    )
                });
        if let Some(notification) = check.notification {
            let delivery = colored_player_notice_message(
                0xffff_ffff,
                0,
                self.get_string_by_id(notification.string_id().as_bytes()),
            )
            .send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                delivery,
                "уведомление проверки соединения боевой феи отправлено"
            );
        }
        if let Some(availability) = check.availability {
            let mut message = CMessage::new(availability.message_type as i32);
            message.add_ulong(availability.deplete_fetch);
            message.add_ulong(availability.truncated_success_rate);
            let delivery = message.send_to_player(self.net_server(), player_id);
            tracing::trace!(
                player_id,
                delivery,
                "доступность соединения боевой феи отправлена"
            );
        }
        tracing::trace!(player_id, ?check.result, "проверка соединения боевой феи завершена");
    }

    /// Исполняемый caller combine из `goodsmessage` после lookup player-а.
    /// Отсутствующий player, как и исходный outer lookup, не посылает packet.
    /// Old-client serializer остаётся explicit transport boundary: его нельзя
    /// заменить пустым payload без изменения `OT_NEW_OBJECT/0xbf918`.
    pub(crate) fn combine_battle_fairy<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) -> Option<()> {
        let battle_fairy_enabled = self.globe_setup.battle_fairy_enabled();
        let maximum_fetch_power = self.globe_setup.maximum_fetch_power();
        let (
            players,
            random_state,
            goods_factory,
            skill_factory,
            fairy_exp_conf,
            battle_fairy_exp_config,
            battle_fairy_property,
        ) = (
            &mut self.players,
            &mut self.random_state,
            &self.goods_factory,
            &self.skill_factory,
            &self.fairy_exp_conf,
            &self.battle_fairy_exp_config,
            &self.battle_fairy_property,
        );
        let player = players.get_mut(&player_id)?;
        let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
        let mut create_goods = |goods_index, random: &mut dyn FnMut(i32) -> i32| {
            goods_factory.create_goods(
                goods_index,
                |upper_bound| random(upper_bound),
                || CGuid::create().unwrap_or(CGuid::GUID_INVALID),
                |equip_level, level| fairy_exp_conf.dw_exp_up(equip_level, level),
                |equip_level, level| battle_fairy_exp_config.dw_exp_up(equip_level, level),
            )
        };
        let mut report = {
            let mut encode_old_client = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.combine_battle_fairy(
                battle_fairy_enabled,
                maximum_fetch_power,
                goods_factory,
                battle_fairy_property.compose(),
                skill_factory,
                &mut random,
                &mut create_goods,
                &mut encode_old_client,
            )
        };
        for effect in report.effects.take_all() {
            let GameEffect::BattleFairyCombine(effect) = effect else {
                tracing::error!("журнал соединения боевой феи содержит чужой эффект");
                continue;
            };
            match effect {
                BattleFairyCombineEffect::Notification {
                    player_id,
                    string_id,
                    color,
                } => {
                    let delivery = colored_player_notice_message(
                        color,
                        0,
                        self.get_string_by_id(string_id.as_bytes()),
                    )
                    .send_to_player(self.net_server(), player_id);
                    tracing::trace!(
                        player_id,
                        delivery,
                        "уведомление соединения боевой феи отправлено"
                    );
                }
                BattleFairyCombineEffect::FetchPowerChanged {
                    message_type,
                    player_id,
                    subject_id,
                    property_name,
                    value,
                } => {
                    let mut message = CMessage::new(message_type as i32);
                    message.add_long(PLAYER_TYPE);
                    message.add_long(subject_id);
                    add_legacy_c_string(message.base_mut(), property_name.as_bytes());
                    message.add_ulong(value);
                    let delivery = message.send_to_player(self.net_server(), player_id);
                    tracing::trace!(player_id, delivery, "изменение силы боевой феи отправлено");
                }
                BattleFairyCombineEffect::ObjectMove(object_move) => {
                    let delivery = self.send_battle_fairy_container_object_move(&object_move);
                    tracing::trace!(
                        player_id,
                        delivery,
                        "перемещение предмета соединения боевой феи отправлено"
                    );
                }
                BattleFairyCombineEffect::SkillAdded(skill) => {
                    if let Some(message) = player_skill_learned_message(
                        skill.message_type,
                        skill.skill_id,
                        skill.skill_level,
                        skill.skill_level,
                        &skill.skill_name,
                        &self.skill_factory,
                        false,
                    ) {
                        let delivery = message.send_to_player(self.net_server(), skill.player_id);
                        tracing::trace!(
                            player_id = skill.player_id,
                            delivery,
                            "навык соединённой боевой феи отправлен"
                        );
                    }
                }
                BattleFairyCombineEffect::GoodsUpdated(update) => {
                    let delivery = self.send_battle_fairy_goods_update(&update);
                    tracing::trace!(
                        player_id = update.player_id,
                        delivery,
                        "предмет соединённой боевой феи обновлён"
                    );
                }
                BattleFairyCombineEffect::Audit(audit) => {
                    let template = self.get_string_by_id(audit.string_id.as_bytes());
                    // В ветке ZHGS0003 оригинал передаёт в GetName null goods;
                    // безопасная Rust-проекция сохраняет второй форматный аргумент
                    // пустым, не выдумывая имя не созданного предмета.
                    let formatted = if audit.string_id == "ZHGS0007" {
                        format_legacy_text_fields(template, &[&audit.account], 0xff)
                    } else {
                        format_legacy_text_fields(
                            template,
                            &[&audit.account, &audit.goods_name],
                            0xff,
                        )
                    };
                    put_string_to_file("BattleFairy", &formatted);
                    tracing::trace!(player_id, "аудит соединения боевой феи записан");
                }
            }
        }
        tracing::debug!(player_id, ?report.outcome, "соединение боевой феи завершено");
        Some(())
    }

    fn send_battle_fairy_container_object_move(&self, object_move: &BattleFairyObjectMove) -> i32 {
        let mut message = CS2CContainerObjectMove::default();
        match object_move.operation {
            BattleFairyObjectMoveOperation::Delete => {
                message.set_operation(ContainerObjectMoveOperation::DeleteObject);
                message.set_source_container(
                    PLAYER_TYPE,
                    object_move.player_id,
                    object_move.position,
                );
                message.set_source_container_extend_id(object_move.container_extend_id as i32);
                message.set_source_object(
                    object_move.goods.object_type,
                    object_move.goods.ex_id,
                    object_move.amount,
                );
            }
            BattleFairyObjectMoveOperation::New => {
                message.set_operation(ContainerObjectMoveOperation::NewObject);
                message.set_destination_container(
                    PLAYER_TYPE,
                    object_move.player_id,
                    object_move.position,
                );
                message.set_destination_container_extend_id(object_move.container_extend_id as i32);
                message
                    .set_destination_object(object_move.goods.object_type, object_move.goods.ex_id);
                message
                    .set_object_stream(object_move.old_client_payload.clone().unwrap_or_default());
            }
        }
        message.send_to_player(self, object_move.player_id)
    }

    /// Исполняемый entry point для `goodsmessage` opcode `0x8FC2C/0x8FC2D`.
    /// Player сохраняет порядок guards и broadcast effects, а region map
    /// меняется здесь, потому что `CGame` — первый живой owner обоих runtime
    /// объектов. Around transport использует те же owned session и area maps.
    pub(crate) fn summon_battle_fairy(&mut self, player_id: i32, mode: i32) -> Option<()> {
        let battle_fairy_enabled = self.globe_setup.battle_fairy_enabled();
        let mut report = {
            let player = self.players.get_mut(&player_id)?;
            player.summon_battle_fairy(battle_fairy_enabled, mode, &self.goods_factory)
        };
        if let Some(action) = report.spatial_action {
            let spatial_applied = report.region_id.is_some_and(|region_id| {
                let Some(region) = self.regions.get_mut(&region_id) else {
                    return false;
                };
                match action {
                    BattleFairyWarSoulAction::SetPosition { previous, target } => region
                        .base_mut()
                        .set_war_soul_position(player_id as u32, previous, target),
                    BattleFairyWarSoulAction::Delete { previous, .. } => region
                        .base_mut()
                        .delete_war_soul(player_id as u32, previous),
                }
            });
            if let Some(player) = self.players.get_mut(&player_id) {
                player.apply_war_soul_action(action, spatial_applied);
            }
        }
        self.deliver_battle_fairy_summon_effects(&mut report);
        tracing::debug!(player_id, mode, ?report.outcome, "призыв боевой феи обработан");
        Some(())
    }

    /// Reached tail virtual `CPlayer::UpdateProperty`: equipment recompute
    /// меняет canonical combat snapshot, `OnChangeProperties` публикует
    /// `0xBF721`, затем активный `bTaoZhuangModify` запускает reached
    /// set-completion owner. Один owner обслуживает callers из battle-fairy
    /// goods message и обоих FourNation exploit paths.
    pub(crate) fn update_player_properties<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) -> Option<(i32, bool)> {
        let properties = self
            .find_player(player_id)
            .map(|player| context.recompute_enhancement_player_properties(player))?;
        if !self.apply_recomputed_player_properties(player_id, properties) {
            return None;
        }
        let property_delivery = self
            .find_player(player_id)
            .map(|player| self.send_player_properties_changed(player))?;
        let tao_zhuang_ran =
            self.globe_setup.tao_zhuang_modify_enabled() && self.done_player_tao_zhuang(player_id);
        Some((property_delivery, tao_zhuang_ran))
    }

    /// Точная граница владельцев `CPlayer::RestoreHpMp`: внешнее состояние
    /// предмета завершается до атомарной замены четырёх канонических
    /// автоматических состояний.
    pub(crate) fn restore_player_hp_mp_states<Runtime: GameMainLoopRuntime>(
        &mut self,
        player_id: i32,
        runtime: &mut Runtime,
    ) -> Option<()> {
        runtime.end_player_particular_states_for_restore(self, player_id);
        self.find_player_mut(player_id)?.restore_automatic_hp_mp_states();
        Some(())
    }

    fn deliver_battle_fairy_summon_effects(&mut self, report: &mut BattleFairySummonReport) {
        for effect in report.effects.take_all() {
            let GameEffect::BattleFairySummon(effect) = effect else {
                tracing::error!("журнал призыва боевой феи содержит чужой эффект");
                continue;
            };
            match effect {
                BattleFairySummonEffect::Notification {
                    player_id,
                    string_id,
                    color,
                } => {
                    let text = self.get_string_by_id(string_id.as_bytes());
                    let delivery = colored_player_notice_message(color, 0, text)
                        .send_to_player(self.net_server(), player_id);
                    tracing::trace!(
                        player_id,
                        delivery,
                        "уведомление призыва боевой феи отправлено"
                    );
                }
                BattleFairySummonEffect::AroundMessage {
                    message_type,
                    player_id,
                    values,
                } => {
                    let mut message = CMessage::new(message_type as i32);
                    if message_type == 0x0b_f605 && values.len() == 4 {
                        message.add_long(values[0]);
                        message.add_ulong(values[1] as u32);
                        message.add_ulong((values[2] as f32).to_bits());
                        message.add_ulong((values[3] as f32).to_bits());
                    } else {
                        for value in values {
                            message.add_long(value);
                        }
                    }
                    let delivery = report
                        .region_id
                        .and_then(|region_id| self.take_region_owner(region_id))
                        .map(|owner| {
                            let player = self.find_player(player_id);
                            let delivery = player.map(|player| {
                                self.send_battle_fairy_around(
                                    owner.base(),
                                    player.shape(),
                                    &message,
                                )
                            });
                            self.restore_region_owner(owner);
                            delivery
                        })
                        .flatten();
                    tracing::trace!(
                        player_id,
                        ?delivery,
                        "состояние призыва боевой феи отправлено окружению"
                    );
                }
                BattleFairySummonEffect::PropertiesChanged { player_id } => {
                    if let Some(player) = self.find_player(player_id) {
                        let delivery = self.send_player_properties_changed(player);
                        tracing::trace!(
                            player_id,
                            delivery,
                            "свойства после призыва боевой феи отправлены"
                        );
                    }
                }
            }
        }
    }

    /// Замыкает positional add battle-fairy container-а с player property и
    /// загруженными GlobeSetup coefficients. Old-client codec остаётся
    /// transport boundary и вызывается только на подтверждённом update path.
    pub(crate) fn add_battle_fairy_goods(
        &mut self,
        player_id: i32,
        cell: BattleFairyCell,
        incoming: &mut Option<CGoods>,
        owner_progress_allows: bool,
        encode_old_client: &mut dyn FnMut(&CGoods) -> Vec<u8>,
    ) -> Option<BattleFairyEquipmentMutationReport> {
        let coefficients = self.globe_setup.player_property_coefficients();
        let mut report = self.players.get_mut(&player_id).map(|player| {
            player.add_battle_fairy_goods(
                cell,
                incoming,
                &self.goods_factory,
                coefficients,
                owner_progress_allows,
                encode_old_client,
            )
        })?;
        self.deliver_battle_fairy_equipment_effects(&mut report);
        Some(report)
    }

    /// Полный player-owned tail `CEquipmentContainer::Remove`: callback
    /// materializes reached результат ещё отдельного virtual
    /// `PropertiesChanged`, наблюдая player уже без removed slot-а.
    pub(crate) fn remove_player_equipment(
        &mut self,
        player_id: i32,
        ex_id: CGuid,
        runtime: PlayerEquipmentRemoveRuntimeFacts,
        recompute_properties: &mut dyn FnMut(&CPlayer) -> PlayerCombatProperties,
    ) -> Option<PlayerEquipmentRemoveReport> {
        let (players, goods_factory, skill_factory) =
            (&mut self.players, &self.goods_factory, &self.skill_factory);
        let mut report = players.get_mut(&player_id).map(|player| {
            player.remove_equipment_goods(
                ex_id,
                goods_factory,
                skill_factory,
                runtime,
                recompute_properties,
            )
        })?;
        self.publish_player_equipment_remove_report(&mut report);
        if self.globe_setup.tao_zhuang_modify_enabled() {
            let _ = self.done_player_tao_zhuang(player_id);
        }
        Some(report)
    }

    fn publish_player_equipment_remove_report(&self, report: &mut PlayerEquipmentRemoveReport) {
        for effect in report.effects.take_all() {
            let GameEffect::PlayerEquipmentRemove(effect) = effect else {
                tracing::error!("журнал снятия экипировки содержит чужой эффект");
                continue;
            };
            match effect {
                PlayerEquipmentRemoveEffect::WarSoulSkillDetached { .. } => {}
                PlayerEquipmentRemoveEffect::SkillRemoved(skill) => {
                    let mut message = CMessage::new(skill.message_type as i32);
                    add_legacy_c_string(message.base_mut(), &skill.skill_name);
                    let delivery = message.send_to_player(self.net_server(), skill.player_id);
                    tracing::trace!(
                        player_id = skill.player_id,
                        skill_id = skill.skill_id,
                        delivery,
                        "удаление навыка экипировки отправлено игроку"
                    );
                }
                PlayerEquipmentRemoveEffect::WarSoulStatusAround {
                    message_type,
                    player_id,
                    values,
                } => {
                    let mut message = CMessage::new(message_type as i32);
                    message.add_long(values[0]);
                    message.add_long(values[1]);
                    let deliveries = self.send_player_equipment_around(player_id, None, &message);
                    tracing::trace!(
                        player_id,
                        ?deliveries,
                        "изменение статуса боевой феи опубликовано вокруг игрока"
                    );
                }
                PlayerEquipmentRemoveEffect::PropertiesChangedWithoutRemovedSlot { .. } => {
                    let deliveries = self
                        .find_player(report.player_id)
                        .map(|player| vec![self.send_player_properties_changed(player)])
                        .unwrap_or_default();
                    tracing::trace!(
                        player_id = report.player_id,
                        ?deliveries,
                        "изменение свойств после снятия экипировки отправлено"
                    );
                }
                PlayerEquipmentRemoveEffect::VitalsClamped { .. } => {}
                PlayerEquipmentRemoveEffect::AroundUpdate(update) => {
                    let deliveries = self.send_player_equipment_update(update);
                    tracing::trace!(
                        player_id = report.player_id,
                        ?deliveries,
                        "снятие экипировки опубликовано вокруг игрока"
                    );
                }
            }
        }
    }

    /// Полный player-owned tail positional `CEquipmentContainer::Add`; оба
    /// callback-а вызываются в native порядке относительно container commit.
    pub(crate) fn add_player_equipment(
        &mut self,
        player_id: i32,
        position: u32,
        incoming: &mut Option<CGoods>,
        runtime: PlayerEquipmentAddRuntimeFacts,
        register_with_goods_ai: &mut dyn FnMut(&CGoods),
        recompute_properties: &mut dyn FnMut(&CPlayer) -> PlayerCombatProperties,
    ) -> Option<PlayerEquipmentAddReport> {
        let (players, goods_factory, skill_factory) =
            (&mut self.players, &self.goods_factory, &self.skill_factory);
        let mut report = players.get_mut(&player_id).map(|player| {
            player.add_equipment_goods(
                position,
                incoming,
                goods_factory,
                skill_factory,
                runtime,
                register_with_goods_ai,
                recompute_properties,
            )
        })?;
        self.publish_player_equipment_add_report(&mut report);
        if self.globe_setup.tao_zhuang_modify_enabled() {
            let _ = self.done_player_tao_zhuang(player_id);
        }
        Some(report)
    }

    fn publish_player_equipment_add_report(&self, report: &mut PlayerEquipmentAddReport) {
        for effect in report.effects.take_all() {
            let GameEffect::PlayerEquipmentAdd(effect) = effect else {
                tracing::error!("журнал надевания экипировки содержит чужой эффект");
                continue;
            };
            match effect {
                PlayerEquipmentAddEffect::WarSoulSkillAttached { .. } => {}
                PlayerEquipmentAddEffect::SkillAdded(skill) => {
                    if let Some(message) = player_skill_learned_message(
                        skill.message_type,
                        skill.skill_id,
                        skill.skill_level,
                        skill.skill_level,
                        &skill.skill_name,
                        &self.skill_factory,
                        true,
                    ) {
                        let delivery = message.send_to_player(self.net_server(), skill.player_id);
                        tracing::trace!(
                            player_id = skill.player_id,
                            skill_id = skill.skill_id,
                            delivery,
                            "добавление навыка экипировки отправлено игроку"
                        );
                    }
                }
                PlayerEquipmentAddEffect::PropertiesChanged { .. } => {
                    let deliveries = self
                        .find_player(report.player_id)
                        .map(|player| vec![self.send_player_properties_changed(player)])
                        .unwrap_or_default();
                    tracing::trace!(
                        player_id = report.player_id,
                        ?deliveries,
                        "изменение свойств после надевания экипировки отправлено"
                    );
                }
                PlayerEquipmentAddEffect::AroundUpdate(update) => {
                    let deliveries = self.send_player_equipment_update(update);
                    tracing::trace!(
                        player_id = report.player_id,
                        ?deliveries,
                        "надевание экипировки опубликовано вокруг игрока"
                    );
                }
                PlayerEquipmentAddEffect::PackageExtensionLogged {
                    category,
                    string_id,
                    expanded_package_num,
                } => {
                    if let Some(player) = self.find_player(report.player_id) {
                        let text = format_legacy_mixed(
                            self.get_string_by_id(string_id.as_bytes()),
                            &[
                                LegacyFormatArgument::Bytes(player.player_name()),
                                LegacyFormatArgument::Signed(expanded_package_num as i32),
                            ],
                            265,
                        );
                        put_string_to_file(category, &text);
                    }
                }
            }
        }
    }

    fn send_player_equipment_update(&self, update: EquipmentAroundUpdate) -> Vec<i32> {
        let mut message = CMessage::new(EQUIPMENT_AROUND_UPDATE_MESSAGE_TYPE as i32);
        message.add_long(update.owner_id);
        message.add_ulong(update.column.position());
        message.add_byte(u8::from(update.added));
        message.add_ulong(update.base_properties_index);
        message.add_ulong(update.weapon_level);
        self.send_player_equipment_around(
            update.owner_id,
            update.exclude_owner.then_some(update.owner_id),
            &message,
        )
    }

    fn send_player_equipment_around(
        &self,
        player_id: i32,
        excluded_player_id: Option<i32>,
        message: &CMessage,
    ) -> Vec<i32> {
        let Some(player) = self.find_player(player_id) else {
            return Vec::new();
        };
        let Some(region) = player
            .server_region_id()
            .and_then(|region_id| self.find_region(region_id))
        else {
            return Vec::new();
        };
        self.send_game_shape_around(region.base(), player.shape(), excluded_player_id, message)
            .into_iter()
            .collect()
    }

    /// Замыкает remove по GUID с тем же player/equipment state и сохраняет
    /// подтверждённую двойную публикацию `0xBF918` после property removal.
    pub(crate) fn remove_battle_fairy_goods(
        &mut self,
        player_id: i32,
        ex_id: CGuid,
        encode_old_client: &mut dyn FnMut(&CGoods) -> Vec<u8>,
    ) -> Option<BattleFairyEquipmentMutationReport> {
        let coefficients = self.globe_setup.player_property_coefficients();
        let mut report = self.players.get_mut(&player_id).map(|player| {
            player.remove_battle_fairy_goods(
                ex_id,
                &self.goods_factory,
                coefficients,
                encode_old_client,
            )
        })?;
        self.deliver_battle_fairy_equipment_effects(&mut report);
        Some(report)
    }

    fn deliver_battle_fairy_equipment_effects(
        &self,
        report: &mut BattleFairyEquipmentMutationReport,
    ) {
        let player = self.find_player(report.player_id);
        self.deliver_battle_fairy_equipment_effects_for_player(player, report);
    }

    fn deliver_battle_fairy_equipment_effects_for_player(
        &self,
        player: Option<&CPlayer>,
        report: &mut BattleFairyEquipmentMutationReport,
    ) {
        for effect in report.effects.take_all() {
            let GameEffect::BattleFairyEquipmentMutation(effect) = effect else {
                tracing::error!("журнал экипировки боевой феи содержит чужой эффект");
                continue;
            };
            match effect {
                BattleFairyEquipmentMutationEffect::PropertiesChanged { player_id } => {
                    if let Some(player) = player.filter(|player| player.player_id() == player_id) {
                        let delivery = self.send_player_properties_changed(player);
                        tracing::trace!(
                            player_id,
                            delivery,
                            "изменение свойств боевой феи отправлено игроку"
                        );
                    }
                }
                BattleFairyEquipmentMutationEffect::BattleFairyUpdated(update) => {
                    let delivery = self.send_battle_fairy_goods_update(&update);
                    tracing::trace!(
                        player_id = update.player_id,
                        delivery,
                        "изменение экипировки боевой феи отправлено игроку"
                    );
                }
            }
        }
    }

    fn send_battle_fairy_goods_update(
        &self,
        update: &crate::gameserver::appserver::container::cbattlefairycontainer::BattleFairyDefaultGoodsUpdate,
    ) -> i32 {
        let mut message = CMessage::new(update.message_type as i32);
        message.add_long(update.player_id);
        message.base_mut().add_guid(update.goods.ex_id);
        message.add_ulong(update.old_client_payload.len() as u32);
        message.base_mut().add(&update.old_client_payload);
        message.send_to_player(self.net_server(), update.player_id)
    }

    /// Исполняемый entry point goods-message `0x8FC2A`; decoder передаёт пары
    /// property/client-points без предварительного масштабирования.
    pub(crate) fn allocate_battle_fairy_potential<Context: BattleFairyDeathContext>(
        &mut self,
        player_id: i32,
        allocations: &[(i32, i32)],
        context: &mut Context,
    ) -> Option<()> {
        let enabled = self.globe_setup.battle_fairy_enabled();
        let coefficients = self.globe_setup.player_property_coefficients();
        let mut report = {
            let player = self.players.get_mut(&player_id)?;
            let mut encode_old_client = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.allocate_battle_fairy_potential(
                enabled,
                allocations,
                &self.goods_factory,
                coefficients,
                &mut encode_old_client,
            )
        };
        for effect in report.effects.take_all() {
            let GameEffect::BattleFairyPotentialAllocation(effect) = effect else {
                tracing::error!("журнал потенциала боевой феи содержит чужой эффект");
                continue;
            };
            match effect {
                BattleFairyPotentialAllocationEffect::Notification {
                    player_id,
                    string_id,
                    color,
                } => {
                    let delivery = colored_player_notice_message(
                        color,
                        0,
                        self.get_string_by_id(string_id.as_bytes()),
                    )
                    .send_to_player(self.net_server(), player_id);
                    tracing::trace!(
                        player_id,
                        delivery,
                        "уведомление распределения потенциала боевой феи отправлено"
                    );
                }
                BattleFairyPotentialAllocationEffect::PropertiesChanged { player_id } => {
                    if let Some(player) = self.find_player(player_id) {
                        let delivery = self.send_player_properties_changed(player);
                        tracing::trace!(
                            player_id,
                            delivery,
                            "свойства после распределения потенциала боевой феи отправлены"
                        );
                    }
                }
                BattleFairyPotentialAllocationEffect::GoodsUpdated(update) => {
                    let delivery = self.send_battle_fairy_goods_update(&update);
                    tracing::trace!(
                        player_id = update.player_id,
                        delivery,
                        "предмет после распределения потенциала боевой феи обновлён"
                    );
                }
            }
        }
        tracing::debug!(player_id, ?report.outcome, "потенциал боевой феи распределён");
        Some(())
    }

    /// Полный runtime entry point goods-message `0x8FC28`: общий Game RNG,
    /// live log gates, factory, player wallet и positional BF-container
    /// исполняются в одном mutable snapshot-е.
    pub(crate) fn upgrade_battle_fairy_equipment<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) -> Option<()> {
        let log_gates = crate::gameserver::appserver::player::BattleFairyUpgradeLogGates {
            success: self.log_system.goods_upgrade_success_enabled(),
            failure: self.log_system.goods_upgrade_failure_enabled(),
            lost_target: self.log_system.goods_lost_by_upgrade_enabled(),
        };
        let mut report = {
            let (players, random_state, goods_factory) = (
                &mut self.players,
                &mut self.random_state,
                &self.goods_factory,
            );
            let player = players.get_mut(&player_id)?;
            let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
            let mut encode_old_client = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.upgrade_battle_fairy_equipment(
                goods_factory,
                log_gates,
                &mut random,
                &mut encode_old_client,
            )
        };
        for effect in report.effects.take_all() {
            let GameEffect::BattleFairyUpgrade(effect) = effect else {
                tracing::error!("журнал улучшения боевой феи содержит чужой эффект");
                continue;
            };
            match effect {
                BattleFairyUpgradeEffect::Notification {
                    player_id,
                    string_id,
                    color,
                    format_value,
                } => {
                    let template = self.get_string_by_id(string_id.as_bytes());
                    let text = format_value.map_or_else(
                        || legacy_c_string_prefix(template).to_vec(),
                        |value| format_single_legacy_u32(template, value, 255),
                    );
                    let delivery = colored_player_notice_message(color, 0, &text)
                        .send_to_player(self.net_server(), player_id);
                    tracing::trace!(
                        player_id,
                        delivery,
                        "уведомление улучшения боевой феи отправлено"
                    );
                }
                BattleFairyUpgradeEffect::MoneyChanged {
                    player_id, outcome, ..
                } => {
                    let deliveries = self.send_player_money_decrease(player_id, &outcome);
                    tracing::trace!(
                        player_id,
                        ?deliveries,
                        "уменьшение денег за улучшение боевой феи отправлено"
                    );
                }
                BattleFairyUpgradeEffect::GoodsUpdated(update) => {
                    let delivery = self.send_battle_fairy_goods_update(&update);
                    tracing::trace!(
                        player_id = update.player_id,
                        delivery,
                        "улучшенный предмет боевой феи обновлён"
                    );
                }
                effect @ (BattleFairyUpgradeEffect::GemConsumed { .. }
                | BattleFairyUpgradeEffect::TargetDeleted { .. }) => {
                    let deliveries = self.send_battle_fairy_upgrade_container(&effect);
                    tracing::trace!(
                        player_id,
                        ?deliveries,
                        "контейнерный эффект улучшения боевой феи отправлен"
                    );
                }
                effect @ BattleFairyUpgradeEffect::Audit { .. } => {
                    self.send_battle_fairy_upgrade_audit(&effect);
                }
            }
        }
        tracing::debug!(player_id, ?report.outcome, "улучшение боевой феи завершено");
        Some(())
    }

    pub(crate) fn send_player_money_decrease(
        &self,
        player_id: i32,
        outcome: &crate::gameserver::appserver::container::cwallet::CurrencyDecreaseOutcome,
    ) {
        use crate::gameserver::appserver::container::cwallet::CurrencyDecreaseOutcome;

        let mut message = CS2CContainerObjectMove::default();
        match outcome {
            CurrencyDecreaseOutcome::Decreased(change) => {
                message.set_operation(ContainerObjectMoveOperation::MoveObject);
                message.set_source_container(change.owner_type, change.owner_id, change.position);
                message.set_source_container_extend_id(4);
                message.set_source_object(
                    change.identity.object_type,
                    change.identity.ex_id,
                    change.amount,
                );
            }
            CurrencyDecreaseOutcome::Removed(removed) => {
                message.set_operation(ContainerObjectMoveOperation::DeleteObject);
                message.set_source_container(
                    removed.owner_type,
                    removed.owner_id,
                    removed.position,
                );
                message.set_source_container_extend_id(4);
                let identity = removed.goods.identity();
                message.set_source_object(identity.object_type, identity.ex_id, removed.amount);
            }
            CurrencyDecreaseOutcome::NoChange
            | CurrencyDecreaseOutcome::InvalidStoredCurrency { .. } => return,
        }
        let delivery = message.send_to_player(self, player_id);
        tracing::trace!(player_id, delivery, "уменьшение денег отправлено игроку");
    }

    pub(crate) fn decrease_player_money(
        &mut self,
        player_id: i32,
        amount: u32,
    ) -> Option<crate::gameserver::appserver::player::PlayerMoneyDecrease> {
        let (players, goods_factory) = (&mut self.players, &self.goods_factory);
        Some(
            players
                .get_mut(&player_id)?
                .decrease_money(amount, goods_factory),
        )
    }

    /// Exact `CPlayer::SetMoney` boundary для script family `3011..3016`:
    /// wallet остаётся canonical state owner-ом, а CGame публикует соответствующий
    /// create/amount/delete packet с extend ID 4. Как и оригинал, caller считает
    /// найденного игрока успехом даже при отказе wallet создать currency object.
    pub(crate) fn set_script_player_money<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        requested: u32,
        context: &mut Context,
    ) -> bool {
        let Some(previous) = self.find_player(player_id).map(CPlayer::money) else {
            return false;
        };
        if requested < previous {
            let Some(change) = self.decrease_player_money(player_id, previous - requested) else {
                return false;
            };
            let _ = self.send_player_money_decrease(player_id, &change.outcome);
        } else if requested > previous {
            let amount = requested - previous;
            let created = self.create_goods_batch(self.goods_factory.get_gold_coin_index(), amount);
            let outcome = {
                let (players, goods_factory) = (&mut self.players, &self.goods_factory);
                let Some(player) = players.get_mut(&player_id) else {
                    return false;
                };
                player.increase_money(amount, goods_factory, created)
            };
            let _ = self.send_player_money_increase(player_id, &outcome, context);
        }
        true
    }

    /// World `0x7FE34/0x7FE37` повторяет старый `GetMoney - signed fee`, затем
    /// `SetMoney(max(signed(result), 0))`. Обычная положительная плата идёт
    /// через тот же wallet/container wire, что остальные gameplay debits;
    /// отрицательный legacy параметр сохраняет историческое пополнение.
    pub(crate) fn apply_war_application_money<Context: OldClientGoodsCodec>(
        &mut self,
        player_id: i32,
        fee: i32,
        context: &mut Context,
    ) -> Option<()> {
        let previous = self.find_player(player_id)?.money();
        let wrapped = previous.wrapping_sub(fee as u32);
        let resulting = if (wrapped as i32) < 0 { 0 } else { wrapped };
        if resulting < previous {
            let change = self.decrease_player_money(player_id, previous - resulting)?;
            self.send_player_money_decrease(player_id, &change.outcome);
        } else if resulting > previous {
            let amount = resulting - previous;
            let created = self.create_goods_batch(self.goods_factory.get_gold_coin_index(), amount);
            let outcome = {
                let (players, goods_factory) = (&mut self.players, &self.goods_factory);
                players
                    .get_mut(&player_id)?
                    .increase_money(amount, goods_factory, created)
            };
            self.send_player_money_increase(player_id, &outcome, context);
        }
        let current = self.find_player(player_id)?.money();
        tracing::trace!(
            player_id,
            fee,
            previous,
            current,
            "плата за заявку войны применена"
        );
        Some(())
    }

    fn send_battle_fairy_upgrade_container(&self, effect: &BattleFairyUpgradeEffect) -> Vec<i32> {
        match effect {
            BattleFairyUpgradeEffect::GemConsumed {
                player_id,
                consumed,
            } if consumed.removed => {
                vec![self.send_battle_fairy_upgrade_delete_for_player(
                    *player_id,
                    consumed.goods,
                    consumed.cell.position(),
                    consumed.previous_amount,
                )]
            }
            BattleFairyUpgradeEffect::GemConsumed {
                player_id,
                consumed,
            } => {
                let mut message = CS2CContainerObjectAmountChange::default();
                message.set_source_container(PLAYER_TYPE, *player_id, consumed.cell.position());
                message.set_source_container_extend_id(12);
                message.set_object(consumed.goods.object_type, consumed.goods.ex_id);
                message.set_object_amount(consumed.remaining_amount);
                vec![message.send_to_player(self, *player_id)]
            }
            BattleFairyUpgradeEffect::TargetDeleted {
                player_id,
                goods,
                position,
                ..
            } => {
                vec![self.send_battle_fairy_upgrade_delete_for_player(
                    *player_id,
                    goods.identity,
                    *position,
                    goods.amount,
                )]
            }
            _ => Vec::new(),
        }
    }

    fn send_battle_fairy_upgrade_delete_for_player(
        &self,
        player_id: i32,
        goods: crate::gameserver::appserver::shape::ShapeIdentity,
        position: u32,
        amount: u32,
    ) -> i32 {
        let mut message = CS2CContainerObjectMove::default();
        message.set_operation(ContainerObjectMoveOperation::DeleteObject);
        message.set_source_container(PLAYER_TYPE, player_id, position);
        message.set_source_container_extend_id(12);
        message.set_source_object(goods.object_type, goods.ex_id, amount);
        message.send_to_player(self, player_id)
    }

    fn send_battle_fairy_upgrade_audit(&self, effect: &BattleFairyUpgradeEffect) {
        let BattleFairyUpgradeEffect::Audit {
            message_type,
            event,
            player_id,
            player,
            target,
            gems,
        } = effect
        else {
            tracing::error!("неверный эффект передан владельцу аудита улучшения боевой феи");
            return;
        };
        let mut message = CMessage::new(*message_type as i32);
        message.add_byte(*event);
        message.add_long(*player_id);
        if *message_type == 0x0006_0203 {
            add_battle_fairy_upgrade_log_goods(&mut message, Some(target));
            for gem in gems {
                add_battle_fairy_upgrade_log_goods(&mut message, gem.as_ref());
            }
            message.add_long(player.region_id);
            message.add_long(player.tile_x);
            message.add_long(player.tile_y);
        } else {
            message.base_mut().add_short(player.pk_count as i16);
            message.add_ulong(player.money);
            message.add_ulong(player.depot_money);
            message.base_mut().add_guid(target.identity.ex_id);
            // Primary GameServer пишет price в поле, которое WorldServer
            // исторически называет amount, и literal 1 в поле price.
            message.add_ulong(target.price);
            add_legacy_c_string(message.base_mut(), &target.name);
            message.add_ulong(1);
            message.add_long(player.region_id);
            message.add_long(player.tile_x);
            message.add_long(player.tile_y);
            message.add_ulong(player.client_ip);
        }
        let delivery = message.send(self, false);
        tracing::trace!(player_id, ?delivery, "аудит улучшения боевой феи отправлен");
    }

    fn send_battle_fairy_packet_consumption(
        &self,
        effect: &BattleFairyPotentialResetEffect,
    ) -> Vec<i32> {
        let BattleFairyPotentialResetEffect::PacketItemConsumed {
            player_id,
            goods,
            position,
            previous_amount,
            remaining_amount,
            consumed,
            ..
        } = effect
        else {
            return Vec::new();
        };
        let Some(position) = position else {
            return Vec::new();
        };
        if !consumed {
            return Vec::new();
        }
        if *remaining_amount == 0 {
            let mut message = CS2CContainerObjectMove::default();
            message.set_operation(ContainerObjectMoveOperation::DeleteObject);
            message.set_source_container(PLAYER_TYPE, *player_id, *position);
            message.set_source_container_extend_id(1);
            message.set_source_object(goods.object_type, goods.ex_id, *previous_amount);
            return vec![message.send_to_player(self, *player_id)];
        }

        let mut message = CS2CContainerObjectAmountChange::default();
        message.set_source_container(PLAYER_TYPE, *player_id, *position);
        message.set_source_container_extend_id(1);
        message.set_object(goods.object_type, goods.ex_id);
        message.set_object_amount(*remaining_amount);
        vec![message.send_to_player(self, *player_id)]
    }

    /// Исполняемый entry point goods-message `0x8FC2B`: reset item ищется и
    /// расходуется в owned player packet до potential/player mutations.
    pub(crate) fn reset_battle_fairy_potential<Context: BattleFairyDeathContext>(
        &mut self,
        player_id: i32,
        context: &mut Context,
    ) -> Option<()> {
        let enabled = self.globe_setup.battle_fairy_enabled();
        let mut report = {
            let player = self.players.get_mut(&player_id)?;
            let mut encode_old_client = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.reset_battle_fairy_potential(
                enabled,
                &self.goods_factory,
                &mut encode_old_client,
            )
        };
        for effect in report.effects.take_all() {
            let GameEffect::BattleFairyPotentialReset(effect) = effect else {
                tracing::error!("журнал сброса потенциала боевой феи содержит чужой эффект");
                continue;
            };
            match effect {
                BattleFairyPotentialResetEffect::Notification {
                    player_id,
                    string_id,
                    color,
                } => {
                    let delivery = colored_player_notice_message(
                        color,
                        0,
                        self.get_string_by_id(string_id.as_bytes()),
                    )
                    .send_to_player(self.net_server(), player_id);
                    tracing::trace!(
                        player_id,
                        delivery,
                        "уведомление сброса потенциала боевой феи отправлено"
                    );
                }
                effect @ BattleFairyPotentialResetEffect::PacketItemConsumed { .. } => {
                    let deliveries = self.send_battle_fairy_packet_consumption(&effect);
                    tracing::trace!(
                        player_id,
                        ?deliveries,
                        "расход предмета сброса потенциала боевой феи отправлен"
                    );
                }
                BattleFairyPotentialResetEffect::PropertiesChanged { player_id } => {
                    if let Some(player) = self.find_player(player_id) {
                        let delivery = self.send_player_properties_changed(player);
                        tracing::trace!(
                            player_id,
                            delivery,
                            "свойства после сброса потенциала боевой феи отправлены"
                        );
                    }
                }
                BattleFairyPotentialResetEffect::GoodsUpdated(update) => {
                    let delivery = self.send_battle_fairy_goods_update(&update);
                    tracing::trace!(
                        player_id = update.player_id,
                        delivery,
                        "предмет после сброса потенциала боевой феи обновлён"
                    );
                }
            }
        }
        tracing::debug!(player_id, ?report.outcome, "потенциал боевой феи сброшен");
        Some(())
    }

    /// Runtime entry point `CBattleFairyContainer::ResetSkill`, общий для
    /// script-functions распределения обычного/special skill и прямого caller-а
    /// с расходом reset item. RNG принадлежит одному `CGame` sequence.
    pub(crate) fn reset_battle_fairy_skill<Context>(
        &mut self,
        player_id: i32,
        position: i32,
        consume_item: bool,
        context: &mut Context,
    ) -> Option<BattleFairySkillResetReport>
    where
        Context: BattleFairySkillResetContext + OldClientGoodsCodec,
    {
        let enabled = self.globe_setup.battle_fairy_enabled();
        let mut report = {
            let (players, random_state, goods_factory, skill_factory) = (
                &mut self.players,
                &mut self.random_state,
                &self.goods_factory,
                &self.skill_factory,
            );
            let player = players.get_mut(&player_id)?;
            let mut random = |upper_bound| game_legacy_random(random_state, upper_bound);
            let mut encode_old_client = |goods: &CGoods| context.encode_goods_for_old_client(goods);
            player.reset_battle_fairy_skill(
                enabled,
                position,
                consume_item,
                goods_factory,
                skill_factory,
                &mut random,
                &mut encode_old_client,
            )
        };
        for effect in report.effects.take_all() {
            let GameEffect::BattleFairySkillReset(effect) = effect else {
                tracing::error!("журнал сброса навыка боевой феи содержит чужой эффект");
                continue;
            };
            match effect {
                BattleFairySkillResetEffect::Notification {
                    player_id,
                    string_id,
                    color,
                } => {
                    let delivery = colored_player_notice_message(
                        color,
                        0,
                        self.get_string_by_id(string_id.as_bytes()),
                    )
                    .send_to_player(self.net_server(), player_id);
                    tracing::trace!(
                        player_id,
                        delivery,
                        "уведомление сброса навыка боевой феи отправлено"
                    );
                }
                effect @ BattleFairySkillResetEffect::PacketItemConsumed { .. } => {
                    let deliveries =
                        context.publish_battle_fairy_skill_reset_packet_consumption(&effect);
                    tracing::trace!(
                        player_id,
                        ?deliveries,
                        "расход предмета сброса навыка боевой феи опубликован"
                    );
                }
                BattleFairySkillResetEffect::SkillRemoved(skill) => {
                    let mut message = CMessage::new(skill.message_type as i32);
                    add_legacy_c_string(message.base_mut(), &skill.skill_name);
                    let delivery = message.send_to_player(self.net_server(), skill.player_id);
                    tracing::trace!(
                        player_id = skill.player_id,
                        skill_id = skill.skill_id,
                        delivery,
                        "удаление навыка боевой феи отправлено"
                    );
                }
                BattleFairySkillResetEffect::SkillAdded(skill) => {
                    if let Some(message) = player_skill_learned_message(
                        skill.message_type,
                        skill.skill_id,
                        skill.skill_level,
                        skill.skill_level,
                        &skill.skill_name,
                        &self.skill_factory,
                        true,
                    ) {
                        let delivery = message.send_to_player(self.net_server(), skill.player_id);
                        tracing::trace!(
                            player_id = skill.player_id,
                            skill_id = skill.skill_id,
                            delivery,
                            "возвращённый навык боевой феи отправлен"
                        );
                    }
                }
                BattleFairySkillResetEffect::SelectedSkillLearned(skill) => {
                    if let Some(message) = player_skill_learned_message(
                        skill.message_type,
                        skill.skill_id,
                        skill.skill_level,
                        skill.skill_level,
                        &skill.skill_name,
                        &self.skill_factory,
                        false,
                    ) {
                        let delivery = message.send_to_player(self.net_server(), skill.player_id);
                        tracing::trace!(
                            player_id = skill.player_id,
                            skill_id = skill.skill_id,
                            delivery,
                            "выбранный навык боевой феи отправлен"
                        );
                    }
                }
                BattleFairySkillResetEffect::GoodsUpdated(update) => {
                    let delivery = self.send_battle_fairy_goods_update(&update);
                    tracing::trace!(
                        player_id = update.player_id,
                        delivery,
                        "предмет после сброса навыка боевой феи обновлён"
                    );
                }
            }
        }
        Some(report)
    }

    /// Начальный player/equipment участок goods-message `0x8FC29`.
    /// Отсутствующий либо не-BF headgear не запускает script и не шлёт ack.
    pub(crate) fn detach_battle_fairy_script_skills(&mut self, player_id: i32) -> Option<Vec<u32>> {
        let valid = self
            .find_player(player_id)?
            .war_soul_goods(&self.goods_factory)
            .is_some();
        if !valid {
            return None;
        }
        let (players, goods_factory, skill_factory) =
            (&mut self.players, &self.goods_factory, &self.skill_factory);
        Some(
            players
                .get_mut(&player_id)
                .expect("проверенный player остаётся в game map")
                .detach_battle_fairy_script_skills(goods_factory, skill_factory),
        )
    }

    /// Завершающий player/equipment участок `0x8FC29` после script mutation.
    /// Safe owner перечитывает equipped headgear вместо удержания native raw
    /// pointer через произвольный script callback.
    pub(crate) fn attach_battle_fairy_script_skills(&mut self, player_id: i32) {
        let skills = self
            .players
            .get_mut(&player_id)
            .map_or_else(Vec::new, |player| {
                player.attach_battle_fairy_script_skills(&self.goods_factory, &self.skill_factory)
            });
        for skill in &skills {
            if let Some(message) = player_skill_learned_message(
                skill.message_type,
                skill.skill_id,
                skill.skill_level,
                skill.skill_level,
                &skill.skill_name,
                &self.skill_factory,
                true,
            ) {
                let delivery = message.send_to_player(self.net_server(), skill.player_id);
                tracing::trace!(
                    player_id = skill.player_id,
                    skill_id = skill.skill_id,
                    delivery,
                    "сценарный навык боевой феи отправлен игроку"
                );
            }
        }
        tracing::debug!(
            player_id,
            skill_count = skills.len(),
            "сценарные навыки боевой феи подключены"
        );
    }

    /// Script `2249 / FairyExpUp`: enhancement хранит только shadow, поэтому
    /// mutation всегда разрешает исходный live goods. При созревании native
    /// owner сначала окончательно удаляет старый экземпляр из packet/equipment,
    /// затем пытается положить ripe replacement в packet; поздний отказ не
    /// откатывает уже выполненное удаление.
    pub(crate) fn fairy_exp_up_selected_goods<Context: GameContainerMessageRuntime>(
        &mut self,
        player_id: i32,
        experience: u32,
        context: &mut Context,
    ) -> bool {
        let Some((goods_id, source)) = self.players.get(&player_id).and_then(|player| {
            let goods_id = player.enhancement_selected_goods_id()?;
            let source = player.enhancement_original_container(0, goods_id)?;
            player
                .trade_source_goods(source.container_extend_id, source.goods_position, goods_id)
                .map(|_| (goods_id, source))
        }) else {
            return false;
        };

        let grow_log_enabled = self.log_system.fairy_grow_enabled();
        let egg_max_level = self.globe_setup.fairy_egg_max_level();
        let upgrade_rate = self.globe_setup.fairy_upgrade_rate();
        let mut remaining = experience;
        let (mut exp, ripe_id, update) = {
            let (players, factory, exp_config) =
                (&mut self.players, &self.goods_factory, &self.fairy_exp_conf);
            let Some(goods) = players
                .get_mut(&player_id)
                .and_then(|player| player.get_goods_by_id_mut(goods_id))
            else {
                return false;
            };
            let fairy_guid = goods.identity().ex_id.to_string().into_bytes();
            let fairy_name = goods.name().to_vec();
            let runtime = FairyExpRuntime {
                player_id,
                fairy_guid: &fairy_guid,
                fairy_name: &fairy_name,
                log_value: 1,
                suppress_grow_log: false,
                grow_log_enabled,
                egg_max_level,
                upgrade_rate,
            };
            let Ok(Some(exp)) =
                goods.fairy_exp_up(&mut remaining, runtime, |equip_level, level| {
                    exp_config.dw_exp_up(equip_level, level)
                })
            else {
                return false;
            };
            if exp.result <= FairyExpUpResult::None {
                return true;
            }
            if !goods.save_fairy_properties(factory).unwrap_or(false) {
                return false;
            }
            let ripe_id = (exp.result == FairyExpUpResult::ChangeState).then(|| {
                goods
                    .fairy_properties()
                    .expect("successful fairy state change сохраняет property owner")
                    .ripe_id
            });
            let update = ripe_id
                .is_none()
                .then(|| (goods.identity(), context.encode_goods_for_old_client(goods)));
            (exp, ripe_id, update)
        };

        self.deliver_fairy_exp_effects(&mut exp.effects);
        if let Some((goods, payload)) = update {
            let mut message = CMessage::new(0x0b_f918);
            message.add_long(player_id);
            message.base_mut().add_guid(goods.ex_id);
            message.add_ulong(payload.len() as u32);
            message.base_mut().add(&payload);
            let _ = message.send_to_player(self.net_server(), player_id);
            return true;
        }

        let Some(ripe_id) = ripe_id else {
            return true;
        };
        let Some(mut replacement) = self.create_goods_batch(ripe_id, 1).into_iter().next() else {
            return false;
        };
        let copied = self
            .players
            .get(&player_id)
            .and_then(|player| player.get_goods_by_id(goods_id))
            .is_some_and(|goods| {
                replacement
                    .copy_fairy_addon_properties_from(
                        goods,
                        &self.goods_factory,
                        |equip_level, level| self.fairy_exp_conf.dw_exp_up(equip_level, level),
                    )
                    .is_ok_and(|loaded| loaded)
            });
        if !copied {
            return false;
        }
        let Some(fairy) = replacement.fairy_properties_mut() else {
            return false;
        };
        fairy.fairy_state = 2;
        if !replacement
            .save_fairy_properties(&self.goods_factory)
            .unwrap_or(false)
        {
            return false;
        }

        let mut player = self
            .players
            .remove(&player_id)
            .expect("selected fairy player остаётся в game map");
        let old_identity = player
            .get_goods_by_id(goods_id)
            .expect("selected fairy проверена до replacement")
            .identity();
        let old_amount = player
            .get_goods_by_id(goods_id)
            .expect("selected fairy проверена до replacement")
            .amount();
        let removed = if source.container_extend_id == 1 {
            matches!(
                player.packet_mut().remove_goods(goods_id),
                Some(VolumeGoodsRemoveOutcome::Removed(
                    AmountLimitGoodsTaken::Removed(_)
                ))
            )
        } else if source.container_extend_id == 2 {
            let facts = {
                let goods = player
                    .get_goods_by_id(goods_id)
                    .expect("equipment fairy проверена до remove facts");
                context.enhancement_equipment_remove_facts(
                    &player,
                    goods,
                    self.globe_setup.pack_add_enabled(),
                )
            };
            let mut recompute =
                |player: &CPlayer| context.recompute_enhancement_player_properties(player);
            let mut report = player.remove_equipment_goods(
                goods_id,
                &self.goods_factory,
                &self.skill_factory,
                facts,
                &mut recompute,
            );
            drop(recompute);
            self.publish_player_equipment_remove_report(&mut report);
            matches!(report.outcome, EquipmentRemoveOutcome::Removed(_))
        } else {
            false
        };
        if !removed {
            let update = player
                .get_goods_by_id(goods_id)
                .map(|goods| (goods.identity(), context.encode_goods_for_old_client(goods)));
            self.players.insert(player_id, player);
            if let Some((goods, payload)) = update {
                let mut message = CMessage::new(0x0b_f918);
                message.add_long(player_id);
                message.base_mut().add_guid(goods.ex_id);
                message.add_ulong(payload.len() as u32);
                message.base_mut().add(&payload);
                let _ = message.send_to_player(self.net_server(), player_id);
            }
            return true;
        }

        let _ = player.enhancement_remove_shadow(goods_id);
        let _ = self.send_container_object_delete(player_id, &source, old_identity, old_amount);
        let (additions, _rejected) = player.add_script_fairy_goods_to_packet(
            vec![replacement],
            &self.goods_factory,
            &mut |goods| context.encode_goods_for_old_client(goods),
        );
        let mut goods_ai_ids = Vec::new();
        for addition in &additions {
            if let Some(position) = addition.position
                && matches!(addition.outcome, VolumeGoodsAddOutcome::Added(_))
                && let Some(goods) = player.packet().get_goods(position)
            {
                goods_ai_ids.push(goods.identity().ex_id);
            }
        }
        for goods_id in goods_ai_ids {
            Self::register_player_goods_ai(&mut player, &self.goods_factory, goods_id);
        }
        self.players.insert(player_id, player);
        for addition in &additions {
            let _ = self.send_player_packet_addition(addition);
        }
        true
    }

    /// Игровой владелец сценарного семейства `9400..9411`. Селектор и
    /// вычисление аргументов остаются в `CScript::RunFunction`; здесь замкнуты
    /// канонические мутации игрока и экипировки, RNG, клиентские сообщения и
    /// локальный журнал.
    pub(crate) fn run_battle_fairy_script_action<Context>(
        &mut self,
        script_player_id: Option<i32>,
        action: BattleFairyScriptAction,
        context: &mut Context,
    ) -> i32
    where
        Context: BattleFairyDeathContext + BattleFairySkillResetContext,
    {
        let target_id = |game: &Self, player_name: &[u8]| {
            if player_name.is_empty() {
                script_player_id.filter(|player_id| game.find_player(*player_id).is_some())
            } else {
                game.find_player_by_name(player_name)
                    .map(CPlayer::player_id)
            }
        };
        match action {
            BattleFairyScriptAction::GetFetchPower { player_name } => target_id(self, &player_name)
                .and_then(|player_id| self.find_player(player_id))
                .map_or(0, |player| player.fetch_power() as i32),
            BattleFairyScriptAction::GetSkillValue {
                player_name,
                position,
                value_id,
            } => target_id(self, &player_name)
                .and_then(|player_id| self.find_player(player_id))
                .and_then(|player| player.equipment().get_goods(10))
                .map_or(0, |goods| {
                    goods.addon_property_value(&self.goods_factory, GAP_BF_SKY + position, value_id)
                }),
            BattleFairyScriptAction::GetAttribute {
                player_name,
                attribute,
            } => {
                if !is_battle_fairy_script_attribute(attribute) {
                    return 0;
                }
                let stored = target_id(self, &player_name)
                    .and_then(|player_id| self.find_player(player_id))
                    .and_then(|player| player.equipment().get_goods(10))
                    .map_or(0, |goods| {
                        goods.addon_property_value(&self.goods_factory, attribute, 1)
                    });
                if matches!(attribute, GAP_BF_LEVEL..=GAP_BF_CURRENT_MAX_EXP)
                    || attribute == GAP_BF_PULLULATERATE
                {
                    stored
                } else {
                    (f64::from(stored) * 0.0001_f64) as i32
                }
            }
            BattleFairyScriptAction::AddSkill {
                player_name,
                skill_name,
                skill_level,
                position,
            } => {
                let Some(player_id) = target_id(self, &player_name) else {
                    return -1;
                };
                let skill_level = if skill_level == 0x09ff_fff9 {
                    1
                } else {
                    skill_level
                };
                let skill_id = self.skill_factory.query_skill_id(Some(&skill_name));
                if skill_id == 0
                    || !self.find_player(player_id).is_some_and(|player| {
                        player.equipment().get_goods(10).is_some_and(|goods| {
                            goods.addon_property_value(&self.goods_factory, GAP_BF_HP, 1) != 0
                        })
                    })
                {
                    return -1;
                }
                let Some(mutation) =
                    self.add_remote_player_skill(player_id, &skill_name, skill_level as u16)
                else {
                    return -1;
                };
                let legacy_return = i32::from(mutation.legacy_result);
                if legacy_return == 0 {
                    return 0;
                }
                let Some(position) = position.filter(|position| (0..=6).contains(position)) else {
                    return legacy_return;
                };
                let update = {
                    let player = self
                        .find_player_mut(player_id)
                        .expect("resolved battle-fairy script player остаётся в map");
                    let goods = player
                        .equipment_mut()
                        .get_goods_mut(10)
                        .expect("AddSkill guard сохранил slot 10");
                    let property = GAP_BF_SKY + position;
                    if position >= 3 {
                        let _ = goods.set_addon_property_value_core(property, 1, 0);
                        let _ = goods.set_addon_property_value_core(property, 2, 0);
                    }
                    let _ = goods.set_addon_property_value_core(property, 1, skill_level);
                    if position >= 3 {
                        let _ = goods.set_addon_property_value_core(property, 2, skill_id as i32);
                    }
                    crate::gameserver::appserver::container::cbattlefairycontainer::BattleFairyDefaultGoodsUpdate {
                        message_type: 0x0b_f918,
                        player_id,
                        goods: goods.identity(),
                        old_client_payload: context.encode_goods_for_old_client(goods),
                    }
                };
                let _ = self.send_battle_fairy_goods_update(&update);
                if let Some(initiator_id) = script_player_id {
                    if let Some(message) = player_skill_learned_message(
                        0x0b_f71d,
                        skill_id,
                        mutation.skill_level,
                        mutation.skill_level,
                        &skill_name,
                        &self.skill_factory,
                        true,
                    ) {
                        let _ = message.send_to_player(self.net_server(), initiator_id);
                    }
                    if let Some(player) = self.find_player(initiator_id) {
                        let account = player.account();
                        let skill_id_text = skill_id.to_string();
                        let skill_level_text = skill_level.to_string();
                        let text = format_legacy_text_fields(
                            self.get_string_by_id(b"ZHGS0039"),
                            &[
                                account,
                                skill_id_text.as_bytes(),
                                skill_level_text.as_bytes(),
                            ],
                            0xff,
                        );
                        put_string_to_file("BattleFairy", &text);
                    }
                }
                legacy_return
            }
            BattleFairyScriptAction::SetAttribute {
                player_name,
                attribute,
                value,
            } => {
                if !is_battle_fairy_script_attribute(attribute) {
                    return 0;
                }
                let resolved = target_id(self, &player_name);
                if let Some(player_id) = resolved {
                    let update = {
                        let (players, factory) = (&mut self.players, &self.goods_factory);
                        let Some(player) = players.get_mut(&player_id) else {
                            return 0;
                        };
                        let Some(goods) = player.equipment_mut().get_goods_mut(10) else {
                            return 0;
                        };
                        if matches!(attribute, GAP_BF_LEVEL..=GAP_BF_CURRENT_MAX_EXP) {
                            let _ = goods.set_addon_property_value_core(attribute, 1, value);
                        } else {
                            let scaled = i64::from(value).wrapping_mul(10_000);
                            if (GAP_BF_BRAVE..=GAP_BF_STRENGH).contains(&attribute) {
                                let balanced =
                                    i64::from(goods.addon_property_value(factory, attribute, 1))
                                        .wrapping_add(scaled)
                                        .wrapping_sub(i64::from(
                                            goods.addon_property_value(factory, attribute, 2),
                                        ));
                                let _ = goods.set_addon_property_value_core(attribute, 1, 0);
                                let _ = goods.set_addon_property_value_core(attribute, 2, 0);
                                let _ = goods.set_addon_property_value_core(
                                    attribute,
                                    1,
                                    clamp_battle_fairy_script_value(balanced),
                                );
                                let _ = goods.set_addon_property_value_core(
                                    attribute,
                                    2,
                                    scaled as i32,
                                );
                            } else {
                                let changed =
                                    i64::from(goods.addon_property_value(factory, attribute, 1))
                                        .wrapping_add(scaled);
                                let _ = goods.set_addon_property_value_core(
                                    attribute,
                                    1,
                                    clamp_battle_fairy_script_value(changed),
                                );
                            }
                        }
                        crate::gameserver::appserver::container::cbattlefairycontainer::BattleFairyDefaultGoodsUpdate {
                            message_type: 0x0b_f918,
                            player_id,
                            goods: goods.identity(),
                            old_client_payload: context.encode_goods_for_old_client(goods),
                        }
                    };
                    let _ = self.send_battle_fairy_goods_update(&update);
                }
                if let Some(initiator_id) = script_player_id {
                    if let Some(player) = self.find_player(initiator_id) {
                        let attribute_text = attribute.to_string();
                        let value_text = value.to_string();
                        let text = format_legacy_text_fields(
                            self.get_string_by_id(b"ZHGS0040"),
                            &[
                                player.account(),
                                attribute_text.as_bytes(),
                                value_text.as_bytes(),
                            ],
                            0xff,
                        );
                        put_string_to_file("BattleFairy", &text);
                    }
                }
                0
            }
            BattleFairyScriptAction::ResetSkill {
                player_name,
                position,
            } => {
                let Some(player_id) = target_id(self, &player_name) else {
                    return 0;
                };
                if self
                    .find_player(player_id)
                    .and_then(|player| player.equipment().get_goods(10))
                    .is_none()
                {
                    return 0;
                }
                let _ = self.reset_battle_fairy_skill(player_id, position, false, context);
                0
            }
            BattleFairyScriptAction::DeleteSkillSlot {
                player_name,
                position,
            } => {
                let Some(player_id) = target_id(self, &player_name) else {
                    return 0;
                };
                let update = {
                    let Some(player) = self.find_player_mut(player_id) else {
                        return 0;
                    };
                    let Some(goods) = player.equipment_mut().get_goods_mut(10) else {
                        return 0;
                    };
                    let property = GAP_BF_SKY + position;
                    if position >= 3 {
                        let _ = goods.set_addon_property_value_core(property, 2, 0);
                    }
                    let _ = goods.set_addon_property_value_core(property, 1, 0);
                    crate::gameserver::appserver::container::cbattlefairycontainer::BattleFairyDefaultGoodsUpdate {
                        message_type: 0x0b_f918,
                        player_id,
                        goods: goods.identity(),
                        old_client_payload: context.encode_goods_for_old_client(goods),
                    }
                };
                let _ = self.send_battle_fairy_goods_update(&update);
                0
            }
            BattleFairyScriptAction::Revive { player_name } => {
                let Some(player_id) = target_id(self, &player_name) else {
                    return 0;
                };
                let alive = self.find_player(player_id).is_some_and(|player| {
                    player.equipment().get_goods(10).is_some_and(|goods| {
                        goods.addon_property_value(&self.goods_factory, GAP_BF_HP, 1) > 0
                    })
                });
                if alive {
                    let text = self.get_string_by_id(b"ZHGS0041");
                    let _ = colored_player_notice_message(0xffff_ffff, 0, text)
                        .send_to_player(self.net_server(), player_id);
                    return 0;
                }
                let revived = {
                    let (players, factory) = (&mut self.players, &self.goods_factory);
                    players
                        .get_mut(&player_id)
                        .is_some_and(|player| player.revive_battle_fairy(factory))
                };
                if !revived {
                    return 0;
                }
                let update = self.find_player(player_id).and_then(|player| {
                    player.equipment().get_goods(10).map(|goods| {
                        crate::gameserver::appserver::container::cbattlefairycontainer::BattleFairyDefaultGoodsUpdate {
                            message_type: 0x0b_f918,
                            player_id,
                            goods: goods.identity(),
                            old_client_payload: context.encode_goods_for_old_client(goods),
                        }
                    })
                });
                if let Some(update) = update {
                    let _ = self.send_battle_fairy_goods_update(&update);
                }
                let _ = self.publish_player_states(player_id);
                1
            }
            BattleFairyScriptAction::AddExperience {
                player_name,
                experience,
            } => {
                if experience <= 0 {
                    return 0;
                }
                let Some(target_player_id) = target_id(self, &player_name) else {
                    return 0;
                };
                let Some(source_player_id) = script_player_id else {
                    return 0;
                };
                let mut remaining = experience as u32;
                let report_and_update = {
                    let (players, factory, exp_config) = (
                        &mut self.players,
                        &self.goods_factory,
                        &self.battle_fairy_exp_config,
                    );
                    let Some(goods) = players
                        .get_mut(&source_player_id)
                        .and_then(CPlayer::enhancement_selected_goods_mut)
                    else {
                        return 0;
                    };
                    if goods.addon_property_value(factory, GAP_BF_BATTLE_FAIRY, 1) != 1 {
                        return 0;
                    }
                    let facts = BattleFairyPlayerFacts {
                        player_id: target_player_id,
                    };
                    let Ok(Some(report)) = goods.battle_fairy_exp_up(
                        factory,
                        Some(facts),
                        &mut remaining,
                        |equip_level, level| exp_config.dw_exp_up(equip_level, level),
                    ) else {
                        return 0;
                    };
                    if report.result <= BattleFairyExpUpResult::None {
                        return 0;
                    }
                    let _ = goods.save_battle_fairy_property(factory);
                    let update =
                        crate::gameserver::appserver::container::cbattlefairycontainer::BattleFairyDefaultGoodsUpdate {
                            message_type: 0x0b_f918,
                            player_id: target_player_id,
                            goods: goods.identity(),
                            old_client_payload: context.encode_goods_for_old_client(goods),
                        };
                    (report, update)
                };
                let _ = self.send_battle_fairy_goods_update(&report_and_update.1);
                0
            }
            BattleFairyScriptAction::RecreateAttributes {
                player_name,
                mode,
                minimum,
                maximum,
            } => {
                let Some(target_player_id) = target_id(self, &player_name) else {
                    return 0;
                };
                let Some(source_player_id) = script_player_id else {
                    return 0;
                };
                let update = {
                    let (players, factory, random_state) = (
                        &mut self.players,
                        &self.goods_factory,
                        &mut self.random_state,
                    );
                    let Some(goods) = players
                        .get_mut(&source_player_id)
                        .and_then(CPlayer::enhancement_selected_goods_mut)
                    else {
                        return 0;
                    };
                    if !factory.recreate_battle_fairy_attributes(
                        goods,
                        mode,
                        minimum,
                        maximum,
                        |upper_bound| game_legacy_random(random_state, upper_bound),
                    ) {
                        return 0;
                    }
                    crate::gameserver::appserver::container::cbattlefairycontainer::BattleFairyDefaultGoodsUpdate {
                        message_type: 0x0b_f918,
                        player_id: target_player_id,
                        goods: goods.identity(),
                        old_client_payload: context.encode_goods_for_old_client(goods),
                    }
                };
                if let Some(player) = self.find_player(target_player_id) {
                    let _ = self.send_player_properties_changed(player);
                }
                let _ = self.send_battle_fairy_goods_update(&update);
                0
            }
        }
    }

    /// Runtime entry point уже декодированного `skillmessage 0x90001`.
    /// Player mutation и effects сохраняют native order: optional contend
    /// notice, безусловный `ClearEmotion 0xBF611`, authorization, socket
    /// reject либо очередь concrete `CPlayerAI`.
    pub(crate) fn request_player_skill(
        &mut self,
        player_id: i32,
        socket_id: i32,
        request: PlayerSkillRequest,
        facts: PlayerSkillRequestFacts,
    ) -> Option<()> {
        let journal = self.players.get_mut(&player_id).map(|player| {
            player.request_player_skill(socket_id, request, facts, &self.skill_factory)
        })?;
        self.apply_skill_effect_journal(journal);
        Some(())
    }

    pub(crate) fn request_item_skill(
        &mut self,
        player_id: i32,
        socket_id: i32,
        request: PlayerSkillRequest,
        skill_level: i32,
        facts: PlayerSkillRequestFacts,
    ) -> Option<()> {
        let journal = self.players.get_mut(&player_id).map(|player| {
            player.request_item_skill(socket_id, request, skill_level, facts, &self.skill_factory)
        })?;
        self.apply_skill_effect_journal(journal);
        Some(())
    }

    fn apply_skill_effect_journal(&mut self, mut journal: GameEffectJournal) {
        for effect in journal.take_all() {
            match effect {
                GameEffect::SkillNotification {
                    player_id,
                    string_id,
                    color,
                    message_type,
                } => {
                    let delivery = colored_player_notice_message(
                        color,
                        message_type,
                        self.get_string_by_id(string_id.as_bytes()),
                    )
                    .send_to_player(self.net_server(), player_id);
                    trace!(
                        player_id,
                        string_id, delivery, "Отправлено уведомление навыка"
                    );
                }
                GameEffect::ClearPlayerEmotion {
                    player_id,
                    region_id,
                } => {
                    let delivery = region_id
                        .and_then(|region_id| self.take_region_owner(region_id))
                        .and_then(|owner| {
                            let delivery = self.find_player(player_id).map(|player| {
                                let mut message = CMessage::new(0x0b_f611);
                                message.add_long(player.shape().identity().object_type);
                                message.add_long(player_id);
                                message.add_long(0);
                                self.send_player_around_excluding_self(
                                    owner.base(),
                                    player.shape(),
                                    player_id,
                                    &message,
                                )
                            });
                            self.restore_region_owner(owner);
                            delivery
                        });
                    trace!(
                        player_id,
                        ?region_id,
                        ?delivery,
                        "Очищена эмоция перед навыком"
                    );
                }
                GameEffect::SkillSocketReject {
                    socket_id,
                    message_type,
                    reason,
                    code,
                } => {
                    let mut message = CMessage::new(message_type as i32);
                    message.base_mut().add_byte(reason as u8);
                    message.base_mut().add_byte(code);
                    let delivery = message.send_to_socket(self.net_server(), socket_id);
                    trace!(
                        socket_id,
                        message_type, reason, code, delivery, "Отправлен отказ навыка"
                    );
                }
                GameEffect::QueuePlayerSkill {
                    player_id,
                    dispatch,
                } => {
                    let (
                        rejected,
                        interrupted_rage_level,
                        interrupted_flash,
                        interrupted_little_flash,
                    ) = {
                        let player = self
                            .players
                            .get_mut(&player_id)
                            .expect("skill dispatch сохраняет canonical player");
                        let changes_command = player.player_ai().next_player_skill() != Some(dispatch);
                        let interrupted_rage_level = (changes_command
                            && player.player_ai().rage().is_some())
                            .then(|| player.learned_skill_level(RAGE_SKILL_ID));
                        let interrupted_flash = changes_command && player.player_ai().flash().is_some();
                        let interrupted_little_flash = changes_command
                            .then_some(())
                            .and_then(|()| player.player_ai().little_flash().map(|state| state.skill_id()));
                        let interrupted_agility = player.player_ai().agility_family().is_some()
                            && changes_command;
                        let interrupted_delayed_skill = (player.player_ai().base_magic().is_some()
                            || player.player_ai().archery().is_some()
                            || player.player_ai().heartless_arrow().is_some()
                            || player.player_ai().heartless_arrow_area().is_some()
                            || player.player_ai().lighting_arrow().is_some()
                            || player.player_ai().lighting_arrow_2().is_some()
                            || player.player_ai().meteor_arrow_mass().is_some()
                            || player.player_ai().meteor_arrow().is_some()
                            || player.player_ai().rain_arrow().is_some()
                            || player.player_ai().poison_moth().is_some()
                            || player.player_ai().kerosene().is_some()
                            || player.player_ai().ignition().is_some()
                            || player.player_ai().blind().is_some()
                            || player.player_ai().blood_rose().is_some()
                            || player.player_ai().scorpion().is_some()
                            || player.player_ai().boa_lock().is_some()
                            || player.player_ai().falling_star().is_some()
                            || player.player_ai().explosive_arrow().is_some()
                            || player.player_ai().strike().is_some()
                            || player.player_ai().agility_family().is_some()
                            || player.player_ai().callosity().is_some()
                            || player.player_ai().ju_cut().is_some()
                            || player.player_ai().lightning_sword().is_some()
                            || player.player_ai().little_flash().is_some()
                            || player.player_ai().little_star().is_some()
                            || player.player_ai().path_projectile().is_some()
                            || player.player_ai().sprite_burn().is_some()
                            || player.player_ai().wide_arc_attack().is_some()
                            || player.player_ai().lord_fast_attack().is_some()
                            || player.player_ai().thunder_slash().is_some()
                            || player.player_ai().pillar().is_some()
                            || player.player_ai().rush().is_some()
                            || player.player_ai().rush_2().is_some()
                            || player.player_ai().knock_out().is_some())
                            && changes_command;
                        if interrupted_delayed_skill {
                            player.set_skill_moveable(true);
                            if interrupted_agility {
                                player.set_skill_moveable(true);
                            }
                            player.set_current_skill_id(None);
                        }
                        let rejected = player.player_ai_mut().queue_player_skill(dispatch);
                        (rejected, interrupted_rage_level, interrupted_flash, interrupted_little_flash)
                    };
                    if let Some(level) = interrupted_rage_level {
                        end_player_rage(self, player_id, level);
                        let interrupted_at_ms = game_tick_milliseconds();
                        if let Some(player) = self.players.get_mut(&player_id) {
                            player.player_ai_mut().mark_rage_used(interrupted_at_ms);
                        }
                    }
                    if interrupted_flash || interrupted_little_flash.is_some() {
                        let interrupted_at_ms = game_tick_milliseconds();
                        if let Some(player) = self.players.get_mut(&player_id) {
                            if interrupted_flash { player.player_ai_mut().mark_flash_used(interrupted_at_ms); }
                            if let Some(skill_id) = interrupted_little_flash {
                                player
                                    .player_ai_mut()
                                    .mark_little_flash_used(skill_id, interrupted_at_ms);
                            }
                        }
                    }
                    for _ in 0..rejected {
                        let mut message = CMessage::new(0x000b_fe01);
                        message.add_byte(0);
                        message.add_byte(2);
                        let _delivery = message.send_to_player(self.net_server(), player_id);
                    }
                    trace!(
                        player_id,
                        ?dispatch,
                        rejected,
                        "Навык поставлен в очередь AI"
                    );
                }
                GameEffect::QueueBattleFairySkill {
                    player_id,
                    dispatch,
                } => {
                    let replaced = self
                        .players
                        .get_mut(&player_id)
                        .expect("battle-fairy dispatch сохраняет canonical player")
                        .player_ai_mut()
                        .queue_battle_fairy_skill(dispatch);
                    trace!(
                        player_id,
                        ?dispatch,
                        replaced,
                        "Навык боевой феи поставлен в очередь AI"
                    );
                }
                GameEffect::RegionTaxPrompt { .. }
                | GameEffect::RegionTaxResult { .. }
                | GameEffect::BattleFairyCombine(_)
                | GameEffect::BattleFairySummon(_)
                | GameEffect::BattleFairyFollow(_)
                | GameEffect::PlayerEquipmentRemove(_)
                | GameEffect::PlayerEquipmentAdd(_)
                | GameEffect::BattleFairyEquipmentMutation(_)
                | GameEffect::BattleFairyPotentialAllocation(_)
                | GameEffect::BattleFairyUpgrade(_)
                | GameEffect::BattleFairyPotentialReset(_)
                | GameEffect::BattleFairySkillReset(_)
                | GameEffect::FairyGrowLog(_) => {
                    warn!("Чужой эффект попал в локальный журнал навыка");
                }
            }
        }
    }

    /// Точный `CPKSys::OnFirstAttack` для уже достигнутых контактных навыков.
    /// В отличие от `OnFirstSkill`, участник страны с identity `7` становится
    /// преступником только после десяти убийств; World-аудит и packet перехода
    /// остаются в том же порядке.
    pub(crate) fn player_on_first_attack<Context: GameClockContext>(
        &mut self,
        attacker_id: i32,
        victim_id: i32,
        region_id: Option<i32>,
        context: &mut Context,
    ) -> Option<()> {
        self.player_on_first_attack_at(
            attacker_id, victim_id, region_id, None, context,
        )
    }

    /// Вариант `CPKSys::OnFirstAttack` из общего `CMoveShape::OnBeenAttacked`:
    /// security выбирается по уже перемещённой цели, а не по атакующему.
    pub(crate) fn player_on_first_attack_at_victim<Context: GameClockContext>(
        &mut self,
        attacker_id: i32,
        victim_id: i32,
        region_id: Option<i32>,
        context: &mut Context,
    ) -> Option<()> {
        let security_position = self.find_player(victim_id).and_then(|victim| {
            Some((victim.shape().get_tile_x().ok()?, victim.shape().get_tile_y().ok()?))
        })?;
        self.player_on_first_attack_at(
            attacker_id, victim_id, region_id, Some(security_position), context,
        )
    }

    pub(crate) fn player_on_first_attack_at_position<Context: GameClockContext>(
        &mut self,
        attacker_id: i32,
        victim_id: i32,
        region_id: Option<i32>,
        security_position: (i32, i32),
        context: &mut Context,
    ) -> Option<()> {
        self.player_on_first_attack_at(
            attacker_id, victim_id, region_id, Some(security_position), context,
        )
    }

    fn player_on_first_attack_at<Context: GameClockContext>(
        &mut self,
        attacker_id: i32,
        victim_id: i32,
        region_id: Option<i32>,
        security_position: Option<(i32, i32)>,
        context: &mut Context,
    ) -> Option<()> {
        let region_id = region_id?;
        let (
            victim_is_badman, security, city_war_enemies, faction_war_enemies,
            gods_battle_region, same_gods_battle_faction, same_country,
            attacker_kill_count, victim_level, victim_x, victim_y,
        ) = {
            let attacker = self.find_player(attacker_id)?;
            let victim = self.find_player(victim_id)?;
            if attacker.server_region_id() != Some(region_id)
                || victim.server_region_id() != Some(region_id)
            {
                return None;
            }
            let victim_x = victim.shape().get_tile_x().ok()?;
            let victim_y = victim.shape().get_tile_y().ok()?;
            let attacker_x = attacker.shape().get_tile_x().ok()?;
            let attacker_y = attacker.shape().get_tile_y().ok()?;
            let owner = self.find_region(region_id)?;
            let (security_x, security_y) = security_position.unwrap_or((attacker_x, attacker_y));
            let security = owner.get_security(security_x, security_y).ok()?;
            let attacker_faction = attacker.faction_id();
            let victim_faction = victim.faction_id();
            (
                victim.is_badman(self.globe_setup.pk_count_per_kill()),
                security,
                attacker_faction > 0 && victim_faction > 0
                    && (attacker.is_city_war_enemy_faction_member(victim_faction)
                        || victim.is_city_war_enemy_faction_member(attacker_faction)),
                attacker_faction > 0 && victim_faction > 0
                    && (attacker.is_enemy_faction_member(victim_faction)
                        || victim.is_enemy_faction_member(attacker_faction)),
                owner.is_gods_battle(),
                attacker.gods_battle_faction() == victim.gods_battle_faction(),
                attacker.country() == victim.country(),
                attacker.kill_count(),
                victim.level(),
                victim_x,
                victim_y,
            )
        };
        let attacker_country_identity = self.player_country_identity(attacker_id);
        let disposition = CPKSys::on_first_attack(FirstAttackPkFacts {
            victim_is_badman,
            security,
            city_war_enemies,
            faction_war_enemies,
            gods_battle_region,
            same_gods_battle_faction,
            same_country,
            attacker_country_identity,
            attacker_kill_count,
        });
        let pk_count_per_kill = self.globe_setup.pk_count_per_kill();
        let mut criminal_timestamp_refreshed = false;
        let mut criminal_state_started = false;
        let mut criminal_delivery = None;
        if disposition == FirstContactPkDisposition::EnterCriminalState {
            if let Some(started) = self.find_player_mut(attacker_id)?
                .enter_criminal_state(pk_count_per_kill, || context.now_milliseconds())
            {
                criminal_timestamp_refreshed = true;
                criminal_state_started = started;
                if started {
                    let mut message = CMessage::new(0x000b_f60e);
                    message.add_long(attacker_id);
                    message.add_byte(1);
                    criminal_delivery = self.send_player_shape_around(attacker_id, None, &message);
                }
            }
        }
        let eligible = matches!(
            disposition,
            FirstContactPkDisposition::AllowedCombat | FirstContactPkDisposition::EnterCriminalState
        );
        let world_log_delivery = (eligible && self.log_system.player_killer_log_enabled()).then(|| {
            let mut message = CMessage::new(0x0006_020a);
            message.add_byte(0);
            message.add_long(victim_id);
            message.add_long(attacker_id);
            message.add_ulong(u32::from(victim_level));
            message.add_long(victim_x);
            message.add_long(victim_y);
            message.send(self, false)
        });
        tracing::debug!(
            attacker_id,
            victim_id,
            region_id,
            ?disposition,
            criminal_timestamp_refreshed,
            criminal_state_started,
            ?criminal_delivery,
            ?world_log_delivery,
            "обработан первый контактный удар по игроку"
        );
        Some(())
    }

    /// Reached `CPKSys::OnFirstSkill` caller: вызывается AI execution owner-ом
    /// только после подтверждённого первого контакта object-target skill.
    pub(crate) fn player_on_first_skill<Context: GameClockContext>(
        &mut self,
        attacker_id: i32,
        victim_id: i32,
        region_id: Option<i32>,
        context: &mut Context,
    ) -> Option<()> {
        let region_id = region_id?;
        let victim = self.find_player(victim_id)?;
        let security_x = victim.shape().get_tile_x().ok()?;
        let security_y = victim.shape().get_tile_y().ok()?;
        self.player_on_first_skill_at(
            attacker_id,
            victim_id,
            region_id,
            security_x,
            security_y,
            context,
        )
    }

    pub(crate) fn player_on_first_skill_at_position<Context: GameClockContext>(
        &mut self,
        attacker_id: i32,
        victim_id: i32,
        region_id: i32,
        security_x: i32,
        security_y: i32,
        context: &mut Context,
    ) -> Option<()> {
        self.player_on_first_skill_at(
            attacker_id,
            victim_id,
            region_id,
            security_x,
            security_y,
            context,
        )
    }

    fn player_on_first_skill_at<Context: GameClockContext>(
        &mut self,
        attacker_id: i32,
        victim_id: i32,
        region_id: i32,
        security_x: i32,
        security_y: i32,
        context: &mut Context,
    ) -> Option<()> {
        let attacker = self.find_player(attacker_id)?;
        let victim = self.find_player(victim_id)?;
        if attacker.server_region_id() != Some(region_id)
            || victim.server_region_id() != Some(region_id)
        {
            return None;
        }
        let victim_x = victim.shape().get_tile_x().ok()?;
        let victim_y = victim.shape().get_tile_y().ok()?;
        let owner = self.find_region(region_id)?;
        let security = owner.get_security(security_x, security_y).ok()?;
        let gods_battle_region = owner.is_gods_battle();
        let attacker_faction = attacker.faction_id();
        let victim_faction = victim.faction_id();
        let city_war_enemies = attacker_faction > 0
            && victim_faction > 0
            && (attacker.is_city_war_enemy_faction_member(victim_faction)
                || victim.is_city_war_enemy_faction_member(attacker_faction));
        let faction_war_enemies = attacker_faction > 0
            && victim_faction > 0
            && (attacker.is_enemy_faction_member(victim_faction)
                || victim.is_enemy_faction_member(attacker_faction));
        let disposition = CPKSys::on_first_skill(FirstSkillPkFacts {
            victim_is_badman: victim.is_badman(self.globe_setup.pk_count_per_kill()),
            security,
            city_war_enemies,
            faction_war_enemies,
            gods_battle_region,
            same_gods_battle_faction: attacker.gods_battle_faction()
                == victim.gods_battle_faction(),
            same_country: attacker.country() == victim.country(),
        });
        let victim_level = victim.level();
        let pk_count_per_kill = self.globe_setup.pk_count_per_kill();
        let mut criminal_timestamp_refreshed = false;
        let mut criminal_state_started = false;
        let mut criminal_delivery = None;
        if disposition == FirstContactPkDisposition::EnterCriminalState {
            if let Some(started) = self
                .find_player_mut(attacker_id)?
                .enter_criminal_state(pk_count_per_kill, || context.now_milliseconds())
            {
                criminal_timestamp_refreshed = true;
                criminal_state_started = started;
                if started {
                    let mut message = CMessage::new(0x000b_f60e);
                    message.add_long(attacker_id);
                    message.add_byte(1);
                    criminal_delivery = self.send_player_shape_around(attacker_id, None, &message);
                }
            }
        }
        let eligible = matches!(
            disposition,
            FirstContactPkDisposition::AllowedCombat | FirstContactPkDisposition::EnterCriminalState
        );
        let world_log_delivery =
            (eligible && self.log_system.player_killer_log_enabled()).then(|| {
                let mut message = CMessage::new(0x0006_020a);
                message.add_byte(0);
                message.add_long(victim_id);
                message.add_long(attacker_id);
                message.add_ulong(u32::from(victim_level));
                message.add_long(victim_x);
                message.add_long(victim_y);
                message.send(self, false)
            });
        tracing::debug!(
            attacker_id,
            victim_id,
            region_id,
            ?disposition,
            criminal_timestamp_refreshed,
            criminal_state_started,
            ?criminal_delivery,
            ?world_log_delivery,
            "обработан первый удар навыком по игроку"
        );
        Some(())
    }

    pub(crate) fn player_base_attackable(&self, attacker_id: i32, victim_id: i32) -> bool {
        let Some(attacker) = self.find_player(attacker_id) else {
            return false;
        };
        let Some(victim) = self.find_player(victim_id) else {
            return false;
        };
        if attacker_id == victim_id
            || victim.is_dead()
            || victim.is_god_mode()
            || victim.is_nation_war_player_weak()
        {
            return false;
        }
        let Some(region_id) = attacker
            .server_region_id()
            .filter(|region_id| victim.server_region_id() == Some(*region_id))
        else {
            return false;
        };
        let Some(region) = self.find_region(region_id) else {
            return false;
        };
        let (Ok(attacker_x), Ok(attacker_y), Ok(victim_x), Ok(victim_y)) = (
            attacker.shape().get_tile_x(),
            attacker.shape().get_tile_y(),
            victim.shape().get_tile_x(),
            victim.shape().get_tile_y(),
        ) else {
            return false;
        };
        if region.base().no_pk
            || region.get_security(attacker_x, attacker_y).ok() == Some(RegionSecurity::SAFE)
            || region.get_security(victim_x, victim_y).ok() == Some(RegionSecurity::SAFE)
        {
            return false;
        }
        let faction_enemies = attacker.is_enemy_faction_member(victim.faction_id())
            || attacker.is_city_war_enemy_faction_member(victim.faction_id());
        if faction_enemies {
            return true;
        }
        let permissions = attacker.pk_permissions();
        let victim_badman = victim.is_badman(self.globe_setup.pk_count_per_kill());
        let mut attackable = true;
        if !permissions.player && !victim_badman && attacker.country() == victim.country() {
            attackable = false;
        }
        if !permissions.teammate && victim.team_id() != 0 && attacker.team_id() == victim.team_id()
        {
            attackable = false;
        }
        if !permissions.guild_member
            && ((victim.faction_id() != 0 && attacker.faction_id() == victim.faction_id())
                || (victim.union_id() != 0 && attacker.union_id() == victim.union_id()))
        {
            attackable = false;
        }
        if !permissions.criminal && victim_badman {
            attackable = false;
        }
        if !permissions.country && !victim_badman && attacker.country() != victim.country() {
            attackable = false;
        }
        if region.is_gods_battle()
            && !permissions.player
            && attacker.gods_battle_faction() == victim.gods_battle_faction()
            && !victim_badman
        {
            attackable = false;
        }
        attackable
    }

    pub(crate) fn guard_monster_attackable(
        &self,
        attacker_id: i32,
        region_id: i32,
        property: &crate::setup::monsterlist::MonsterProperties,
    ) -> bool {
        if property.kind != 5 {
            return true;
        }
        let Some(player) = self.find_player(attacker_id) else {
            return false;
        };
        let Some(region) = self.find_region(region_id) else {
            return false;
        };
        let permissions = player.pk_permissions();
        match property.ai as i32 {
            8..=9 => permissions.player,
            10..=11 => region.symbol_is_attackable(),
            13 => {
                if u32::from(player.country()) == property.race {
                    permissions.player
                } else {
                    permissions.country
                }
            }
            14 => u32::from(player.country()) != property.race && permissions.country,
            15..=16 => {
                if player.country() == region.base().country {
                    permissions.player
                } else {
                    permissions.country
                }
            }
            17..=18 => {
                property.ai as i32 - 17
                    != self
                        .country_war_sys
                        .get_war_camp(i32::from(player.country()))
                    && permissions.country
            }
            23 => {
                if player.gods_battle_faction() as u32 == property.race {
                    permissions.player
                } else {
                    true
                }
            }
            _ => true,
        }
    }

    /// Exact `PetLikeTargetAttackableByMonster` policy for a carriage target.
    pub(crate) fn carriage_attackable_by_monster(
        &self,
        attacker_property: &crate::setup::monsterlist::MonsterProperties,
        attacker_tamed: bool,
        attacker_master: crate::gameserver::appserver::masterinfo::MasterInfo,
        target_master: crate::gameserver::appserver::masterinfo::MasterInfo,
        region_id: i32,
    ) -> bool {
        let target_player = (target_master.master_type == PLAYER_TYPE
            && target_master.master_id != 0)
            .then_some(target_master.master_id);
        let Some(target_player) = target_player else {
            return true;
        };
        if attacker_tamed {
            return (attacker_master.master_type != PLAYER_TYPE || attacker_master.master_id == 0)
                || self.player_base_attackable(attacker_master.master_id, target_player);
        }
        if attacker_property.kind != 5 {
            return true;
        }
        if matches!(attacker_property.ai as i32, 10..=11) {
            let Some(player) = self.find_player(target_player) else {
                return true;
            };
            let Some(region) = self.find_region(region_id) else {
                return true;
            };
            return !((player.faction_id() != 0
                && player.faction_id() == region.base().owned_city_faction())
                || (player.union_id() != 0
                    && player.union_id() == region.base().owned_city_union()));
        }
        self.guard_monster_attackable(target_player, region_id, attacker_property)
    }

    fn apply_guard_monster_first_attack(
        &mut self,
        attacker_id: i32,
        region_id: i32,
        property: &crate::setup::monsterlist::MonsterProperties,
        now_ms: u32,
    ) {
        if property.kind != 5 {
            return;
        }
        let starts_criminal = match property.ai as i32 {
            8..=9 => true,
            13..=14 | 19..=21 => self
                .find_player(attacker_id)
                .is_some_and(|player| u32::from(player.country()) == property.race),
            15..=16 => self.find_player(attacker_id).is_some_and(|player| {
                self.find_region(region_id)
                    .is_some_and(|region| player.country() == region.base().country)
            }),
            23 => self
                .find_player(attacker_id)
                .is_some_and(|player| player.gods_battle_faction() as u32 == property.race),
            _ => false,
        };
        if !starts_criminal {
            return;
        }
        let pk_count_per_kill = self.globe_setup.pk_count_per_kill();
        let started = self
            .find_player_mut(attacker_id)
            .and_then(|player| player.enter_criminal_state(pk_count_per_kill, || now_ms));
        if started == Some(true) {
            let mut message = CMessage::new(0x000b_f60e);
            message.add_long(attacker_id);
            message.add_byte(1);
            let _ = self.send_player_shape_around(attacker_id, None, &message);
        }
    }

    pub(crate) fn player_base_attack_level_block(
        &self,
        attacker_id: i32,
        victim_id: i32,
    ) -> Option<(&'static [u8], u32)> {
        let attacker = self.find_player(attacker_id)?;
        let victim = self.find_player(victim_id)?;
        let region_id = attacker
            .server_region_id()
            .filter(|region_id| victim.server_region_id() == Some(*region_id))?;
        let region = self.find_region(region_id)?.base();
        if attacker_id == victim_id || region.war_region_type != 0 {
            return None;
        }
        let (national_limit, enemy_limit) = self.globe_setup.player_attack_level_limits();
        if victim.country() == region.country {
            if victim.country() == attacker.country() {
                if i32::from(victim.level()) <= national_limit {
                    return Some((b"GS0160", national_limit as u32));
                }
                if i32::from(attacker.level()) <= national_limit {
                    return Some((b"GS0161", national_limit as u32));
                }
            } else if i32::from(victim.level()) <= enemy_limit {
                return Some((b"GS0162", enemy_limit as u32));
            }
        } else if attacker.country() == region.country
            && i32::from(attacker.level()) <= national_limit
        {
            return Some((b"GS0161", national_limit as u32));
        }
        None
    }

    pub(crate) fn send_base_attack_level_block(
        &self,
        player_id: i32,
        string_id: &[u8],
        limit: u32,
    ) {
        let text = format_single_legacy_u32(self.get_string_by_id(string_id), limit, 255);
        let mut message = CMessage::new(0x000b_f807);
        message.add_ulong(0xffff_0000);
        add_legacy_c_string(message.base_mut(), &text);
        let _ = message.send_to_player(self.net_server(), player_id);
    }

    pub(crate) fn enter_player_combat_state(&mut self, player_id: i32) {
        let fight_timer = self.globe_setup.fight_state_timer_ms();
        let (transition, had_auto_protect) = self
            .find_player_mut(player_id)
            .map(|player| {
                let transition = player.enter_combat_state(fight_timer);
                let had_state = player.script_move_state_count(STATE_AUTO_PROTECT) != 0;
                (transition, had_state)
            })
            .unzip();
        if had_auto_protect == Some(true) {
            // `EnterCombatState` вызывает `End` после установки боевого
            // счётчика и до публикации `0xBF607`.
            let _ = self.end_script_auto_protect_state(player_id);
        }
        if let Some(transition) = transition {
            let mut state = CMessage::new(0x000b_f607);
            state.add_long(transition.player_id);
            state.add_long(1);
            let _ = self.send_player_shape_around(player_id, None, &state);
        }
    }

    fn send_base_attack_failure(&self, player_id: i32, action: u8) -> i32 {
        let mut message = CMessage::new(0x000b_fe01);
        message.add_byte(0);
        message.add_byte(action);
        message.send_to_player(self.net_server(), player_id)
    }

    pub(crate) fn release_reciprocal_player_target(
        &mut self,
        player_id: i32,
        target: ShapeIdentity,
    ) {
        let mut interrupted_rage_level = None;
        let mut interrupted_flash = false;
        let mut interrupted_little_flash = None;
        let released = self.find_player_mut(player_id).is_some_and(|player| {
            let interrupted_agility = player.player_ai().agility_family().is_some();
            if player.player_ai().rage().is_some() {
                interrupted_rage_level = Some(player.learned_skill_level(RAGE_SKILL_ID));
            }
            interrupted_flash = player.player_ai().flash().is_some();
            interrupted_little_flash = player.player_ai().little_flash().map(|state| state.skill_id());
            let interrupted_delayed_skill = player.player_ai().base_magic().is_some()
                || player.player_ai().archery().is_some()
                || player.player_ai().heartless_arrow().is_some()
                || player.player_ai().heartless_arrow_area().is_some()
                || player.player_ai().lighting_arrow().is_some()
                || player.player_ai().lighting_arrow_2().is_some()
                || player.player_ai().meteor_arrow_mass().is_some()
                || player.player_ai().meteor_arrow().is_some()
                || player.player_ai().rain_arrow().is_some()
                || player.player_ai().poison_moth().is_some()
                || player.player_ai().kerosene().is_some()
                || player.player_ai().ignition().is_some()
                || player.player_ai().blind().is_some()
                || player.player_ai().blood_rose().is_some()
                || player.player_ai().scorpion().is_some()
                || player.player_ai().boa_lock().is_some()
                || player.player_ai().falling_star().is_some()
                || player.player_ai().explosive_arrow().is_some()
                || player.player_ai().strike().is_some()
                || player.player_ai().agility_family().is_some()
                || player.player_ai().callosity().is_some()
                || player.player_ai().mosou().is_some()
                || player.player_ai().ghost_cut().is_some()
                || player.player_ai().knight_cut().is_some()
                || player.player_ai().army_break().is_some()
                || player.player_ai().rage().is_some()
                || player.player_ai().rage_break().is_some()
                || player.player_ai().fury().is_some()
                || player.player_ai().flash().is_some()
                || player.player_ai().swallow().is_some()
                || player.player_ai().leaf_cut().is_some()
                || player.player_ai().ju_cut().is_some()
                || player.player_ai().lightning_sword().is_some()
                || player.player_ai().little_flash().is_some()
                || player.player_ai().little_star().is_some()
                || player.player_ai().path_projectile().is_some()
                || player.player_ai().sprite_burn().is_some()
                || player.player_ai().wide_arc_attack().is_some()
                || player.player_ai().lord_fast_attack().is_some()
                || player.player_ai().thunder_slash().is_some()
                || player.player_ai().pillar().is_some()
                || player.player_ai().rush().is_some()
                || player.player_ai().rush_2().is_some()
                || player.player_ai().knock_out().is_some();
            let released = player.player_ai_mut().release_object_target(target);
            if released {
                if interrupted_delayed_skill {
                    player.set_skill_moveable(true);
                    if interrupted_agility {
                        player.set_skill_moveable(true);
                    }
                }
                player.set_current_skill_id(None);
            }
            released
        });
        if released {
            if let Some(level) = interrupted_rage_level {
                end_player_rage(self, player_id, level);
                let interrupted_at_ms = game_tick_milliseconds();
                if let Some(player) = self.find_player_mut(player_id) {
                    player.player_ai_mut().mark_rage_used(interrupted_at_ms);
                }
            }
            if interrupted_flash || interrupted_little_flash.is_some() {
                let interrupted_at_ms = game_tick_milliseconds();
                if let Some(player) = self.find_player_mut(player_id) {
                    if interrupted_flash { player.player_ai_mut().mark_flash_used(interrupted_at_ms); }
                    if let Some(skill_id) = interrupted_little_flash {
                        player
                            .player_ai_mut()
                            .mark_little_flash_used(skill_id, interrupted_at_ms);
                    }
                }
            }
            let _ = self.send_base_attack_failure(player_id, 2);
        }
    }

    pub(crate) fn append_base_attack_tail(
        message: &mut CMessage,
        attack: &AttackInformation,
    ) {
        message
            .base_mut()
            .add_char(if attack.critical { 1 } else { 0 });
        message
            .base_mut()
            .add_char(if attack.blast_attack { 1 } else { 0 });
        message.add_long(attack.skill_id as i32);
        message.add_byte(attack.skill_level);
    }

    pub(crate) fn applied_attack_damage(
        attack: &AttackInformation,
        target_health: u32,
        target_mana: u32,
    ) -> (u32, u32) {
        (
            attack.hp_damage().min(target_health),
            attack.mp_damage().min(target_mana),
        )
    }

    pub(crate) fn append_hurt_damage_records(
        message: &mut CMessage,
        health_damage: u32,
        mana_damage: u32,
    ) {
        message.add_byte(u8::from(health_damage != 0) + u8::from(mana_damage != 0));
        if health_damage != 0 {
            message.add_byte(0);
            message.add_ulong(health_damage);
        }
        if mana_damage != 0 {
            message.add_byte(1);
            message.add_ulong(mana_damage);
        }
    }

    fn damage_player_equipment<Runtime: GameMainLoopRuntime>(
        &mut self,
        player_id: i32,
        position: u32,
        runtime: &mut Runtime,
    ) {
        let fray = self.globe_setup.goods_durability_fray();
        let (old, current, identity, payload) = {
            let (players, factory) = (&mut self.players, &self.goods_factory);
            let Some(player) = players.get_mut(&player_id) else {
                return;
            };
            let Some(goods) = player.equipment_mut().get_goods_mut(position) else {
                return;
            };
            let maximum = goods.addon_property_value(
                factory,
                crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_GOODS_MAXIMUM_DURABILITY,
                1,
            );
            let old = goods.addon_property_value(
                factory,
                crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_GOODS_MAXIMUM_DURABILITY,
                2,
            );
            if maximum <= 0 || old == 0 {
                return;
            }
            let current = old.wrapping_sub(fray);
            if !goods.set_addon_property_value_first_core(
                crate::gameserver::appserver::goods::cgoodsbaseproperties::GAP_GOODS_MAXIMUM_DURABILITY,
                2,
                current,
            ) {
                return;
            }
            let mut payload = Vec::new();
            if !goods.serialize_for_old_client(
                &mut payload,
                factory,
                self.globe_setup.da_kong_key(),
            ) {
                return;
            }
            (old, current, goods.identity().ex_id, payload)
        };
        if current < 1 {
            let mut update = CMessage::new(0x000b_f918);
            update.add_long(player_id);
            update.base_mut().add_guid(identity);
            update.add_ulong(payload.len() as u32);
            update.base_mut().add(&payload);
            let _ = update.send_to_player(self.net_server(), player_id);
            if let Some(properties) = self
                .find_player(player_id)
                .map(|player| runtime.recompute_enhancement_player_properties(player))
            {
                let _ = self.apply_recomputed_player_properties(player_id, properties);
                if let Some(player) = self.find_player(player_id) {
                    let _ = self.send_player_properties_changed(player);
                }
            }
        } else if old / 100 != current / 100 {
            let mut durability = CMessage::new(0x000b_f90c);
            durability.add_byte(position as u8);
            durability.add_ulong(current as u32);
            let _ = durability.send_to_player(self.net_server(), player_id);
        }
    }

    pub(crate) fn damage_player_weapon<Runtime: GameMainLoopRuntime>(
        &mut self,
        player_id: i32,
        runtime: &mut Runtime,
    ) {
        self.damage_player_equipment(player_id, 2, runtime);
    }

    fn drop_monster_goods<Runtime: MonsterDeathContext>(
        &mut self,
        region_id: i32,
        monster_original_name: &[u8],
        monster_level: i32,
        origin_x: i32,
        origin_y: i32,
        beneficiary_id: i32,
        runtime: &mut Runtime,
    ) {
        let Some(drop_list) = self
            .monster_drop_registry
            .get(monster_original_name)
            .cloned()
        else {
            return;
        };
        let beneficiary = self
            .find_player(beneficiary_id)
            .map(|player| (player.level(), player.team_id()));
        let mut drop_offset = 0usize;
        for drop in drop_list.drops {
            let mut maximum_odds = drop.maximum_odds;
            if drop.level_attenuation != 0.0
                && let Some((beneficiary_level, _)) = beneficiary
            {
                let level_delta = i32::from(beneficiary_level) - monster_level;
                if level_delta > 0 {
                    let attenuation = (level_delta as f32 * drop.level_attenuation)
                        .min(drop.level_attenuation_limit);
                    let remaining = 1.0 - attenuation;
                    if remaining > 0.0 {
                        maximum_odds = (maximum_odds as f32 / remaining).round_ties_even() as i32;
                    } else {
                        continue;
                    }
                }
            }
            if maximum_odds == 0 {
                continue;
            }
            let odds = (drop.odds as f32 * self.globe_setup.monster_drop_goods_scale())
                .round_ties_even() as i32;
            if odds <= game_legacy_random(&mut self.random_state, maximum_odds) {
                continue;
            }
            let amount = if drop.goods_index as u32 == self.goods_factory.get_gold_coin_index() {
                let difference = drop.maximum_money.wrapping_sub(drop.minimum_money);
                let spread = difference.wrapping_abs();
                game_legacy_random(&mut self.random_state, spread).wrapping_add(drop.minimum_money)
                    as u32
            } else {
                1
            };
            let mut created = self.create_goods_batch(drop.goods_index as u32, amount);
            for mut goods in created.drain(..) {
                if drop.level > 0 {
                    let (factory, random_state) = (&self.goods_factory, &mut self.random_state);
                    let _ = factory.upgrade_equipment(&mut goods, drop.level, |upper_bound| {
                        game_legacy_random(random_state, upper_bound)
                    });
                }
                let old_client_payload = runtime.encode_goods_for_old_client(&goods);
                let item_amount = goods.amount();
                let particular_attribute =
                    goods.addon_property_value(&self.goods_factory, GAP_PARTICULAR_ATTRIBUTE, 1)
                        as u32;
                let identity = goods.identity();
                let now_ms = runtime.now_milliseconds();
                let Some(mut owner) = self.take_region_owner(region_id) else {
                    return;
                };
                let position =
                    owner
                        .base()
                        .get_drop_goods_position(origin_x, origin_y, drop_offset);
                let Ok(Some((tile_x, tile_y, destination_position))) = position else {
                    self.restore_region_owner(owner);
                    continue;
                };
                drop_offset = drop_offset.wrapping_add(1);
                let (area_width, area_height) = self.area_dimensions();
                let added = owner.base_mut().add_owned_ground_goods(
                    goods,
                    tile_x,
                    tile_y,
                    particular_attribute,
                    now_ms,
                    area_width,
                    area_height,
                    runtime,
                );
                if added.is_err() {
                    self.restore_region_owner(owner);
                    continue;
                }
                if let Some((_, team_id)) = beneficiary {
                    owner.base_mut().set_ground_goods_protection(
                        identity.ex_id,
                        beneficiary_id,
                        team_id,
                        now_ms,
                    );
                }
                self.restore_region_owner(owner);

                let mut appeared = CS2CContainerObjectMove::default();
                appeared.set_operation(ContainerObjectMoveOperation::NewObject);
                appeared.set_destination_container(200, region_id, destination_position);
                appeared.set_destination_object(GOODS_TYPE, identity.ex_id);
                appeared.set_destination_object_amount(item_amount);
                appeared.set_object_stream(old_client_payload);
                let _ = self.send_shape_position_around(
                    region_id,
                    origin_x,
                    origin_y,
                    &appeared.message(),
                );
            }
        }
    }

    fn add_player_experience<Runtime: MonsterDeathContext>(
        &mut self,
        player_id: i32,
        experience_gain: u32,
        runtime: &mut Runtime,
    ) -> bool {
        if experience_gain == 0 {
            return false;
        }
        let (previous_experience, previous_vigour) = match self.find_player(player_id) {
            Some(player) => (player.experience(), player.vigour()),
            None => return false,
        };
        let raw_vigour = f64::from(self.globe_setup.exp_to_vigour_x())
            * f64::from(experience_gain.wrapping_add(600))
            * 0.30103
            - f64::from(self.globe_setup.exp_to_vigour_y());
        let vigour_gain = if raw_vigour <= 0.0 {
            0
        } else {
            (raw_vigour.round_ties_even() as u32).min(self.globe_setup.maximum_vigour_once())
        };
        let Some(player) = self.find_player_mut(player_id) else {
            return false;
        };
        player.set_experience(previous_experience.wrapping_add(experience_gain));
        player.set_vigour_clamped(previous_vigour.wrapping_add(vigour_gain));
        let mutation = PlayerAutoProgress {
            player_id,
            sampled_at_ms: runtime.now_milliseconds(),
            experience_gain,
            vigour_gain,
            previous_experience,
            current_experience: player.experience(),
            previous_vigour,
            current_vigour: player.vigour(),
        };
        let _ = self.finish_player_auto_progress(mutation, runtime);
        true
    }

    fn increase_player_continuous_kill<Runtime: MonsterDeathContext>(
        &mut self,
        player_id: i32,
        runtime: &mut Runtime,
    ) -> Option<u32> {
        let (_, hit_time_ms, _, _) = self.globe_setup.monster_continuous_kill_parameters();
        let hit_levels = self.hit_level_setup.entries().to_vec();
        let update = self.find_player_mut(player_id)?.increase_continuous_kill(
            runtime.now_milliseconds(),
            hit_time_ms,
            &hit_levels,
        );
        if update.bonus_experience != 0 {
            let _ = self.add_player_experience(player_id, update.bonus_experience, runtime);
        }
        if let Some(top_log) = update.new_top_log {
            let mut message = CMessage::new(0x000b_f706);
            message.add_short(top_log as i16);
            let _ = message.send_to_player(self.net_server(), player_id);
        }
        let mut message = CMessage::new(0x000b_f707);
        message.add_ulong(update.amount);
        let _ = message.send_to_player(self.net_server(), player_id);
        Some(update.amount)
    }

    fn increase_player_followers_experience(
        &mut self,
        player_id: i32,
        region_id: i32,
        experience: u32,
    ) {
        let pets = self
            .find_player(player_id)
            .map(|player| player.active_pets().to_vec())
            .unwrap_or_default();
        if pets.is_empty() {
            return;
        }
        let configurations: Vec<_> = pets
            .iter()
            .filter(|pet| pet.object_type == MONSTER_TYPE)
            .filter_map(|pet| {
                let monster = self
                    .find_region(region_id)?
                    .base()
                    .find_monster_by_id(pet.id)?;
                let property = self
                    .find_monster_property_by_origin_name(monster.base_property_key()?)?
                    .clone();
                let (experience_factor, _) =
                    self.globe_setup.pet_progression(monster.pet_progress().0)?;
                let next_factors = self
                    .globe_setup
                    .pet_progression(monster.pet_progress().0.wrapping_add(1))
                    .map(|(_, factors)| factors);
                Some((pet.id, property, experience_factor, next_factors))
            })
            .collect();
        if configurations.is_empty() {
            return;
        }
        let share = experience / configurations.len() as u32;
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return;
        };
        for (pet_id, property, experience_factor, next_factors) in configurations {
            let Some(pet) = owner.base_mut().find_monster_by_id_mut(pet_id) else {
                continue;
            };
            let Some(update) =
                pet.increase_pet_experience(share, &property, experience_factor, next_factors)
            else {
                continue;
            };
            let shape = pet.move_shape().shape().clone();
            let mut message = CMessage::new(0x000c_0203);
            message.add_long(MONSTER_TYPE);
            message.add_long(pet_id);
            message.add_ulong(update.level);
            message.add_ulong(update.experience);
            message.add_ulong(update.maximum_hp);
            message.add_ulong(update.hit_points);
            let _ = self.send_game_shape_around(owner.base(), &shape, None, &message);
        }
        self.restore_region_owner(owner);
    }

    fn award_monster_experience<Runtime: MonsterDeathContext>(
        &mut self,
        beneficiary_id: i32,
        first_attacker_id: i32,
        region_id: i32,
        monster: &crate::setup::monsterlist::MonsterProperties,
        runtime: &mut Runtime,
    ) {
        let Some(beneficiary) = self.find_player(beneficiary_id) else {
            return;
        };
        let team_id = beneficiary.team_id();
        let mut recipients: Vec<i32> = if team_id <= 0 {
            (!beneficiary.is_dead())
                .then_some(beneficiary_id)
                .into_iter()
                .collect()
        } else {
            self.players
                .values()
                .filter(|player| {
                    player.team_id() == team_id
                        && player.server_region_id() == Some(region_id)
                        && !player.is_dead()
                })
                .map(CPlayer::player_id)
                .collect()
        };
        if recipients.is_empty() {
            return;
        }
        recipients.sort_unstable();
        let average_level = recipients
            .iter()
            .filter_map(|id| self.find_player(*id))
            .map(|player| f32::from(player.level()))
            .sum::<f32>()
            / recipients.len() as f32;
        let alive_amount = recipients.len() as u32;
        let region_scale = self
            .find_region(region_id)
            .map_or(1.0, |owner| owner.base().region.exp_scale());
        let (ratios, exp_difference, exp_limit, amerce, amerce_limit, amerce_start, exp_scale) =
            self.globe_setup.monster_experience_parameters();
        let (hit_base_level, _, hit_prize, maximum_hit_prize) =
            self.globe_setup.monster_continuous_kill_parameters();

        for player_id in recipients {
            let Some(player) = self.find_player(player_id) else {
                continue;
            };
            let player_level = player.level();
            let quota = if team_id <= 0 {
                monster.experience
            } else {
                let factor = ((1.0 - exp_difference * (average_level - f32::from(player_level)))
                    / alive_amount as f32)
                    .max(exp_limit);
                (monster.experience as f32
                    * factor
                    * ratios[(alive_amount.saturating_sub(1).min(7)) as usize])
                    .round_ties_even() as u32
            };
            let level_delta = i32::from(player_level) - monster.level as i32;
            let amerce_level = level_delta.wrapping_sub(amerce_start).max(0);
            let corrective_factor = (1.0 - amerce_level as f32 * amerce).max(amerce_limit);
            let mut corrected = (quota as f32 * corrective_factor)
                .round_ties_even()
                .max(0.0) as u32;
            corrected = corrected.min(monster.experience);
            if level_delta.max(0) <= hit_base_level && player_id == first_attacker_id {
                let amount = player.continuous_kill_amount();
                if amount != 0 {
                    let prize = (amount as f32 * hit_prize).min(maximum_hit_prize);
                    corrected = (corrected as f32 * (prize + 1.0))
                        .round_ties_even()
                        .max(0.0) as u32;
                }
            }
            let improve_multiplier = player.improve_experience_multiplier();
            let experience_gain =
                ((corrected as f32) * exp_scale * region_scale * improve_multiplier)
                    .round_ties_even()
                    .max(0.0) as u32;
            if self.add_player_experience(player_id, experience_gain, runtime) {
                self.increase_player_followers_experience(player_id, region_id, experience_gain);
            }
        }
    }

    fn finish_monster_kill_effects<Runtime: MonsterDeathContext>(
        &mut self,
        region_id: i32,
        monster_id: i32,
        killer_id: i32,
        target_x: i32,
        target_y: i32,
        monster_property: &crate::setup::monsterlist::MonsterProperties,
        runtime: &mut Runtime,
    ) {
        let monster_snapshot = self.find_region(region_id).and_then(|owner| {
            let monster = owner.base().find_monster_by_id(monster_id)?;
            Some((
                monster.first_attack_player_id(),
                monster
                    .killed_by()
                    .filter(|attack| attack.attacker_type == PLAYER_TYPE)
                    .map_or(killer_id, |attack| attack.attacker_id),
                monster.original_name().to_vec(),
                monster.script_file().to_vec(),
            ))
        });
        let Some((first_attacker, killing_player, original_name, script_file)) = monster_snapshot
        else {
            return;
        };
        let beneficiary_id = [first_attacker, killing_player]
            .into_iter()
            .find(|candidate| {
                self.find_player(*candidate).is_some_and(|player| {
                    if player.is_dead() || player.server_region_id() != Some(region_id) {
                        return false;
                    }
                    let (Ok(x), Ok(y)) = (player.shape().get_tile_x(), player.shape().get_tile_y())
                    else {
                        return false;
                    };
                    real_distance(x, y, target_x, target_y)
                        <= self.globe_setup.contribution_distance_limit()
                })
            });
        if let Some(beneficiary_id) = beneficiary_id {
            let (hit_base_level, _, _, _) = self.globe_setup.monster_continuous_kill_parameters();
            if i32::from(self.find_player(beneficiary_id).map_or(0, CPlayer::level))
                - hit_base_level
                <= monster_property.level as i32
            {
                let _ = self.increase_player_continuous_kill(beneficiary_id, runtime);
            }
            self.award_monster_experience(
                beneficiary_id,
                first_attacker,
                region_id,
                monster_property,
                runtime,
            );
        }
        self.drop_monster_goods(
            region_id,
            &original_name,
            monster_property.level as i32,
            target_x,
            target_y,
            beneficiary_id.unwrap_or(0),
            runtime,
        );
        let context = ScriptExecutionContext {
            player_id: beneficiary_id,
            region_id: Some(region_id),
            died_monster_index: Some(monster_property.index),
            drop_goods_position: Some((target_x, target_y)),
            ..ScriptExecutionContext::default()
        };
        if !script_file.is_empty() {
            let _ = self.queue_script_file(&script_file, context);
        }
        let _ = self.queue_script_file(b"scripts/monster/monster_all.script", context);
    }

    pub(crate) fn damage_player_armor<Runtime: GameMainLoopRuntime>(
        &mut self,
        player_id: i32,
        runtime: &mut Runtime,
    ) {
        const POSITIONS: [u32; 10] = [0, 1, 3, 4, 9, 10, 12, 13, 14, 15];
        let probabilities = self.globe_setup.armor_waste_probabilities();
        let rolls: [i32; 10] =
            std::array::from_fn(|_| game_legacy_random(&mut self.random_state, 100));
        for ((position, probability), roll) in POSITIONS.into_iter().zip(probabilities).zip(rolls) {
            if roll < probability {
                self.damage_player_equipment(player_id, position, runtime);
            }
        }
    }

    /// Reached `CPet::OnSearchEnemy`: active-mode pet scans type `600` around
    /// its master and transfers the nearest attackable wild target into the
    /// same canonical attack state used by command and retaliation paths.
    fn run_owned_pet_active_search(&mut self, region_id: i32, monster_id: i32) -> bool {
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return false;
        };
        let selected =
            execute_owned_pet_active_search(self, owner.base_mut(), region_id, monster_id);
        self.restore_region_owner(owner);
        selected
    }

    /// Reached one-second/lifecycle tail `CPet::OnSchedule`: master lookup,
    /// safe-cell mode, return-to-master, 6-hour warnings, wild timeout и
    /// `Evanish -> owner unlink -> BF504` остаются одним runtime проходом.
    fn run_owned_pet_lifecycle<Runtime: GameMainLoopRuntime>(
        &mut self,
        region_id: i32,
        monster_id: i32,
        runtime: &mut Runtime,
    ) -> Option<bool> {
        const MONSTER_TAMING_SKILL_ID: u32 = 0xD4;
        const SKILL_USAGE_PET_AMOUNT_LIMIT: u32 = 31_001;

        let mut owner = self.take_region_owner(region_id)?;
        let snapshot = owner
            .base()
            .find_monster_by_id(monster_id)
            .and_then(|monster| {
                if !monster.is_tamed() {
                    return None;
                }
                let property =
                    self.find_monster_property_by_origin_name(monster.base_property_key()?)?;
                Some((
                    monster.master_info(),
                    monster.shape_view(property)?,
                    monster.move_shape().shape().clone(),
                    CMonster::figure(property),
                    monster.display_name().to_vec(),
                    CMoveShape::is_died(monster.hit_points()),
                ))
            });
        let Some((master, pet_view, pet_shape, pet_figure, pet_name, pet_dead)) = snapshot else {
            self.restore_region_owner(owner);
            return None;
        };
        if pet_dead {
            self.restore_region_owner(owner);
            return Some(false);
        }

        let master_snapshot = (master.master_type == PLAYER_TYPE && master.master_id != 0)
            .then(|| self.find_player(master.master_id))
            .flatten()
            .filter(|player| player.server_region_id() == Some(region_id))
            .and_then(|player| {
                Some((
                    player.shape_view()?,
                    player.learned_skill_level(MONSTER_TAMING_SKILL_ID),
                    player.active_pets().len() as u32,
                ))
            });
        let master_present = master_snapshot.is_some();
        let master_close = master_snapshot.is_some_and(|(view, _, _)| view.distance(pet_view) < 33);
        let reclaimable = master_snapshot.is_some_and(|(_, level, pet_count)| {
            level != 0
                && self
                    .skill_factory
                    .query_skill_base_properties(MONSTER_TAMING_SKILL_ID, level)
                    .is_some_and(|properties| {
                        pet_count < properties.query_property(SKILL_USAGE_PET_AMOUNT_LIMIT)
                    })
        });
        let safe_cell = owner
            .base()
            .region
            .get_security(pet_view.tile_x, pet_view.tile_y)
            .ok()
            == Some(RegionSecurity::SAFE);
        let outcome = owner
            .base_mut()
            .find_monster_by_id_mut(monster_id)
            .expect("pet snapshot принадлежит вынутому region owner-у")
            .tick_pet_lifecycle(PetLifecycleFacts {
                now_ms: runtime.now_milliseconds(),
                wild_time_ms: self.globe_setup.pet_wild_time_ms(),
                master_present,
                master_close,
                safe_cell,
                reclaimable,
            });

        if let Some(notice) = outcome.notice
            && master_present
        {
            let text = match notice {
                PetLifecycleNotice::AgeWarning => self.get_string_by_id(b"GS0010").to_vec(),
                PetLifecycleNotice::AgeExpired => {
                    format_legacy_text_fields(self.get_string_by_id(b"GS0011"), &[&pet_name], 0x3ff)
                }
                PetLifecycleNotice::BecameWild => {
                    format_legacy_text_fields(self.get_string_by_id(b"GS0012"), &[&pet_name], 0x3ff)
                }
            };
            let _ = colored_player_notice_message(0xffff_0000, 0xffff_ffff, &text)
                .send_to_player(self.net_server(), master.master_id);
        }
        if outcome.reclaim
            && let Some(player) = self.find_player_mut(master.master_id)
            && !player
                .active_pets()
                .iter()
                .any(|pet| pet.object_type == MONSTER_TYPE && pet.id == monster_id)
        {
            player.add_active_pet(MONSTER_TYPE, monster_id, i32::from(pet_figure.get(0)));
        }
        if outcome.vanish {
            if master_present && let Some(player) = self.find_player_mut(master.master_id) {
                let _ = player.remove_active_pet(MONSTER_TYPE, monster_id);
            }
            owner
                .base_mut()
                .find_monster_by_id_mut(monster_id)
                .expect("lifecycle pet остаётся owned до region delete tail")
                .evanish_pet();
            let mut vanished = CMessage::new(0x000b_f504);
            vanished.add_long(MONSTER_TYPE);
            vanished.add_long(monster_id);
            vanished.add_long(0);
            vanished
                .base_mut()
                .add(&pet_shape.get_pos_x().to_bits().to_le_bytes());
            vanished
                .base_mut()
                .add(&pet_shape.get_pos_y().to_bits().to_le_bytes());
            let _ = self.send_game_shape_around(owner.base(), &pet_shape, None, &vanished);
        }
        self.restore_region_owner(owner);
        Some(outcome.vanish)
    }

    /// Reached `CPet::OnFallowingSchedule`: pet slot определяет устойчивую
    /// точку позади master-а; близкий pet идёт туда обычным `BF605`, а далёкий
    /// переносится в свободную клетку `7x7` с exact `BF603` ordering.
    fn run_owned_pet_follow<Runtime: GameMainLoopRuntime>(
        &mut self,
        region_id: i32,
        monster_id: i32,
        runtime: &mut Runtime,
    ) -> bool {
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return false;
        };
        let handled =
            execute_owned_pet_follow(self, owner.base_mut(), region_id, monster_id, runtime);
        self.restore_region_owner(owner);
        handled
    }

    /// Reached `CCarriage::OnSchedule`: following/staying movement, one-second
    /// master rebinding, duplicate-owner eviction and disappearance timeout
    /// execute against the same live player/region/monster owners.
    fn run_owned_carriage_lifecycle<Runtime: GameMainLoopRuntime>(
        &mut self,
        region_id: i32,
        monster_id: i32,
        runtime: &mut Runtime,
    ) -> bool {
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return false;
        };
        let snapshot = owner
            .base()
            .find_monster_by_id(monster_id)
            .and_then(|monster| {
                let property = self
                    .find_monster_property_by_origin_name(monster.base_property_key()?)?
                    .clone();
                monster.is_carriage(&property).then(|| {
                    (
                        property,
                        monster.move_shape().shape().clone(),
                        monster.hit_points(),
                        monster.move_shape().is_moveable(),
                        monster.master_info(),
                        monster.carriage_action(),
                    )
                })
            });
        let Some((property, carriage_shape, health, moveable, master, action)) = snapshot else {
            self.restore_region_owner(owner);
            return false;
        };
        let now_ms = runtime.now_milliseconds();
        let master_snapshot = (master.master_type == PLAYER_TYPE && master.master_id != 0)
            .then(|| self.find_player(master.master_id))
            .flatten()
            .filter(|player| player.server_region_id() == Some(region_id))
            .map(|player| (player.shape().clone(), player.active_carriage_id()));
        let master_present = master_snapshot.is_some();
        let mut master_owns = master_snapshot
            .as_ref()
            .is_some_and(|(_, carriage_id)| *carriage_id == monster_id);
        let master_owns_other = master_snapshot
            .as_ref()
            .is_some_and(|(_, carriage_id)| *carriage_id != 0 && *carriage_id != monster_id);

        let mut vanish_reason = CMoveShape::is_died(health).then_some(3);
        let mut vanish = vanish_reason.is_some();
        if !vanish {
            let movement = plan_carriage_movement(
                action,
                moveable,
                &carriage_shape,
                master_snapshot.as_ref().map(|(shape, _)| shape),
                self.globe_setup.carriage_stop_distance() as i32,
            );
            match movement {
                CarriageMovementPlan::None => {}
                CarriageMovementPlan::Move { x, y } => {
                    if let Some(around) = GameServerAroundRuntime::new(
                        self,
                        &self.session_factory,
                        self.area_width,
                        self.area_height,
                    ) {
                        let _ = owner.base_mut().move_owned_monster(
                            monster_id,
                            x,
                            y,
                            0,
                            CMonster::figure(&property),
                            self.area_width,
                            self.area_height,
                            &around,
                        );
                    }
                }
                CarriageMovementPlan::Wait => {
                    if master_owns {
                        let _ = colored_player_notice_message(
                            0xffff_ffff,
                            0,
                            self.get_string_by_id(b"GS0008"),
                        )
                        .send_to_player(self.net_server(), master.master_id);
                    }
                    if let Some(carriage) = owner.base_mut().find_monster_by_id_mut(monster_id) {
                        carriage.set_carriage_action(CARRIAGE_STAYING);
                    }
                }
                CarriageMovementPlan::Follow => {
                    if master_owns {
                        let _ = colored_player_notice_message(
                            0xffff_ffff,
                            0,
                            self.get_string_by_id(b"GS0009"),
                        )
                        .send_to_player(self.net_server(), master.master_id);
                    }
                    if let Some(carriage) = owner.base_mut().find_monster_by_id_mut(monster_id) {
                        carriage.set_carriage_action(CARRIAGE_FOLLOWING);
                    }
                }
            }
        }

        let master_close = master_snapshot.as_ref().is_some_and(|(master_shape, _)| {
            carriage_shape
                .get_tile_x()
                .ok()
                .zip(carriage_shape.get_tile_y().ok())
                .zip(
                    master_shape
                        .get_tile_x()
                        .ok()
                        .zip(master_shape.get_tile_y().ok()),
                )
                .is_some_and(|((cx, cy), (mx, my))| {
                    real_distance(cx, cy, mx, my)
                        <= self.globe_setup.carriage_stop_distance() as i32
                })
        });
        let master_outcome = if vanish {
            Default::default()
        } else {
            owner
                .base_mut()
                .find_monster_by_id_mut(monster_id)
                .expect("повозка остаётся у вынутого region owner-а")
                .tick_carriage_master(CarriageMasterFacts {
                    now_ms,
                    disappear_time_ms: self.globe_setup.carriage_disappear_time_ms(),
                    master_present,
                    master_owns_other,
                    master_close,
                })
        };
        if !vanish && master_outcome.checked {
            if master_outcome.rebound
                && let Some(player) = self.find_player_mut(master.master_id)
            {
                player.bind_active_carriage(monster_id);
                master_owns = true;
            }
            if let Some(reason) = master_outcome.vanish_reason {
                vanish = true;
                vanish_reason = Some(reason);
            }
        }

        if vanish {
            if let Some(reason) = vanish_reason {
                let _ = self.send_carriage_log_snapshot(
                    master.master_id,
                    property.index,
                    region_id,
                    carriage_shape.get_tile_x().unwrap_or_default(),
                    carriage_shape.get_tile_y().unwrap_or_default(),
                    reason,
                );
            }
            if master_owns {
                if !CMoveShape::is_died(health) {
                    let _ = colored_player_notice_message(
                        0xffff_ffff,
                        0,
                        self.get_string_by_id(b"GS0007"),
                    )
                    .send_to_player(self.net_server(), master.master_id);
                }
                if let Some(player) = self.find_player_mut(master.master_id) {
                    player.clear_active_carriage(monster_id);
                }
            }
            if let Some(carriage) = owner.base_mut().find_monster_by_id_mut(monster_id) {
                carriage.stage_for_delete();
            }
            let mut vanished = CMessage::new(0x000b_f504);
            vanished.add_long(MONSTER_TYPE);
            vanished.add_long(monster_id);
            vanished.add_long(0);
            vanished
                .base_mut()
                .add(&carriage_shape.get_pos_x().to_bits().to_le_bytes());
            vanished
                .base_mut()
                .add(&carriage_shape.get_pos_y().to_bits().to_le_bytes());
            let _ = self.send_game_shape_around(owner.base(), &carriage_shape, None, &vanished);
        }
        if let Some(carriage) = owner.base_mut().find_monster_by_id_mut(monster_id) {
            carriage.set_base_attack_owned_tick(true);
        }
        self.restore_region_owner(owner);
        true
    }

    /// Исполняет достигнутую начальную часть `CSummonedCreature::AI`: смерть и
    /// строгое истечение срока вызывают `CMoveShape::Evanish` до обычного ИИ
    /// монстра.
    fn run_owned_summoned_creature_lifecycle(
        &mut self,
        region_id: i32,
        monster_id: i32,
        now_ms: u32,
    ) -> Option<bool> {
        let mut owner = self.take_region_owner(region_id)?;
        let snapshot = owner
            .base()
            .find_monster_by_id(monster_id)
            .and_then(|monster| {
                monster
                    .is_summoned_creature()
                    .then(|| {
                        (
                            monster.move_shape().shape().clone(),
                            monster.tick_summoned_creature(now_ms),
                        )
                    })
            });
        let Some((shape, tick)) = snapshot else {
            self.restore_region_owner(owner);
            return None;
        };
        let vanish = tick == Some(SummonedCreatureTick::Vanish);
        if vanish {
            if let Some(monster) = owner.base_mut().find_monster_by_id_mut(monster_id) {
                monster.stage_for_delete();
            }
            let mut message = CMessage::new(0x000b_f504);
            message.add_long(MONSTER_TYPE);
            message.add_long(monster_id);
            message.add_long(0);
            message.base_mut().add(&shape.get_pos_x().to_bits().to_le_bytes());
            message.base_mut().add(&shape.get_pos_y().to_bits().to_le_bytes());
            let _ = self.send_game_shape_around(owner.base(), &shape, None, &message);
        }
        self.restore_region_owner(owner);
        Some(vanish)
    }

    fn apply_monster_attack_deaths<Runtime: GameMainLoopRuntime>(
        &mut self,
        region_id: i32,
        deaths: Vec<MonsterAttackDeath>,
        runtime: &mut Runtime,
    ) {
        for death in deaths {
            let blow = match death {
                MonsterAttackDeath::Player(killing_blow) => {
                    let _ = self.player_on_death(killing_blow, runtime);
                    continue;
                }
                MonsterAttackDeath::Monster(blow) => blow,
            };
            let _ = self.gods_battle_monster_died(
                region_id,
                blow.victim_id,
                MONSTER_TYPE,
                blow.attacker_id,
            );
            let _ = self.monster_on_died(region_id, blow.victim_id, blow.master_id, runtime);
            self.finish_monster_kill_effects(
                region_id,
                blow.victim_id,
                blow.master_id,
                blow.target_x,
                blow.target_y,
                &blow.property,
                runtime,
            );
            let mut exit = CMessage::new(0x000b_f504);
            exit.add_long(MONSTER_TYPE);
            exit.add_long(blow.victim_id);
            exit.add_long(0);
            exit.add_ulong(blow.pos_x_bits);
            exit.add_ulong(blow.pos_y_bits);
            let _ = self.send_shape_position_around(
                region_id,
                blow.target_x,
                blow.target_y,
                &exit,
            );
            if let Some(mut owner) = self.take_region_owner(region_id) {
                owner.base_mut().finish_owned_monster_death(blow.victim_id);
                self.restore_region_owner(owner);
            }
        }
    }

    /// Тонко координирует владельца региона для самостоятельного ИИ слабого
    /// существа; поиск, потеря цели и направление отхода остаются в его модуле-владельце.
    fn run_owned_puniness_creature<Runtime: GameMainLoopRuntime>(
        &mut self,
        region_id: i32,
        monster_id: i32,
        runtime: &mut Runtime,
    ) -> bool {
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return false;
        };
        let handled = execute_owned_puniness_creature(
            self,
            owner.base_mut(),
            monster_id,
            runtime,
        );
        self.restore_region_owner(owner);
        handled
    }

    /// Достигнутый путь `CMonsterAI/CPet::OnSchedule` для
    /// `0x2bd/0x2d1/0x2ef/0x197/0x191/0x198/0x199/0x19a/0x19b/0x19c/0x19d/0x19e/0x19f/0x1a0/0x1a1/0x1a2/0x1a3/0x1a4/0x1a5/0x1a6/0x1a7/0x1f5/0x1f6/0x1f7/0x1f8/0x1f9/0x1fa`,
    /// включая их полностью достигнутые
    /// многокомандные списки с исходным взвешенным выбором:
    /// ответный удар, поиск и преследование агрессивного ИИ `0/3`, атака
    /// питомцем дикого монстра либо разрешённого политикой игрока. `false`
    /// оставляет сторожевые, бездействующие и списки с недостигнутыми навыками
    /// внешнему ИИ.
    fn run_owned_monster_base_attack<Runtime: GameMainLoopRuntime>(
        &mut self,
        region_id: i32,
        monster_id: i32,
        runtime: &mut Runtime,
    ) -> bool {
        let Some(mut owner) = self.take_region_owner(region_id) else {
            return false;
        };
        let mut deaths = Vec::new();
        let mut range_dispatch = None;
        let mut wide_arc_dispatch = None;
        let mut projectile_dispatch = None;
        let handled = execute_owned_monster_base_attack(
            self,
            owner.base_mut(),
            monster_id,
            runtime,
            &mut deaths,
            &mut range_dispatch,
            &mut wide_arc_dispatch,
            &mut projectile_dispatch,
        );
        let _ = synchronize_jiumai_target_loss(owner.base_mut(), monster_id);
        if let Some(monster) = owner.base_mut().find_monster_by_id_mut(monster_id) {
            monster.set_base_attack_owned_tick(handled);
        }
        self.restore_region_owner(owner);
        self.apply_monster_attack_deaths(region_id, deaths, runtime);
        if let Some(dispatch) = wide_arc_dispatch {
            'cells: for (tile_x, tile_y) in dispatch.cells.iter().copied() {
                let Some(owner) = self.take_region_owner(region_id) else {
                    break 'cells;
                };
                let candidates = wide_arc_attack_cell_candidates(
                    self,
                    owner.base(),
                    &dispatch,
                    tile_x,
                    tile_y,
                );
                self.restore_region_owner(owner);
                for identity in candidates {
                    let Some(mut owner) = self.take_region_owner(region_id) else {
                        break 'cells;
                    };
                    let mut deaths = Vec::new();
                    let applied = execute_owned_wide_arc_attack_target(
                        self,
                        owner.base_mut(),
                        &dispatch,
                        identity,
                        runtime,
                        &mut deaths,
                    );
                    self.restore_region_owner(owner);
                    if applied {
                        self.apply_monster_attack_deaths(region_id, deaths, runtime);
                    }
                }
            }
            if let Some(mut owner) = self.take_region_owner(region_id) {
                finish_owned_wide_arc_attack(owner.base_mut(), &dispatch);
                self.restore_region_owner(owner);
            }
        }
        if let Some(dispatch) = range_dispatch {
            let mut attacked = Vec::new();
            'cells: for (offset_x, offset_y) in range_attack_scope_cells() {
                let Some(owner) = self.take_region_owner(region_id) else {
                    break 'cells;
                };
                let candidates = range_attack_cell_candidates(
                    self,
                    owner.base(),
                    dispatch.monster_id,
                    dispatch.center_x.wrapping_add(offset_x),
                    dispatch.center_y.wrapping_add(offset_y),
                );
                self.restore_region_owner(owner);
                for identity in candidates {
                    if attacked.contains(&identity) {
                        continue;
                    }
                    let Some(mut owner) = self.take_region_owner(region_id) else {
                        break 'cells;
                    };
                    let mut deaths = Vec::new();
                    let applied = execute_owned_monster_range_target(
                        self,
                        owner.base_mut(),
                        &dispatch,
                        identity,
                        runtime,
                        &mut deaths,
                    );
                    self.restore_region_owner(owner);
                    if applied {
                        attacked.push(identity);
                        self.apply_monster_attack_deaths(region_id, deaths, runtime);
                    }
                }
            }
            if let Some(mut owner) = self.take_region_owner(region_id) {
                finish_owned_monster_range_cast(owner.base_mut(), &dispatch);
                self.restore_region_owner(owner);
            }
        }
        if let Some(dispatch) = projectile_dispatch {
            let candidates = if let Some(owner) = self.take_region_owner(region_id) {
                let candidates = monster_attack_cell_candidates(
                    self,
                    owner.base(),
                    dispatch.monster_id,
                    dispatch.impact_x,
                    dispatch.impact_y,
                );
                self.restore_region_owner(owner);
                candidates
            } else {
                Vec::new()
            };
            for identity in candidates {
                let Some(mut owner) = self.take_region_owner(region_id) else {
                    break;
                };
                let mut deaths = Vec::new();
                let applied = execute_owned_monster_projectile_target(
                    self,
                    owner.base_mut(),
                    &dispatch,
                    identity,
                    runtime,
                    &mut deaths,
                );
                self.restore_region_owner(owner);
                if applied {
                    self.apply_monster_attack_deaths(region_id, deaths, runtime);
                }
            }
            if let Some(mut owner) = self.take_region_owner(region_id) {
                finish_owned_monster_projectile(owner.base_mut(), &dispatch);
                self.restore_region_owner(owner);
            }
        }
        handled
    }

    pub(crate) fn send_skill_system_info(&self, player_id: i32, string_id: &[u8]) {
        let mut message = CMessage::new(0x000b_f807);
        message.add_ulong(CSkillFactory::get_skill_failed_message_color());
        add_legacy_c_string(message.base_mut(), self.get_string_by_id(string_id));
        let _ = message.send_to_player(self.net_server(), player_id);
    }

    pub(crate) fn send_skill_system_info_with_text(
        &self,
        player_id: i32,
        string_id: &[u8],
        value: &[u8],
    ) {
        let text = format_legacy_text_fields(self.get_string_by_id(string_id), &[value], 0xff);
        let mut message = CMessage::new(0x000b_f807);
        message.add_ulong(CSkillFactory::get_skill_failed_message_color());
        add_legacy_c_string(message.base_mut(), &text);
        let _ = message.send_to_player(self.net_server(), player_id);
    }

    pub(crate) fn send_skill_system_info_with_unsigned(
        &self,
        player_id: i32,
        string_id: &[u8],
        value: u32,
    ) {
        let text = format_legacy_mixed(
            self.get_string_by_id(string_id),
            &[LegacyFormatArgument::Unsigned(value)],
            0xff,
        );
        let mut message = CMessage::new(0x000b_f807);
        message.add_ulong(CSkillFactory::get_skill_failed_message_color());
        add_legacy_c_string(message.base_mut(), &text);
        let _ = message.send_to_player(self.net_server(), player_id);
    }

    pub(crate) fn base_magic_target_view(
        &self,
        region_id: i32,
        target: ShapeIdentity,
    ) -> Option<ShapeView> {
        match target.object_type {
            PLAYER_TYPE => self
                .find_player(target.id)
                .filter(|player| player.server_region_id() == Some(region_id))
                .and_then(CPlayer::shape_view),
            MONSTER_TYPE => {
                let monster = self
                    .find_region(region_id)?
                    .base()
                    .find_monster_by_id(target.id)?;
                let property = self
                    .find_monster_property_by_origin_name(monster.base_property_key()?)?;
                monster.shape_view(property)
            }
            _ => None,
        }
    }

    pub(crate) fn base_magic_path(
        &self,
        region_id: i32,
        source_x: i32,
        source_y: i32,
        target_x: i32,
        target_y: i32,
        forced_length: Option<u32>,
    ) -> Vec<(i32, i32, u8)> {
        let Some(region) = self.find_region(region_id) else {
            return Vec::new();
        };
        region.base().straight_skill_path(
            source_x,
            source_y,
            target_x,
            target_y,
            forced_length,
        )
    }

