    pub(crate) fn finish_self_shield_movement(&mut self, player_id: i32) {
        if let Some(player) = self.find_player_mut(player_id) {
            player.set_skill_moveable(true);
            player.set_current_skill_id(None);
        }
    }

    fn execute_player_base_attack<Runtime: GameMainLoopRuntime>(
        &mut self,
        player_id: i32,
        dispatch: PlayerSkillDispatch,
        player_ai: &mut CPlayerAI,
        runtime: &mut Runtime,
    ) -> QueuedSkillExecutionOutcome {
        let rejected = || QueuedSkillExecutionOutcome {
            state: QueuedSkillExecutionState::Rejected,
            first_contact: false,
            killing_blow: None,
        };
        let Some(player) = self.find_player(player_id) else {
            return rejected();
        };
        let skill_level = player.learned_skill_level(BASE_ATTACK_SKILL_ID);
        let Some(properties) = self
            .skill_factory
            .query_skill_base_properties(BASE_ATTACK_SKILL_ID, skill_level)
        else {
            return rejected();
        };
        let delay_ms = properties.query_property(SKILL_USAGE_DELAY_TIME);
        let reuse_delay_ms = properties.query_property(SKILL_USAGE_REUSE_DELAY_TIME);
        let maximum_distance = properties.query_property(SKILL_USAGE_TARGET_MAX_DISTANCE);
        let hit_modifier = properties.query_property(SKILL_USAGE_USER_HIT_MODIFIER) as i32;
        let now_ms = runtime.now_milliseconds();
        let target = match dispatch {
            PlayerSkillDispatch::Object { target, .. } if target.object_type == PLAYER_TYPE => self
                .find_player(target.id)
                .and_then(|player| player.shape_view())
                .map(|view| (target, view)),
            PlayerSkillDispatch::Object { target, .. } if target.object_type == 600 => player
                .server_region_id()
                .and_then(|region_id| self.find_region(region_id))
                .and_then(|owner| owner.base().find_monster_by_id(target.id))
                .and_then(|monster| {
                    let property = monster
                        .base_property_key()
                        .and_then(|key| self.find_monster_property_by_origin_name(key))?;
                    monster.shape_view(property)
                })
                .map(|view| (target, view)),
            _ => None,
        };

        if player_ai.base_attack().is_none() {
            if matches!(dispatch, PlayerSkillDispatch::Object { .. }) && target.is_none() {
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            if player.is_rider() || !player.can_fight() {
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            let last_used_ms = player_ai.base_attack_last_used_ms();
            if last_used_ms != 0 && !time_reached(now_ms, last_used_ms, reuse_delay_ms) {
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            if let Some((target_identity, _)) = target
                && target_identity.object_type == PLAYER_TYPE
                && self
                    .find_player(target_identity.id)
                    .is_some_and(CPlayer::is_dead)
            {
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            if let Some((target_identity, _)) = target
                && target_identity.object_type == PLAYER_TYPE
                && let Some((string_id, limit)) =
                    self.player_base_attack_level_block(player_id, target_identity.id)
            {
                self.send_base_attack_level_block(player_id, string_id, limit);
                self.enter_player_combat_state(player_id);
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            if let Some((target_identity, _)) = target
                && target_identity.object_type == PLAYER_TYPE
                && !self.player_base_attackable(player_id, target_identity.id)
            {
                self.enter_player_combat_state(player_id);
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            let (source_x, source_y) =
                match (player.shape().get_tile_x(), player.shape().get_tile_y()) {
                    (Ok(x), Ok(y)) => (x, y),
                    _ => return rejected(),
                };
            let (target_x, target_y) = match (dispatch, target) {
                (_, Some((_, view))) => (view.tile_x, view.tile_y),
                (PlayerSkillDispatch::Point { x, y, .. }, None) => (x, y),
                _ => (source_x, source_y),
            };
            if maximum_distance != 0
                && (maximum_distance as i32) < real_distance(source_x, source_y, target_x, target_y)
            {
                let _ = self.send_base_attack_failure(player_id, 0x0b);
                return rejected();
            }
            if let Some(player) = self.find_player_mut(player_id) {
                player
                    .movement_shape_mut()
                    .set_direction(get_line_direction(source_x, source_y, target_x, target_y));
                player.set_current_skill_id(Some(BASE_ATTACK_SKILL_ID));
            }
            self.enter_player_combat_state(player_id);
            let direction = self
                .find_player(player_id)
                .map(|player| player.shape().get_direction())
                .unwrap_or_default();
            let mut start = CMessage::new(0x000b_fe01);
            start.add_byte(1);
            start.add_long(BASE_ATTACK_SKILL_ID as i32);
            start.base_mut().add_short(skill_level as i16);
            start.add_long(PLAYER_TYPE);
            start.add_long(player_id);
            start.add_long(direction);
            let _ = self.send_player_shape_around(player_id, None, &start);
            let mut execution = BaseAttackExecutionState::begin(dispatch, now_ms);
            let _ = execution.advance(SkillStage::Begin, SkillStage::Check);
            player_ai.begin_base_attack(execution);
            if !time_reached(now_ms, now_ms, delay_ms) {
                return QueuedSkillExecutionOutcome {
                    state: QueuedSkillExecutionState::Pending,
                    first_contact: false,
                    killing_blow: None,
                };
            }
        } else if player_ai
            .base_attack()
            .is_none_or(|state| state.dispatch() != dispatch)
        {
            return rejected();
        } else if !time_reached(
            now_ms,
            player_ai
                .base_attack()
                .map_or(now_ms, BaseAttackExecutionState::started_at_ms),
            delay_ms,
        ) {
            return QueuedSkillExecutionOutcome {
                state: QueuedSkillExecutionState::Pending,
                first_contact: false,
                killing_blow: None,
            };
        }

        if let Some((target_identity, _)) = target
            && target_identity.object_type == PLAYER_TYPE
            && self
                .find_player(target_identity.id)
                .is_some_and(CPlayer::is_dead)
        {
            let _ = self.send_base_attack_failure(player_id, 2);
            if let Some(player) = self.find_player_mut(player_id) {
                player.set_current_skill_id(None);
            }
            return rejected();
        }
        if let Some((target_identity, _)) = target
            && target_identity.object_type == MONSTER_TYPE
        {
            let monster_unavailable = self
                .find_player(player_id)
                .and_then(CPlayer::server_region_id)
                .and_then(|region_id| self.find_region(region_id))
                .and_then(|owner| owner.base().find_monster_by_id(target_identity.id))
                .is_none_or(|monster| monster.hit_points() == 0 || monster.move_shape().is_god());
            if monster_unavailable {
                let _ = self.send_base_attack_failure(player_id, 2);
                if let Some(player) = self.find_player_mut(player_id) {
                    player.set_current_skill_id(None);
                }
                return rejected();
            }
        }
        let _ = player_ai.advance_base_attack(SkillStage::Check, SkillStage::Calculate);
        let (target_type, target_id, target_x, target_y) = match target {
            Some((target, view)) => (target.object_type, target.id, view.tile_x, view.tile_y),
            None => match dispatch {
                PlayerSkillDispatch::Point { x, y, .. } => (0, 0, x, y),
                _ => (0, 0, 0, 0),
            },
        };
        let mut fire = CMessage::new(0x000b_fe01);
        fire.add_byte(2);
        fire.add_long(BASE_ATTACK_SKILL_ID as i32);
        fire.base_mut().add_short(skill_level as i16);
        fire.add_long(PLAYER_TYPE);
        fire.add_long(player_id);
        fire.add_long(target_type);
        fire.add_long(target_id);
        fire.add_long(target_x);
        fire.add_long(target_y);
        let _ = self.send_player_shape_around(player_id, None, &fire);

        let mut killing_blow = None;
        let mut first_contact = false;
        if target_type == PLAYER_TYPE && self.player_base_attackable(player_id, target_id) {
            let (
                mut attacker_properties,
                attacker_occupation,
                attacker_team,
                attacker_faction,
                attacker_union,
                target_properties,
                target_level,
                target_health,
                target_mana,
                target_war_soul_mana,
            ) = {
                let attacker = self
                    .find_player(player_id)
                    .expect("base-attack attacker сохранён");
                let target = self
                    .find_player(target_id)
                    .expect("base-attack target сохранён");
                (
                    attacker.combat_properties(),
                    attacker.occupation(),
                    attacker.team_id(),
                    attacker.faction_id(),
                    attacker.union_id(),
                    target.combat_properties(),
                    target.level(),
                    target.health(),
                    target.mana(),
                    target.war_soul_mana(&self.goods_factory),
                )
            };
            let [
                blast_attack,
                blast_defense,
                element_blast_attack,
                element_blast_defense,
                full_miss,
            ] = self.globe_setup.base_combat_scales();
            if attacker_properties.blast_attack_scale() < 1.0 {
                attacker_properties.blast_attack_scale_bits = blast_attack.max(1.0).to_bits();
            }
            if attacker_properties.blast_defense_scale() < 0.01 {
                attacker_properties.blast_defense_scale_bits = blast_defense.max(0.01).to_bits();
            }
            if attacker_properties.element_blast_attack_scale() < 1.0 {
                attacker_properties.element_blast_attack_scale_bits =
                    element_blast_attack.max(1.0).to_bits();
            }
            if attacker_properties.element_blast_defense_scale() < 0.01 {
                attacker_properties.element_blast_defense_scale_bits =
                    element_blast_defense.max(0.01).to_bits();
            }
            if attacker_properties.full_miss_scale() < 0.01 {
                attacker_properties.full_miss_scale_bits = full_miss.max(0.01).to_bits();
            }
            if attacker_properties.critical_rate() < 1.0 {
                attacker_properties.critical_rate_bits =
                    self.globe_setup.critical_rate().max(1.0).to_bits();
            }
            let weapon_level = self
                .find_player(player_id)
                .and_then(|player| player.equipment().get_goods(2))
                .map_or(0, |goods| {
                    goods.addon_property_value(&self.goods_factory, GAP_WEAPON_DAMAGE_LEVEL, 1)
                });
            let (weapon_divisor, weapon_minimum) = self.globe_setup.weapon_damage_factors();
            let delta = weapon_level.wrapping_sub(i32::from(target_level)).max(0);
            let mut damage_factor = if weapon_divisor == 0.0 {
                1.0
            } else {
                delta as f32 / weapon_divisor
            };
            damage_factor = damage_factor.min(1.0).max(weapon_minimum);
            let minimum = attacker_properties.minimum_attack as i32;
            let maximum = attacker_properties.maximum_attack as i32;
            let span = maximum.wrapping_sub(minimum).max(0).wrapping_add(1);
            let physical = minimum.wrapping_add(game_legacy_random(&mut self.random_state, span));
            let mut attack = AttackInformation {
                skill_id: BASE_ATTACK_SKILL_ID,
                skill_level: skill_level as u8,
                attacker_type: PLAYER_TYPE,
                attacker_id: player_id,
                attacker_team_id: attacker_team,
                attacker_faction_id: attacker_faction,
                attacker_union_id: attacker_union,
                hit_modifier,
                damage_factor,
                damage_modifier: 0,
                critical: false,
                blast_attack: false,
                full_miss: 0,
                damages: vec![
                    AttackPower {
                        kind: AttackPowerType::Physical,
                        hp_damage: physical.max(0),
                        mp_damage: 0,
                    },
                    AttackPower {
                        kind: AttackPowerType::Element,
                        hp_damage: attacker_properties.add_element_attack as i32,
                        mp_damage: 0,
                    },
                    AttackPower {
                        kind: AttackPowerType::Soul,
                        hp_damage: i32::from(attacker_properties.add_soul_attack),
                        mp_damage: 0,
                    },
                ],
            };
            if game_legacy_random(&mut self.random_state, 100) < i32::from(attacker_properties.cch)
            {
                attack.critical = true;
                let critical_rate = self.globe_setup.critical_rate();
                for power in &mut attack.damages {
                    power.hp_damage =
                        ((power.hp_damage as f32) * critical_rate).round_ties_even() as i32;
                }
            }
            let pillar_damage_factor = self.find_player(target_id)
                .and_then(CPlayer::pillar_state).map(|state| state.damage_factor());
            let mut defense_shields = self
                .find_player_mut(target_id)
                .map(CPlayer::take_defense_shields)
                .unwrap_or_default();
            let mut random = |maximum| game_legacy_random(&mut self.random_state, maximum);
            defend_player_base_attack(
                &mut attack,
                attacker_properties,
                attacker_occupation,
                target_properties,
                target_mana,
                target_war_soul_mana,
                &self.globe_setup,
                &mut random,
                &mut defense_shields,
                pillar_damage_factor,
            );
            if let Some(target) = self.find_player_mut(target_id) {
                target.restore_defense_shields(defense_shields);
            }
            let _ = player_ai.advance_base_attack(SkillStage::Calculate, SkillStage::Attack);
            first_contact = true;
            let (damage, mana_damage) =
                Self::applied_attack_damage(&attack, target_health, target_mana);
            if attack.full_miss != 0 {
                let mut missed = CMessage::new(0x000b_f612);
                missed.add_byte(attack.full_miss);
                missed.add_long(PLAYER_TYPE);
                missed.add_long(target_id);
                let _ = self.send_player_shape_around(target_id, None, &missed);
            } else if damage != 0 || mana_damage != 0 {
                let current_health = target_health - damage;
                if let Some(target) = self.find_player_mut(target_id) {
                    target.set_health(current_health);
                    target.set_mana(target_mana - mana_damage);
                    target
                        .movement_shape_mut()
                        .set_action(if current_health == 0 { 6 } else { 5 });
                }
                if current_health != 0 {
                    let _ = finish_player_blind_states_on_defense(self, target_id, now_ms);
                }
                if current_health == 0 {
                    let mut died = CMessage::new(0x000b_f60b);
                    died.add_long(PLAYER_TYPE);
                    died.add_long(player_id);
                    died.add_long(PLAYER_TYPE);
                    died.add_long(target_id);
                    died.add_ulong(damage);
                    died.base_mut().add_char(1);
                    Self::append_base_attack_tail(&mut died, &attack);
                    let _ = self.send_player_shape_around(target_id, None, &died);
                    killing_blow = Some(PlayerKillingBlow {
                        victim_id: target_id,
                        attacker_type: PLAYER_TYPE,
                        attacker_id: player_id,
                        attacker_faction_id: attacker_faction,
                    });
                } else {
                    let mut hurt = CMessage::new(0x000b_f60a);
                    hurt.add_long(PLAYER_TYPE);
                    hurt.add_long(player_id);
                    hurt.add_long(PLAYER_TYPE);
                    hurt.add_long(target_id);
                    Self::append_hurt_damage_records(&mut hurt, damage, mana_damage);
                    hurt.add_ulong(current_health);
                    Self::append_base_attack_tail(&mut hurt, &attack);
                    let _ = self.send_player_shape_around(target_id, None, &hurt);
                    self.damage_player_armor(target_id, runtime);
                }
            }
            if let Some(attacker) = self.find_player_mut(player_id) {
                attacker.movement_shape_mut().set_action(1);
            }
        } else if target_type == MONSTER_TYPE {
            let Some(region_id) = self
                .find_player(player_id)
                .and_then(CPlayer::server_region_id)
            else {
                return rejected();
            };
            let monster_property = self
                .find_region(region_id)
                .and_then(|owner| owner.base().find_monster_by_id(target_id))
                .and_then(CMonster::base_property_key)
                .and_then(|key| self.find_monster_property_by_origin_name(key))
                .cloned();
            let Some(monster_property) = monster_property else {
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            };
            let monster_snapshot = self.find_region(region_id).and_then(|owner| {
                let monster = owner.base().find_monster_by_id(target_id)?;
                Some((
                    monster.combat_properties(&monster_property),
                    monster.hit_points(),
                    monster.is_tamed(),
                    monster.is_carriage(&monster_property),
                    monster.move_shape().is_god(),
                    monster.master_info(),
                ))
            });
            let Some((
                monster_properties,
                monster_health,
                monster_tamed,
                monster_carriage,
                monster_god,
                monster_master,
            )) = monster_snapshot
            else {
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            };
            if monster_health == 0 || monster_god {
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            if !self.guard_monster_attackable(player_id, region_id, &monster_property) {
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            let owned_target_player = ((monster_tamed || monster_carriage)
                && monster_master.master_type == PLAYER_TYPE
                && monster_master.master_id != 0)
                .then_some(monster_master.master_id);
            if let Some(owner_id) = owned_target_player
                && owner_id != player_id
                && let Some((string_id, limit)) =
                    self.player_base_attack_level_block(player_id, owner_id)
            {
                self.send_base_attack_level_block(player_id, string_id, limit);
                self.enter_player_combat_state(player_id);
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            let owned_target_attackable = owned_target_player.is_none_or(|owner_id| {
                if owner_id == player_id {
                    self.find_player(player_id)
                        .is_some_and(|player| player.pk_permissions().criminal)
                } else {
                    self.player_base_attackable(player_id, owner_id)
                }
            });
            if !owned_target_attackable {
                self.enter_player_combat_state(player_id);
                let _ = self.send_base_attack_failure(player_id, 2);
                return rejected();
            }
            if let Some(owner_id) = owned_target_player {
                let _ = self.player_on_first_skill(player_id, owner_id, Some(region_id), runtime);
            }
            self.apply_guard_monster_first_attack(player_id, region_id, &monster_property, now_ms);

            let (
                mut attacker_properties,
                attacker_occupation,
                attacker_level,
                attacker_team,
                attacker_faction,
                attacker_union,
            ) = {
                let attacker = self
                    .find_player(player_id)
                    .expect("base-attack attacker сохранён");
                (
                    attacker.combat_properties(),
                    attacker.occupation(),
                    attacker.level(),
                    attacker.team_id(),
                    attacker.faction_id(),
                    attacker.union_id(),
                )
            };
            let [
                blast_attack,
                blast_defense,
                element_blast_attack,
                element_blast_defense,
                full_miss,
            ] = self.globe_setup.base_combat_scales();
            if attacker_properties.blast_attack_scale() < 1.0 {
                attacker_properties.blast_attack_scale_bits = blast_attack.max(1.0).to_bits();
            }
            if attacker_properties.blast_defense_scale() < 0.01 {
                attacker_properties.blast_defense_scale_bits = blast_defense.max(0.01).to_bits();
            }
            if attacker_properties.element_blast_attack_scale() < 1.0 {
                attacker_properties.element_blast_attack_scale_bits =
                    element_blast_attack.max(1.0).to_bits();
            }
            if attacker_properties.element_blast_defense_scale() < 0.01 {
                attacker_properties.element_blast_defense_scale_bits =
                    element_blast_defense.max(0.01).to_bits();
            }
            if attacker_properties.full_miss_scale() < 0.01 {
                attacker_properties.full_miss_scale_bits = full_miss.max(0.01).to_bits();
            }
            if attacker_properties.critical_rate() < 1.0 {
                attacker_properties.critical_rate_bits =
                    self.globe_setup.critical_rate().max(1.0).to_bits();
            }
            let minimum = attacker_properties.minimum_attack as i32;
            let maximum = attacker_properties.maximum_attack as i32;
            let span = maximum.wrapping_sub(minimum).max(0).wrapping_add(1);
            let physical = minimum.wrapping_add(game_legacy_random(&mut self.random_state, span));
            let weapon_level = self
                .find_player(player_id)
                .and_then(|player| player.equipment().get_goods(2))
                .map_or(0, |goods| {
                    goods.addon_property_value(&self.goods_factory, GAP_WEAPON_DAMAGE_LEVEL, 1)
                });
            let (weapon_divisor, weapon_minimum) = self.globe_setup.weapon_damage_factors();
            let delta = weapon_level
                .wrapping_sub(i32::from(monster_properties.level))
                .max(0);
            let mut damage_factor = if weapon_divisor == 0.0 {
                1.0
            } else {
                delta as f32 / weapon_divisor
            };
            damage_factor = damage_factor.min(1.0).max(weapon_minimum);
            let mut attack = AttackInformation {
                skill_id: BASE_ATTACK_SKILL_ID,
                skill_level: skill_level as u8,
                attacker_type: PLAYER_TYPE,
                attacker_id: player_id,
                attacker_team_id: attacker_team,
                attacker_faction_id: attacker_faction,
                attacker_union_id: attacker_union,
                hit_modifier,
                damage_factor,
                damage_modifier: 0,
                critical: false,
                blast_attack: false,
                full_miss: 0,
                damages: vec![
                    AttackPower {
                        kind: AttackPowerType::Physical,
                        hp_damage: physical.max(0),
                        mp_damage: 0,
                    },
                    AttackPower {
                        kind: AttackPowerType::Element,
                        hp_damage: attacker_properties.add_element_attack as i32,
                        mp_damage: 0,
                    },
                    AttackPower {
                        kind: AttackPowerType::Soul,
                        hp_damage: i32::from(attacker_properties.add_soul_attack),
                        mp_damage: 0,
                    },
                ],
            };
            if game_legacy_random(&mut self.random_state, 100) < i32::from(attacker_properties.cch)
            {
                attack.critical = true;
                let critical_rate = self.globe_setup.critical_rate();
                for power in &mut attack.damages {
                    power.hp_damage =
                        ((power.hp_damage as f32) * critical_rate).round_ties_even() as i32;
                }
            }
            let mut random = |maximum| game_legacy_random(&mut self.random_state, maximum);
            defend_monster_base_attack(
                &mut attack,
                attacker_properties,
                attacker_occupation,
                attacker_level,
                monster_properties,
                &self.globe_setup,
                &mut random,
            );
            let _ = player_ai.advance_base_attack(SkillStage::Calculate, SkillStage::Attack);
            first_contact = true;
            let damage = attack.hp_damage().min(monster_health);
            let current_health = monster_health - damage;
            let mut owner = self
                .take_region_owner(region_id)
                .expect("monster target region сохранён");
            if let Some(monster) = owner.base_mut().find_monster_by_id_mut(target_id) {
                monster.set_hit_points(current_health);
                if attack.full_miss == 0 && damage != 0 {
                    monster
                        .move_shape_mut()
                        .shape_mut()
                        .set_action(if current_health == 0 { 6 } else { 5 });
                    if current_health == 0 {
                        monster.when_been_killed(now_ms);
                    } else if monster_property.ai == 1 {
                        monster.when_passive_gladiator_hurted_by(
                            ShapeIdentity {
                                object_type: PLAYER_TYPE,
                                id: player_id,
                                ex_id: CGuid::GUID_INVALID,
                            },
                            now_ms,
                            false,
                        );
                    } else if monster_property.ai == 2 {
                        // Владелец AI2 применит реакцию после освобождения
                        // изменяемого заимствования монстра.
                    } else if monster_property.ai == 16 {
                        // Поиск AI16 выполняется после освобождения изменяемого
                        // заимствования монстра.
                    } else if monster_property.ai == 11 {
                        // Поиск AI11 выполняется после освобождения изменяемого
                        // заимствования монстра.
                    } else if monster_property.ai == 0x65 {
                        // AI101 разрешает игрока и связывает близнеца после
                        // освобождения изменяемого заимствования монстра.
                    } else if matches!(monster_property.ai, 8 | 13 | 14 | 20) {
                        monster.when_been_hurted(now_ms);
                    } else {
                        monster.when_been_hurted_by(
                            ShapeIdentity {
                                object_type: PLAYER_TYPE,
                                id: player_id,
                                ex_id: CGuid::GUID_INVALID,
                            },
                            false,
                            now_ms,
                        );
                    }
                }
                if current_health == 0 {
                    monster.set_killed_by(MonsterKillingAttack {
                        attacker_type: PLAYER_TYPE,
                        attacker_id: player_id,
                        skill_id: attack.skill_id,
                        skill_level: attack.skill_level,
                        critical: attack.critical,
                        blast_attack: attack.blast_attack,
                    });
                }
            }
            if attack.full_miss == 0
                && damage != 0
                && current_health != 0
                && monster_property.ai == 2
            {
                crate::gameserver::appserver::ai::smartgladiator::apply_player_hurt_response(
                    self,
                    owner.base_mut(),
                    target_id,
                    &monster_property,
                    player_id,
                    now_ms,
                );
            }
            if attack.full_miss == 0
                && damage != 0
                && current_health != 0
                && monster_property.ai == 11
            {
                crate::gameserver::appserver::ai::cityguardwithbow::retarget_city_bow_guard_after_hurt(
                    self,
                    owner.base_mut(),
                    target_id,
                    &monster_property,
                    now_ms,
                );
            }
            if attack.full_miss == 0
                && damage != 0
                && current_health != 0
                && monster_property.ai == 16
            {
                crate::gameserver::appserver::ai::vilcouguardwithbow::retarget_village_bow_guard_after_hurt(
                    self,
                    owner.base_mut(),
                    target_id,
                    &monster_property,
                    now_ms,
                );
            }
            if attack.full_miss == 0
                && damage != 0
                && current_health != 0
                && monster_property.ai == 0x65
            {
                let _ = retarget_jiumai_after_hurt(
                    self,
                    owner.base_mut(),
                    target_id,
                    ShapeIdentity {
                        object_type: PLAYER_TYPE,
                        id: player_id,
                        ex_id: CGuid::GUID_INVALID,
                    },
                    now_ms,
                );
            }
            if attack.full_miss == 0
                && damage != 0
                && current_health != 0
                && matches!(monster_property.ai, 8 | 13 | 14 | 20)
            {
                crate::gameserver::appserver::ai::guardcountry::retarget_special_guard_after_hurt(
                    self,
                    owner.base_mut(),
                    target_id,
                    &monster_property,
                );
            }
            if attack.full_miss == 0 && damage != 0 && current_health != 0 {
                let _ = finish_blind_states_on_defense(
                    self,
                    owner.base_mut(),
                    ShapeIdentity {
                        object_type: MONSTER_TYPE,
                        id: target_id,
                        ex_id: CGuid::GUID_INVALID,
                    },
                    now_ms,
                );
            }
            self.restore_region_owner(owner);

            if attack.full_miss != 0 {
                let mut missed = CMessage::new(0x000b_f612);
                missed.add_byte(attack.full_miss);
                missed.add_long(MONSTER_TYPE);
                missed.add_long(target_id);
                let _ = self.send_shape_position_around(region_id, target_x, target_y, &missed);
            } else if damage != 0 {
                if current_health == 0 {
                    let mut died = CMessage::new(0x000b_f60b);
                    died.add_long(PLAYER_TYPE);
                    died.add_long(player_id);
                    died.add_long(MONSTER_TYPE);
                    died.add_long(target_id);
                    died.add_ulong(damage);
                    died.base_mut().add_char(1);
                    Self::append_base_attack_tail(&mut died, &attack);
                    let _ = self.send_shape_position_around(region_id, target_x, target_y, &died);
                    let _ =
                        self.gods_battle_monster_died(region_id, target_id, PLAYER_TYPE, player_id);
                    let _ = self.monster_on_died(region_id, target_id, player_id, runtime);
                    if monster_carriage {
                        let _ = self.send_carriage_log_snapshot(
                            monster_master.master_id,
                            monster_property.index,
                            region_id,
                            target_x,
                            target_y,
                            3,
                        );
                        if monster_master.master_type == PLAYER_TYPE
                            && let Some(master) = self.find_player_mut(monster_master.master_id)
                        {
                            master.clear_active_carriage(target_id);
                        }
                    } else if !monster_tamed {
                        self.finish_monster_kill_effects(
                            region_id,
                            target_id,
                            player_id,
                            target_x,
                            target_y,
                            &monster_property,
                            runtime,
                        );
                    } else if monster_master.master_type == PLAYER_TYPE {
                        if let Some(master) = self.find_player_mut(monster_master.master_id) {
                            master.remove_active_pet(MONSTER_TYPE, target_id);
                        }
                    }
                    let monster_position = self.find_region(region_id).and_then(|owner| {
                        let shape = owner
                            .base()
                            .find_monster_by_id(target_id)?
                            .move_shape()
                            .shape();
                        Some((shape.get_pos_x() as u32, shape.get_pos_y() as u32))
                    });
                    if let Some((pos_x, pos_y)) = monster_position {
                        let mut exit = CMessage::new(0x000b_f504);
                        exit.add_long(MONSTER_TYPE);
                        exit.add_long(target_id);
                        exit.add_long(0);
                        exit.add_ulong(pos_x);
                        exit.add_ulong(pos_y);
                        let _ =
                            self.send_shape_position_around(region_id, target_x, target_y, &exit);
                    }
                    if let Some(mut owner) = self.take_region_owner(region_id) {
                        owner.base_mut().finish_owned_monster_death(target_id);
                        self.restore_region_owner(owner);
                    }
                } else {
                    let mut hurt = CMessage::new(0x000b_f60a);
                    hurt.add_long(PLAYER_TYPE);
                    hurt.add_long(player_id);
                    hurt.add_long(MONSTER_TYPE);
                    hurt.add_long(target_id);
                    hurt.add_byte(1);
                    hurt.add_byte(0);
                    hurt.add_ulong(damage);
                    hurt.add_ulong(current_health);
                    Self::append_base_attack_tail(&mut hurt, &attack);
                    let _ = self.send_shape_position_around(region_id, target_x, target_y, &hurt);
                    let _ =
                        self.monster_on_been_hurted(region_id, target_id, PLAYER_TYPE, player_id);
                    if let Some(mut owner) = self.take_region_owner(region_id) {
                        if let Some(monster) = owner.base_mut().find_monster_by_id_mut(target_id) {
                            monster.register_attacking_player(
                                player_id,
                                now_ms,
                                self.globe_setup.attack_monster_protection_ms(),
                            );
                        }
                        self.restore_region_owner(owner);
                    }
                }
            }
            if let Some(attacker) = self.find_player_mut(player_id) {
                attacker.movement_shape_mut().set_action(1);
            }
        }
        let _ = player_ai.advance_base_attack(SkillStage::Calculate, SkillStage::Attack);
        let _ = player_ai.advance_base_attack(SkillStage::Attack, SkillStage::Apply);
        self.damage_player_weapon(player_id, runtime);
        player_ai.mark_base_attack_used(now_ms);
        if let Some(player) = self.find_player_mut(player_id) {
            player.set_current_skill_id(None);
        }
        QueuedSkillExecutionOutcome {
            state: QueuedSkillExecutionState::Completed,
            first_contact,
            killing_blow,
        }
    }

    pub(crate) fn target_has_state_by_skill_id(
        &self,
        region_id: i32,
        target: ShapeIdentity,
        state_id: u32,
    ) -> bool {
        match target.object_type {
            PLAYER_TYPE => self
                .find_player(target.id)
                .is_some_and(|player| player.has_state_by_skill_id(state_id)),
            MONSTER_TYPE => self
                .find_region(region_id)
                .and_then(|owner| owner.base().find_monster_by_id(target.id))
                .is_some_and(|monster| monster.move_shape().has_state_by_skill_id(state_id)),
            _ => false,
        }
    }

    pub(crate) fn periodic_state_target_dead(
        &self,
        region_id: i32,
        target: ShapeIdentity,
    ) -> bool {
        match target.object_type {
            PLAYER_TYPE => self.find_player(target.id).is_none_or(CPlayer::is_dead),
            MONSTER_TYPE => self
                .find_region(region_id)
                .and_then(|owner| owner.base().find_monster_by_id(target.id))
                .is_none_or(|monster| monster.hit_points() == 0),
            _ => true,
        }
    }

    pub(crate) fn move_shape_target_tile(
        &self,
        region_id: Option<i32>,
        target: ShapeIdentity,
    ) -> Option<(i32, i32)> {
        match target.object_type {
            PLAYER_TYPE => {
                let player = self.find_player(target.id)?;
                if region_id.is_some_and(|region_id| player.server_region_id() != Some(region_id)) {
                    return None;
                }
                Some((player.shape().get_tile_x().ok()?, player.shape().get_tile_y().ok()?))
            }
            MONSTER_TYPE => {
                let region_id = region_id?;
                let monster = self.find_region(region_id)?.base().find_monster_by_id(target.id)?;
                Some((
                    monster.move_shape().shape().get_tile_x().ok()?,
                    monster.move_shape().shape().get_tile_y().ok()?,
                ))
            }
            _ => None,
        }
    }

    pub(crate) fn replace_battle_fairy_attribute_state(
        &mut self,
        region_id: i32,
        target: ShapeIdentity,
        state: BattleFairyAttributeState,
    ) -> Option<(Option<BattleFairyAttributeState>, i32, i32)> {
        match target.object_type {
            PLAYER_TYPE => {
                let player = self.find_player_mut(target.id)?;
                if player.server_region_id() != Some(region_id) {
                    return None;
                }
                let tile_x = player.shape().get_tile_x().ok()?;
                let tile_y = player.shape().get_tile_y().ok()?;
                let previous = player.replace_battle_fairy_attribute_state(state);
                Some((previous, tile_x, tile_y))
            }
            MONSTER_TYPE => {
                let mut owner = self.take_region_owner(region_id)?;
                let result = owner.base_mut().find_monster_by_id_mut(target.id).and_then(|monster| {
                    let tile_x = monster.move_shape().shape().get_tile_x().ok()?;
                    let tile_y = monster.move_shape().shape().get_tile_y().ok()?;
                    let previous = monster.move_shape_mut().replace_battle_fairy_attribute_state(state);
                    Some((previous, tile_x, tile_y))
                });
                self.restore_region_owner(owner);
                result
            }
            _ => None,
        }
    }

    pub(crate) fn periodic_state_target_name(
        &self,
        region_id: i32,
        target: ShapeIdentity,
    ) -> &[u8] {
        match target.object_type {
            PLAYER_TYPE => self
                .find_player(target.id)
                .map(CPlayer::player_name)
                .unwrap_or_default(),
            MONSTER_TYPE => self
                .find_region(region_id)
                .and_then(|owner| owner.base().find_monster_by_id(target.id))
                .map(CMonster::display_name)
                .unwrap_or_default(),
            _ => &[],
        }
    }

